CREATE OR REPLACE FUNCTION jornada_private.acquire_matchday_live_layout_cutover_core_lock()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  lock table
    public.matchday_editorials,
    public.matchday_highlights,
    public.matchday_horizontal_news,
    public.matchday_live_layout_items,
    public.matchday_editorial_profile_zone_items
  in row exclusive mode;
  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.apply_matchday_editorial_desk_state_v2_pre_handoff(p_matchday_id uuid, p_expected_revision bigint, p_expected_state_token text, p_faixa_visible boolean, p_articles jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if not exists (select 1 from public.matchday_editorial_desk_control as desk_row where desk_row.matchday_id=p_matchday_id and desk_row.is_managed=true) then
    raise exception 'editorial-desk-matchday-not-live';
  end if;
  perform pg_catalog.set_config('jornada.live_layout_cutover_adapter','on',true);
  v_result := jornada_private.apply_matchday_editorial_desk_state_v2_pre_cutover(p_matchday_id,p_expected_revision,p_expected_state_token,p_faixa_visible,p_articles);
  perform jornada_private.reconcile_matchday_live_layout_from_legacy_adapter(p_matchday_id);
  return v_result || pg_catalog.jsonb_build_object('stateToken',public.matchday_editorial_desk_state_token_v2(p_matchday_id));
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.apply_matchday_editorial_profile_workspace_v9_pre_bridge(p_matchday_id uuid, p_profile_key text, p_expected_revision bigint, p_expected_state_token text, p_overrides jsonb, p_zone_items jsonb, p_faixa_source_ids jsonb, p_opening jsonb, p_page_controls jsonb, p_selection_bank_item_ids jsonb, p_video_module jsonb, p_worked_source_ids jsonb)
 RETURNS TABLE(revision bigint, state_token text, applied_override_count integer, applied_zone_item_count integer, applied_faixa_count integer, applied_opening_count integer, applied_selection_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_requested_layouts jsonb;
  v_apply record;
begin
  if p_zone_items is null
    or pg_catalog.jsonb_typeof(p_zone_items) <> 'array'
    or p_page_controls is null
    or pg_catalog.jsonb_typeof(p_page_controls) <> 'object'
  then
    raise exception 'matchday-editorial-profile-workspace-v9-invalid-input';
  end if;

  v_requested_layouts := p_page_controls -> 'thematic_zone_layouts';

  if pg_catalog.jsonb_typeof(v_requested_layouts) <> 'object'
    or not (
      v_requested_layouts ?& array[
        'benfica',
        'sporting',
        'fc_porto',
        'other_liga_clubs',
        'outside_liga_other'
      ]
    )
    or (
      v_requested_layouts - array[
        'benfica',
        'sporting',
        'fc_porto',
        'other_liga_clubs',
        'outside_liga_other'
      ]::text[]
    ) <> '{}'::jsonb
  then
    raise exception 'matchday-editorial-profile-workspace-v9-invalid-zone-layouts';
  end if;

  if p_selection_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_selection_bank_item_ids) <> 'array'
    or pg_catalog.jsonb_array_length(p_selection_bank_item_ids) <> 4
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_selection_bank_item_ids)
        as selection_row(value)
      where pg_catalog.jsonb_typeof(selection_row.value) not in ('string', 'null')
        or (
          pg_catalog.jsonb_typeof(selection_row.value) = 'string'
          and nullif(pg_catalog.btrim(selection_row.value #>> '{}'), '') is null
        )
    )
  then
    raise exception 'matchday-editorial-profile-workspace-v9-invalid-selection-shape';
  end if;

  if (
    select pg_catalog.count(*)
    from pg_catalog.jsonb_array_elements(p_selection_bank_item_ids)
      as selection_row(value)
    where pg_catalog.jsonb_typeof(selection_row.value) = 'string'
  ) <> (
    select pg_catalog.count(
      distinct pg_catalog.lower(
        pg_catalog.btrim(selection_row.value #>> '{}')
      )
    )
    from pg_catalog.jsonb_array_elements(p_selection_bank_item_ids)
      as selection_row(value)
    where pg_catalog.jsonb_typeof(selection_row.value) = 'string'
  )
  then
    raise exception 'matchday-editorial-profile-workspace-v9-duplicate-selection';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zone_items)
      as zone_row(value)
    where zone_row.value ->> 'zone_key' not in (
      'benfica',
      'sporting',
      'fc_porto',
      'other_liga_clubs',
      'outside_liga_other'
    )
  ) then
    raise exception 'matchday-editorial-profile-workspace-v9-invalid-zone';
  end if;

  if exists (
    with expected_zones(zone_key, capacity) as (
      values
        ('benfica'::text, case v_requested_layouts ->> 'benfica' when 'six_news' then 6 when 'six_news_1_2_3' then 6 when 'five_news_balanced' then 5 when 'five_news_secondary' then 5 else 0 end),
        ('sporting'::text, case v_requested_layouts ->> 'sporting' when 'six_news' then 6 when 'six_news_1_2_3' then 6 when 'five_news_balanced' then 5 when 'five_news_secondary' then 5 else 0 end),
        ('fc_porto'::text, case v_requested_layouts ->> 'fc_porto' when 'six_news' then 6 when 'six_news_1_2_3' then 6 when 'five_news_balanced' then 5 when 'five_news_secondary' then 5 else 0 end),
        ('other_liga_clubs'::text, case v_requested_layouts ->> 'other_liga_clubs' when 'six_news' then 6 when 'six_news_1_2_3' then 6 when 'five_news_balanced' then 5 when 'five_news_secondary' then 5 else 0 end),
        ('outside_liga_other'::text, case v_requested_layouts ->> 'outside_liga_other' when 'six_news' then 6 when 'six_news_1_2_3' then 6 when 'five_news_balanced' then 5 when 'five_news_secondary' then 5 else 0 end)
    ),
    actual_zones as (
      select
        zone_row.value ->> 'zone_key' as zone_key,
        pg_catalog.count(*)::integer as item_count
      from pg_catalog.jsonb_array_elements(p_zone_items) as zone_row(value)
      group by zone_row.value ->> 'zone_key'
    )
    select 1
    from expected_zones as expected
    left join actual_zones as actual on actual.zone_key = expected.zone_key
    where coalesce(actual.item_count, 0) <> expected.capacity
  ) then
    raise exception 'matchday-editorial-profile-workspace-v9-incomplete-zone';
  end if;

  if exists (
    with expected_zones(zone_key, capacity) as (
      values
        ('benfica'::text, case v_requested_layouts ->> 'benfica' when 'six_news' then 6 when 'six_news_1_2_3' then 6 else 5 end),
        ('sporting'::text, case v_requested_layouts ->> 'sporting' when 'six_news' then 6 when 'six_news_1_2_3' then 6 else 5 end),
        ('fc_porto'::text, case v_requested_layouts ->> 'fc_porto' when 'six_news' then 6 when 'six_news_1_2_3' then 6 else 5 end),
        ('other_liga_clubs'::text, case v_requested_layouts ->> 'other_liga_clubs' when 'six_news' then 6 when 'six_news_1_2_3' then 6 else 5 end),
        ('outside_liga_other'::text, case v_requested_layouts ->> 'outside_liga_other' when 'six_news' then 6 when 'six_news_1_2_3' then 6 else 5 end)
    )
    select 1
    from expected_zones as expected
    where exists (
      select 1
      from pg_catalog.generate_series(1, expected.capacity) as required_position(position)
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_zone_items) as zone_row(value)
        where zone_row.value ->> 'zone_key' = expected.zone_key
          and pg_catalog.jsonb_typeof(zone_row.value -> 'sort_order') = 'number'
          and zone_row.value ->> 'sort_order' ~ '^[1-9][0-9]*$'
          and (zone_row.value ->> 'sort_order')::integer = required_position.position
      )
    )
  ) then
    raise exception 'matchday-editorial-profile-workspace-v9-invalid-zone-positions';
  end if;

  select *
  into v_apply
  from public.apply_matchday_editorial_profile_workspace_v8(
    p_matchday_id,
    p_profile_key,
    p_expected_revision,
    p_expected_state_token,
    p_overrides,
    p_zone_items,
    p_faixa_source_ids,
    p_opening,
    p_page_controls,
    p_selection_bank_item_ids,
    p_video_module,
    p_worked_source_ids
  );

  return query
  select
    v_apply.revision,
    v_apply.state_token,
    v_apply.applied_override_count,
    v_apply.applied_zone_item_count,
    v_apply.applied_faixa_count,
    v_apply.applied_opening_count,
    v_apply.applied_selection_count;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.apply_matchday_live_layout_physical_state_v13_shadow(p_matchday_id uuid, p_profile_key text, p_expected_state_token text, p_authoritative_placements jsonb, p_explicit_bank_item_ids jsonb, p_displaced_bank_item_ids jsonb, p_worked_bank_item_ids jsonb, p_faixa_arrival_bank_item_ids jsonb, p_displaced_arrival_bank_item_ids jsonb)
 RETURNS TABLE(state_token text, applied_placement_count integer, explicit_bank_item_count integer, displaced_bank_item_count integer, worked_bank_item_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_assignment_profile_key text;
  v_current_state_token text;
  v_final_state_token text;
  v_plan jsonb := '[]'::jsonb;
  v_placements_before jsonb := '[]'::jsonb;
  v_faixa_before jsonb := '[]'::jsonb;
  v_displaced_before jsonb := '[]'::jsonb;
  v_classification_before text;
  v_faixa_anchor timestamptz;
  v_displaced_anchor timestamptz;
begin
  if p_matchday_id is null
    or p_profile_key is null
    or pg_catalog.btrim(p_profile_key) = ''
    or p_expected_state_token is null
    or pg_catalog.btrim(p_expected_state_token) = ''
    or p_authoritative_placements is null
    or pg_catalog.jsonb_typeof(p_authoritative_placements) <> 'array'
    or p_explicit_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_explicit_bank_item_ids) <> 'array'
    or p_displaced_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_bank_item_ids) <> 'array'
    or p_worked_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_worked_bank_item_ids) <> 'array'
    or p_faixa_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_faixa_arrival_bank_item_ids) <> 'array'
    or p_displaced_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_arrival_bank_item_ids) <> 'array'
  then
    raise exception 'matchday-live-layout-physical-v13-invalid-input';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_authoritative_placements)
      as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
  ) then
    raise exception 'matchday-live-layout-physical-v13-invalid-placement';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_authoritative_placements)
      as raw_row(payload)
    where (
      select pg_catalog.count(*)
      from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
    ) <> 4
      or not raw_row.payload ? 'bank_item_id'
      or not raw_row.payload ? 'placement_type'
      or not raw_row.payload ? 'zone_id'
      or not raw_row.payload ? 'slot_position'
  ) then
    raise exception 'matchday-live-layout-physical-v13-invalid-placement-shape';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_authoritative_placements)
      as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload -> 'bank_item_id') <> 'string'
      or pg_catalog.btrim(raw_row.payload ->> 'bank_item_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or pg_catalog.jsonb_typeof(raw_row.payload -> 'placement_type') <> 'string'
      or pg_catalog.lower(
           pg_catalog.btrim(raw_row.payload ->> 'placement_type')
         ) not in ('opening', 'faixa', 'selection', 'video_highlight', 'zone')
      or pg_catalog.jsonb_typeof(raw_row.payload -> 'slot_position') <> 'number'
      or raw_row.payload ->> 'slot_position' !~ '^[0-9]+$'
      or (raw_row.payload ->> 'slot_position')::numeric > 2147483647
      or not (
        (
          pg_catalog.lower(
            pg_catalog.btrim(raw_row.payload ->> 'placement_type')
          ) = 'zone'
          and pg_catalog.jsonb_typeof(raw_row.payload -> 'zone_id') = 'string'
          and pg_catalog.btrim(raw_row.payload ->> 'zone_id') ~*
              '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        )
        or (
          pg_catalog.lower(
            pg_catalog.btrim(raw_row.payload ->> 'placement_type')
          ) <> 'zone'
          and pg_catalog.jsonb_typeof(raw_row.payload -> 'zone_id') = 'null'
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v13-invalid-placement-value';
  end if;

  if exists (
    select 1
    from (
      select p_explicit_bank_item_ids as payload
      union all
      select p_displaced_bank_item_ids
      union all
      select p_worked_bank_item_ids
      union all
      select p_faixa_arrival_bank_item_ids
      union all
      select p_displaced_arrival_bank_item_ids
    ) as list_row
    cross join lateral pg_catalog.jsonb_array_elements(list_row.payload)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or pg_catalog.btrim(raw_row.value #>> '{}') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    raise exception 'matchday-live-layout-physical-v13-invalid-bank-item-list';
  end if;

  if exists (
    select 1
    from (
      select p_explicit_bank_item_ids as payload
      union all
      select p_displaced_bank_item_ids
      union all
      select p_worked_bank_item_ids
    ) as list_row
    cross join lateral (
      select
        pg_catalog.count(*) as item_count,
        pg_catalog.count(distinct normalized_row.bank_item_id) as unique_count
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        list_row.payload
      ) as normalized_row
    ) as count_row
    where count_row.item_count <> count_row.unique_count
  ) then
    raise exception 'matchday-live-layout-physical-v13-duplicate-state-list';
  end if;

  if exists (
    select 1
    from (
      select p_faixa_arrival_bank_item_ids as payload
      union all
      select p_displaced_arrival_bank_item_ids
    ) as list_row
    cross join lateral (
      select
        pg_catalog.count(*) as item_count,
        pg_catalog.count(distinct normalized_row.bank_item_id) as unique_count
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        list_row.payload
      ) as normalized_row
    ) as count_row
    where count_row.item_count <> count_row.unique_count
  ) then
    raise exception 'matchday-live-layout-physical-v13-duplicate-events';
  end if;

  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-live-layout-physical-v13-matchday-not-found';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as desk_row
    where desk_row.matchday_id = p_matchday_id
      and desk_row.is_managed = true
  ) then
    raise exception 'matchday-live-layout-physical-v13-matchday-not-live';
  end if;

  select assignment_row.profile_key
  into v_assignment_profile_key
  from public.matchday_editorial_profile_assignments as assignment_row
  where assignment_row.matchday_id = p_matchday_id;

  if v_assignment_profile_key is distinct from p_profile_key then
    raise exception 'matchday-live-layout-physical-v13-profile-mismatch';
  end if;

  select token_row.state_token
  into v_current_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  if v_current_state_token is distinct from p_expected_state_token then
    raise exception 'matchday-live-layout-physical-v13-concurrent-write';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_authoritative_placements
    ) as placement_row
    where placement_row.bank_item_id is null
      or placement_row.slot_position is null
      or placement_row.slot_position <= 0
      or not (
        (
          placement_row.placement_type = 'opening'
          and placement_row.zone_id is null
          and placement_row.slot_position between 1 and 5
        )
        or (
          placement_row.placement_type = 'faixa'
          and placement_row.zone_id is null
        )
        or (
          placement_row.placement_type = 'selection'
          and placement_row.zone_id is null
          and placement_row.slot_position between 1 and 4
        )
        or (
          placement_row.placement_type = 'video_highlight'
          and placement_row.zone_id is null
          and placement_row.slot_position = 1
        )
        or (
          placement_row.placement_type = 'zone'
          and placement_row.zone_id is not null
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v13-invalid-placement-target';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_authoritative_placements
    ) as placement_row
  ) <> (
    select pg_catalog.count(distinct placement_row.bank_item_id)
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_authoritative_placements
    ) as placement_row
  ) then
    raise exception 'matchday-live-layout-physical-v13-duplicate-bank-item';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_authoritative_placements
    ) as placement_row
    group by
      placement_row.placement_type,
      placement_row.zone_id,
      placement_row.slot_position
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-physical-v13-duplicate-target';
  end if;

  if exists (
    with requested as materialized (
      select placement_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_authoritative_placements
      ) as placement_row

      union

      select bank_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_explicit_bank_item_ids
      ) as bank_row

      union

      select displaced_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as displaced_row

      union

      select worked_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_worked_bank_item_ids
      ) as worked_row

      union

      select arrival_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_faixa_arrival_bank_item_ids
      ) as arrival_row

      union

      select arrival_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_arrival_bank_item_ids
      ) as arrival_row
    )
    select 1
    from requested as requested_row
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = requested_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
     and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.status, ''))) =
         'active'
    where bank_row.id is null
  ) then
    raise exception 'matchday-live-layout-physical-v13-bank-item-not-active';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = explicit_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) <>
          'editorial_article'
  ) then
    raise exception
      'matchday-live-layout-physical-v13-explicit-bank-source-unsupported';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_authoritative_placements
    ) as placement_row
    left join public.matchday_live_layout_zones as zone_row
      on zone_row.id = placement_row.zone_id
     and zone_row.matchday_id = p_matchday_id
    left join lateral (
      select pg_catalog.count(*) as block_count
      from public.matchday_live_layout_blocks as block_row
      where block_row.matchday_id = p_matchday_id
        and block_row.block_type = 'zone'
        and block_row.zone_id = placement_row.zone_id
    ) as block_state on true
    where placement_row.placement_type = 'zone'
      and (
        zone_row.id is null
        or block_state.block_count <> 1
        or jornada_private
             .matchday_live_layout_visual_family_capacity_v13(
               zone_row.visual_family
             ) is null
        or placement_row.slot_position > jornada_private
             .matchday_live_layout_visual_family_capacity_v13(
               zone_row.visual_family
             )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v13-zone-invalid';
  end if;

  if exists (
    select 1
    from (
      select
        pg_catalog.count(*) as item_count,
        pg_catalog.min(placement_row.slot_position) as min_position,
        pg_catalog.max(placement_row.slot_position) as max_position
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_authoritative_placements
      ) as placement_row
      where placement_row.placement_type = 'faixa'
    ) as faixa_state
    where faixa_state.item_count > 0
      and (
        faixa_state.min_position <> 1
        or faixa_state.max_position <> faixa_state.item_count
      )
  ) then
    raise exception 'matchday-live-layout-physical-v13-faixa-not-contiguous';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_authoritative_placements
    ) as placement_row
      on placement_row.bank_item_id = explicit_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v13-bank-placement-conflict';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    join jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_authoritative_placements
    ) as placement_row
      on placement_row.bank_item_id = displaced_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v13-displaced-placement-conflict';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    join jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
      on explicit_row.bank_item_id = displaced_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v13-displaced-bank-conflict';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as faixa_row
    join jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as displaced_row
      on displaced_row.bank_item_id = faixa_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v13-event-conflict';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as arrival_row
    where not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_authoritative_placements
      ) as placement_row
      where placement_row.bank_item_id = arrival_row.bank_item_id
        and placement_row.placement_type = 'faixa'
    )
      or exists (
        select 1
        from public.matchday_live_layout_placements as placement_row
        where placement_row.matchday_id = p_matchday_id
          and placement_row.bank_item_id = arrival_row.bank_item_id
          and placement_row.placement_type = 'faixa'
      )
  ) then
    raise exception 'matchday-live-layout-physical-v13-faixa-event-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_authoritative_placements
    ) as placement_row
    where placement_row.placement_type = 'faixa'
      and not exists (
        select 1
        from public.matchday_live_layout_placements as current_row
        where current_row.matchday_id = p_matchday_id
          and current_row.bank_item_id = placement_row.bank_item_id
          and current_row.placement_type = 'faixa'
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_faixa_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = placement_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v13-faixa-event-incomplete';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as arrival_row
    where not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as displaced_row
      where displaced_row.bank_item_id = arrival_row.bank_item_id
    )
      or exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = arrival_row.bank_item_id
          and memory_row.memory_kind = 'displaced'
      )
  ) then
    raise exception 'matchday-live-layout-physical-v13-displaced-event-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    where not exists (
      select 1
      from public.matchday_live_layout_bank_item_state_memory as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.bank_item_id = displaced_row.bank_item_id
        and memory_row.memory_kind = 'displaced'
    )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = displaced_row.bank_item_id
      )
  ) then
    raise exception
      'matchday-live-layout-physical-v13-displaced-event-incomplete';
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', placement_row.id,
        'bank_item_id', placement_row.bank_item_id,
        'placement_type', placement_row.placement_type,
        'zone_id', placement_row.zone_id,
        'slot_position', placement_row.slot_position,
        'created_at', placement_row.created_at,
        'updated_at', placement_row.updated_at
      )
      order by placement_row.id
    ),
    '[]'::jsonb
  )
  into v_placements_before
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'bank_item_id', placement_row.bank_item_id,
        'created_at', placement_row.created_at
      )
      order by placement_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_faixa_before
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa';

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'bank_item_id', memory_row.bank_item_id,
        'recorded_at', memory_row.recorded_at
      )
      order by memory_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_displaced_before
  from public.matchday_live_layout_bank_item_state_memory as memory_row
  where memory_row.matchday_id = p_matchday_id
    and memory_row.memory_kind = 'displaced';

  select pg_catalog.md5(coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', bank_row.id,
        'automatic_eligible', bank_row.automatic_eligible,
        'classification_key', bank_row.classification_key,
        'classification_source', bank_row.classification_source,
        'classified_at', bank_row.classified_at
      )
      order by bank_row.id
    ),
    '[]'::jsonb
  )::text)
  into v_classification_before
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.matchday_id = p_matchday_id;

  delete from public.matchday_editorial_profile_manual_overrides
    as override_row
  where override_row.matchday_id = p_matchday_id
    and override_row.profile_key = p_profile_key
    and override_row.placement_target = 'bank'
    and not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_explicit_bank_item_ids
      ) as explicit_row
      join public.matchday_editorial_bank_items as bank_row
        on bank_row.id = explicit_row.bank_item_id
       and bank_row.matchday_id = p_matchday_id
      where pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
            pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
        and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
            pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
    );

  update public.matchday_editorial_profile_manual_overrides as override_row
  set placement_target = 'bank',
      zone_key = null,
      sort_order = null,
      updated_at = pg_catalog.statement_timestamp()
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
         p_explicit_bank_item_ids
       ) as explicit_row
  join public.matchday_editorial_bank_items as bank_row
    on bank_row.id = explicit_row.bank_item_id
   and bank_row.matchday_id = p_matchday_id
  where override_row.matchday_id = p_matchday_id
    and override_row.profile_key = p_profile_key
    and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
    and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
    and (
      override_row.placement_target is distinct from 'bank'
      or override_row.zone_key is not null
      or override_row.sort_order is not null
    );

  insert into public.matchday_editorial_profile_manual_overrides (
    matchday_id,
    profile_key,
    source_type,
    source_id,
    placement_target,
    zone_key,
    sort_order
  )
  select
    p_matchday_id,
    p_profile_key,
    pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)),
    pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)),
    'bank',
    null,
    null
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_explicit_bank_item_ids
  ) as explicit_row
  join public.matchday_editorial_bank_items as bank_row
    on bank_row.id = explicit_row.bank_item_id
   and bank_row.matchday_id = p_matchday_id
  where not exists (
    select 1
    from public.matchday_editorial_profile_manual_overrides as override_row
    where override_row.matchday_id = p_matchday_id
      and override_row.profile_key = p_profile_key
      and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
          pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
      and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
          pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
  )
  order by explicit_row.operation_order;

  with desired as materialized (
    select *
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_authoritative_placements
    )
  ),
  clear_operations as (
    select
      0 as phase,
      current_row.placement_type,
      current_row.zone_id,
      current_row.slot_position,
      current_row.bank_item_id,
      pg_catalog.jsonb_build_object(
        'action', 'clear',
        'bank_item_id', null,
        'placement_type', current_row.placement_type,
        'zone_id', current_row.zone_id,
        'slot_position', current_row.slot_position
      ) as payload
    from public.matchday_live_layout_placements as current_row
    where current_row.matchday_id = p_matchday_id
      and not exists (
        select 1
        from desired as desired_row
        where desired_row.bank_item_id = current_row.bank_item_id
          and desired_row.placement_type = current_row.placement_type
          and desired_row.zone_id is not distinct from current_row.zone_id
          and desired_row.slot_position = current_row.slot_position
      )
      and not exists (
        select 1
        from desired as desired_row
        where desired_row.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from desired as desired_row
        where desired_row.placement_type = current_row.placement_type
          and desired_row.zone_id is not distinct from current_row.zone_id
          and desired_row.slot_position = current_row.slot_position
      )
  ),
  place_operations as (
    select
      1 as phase,
      desired_row.placement_type,
      desired_row.zone_id,
      desired_row.slot_position,
      desired_row.bank_item_id,
      pg_catalog.jsonb_build_object(
        'action', 'place',
        'bank_item_id', desired_row.bank_item_id,
        'placement_type', desired_row.placement_type,
        'zone_id', desired_row.zone_id,
        'slot_position', desired_row.slot_position
      ) as payload
    from desired as desired_row
    where not exists (
      select 1
      from public.matchday_live_layout_placements as current_row
      where current_row.matchday_id = p_matchday_id
        and current_row.bank_item_id = desired_row.bank_item_id
        and current_row.placement_type = desired_row.placement_type
        and current_row.zone_id is not distinct from desired_row.zone_id
        and current_row.slot_position = desired_row.slot_position
    )
  ),
  operations as (
    select * from clear_operations
    union all
    select * from place_operations
  )
  select coalesce(
    pg_catalog.jsonb_agg(
      operation_row.payload
      order by
        operation_row.phase,
        operation_row.placement_type,
        operation_row.zone_id nulls first,
        operation_row.slot_position,
        operation_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_plan
  from operations as operation_row;

  perform jornada_private.apply_matchday_live_layout_placement_plan(
    p_matchday_id,
    v_plan,
    false
  );

  with previous as materialized (
    select
      previous_row.bank_item_id,
      previous_row.created_at
    from pg_catalog.jsonb_to_recordset(v_faixa_before) as previous_row(
      bank_item_id uuid,
      created_at timestamptz
    )
  )
  update public.matchday_live_layout_placements as placement_row
  set created_at = previous.created_at
  from previous
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa'
    and placement_row.bank_item_id = previous.bank_item_id
    and placement_row.created_at is distinct from previous.created_at
    and not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_faixa_arrival_bank_item_ids
      ) as arrival_row
      where arrival_row.bank_item_id = placement_row.bank_item_id
    );

  v_faixa_anchor := pg_catalog.clock_timestamp();

  update public.matchday_live_layout_placements as placement_row
  set created_at = v_faixa_anchor
      - ((arrival_row.operation_order - 1) * interval '1 microsecond')
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_faixa_arrival_bank_item_ids
  ) as arrival_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa'
    and placement_row.bank_item_id = arrival_row.bank_item_id;

  delete from public.matchday_live_layout_bank_item_state_memory as memory_row
  where memory_row.matchday_id = p_matchday_id
    and (
      exists (
        select 1
        from public.matchday_live_layout_placements as placement_row
        where placement_row.matchday_id = p_matchday_id
          and placement_row.bank_item_id = memory_row.bank_item_id
      )
      or exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_explicit_bank_item_ids
        ) as explicit_row
        where explicit_row.bank_item_id = memory_row.bank_item_id
      )
      or (
        memory_row.memory_kind = 'displaced'
        and not exists (
          select 1
          from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
            p_displaced_bank_item_ids
          ) as displaced_row
          where displaced_row.bank_item_id = memory_row.bank_item_id
        )
      )
    );

  insert into public.matchday_live_layout_bank_item_state_memory
    as memory_row (
      matchday_id,
      bank_item_id,
      memory_kind,
      recorded_at
    )
  select
    p_matchday_id,
    displaced_row.bank_item_id,
    'displaced',
    pg_catalog.statement_timestamp()
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_displaced_bank_item_ids
  ) as displaced_row
  on conflict (matchday_id, bank_item_id)
  do update
  set memory_kind = 'displaced',
      recorded_at = excluded.recorded_at
  where memory_row.memory_kind is distinct from 'displaced';

  v_displaced_anchor := pg_catalog.clock_timestamp();

  update public.matchday_live_layout_bank_item_state_memory as memory_row
  set memory_kind = 'displaced',
      recorded_at = v_displaced_anchor
        - ((arrival_row.operation_order - 1) * interval '1 microsecond')
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_displaced_arrival_bank_item_ids
  ) as arrival_row
  where memory_row.matchday_id = p_matchday_id
    and memory_row.bank_item_id = arrival_row.bank_item_id;

  update public.matchday_editorial_bank_items as bank_row
  set editorially_worked_at = pg_catalog.statement_timestamp()
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_worked_bank_item_ids
  ) as worked_row
  where bank_row.matchday_id = p_matchday_id
    and bank_row.id = worked_row.bank_item_id
    and bank_row.editorially_worked_at is null;

  if exists (
    with desired as materialized (
      select
        placement_row.bank_item_id,
        placement_row.placement_type,
        placement_row.zone_id,
        placement_row.slot_position
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_authoritative_placements
      ) as placement_row
    ),
    current_state as materialized (
      select
        placement_row.bank_item_id,
        placement_row.placement_type,
        placement_row.zone_id,
        placement_row.slot_position
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
    ),
    differences as (
      (
        select * from current_state
        except
        select * from desired
      )
      union all
      (
        select * from desired
        except
        select * from current_state
      )
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v13-placement-postcondition';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_matchday_id
    group by placement_row.bank_item_id
    having pg_catalog.count(*) > 1
  ) then
    raise exception
      'matchday-live-layout-physical-v13-transversal-postcondition';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_matchday_id
    group by
      placement_row.placement_type,
      placement_row.zone_id,
      placement_row.slot_position
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-physical-v13-target-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select displaced_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as displaced_row
    ),
    current_state as materialized (
      select memory_row.bank_item_id
      from public.matchday_live_layout_bank_item_state_memory as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.memory_kind = 'displaced'
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v13-displaced-postcondition';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    where exists (
      select 1
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.bank_item_id = displaced_row.bank_item_id
    )
      or exists (
        select 1
        from public.matchday_editorial_profile_manual_overrides as override_row
        join public.matchday_editorial_bank_items as bank_row
          on bank_row.matchday_id = p_matchday_id
         and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) =
             pg_catalog.lower(pg_catalog.btrim(override_row.source_type))
         and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) =
             pg_catalog.lower(pg_catalog.btrim(override_row.source_id))
        where override_row.matchday_id = p_matchday_id
          and override_row.profile_key = p_profile_key
          and override_row.placement_target = 'bank'
          and bank_row.id = displaced_row.bank_item_id
      )
  ) then
    raise exception
      'matchday-live-layout-physical-v13-displaced-conflict-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select explicit_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_explicit_bank_item_ids
      ) as explicit_row
    ),
    current_state as materialized (
      select bank_row.id as bank_item_id
      from public.matchday_editorial_profile_manual_overrides as override_row
      join public.matchday_editorial_bank_items as bank_row
        on bank_row.matchday_id = p_matchday_id
       and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) =
           pg_catalog.lower(pg_catalog.btrim(override_row.source_type))
       and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) =
           pg_catalog.lower(pg_catalog.btrim(override_row.source_id))
      where override_row.matchday_id = p_matchday_id
        and override_row.profile_key = p_profile_key
        and override_row.placement_target = 'bank'
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v13-bank-postcondition';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    where exists (
      select 1
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.bank_item_id = explicit_row.bank_item_id
    )
      or exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = explicit_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v13-bank-conflict-postcondition';
  end if;

  if exists (
    select 1
    from (
      select
        pg_catalog.count(*) as item_count,
        pg_catalog.min(placement_row.slot_position) as min_position,
        pg_catalog.max(placement_row.slot_position) as max_position
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.placement_type = 'faixa'
    ) as faixa_state
    where faixa_state.item_count > 0
      and (
        faixa_state.min_position <> 1
        or faixa_state.max_position <> faixa_state.item_count
      )
  ) then
    raise exception
      'matchday-live-layout-physical-v13-faixa-postcondition';
  end if;

  if (
    select pg_catalog.count(*)
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'selection'
  ) > 4 or (
    select pg_catalog.count(*)
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'opening'
  ) > 5 or (
    select pg_catalog.count(*)
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'video_highlight'
  ) > 1 then
    raise exception
      'matchday-live-layout-physical-v13-fixed-capacity-postcondition';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    left join public.matchday_live_layout_zones as zone_row
      on zone_row.id = placement_row.zone_id
     and zone_row.matchday_id = placement_row.matchday_id
    left join lateral (
      select pg_catalog.count(*) as block_count
      from public.matchday_live_layout_blocks as block_row
      where block_row.matchday_id = placement_row.matchday_id
        and block_row.block_type = 'zone'
        and block_row.zone_id = placement_row.zone_id
    ) as block_state on true
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'zone'
      and (
        zone_row.id is null
        or block_state.block_count <> 1
        or jornada_private
             .matchday_live_layout_visual_family_capacity_v13(
               zone_row.visual_family
             ) is null
        or placement_row.slot_position > jornada_private
             .matchday_live_layout_visual_family_capacity_v13(
               zone_row.visual_family
             )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v13-zone-postcondition';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_to_recordset(v_placements_before) as previous_row(
      id uuid,
      bank_item_id uuid,
      placement_type text,
      zone_id uuid,
      slot_position integer,
      created_at timestamptz,
      updated_at timestamptz
    )
    join public.matchday_live_layout_placements as placement_row
      on placement_row.matchday_id = p_matchday_id
     and placement_row.bank_item_id = previous_row.bank_item_id
     and placement_row.placement_type = previous_row.placement_type
     and placement_row.zone_id is not distinct from previous_row.zone_id
     and placement_row.slot_position = previous_row.slot_position
    where placement_row.id is distinct from previous_row.id
      or placement_row.created_at is distinct from previous_row.created_at
      or placement_row.updated_at is distinct from previous_row.updated_at
  ) then
    raise exception
      'matchday-live-layout-physical-v13-unchanged-clock-postcondition';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_to_recordset(v_displaced_before) as previous_row(
      bank_item_id uuid,
      recorded_at timestamptz
    )
    join public.matchday_live_layout_bank_item_state_memory as memory_row
      on memory_row.matchday_id = p_matchday_id
     and memory_row.bank_item_id = previous_row.bank_item_id
     and memory_row.memory_kind = 'displaced'
    where memory_row.recorded_at is distinct from previous_row.recorded_at
  ) then
    raise exception
      'matchday-live-layout-physical-v13-displaced-clock-postcondition';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as arrival_row
    left join public.matchday_live_layout_placements as placement_row
      on placement_row.matchday_id = p_matchday_id
     and placement_row.bank_item_id = arrival_row.bank_item_id
     and placement_row.placement_type = 'faixa'
    where placement_row.id is null
      or placement_row.created_at is distinct from
         v_faixa_anchor
         - ((arrival_row.operation_order - 1) * interval '1 microsecond')
  ) then
    raise exception
      'matchday-live-layout-physical-v13-faixa-clock-postcondition';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as arrival_row
    left join public.matchday_live_layout_bank_item_state_memory as memory_row
      on memory_row.matchday_id = p_matchday_id
     and memory_row.bank_item_id = arrival_row.bank_item_id
     and memory_row.memory_kind = 'displaced'
    where memory_row.bank_item_id is null
      or memory_row.recorded_at is distinct from
         v_displaced_anchor
         - ((arrival_row.operation_order - 1) * interval '1 microsecond')
  ) then
    raise exception
      'matchday-live-layout-physical-v13-displaced-clock-postcondition';
  end if;

  if v_classification_before is distinct from (
    select pg_catalog.md5(coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', bank_row.id,
          'automatic_eligible', bank_row.automatic_eligible,
          'classification_key', bank_row.classification_key,
          'classification_source', bank_row.classification_source,
          'classified_at', bank_row.classified_at
        )
        order by bank_row.id
      ),
      '[]'::jsonb
    )::text)
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_matchday_id
  ) then
    raise exception
      'matchday-live-layout-physical-v13-classification-changed';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_worked_bank_item_ids
    ) as worked_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = worked_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where bank_row.editorially_worked_at is null
  ) then
    raise exception 'matchday-live-layout-physical-v13-worked-postcondition';
  end if;

  select token_row.state_token
  into v_final_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  return query
  select
    v_final_state_token,
    pg_catalog.jsonb_array_length(p_authoritative_placements),
    pg_catalog.jsonb_array_length(p_explicit_bank_item_ids),
    pg_catalog.jsonb_array_length(p_displaced_bank_item_ids),
    pg_catalog.jsonb_array_length(p_worked_bank_item_ids);
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.apply_matchday_live_layout_physical_workspace_v14_core(p_matchday_id uuid, p_profile_key text, p_expected_physical_state_token text, p_zones jsonb, p_blocks jsonb, p_placements jsonb, p_faixa_slot_count integer, p_explicit_bank_item_ids jsonb, p_displaced_bank_item_ids jsonb, p_worked_bank_item_ids jsonb, p_faixa_arrival_bank_item_ids jsonb, p_displaced_arrival_bank_item_ids jsonb, p_presentation jsonb)
 RETURNS TABLE(state_token text, applied_zone_count integer, applied_block_count integer, applied_placement_count integer, explicit_bank_item_count integer, displaced_bank_item_count integer, worked_bank_item_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_assignment_profile_key text;
  v_current_state_token text;
  v_final_state_token text;
  v_plan jsonb := '[]'::jsonb;
  v_placements_before jsonb := '[]'::jsonb;
  v_faixa_before jsonb := '[]'::jsonb;
  v_displaced_before jsonb := '[]'::jsonb;
  v_zones_before jsonb := '[]'::jsonb;
  v_blocks_before jsonb := '[]'::jsonb;
  v_settings_before jsonb := 'null'::jsonb;
  v_classification_before text;
  v_faixa_anchor timestamptz;
  v_displaced_anchor timestamptz;
  v_block_offset integer;
  v_had_cutover boolean;
  v_had_settings boolean;
begin
  -- Envelope validation is deliberately before locks. It performs no DML and
  -- does not attempt to repair or normalize a malformed request.
  if p_matchday_id is null
    or p_profile_key is null
    or pg_catalog.btrim(p_profile_key) = ''
    or p_expected_physical_state_token is null
    or pg_catalog.btrim(p_expected_physical_state_token) = ''
    or pg_catalog.btrim(p_expected_physical_state_token) !~
       '^[0-9a-f]{32}$'
    or p_zones is null
    or pg_catalog.jsonb_typeof(p_zones) <> 'array'
    or p_blocks is null
    or pg_catalog.jsonb_typeof(p_blocks) <> 'array'
    or p_placements is null
    or pg_catalog.jsonb_typeof(p_placements) <> 'array'
    or p_faixa_slot_count is null
    or p_faixa_slot_count < 0
    or p_explicit_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_explicit_bank_item_ids) <> 'array'
    or p_displaced_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_bank_item_ids) <> 'array'
    or p_worked_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_worked_bank_item_ids) <> 'array'
    or p_faixa_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_faixa_arrival_bank_item_ids) <> 'array'
    or p_displaced_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_arrival_bank_item_ids) <> 'array'
    or p_presentation is null
    or pg_catalog.jsonb_typeof(p_presentation) <> 'object'
  then
    raise exception 'matchday-live-layout-physical-v14-invalid-input';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zones) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
      or (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
      ) <> 3
      or not raw_row.payload ?& array[
        'id', 'public_title', 'visual_family'
      ]
  ) then
    raise exception 'matchday-live-layout-physical-v14-zone-shape-invalid';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_blocks) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
      or (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
      ) <> 4
      or not raw_row.payload ?& array[
        'id', 'block_type', 'zone_id', 'sort_order'
      ]
  ) then
    raise exception 'matchday-live-layout-physical-v14-block-shape-invalid';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_placements) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
      or (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
      ) <> 4
      or not raw_row.payload ?& array[
        'bank_item_id', 'placement_type', 'zone_id', 'slot_position'
      ]
  ) then
    raise exception 'matchday-live-layout-physical-v14-placement-shape-invalid';
  end if;

  if not p_presentation ?& array[
    'headline_title_color',
    'latest_zone_placement',
    'latest_zone_title',
    'video_module_active'
  ] or (
    p_presentation - array[
      'headline_title_color',
      'latest_zone_placement',
      'latest_zone_title',
      'video_module_active'
    ]::text[]
  ) <> '{}'::jsonb
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'headline_title_color'
    ) not in ('null', 'string')
    or (
      pg_catalog.jsonb_typeof(
        p_presentation -> 'headline_title_color'
      ) = 'string'
      and pg_catalog.btrim(
        p_presentation ->> 'headline_title_color'
      ) !~ '^#[0-9A-Fa-f]{6}$'
    )
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'latest_zone_placement'
    ) <> 'string'
    or p_presentation ->> 'latest_zone_placement' not in (
      'top', 'four_news', 'hidden'
    )
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'latest_zone_title'
    ) <> 'string'
    or pg_catalog.char_length(
      pg_catalog.btrim(p_presentation ->> 'latest_zone_title')
    ) > 120
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'video_module_active'
    ) <> 'boolean'
  then
    raise exception 'matchday-live-layout-physical-v14-presentation-invalid';
  end if;

  if exists (
    select 1
    from (
      select p_explicit_bank_item_ids as payload
      union all select p_displaced_bank_item_ids
      union all select p_worked_bank_item_ids
      union all select p_faixa_arrival_bank_item_ids
      union all select p_displaced_arrival_bank_item_ids
    ) as list_row
    cross join lateral pg_catalog.jsonb_array_elements(list_row.payload)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or pg_catalog.btrim(raw_row.value #>> '{}') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    raise exception 'matchday-live-layout-physical-v14-bank-list-invalid';
  end if;

  -- Lock order is the same as existing physical/legacy entrypoints. The
  -- external token is checked after both locks and before the first DML.
  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-live-layout-physical-v14-matchday-not-found';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as desk_row
    where desk_row.matchday_id = p_matchday_id
      and desk_row.is_managed = true
  ) then
    raise exception 'matchday-live-layout-physical-v14-matchday-not-live';
  end if;

  select assignment_row.profile_key
  into v_assignment_profile_key
  from public.matchday_editorial_profile_assignments as assignment_row
  where assignment_row.matchday_id = p_matchday_id;

  if v_assignment_profile_key is distinct from p_profile_key then
    raise exception 'matchday-live-layout-physical-v14-profile-mismatch';
  end if;

  select token_row.state_token
  into v_current_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  if v_current_state_token is distinct from
     p_expected_physical_state_token
  then
    raise exception 'matchday-live-layout-physical-v14-concurrent-write';
  end if;

  -- Everything below this point and above the marker insert remains read-only.
  select exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = p_matchday_id
  ) into v_had_cutover;

  select exists (
    select 1
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
  ) into v_had_settings;

  if v_had_cutover is distinct from v_had_settings then
    raise exception 'matchday-live-layout-physical-v14-authority-state-corrupt';
  end if;

  if v_had_cutover and exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = p_matchday_id
      and cutover_row.profile_key is distinct from p_profile_key
  ) then
    raise exception 'matchday-live-layout-physical-v14-cutover-profile-mismatch';
  end if;

  perform jornada_private.validate_matchday_live_layout_legacy_projection_v14(
    p_matchday_id,
    p_profile_key
  );

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
    where zone_row.zone_id is null
      or zone_row.public_title is null
      or zone_row.public_title = ''
      or pg_catalog.char_length(zone_row.public_title) > 120
      or zone_row.visual_family not in (
        'six_news', 'five_news_balanced', 'five_news_secondary'
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-zone-value-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
  ) <> (
    select pg_catalog.count(distinct zone_row.zone_id)
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
  ) then
    raise exception 'matchday-live-layout-physical-v14-zone-duplicate';
  end if;

  if exists (
    (
      select zone_row.id
      from public.matchday_live_layout_zones as zone_row
      where zone_row.matchday_id = p_matchday_id
      except
      select desired_row.zone_id
      from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
        as desired_row
    )
    union all
    (
      select desired_row.zone_id
      from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
        as desired_row
      except
      select zone_row.id
      from public.matchday_live_layout_zones as zone_row
      where zone_row.matchday_id = p_matchday_id
    )
  ) then
    raise exception 'matchday-live-layout-physical-v14-zone-set-mismatch';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_id is null
      or block_row.block_type not in ('zone', 'latest', 'video')
      or block_row.sort_order is null
      or block_row.sort_order <= 0
      or block_row.sort_order > 1000000000
      or not (
        (block_row.block_type = 'zone' and block_row.zone_id is not null)
        or (
          block_row.block_type in ('latest', 'video')
          and block_row.zone_id is null
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-block-value-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
  ) <> (
    select pg_catalog.count(distinct block_row.block_id)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    group by block_row.sort_order
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-physical-v14-block-duplicate';
  end if;

  if exists (
    (
      select block_row.id
      from public.matchday_live_layout_blocks as block_row
      where block_row.matchday_id = p_matchday_id
      except
      select desired_row.block_id
      from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
        as desired_row
    )
    union all
    (
      select desired_row.block_id
      from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
        as desired_row
      except
      select block_row.id
      from public.matchday_live_layout_blocks as block_row
      where block_row.matchday_id = p_matchday_id
    )
  ) then
    raise exception 'matchday-live-layout-physical-v14-block-set-mismatch';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as desired_row
    join public.matchday_live_layout_blocks as current_row
      on current_row.id = desired_row.block_id
     and current_row.matchday_id = p_matchday_id
    where current_row.block_type is distinct from desired_row.block_type
      or current_row.zone_id is distinct from desired_row.zone_id
  ) then
    raise exception 'matchday-live-layout-physical-v14-block-identity-mismatch';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
    where (
      select pg_catalog.count(*)
      from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
        as block_row
      where block_row.block_type = 'zone'
        and block_row.zone_id = zone_row.zone_id
    ) <> 1
  ) or (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'latest'
  ) <> 1 or (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'video'
  ) > 1 then
    raise exception 'matchday-live-layout-physical-v14-block-topology-invalid';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_placements) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload -> 'bank_item_id') <> 'string'
      or pg_catalog.btrim(raw_row.payload ->> 'bank_item_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or pg_catalog.jsonb_typeof(raw_row.payload -> 'placement_type') <>
         'string'
      or pg_catalog.lower(
           pg_catalog.btrim(raw_row.payload ->> 'placement_type')
         ) not in ('opening', 'faixa', 'selection', 'video_highlight', 'zone')
      or pg_catalog.jsonb_typeof(raw_row.payload -> 'slot_position') <>
         'number'
      or raw_row.payload ->> 'slot_position' !~ '^[0-9]+$'
      or (raw_row.payload ->> 'slot_position')::numeric > 2147483647
      or not (
        (
          pg_catalog.lower(
            pg_catalog.btrim(raw_row.payload ->> 'placement_type')
          ) = 'zone'
          and pg_catalog.jsonb_typeof(raw_row.payload -> 'zone_id') =
              'string'
          and pg_catalog.btrim(raw_row.payload ->> 'zone_id') ~*
              '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        )
        or (
          pg_catalog.lower(
            pg_catalog.btrim(raw_row.payload ->> 'placement_type')
          ) <> 'zone'
          and pg_catalog.jsonb_typeof(raw_row.payload -> 'zone_id') = 'null'
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-placement-value-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    where placement_row.bank_item_id is null
      or placement_row.slot_position is null
      or placement_row.slot_position <= 0
      or not (
        (
          placement_row.placement_type = 'opening'
          and placement_row.zone_id is null
          and placement_row.slot_position between 1 and 5
        )
        or (
          placement_row.placement_type = 'faixa'
          and placement_row.zone_id is null
          and placement_row.slot_position <= p_faixa_slot_count
        )
        or (
          placement_row.placement_type = 'selection'
          and placement_row.zone_id is null
          and placement_row.slot_position between 1 and 4
        )
        or (
          placement_row.placement_type = 'video_highlight'
          and placement_row.zone_id is null
          and placement_row.slot_position = 1
        )
        or (
          placement_row.placement_type = 'zone'
          and placement_row.zone_id is not null
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-placement-target-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    )
  ) <> (
    select pg_catalog.count(distinct placement_row.bank_item_id)
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    group by
      placement_row.placement_type,
      placement_row.zone_id,
      placement_row.slot_position
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-physical-v14-placement-duplicate';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
      on zone_row.zone_id = placement_row.zone_id
    where placement_row.placement_type = 'zone'
      and placement_row.slot_position > jornada_private
          .matchday_live_layout_visual_family_capacity_v13(
            zone_row.visual_family
          )
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    where placement_row.placement_type = 'zone'
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
          as zone_row
        where zone_row.zone_id = placement_row.zone_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-zone-capacity-invalid';
  end if;

  if not (p_presentation ->> 'video_module_active')::boolean
    and exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as placement_row
      where placement_row.placement_type = 'video_highlight'
    )
  then
    raise exception 'matchday-live-layout-physical-v14-video-state-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    where placement_row.placement_type = 'video_highlight'
  ) and not exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'video'
  ) then
    raise exception 'matchday-live-layout-physical-v14-video-block-missing';
  end if;

  if exists (
    select 1
    from (
      select p_explicit_bank_item_ids as payload
      union all select p_displaced_bank_item_ids
      union all select p_worked_bank_item_ids
      union all select p_faixa_arrival_bank_item_ids
      union all select p_displaced_arrival_bank_item_ids
    ) as list_row
    cross join lateral (
      select
        pg_catalog.count(*) as item_count,
        pg_catalog.count(distinct normalized_row.bank_item_id) as unique_count
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        list_row.payload
      ) as normalized_row
    ) as count_row
    where count_row.item_count <> count_row.unique_count
  ) then
    raise exception 'matchday-live-layout-physical-v14-bank-list-duplicate';
  end if;

  if exists (
    with requested as materialized (
      select placement_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as placement_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_explicit_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_worked_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_faixa_arrival_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_arrival_bank_item_ids
      ) as list_row
    )
    select 1
    from requested as requested_row
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = requested_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
     and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.status, ''))) =
         'active'
    where bank_row.id is null
  ) then
    raise exception 'matchday-live-layout-physical-v14-bank-item-not-active';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = explicit_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) <>
          'editorial_article'
  ) then
    raise exception 'matchday-live-layout-physical-v14-explicit-bank-unsupported';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as state_row
    join jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
      on placement_row.bank_item_id = state_row.bank_item_id
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as state_row
    join jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
      on placement_row.bank_item_id = state_row.bank_item_id
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
      on displaced_row.bank_item_id = explicit_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v14-state-conflict';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as current_row
    where current_row.matchday_id = p_matchday_id
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
          p_placements
        ) as desired_row
        where desired_row.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_explicit_bank_item_ids
        ) as explicit_row
        where explicit_row.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_bank_item_ids
        ) as displaced_row
        where displaced_row.bank_item_id = current_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-removed-item-state-missing';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_matchday_id
      and bank_row.editorially_worked_at is not null
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_worked_bank_item_ids
        ) as worked_row
        where worked_row.bank_item_id = bank_row.id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-worked-regression';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as faixa_row
    join jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as displaced_row
      on displaced_row.bank_item_id = faixa_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v14-event-conflict';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as arrival_row
    where not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as desired_row
      where desired_row.bank_item_id = arrival_row.bank_item_id
        and desired_row.placement_type = 'faixa'
    )
      or exists (
        select 1
        from public.matchday_live_layout_placements as current_row
        where current_row.matchday_id = p_matchday_id
          and current_row.bank_item_id = arrival_row.bank_item_id
          and current_row.placement_type = 'faixa'
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-faixa-event-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as desired_row
    where desired_row.placement_type = 'faixa'
      and not exists (
        select 1
        from public.matchday_live_layout_placements as current_row
        where current_row.matchday_id = p_matchday_id
          and current_row.bank_item_id = desired_row.bank_item_id
          and current_row.placement_type = 'faixa'
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_faixa_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = desired_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-faixa-event-incomplete';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as arrival_row
    where not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as displaced_row
      where displaced_row.bank_item_id = arrival_row.bank_item_id
    )
      or exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = arrival_row.bank_item_id
          and memory_row.memory_kind = 'displaced'
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-displaced-event-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    where not exists (
      select 1
      from public.matchday_live_layout_bank_item_state_memory as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.bank_item_id = displaced_row.bank_item_id
        and memory_row.memory_kind = 'displaced'
    )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = displaced_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-displaced-event-incomplete';
  end if;

  -- The downstream compatibility rows must be constructible before authority
  -- is marked. Extra-zone placements are intentionally excluded here.
  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where placement_row.placement_type in (
      'opening', 'faixa', 'video_highlight'
    )
      and nullif(pg_catalog.btrim(bank_row.link_url), '') is null
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where placement_row.placement_type = 'selection'
      and (
        nullif(pg_catalog.btrim(bank_row.source_type), '') is null
        or nullif(pg_catalog.btrim(bank_row.source_id), '') is null
      )
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join jornada_private.matchday_live_layout_zone_legacy_projection
      as projection_row
      on projection_row.matchday_id = p_matchday_id
     and projection_row.zone_id = placement_row.zone_id
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where placement_row.placement_type = 'zone'
      and (
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) <>
          'editorial_article'
        or nullif(pg_catalog.btrim(bank_row.source_id), '') is null
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-downstream-input-invalid';
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', placement_row.id,
        'bank_item_id', placement_row.bank_item_id,
        'placement_type', placement_row.placement_type,
        'zone_id', placement_row.zone_id,
        'slot_position', placement_row.slot_position,
        'created_at', placement_row.created_at,
        'updated_at', placement_row.updated_at
      ) order by placement_row.id
    ),
    '[]'::jsonb
  )
  into v_placements_before
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'bank_item_id', placement_row.bank_item_id,
        'created_at', placement_row.created_at
      ) order by placement_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_faixa_before
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa';

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'bank_item_id', memory_row.bank_item_id,
        'recorded_at', memory_row.recorded_at
      ) order by memory_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_displaced_before
  from public.matchday_live_layout_bank_item_state_memory as memory_row
  where memory_row.matchday_id = p_matchday_id
    and memory_row.memory_kind = 'displaced';

  select coalesce(
    pg_catalog.jsonb_agg(pg_catalog.to_jsonb(zone_row) order by zone_row.id),
    '[]'::jsonb
  )
  into v_zones_before
  from public.matchday_live_layout_zones as zone_row
  where zone_row.matchday_id = p_matchday_id;

  select coalesce(
    pg_catalog.jsonb_agg(pg_catalog.to_jsonb(block_row) order by block_row.id),
    '[]'::jsonb
  )
  into v_blocks_before
  from public.matchday_live_layout_blocks as block_row
  where block_row.matchday_id = p_matchday_id;

  select coalesce(pg_catalog.to_jsonb(settings_row), 'null'::jsonb)
  into v_settings_before
  from public.matchday_live_layout_workspace_settings as settings_row
  where settings_row.matchday_id = p_matchday_id;

  select pg_catalog.md5(coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', bank_row.id,
        'automatic_eligible', bank_row.automatic_eligible,
        'classification_key', bank_row.classification_key,
        'classification_source', bank_row.classification_source,
        'classified_at', bank_row.classified_at
      ) order by bank_row.id
    ),
    '[]'::jsonb
  )::text)
  into v_classification_before
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.matchday_id = p_matchday_id;

  if exists (
    select 1
    from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = p_matchday_id
      and block_row.sort_order > 1000000000
  ) then
    raise exception 'matchday-live-layout-physical-v14-current-block-order-invalid';
  end if;

  -- FIRST DML: authority is marked only after the complete validation above.
  insert into jornada_private.matchday_live_layout_physical_cutovers (
    matchday_id,
    profile_key
  ) values (
    p_matchday_id,
    p_profile_key
  )
  on conflict (matchday_id) do nothing;

  insert into public.matchday_live_layout_workspace_settings as settings_row (
    matchday_id,
    faixa_slot_count,
    headline_title_color,
    latest_zone_placement,
    latest_zone_title,
    video_module_active
  ) values (
    p_matchday_id,
    p_faixa_slot_count,
    case
      when pg_catalog.jsonb_typeof(
        p_presentation -> 'headline_title_color'
      ) = 'null' then null
      else pg_catalog.upper(pg_catalog.btrim(
        p_presentation ->> 'headline_title_color'
      ))
    end,
    p_presentation ->> 'latest_zone_placement',
    pg_catalog.btrim(p_presentation ->> 'latest_zone_title'),
    (p_presentation ->> 'video_module_active')::boolean
  )
  on conflict (matchday_id) do update
  set faixa_slot_count = excluded.faixa_slot_count,
      headline_title_color = excluded.headline_title_color,
      latest_zone_placement = excluded.latest_zone_placement,
      latest_zone_title = excluded.latest_zone_title,
      video_module_active = excluded.video_module_active,
      updated_at = pg_catalog.statement_timestamp()
  where (
    settings_row.faixa_slot_count,
    settings_row.headline_title_color,
    settings_row.latest_zone_placement,
    settings_row.latest_zone_title,
    settings_row.video_module_active
  ) is distinct from (
    excluded.faixa_slot_count,
    excluded.headline_title_color,
    excluded.latest_zone_placement,
    excluded.latest_zone_title,
    excluded.video_module_active
  );

  update public.matchday_live_layout_zones as zone_row
  set public_title = desired_row.public_title,
      visual_family = desired_row.visual_family,
      updated_at = pg_catalog.statement_timestamp()
  from jornada_private.normalize_matchday_live_layout_zones_v14(
    p_zones
  ) as desired_row
  where zone_row.matchday_id = p_matchday_id
    and zone_row.id = desired_row.zone_id
    and (
      zone_row.public_title,
      zone_row.visual_family
    ) is distinct from (
      desired_row.public_title,
      desired_row.visual_family
    );

  -- Move every order into a collision-free range before assigning the exact
  -- requested order. Rows whose final order did not change keep their clock.
  if exists (
    select 1
    from public.matchday_live_layout_blocks as block_row
    join jornada_private.normalize_matchday_live_layout_blocks_v14(
      p_blocks
    ) as desired_row
      on desired_row.block_id = block_row.id
    where block_row.matchday_id = p_matchday_id
      and block_row.sort_order is distinct from desired_row.sort_order
  ) then
    v_block_offset := 1100000000;

    update public.matchday_live_layout_blocks as block_row
    set sort_order = block_row.sort_order + v_block_offset
    where block_row.matchday_id = p_matchday_id;

    update public.matchday_live_layout_blocks as block_row
    set sort_order = desired_row.sort_order,
        updated_at = case
          when block_row.sort_order - v_block_offset
               is distinct from desired_row.sort_order
            then pg_catalog.statement_timestamp()
          else block_row.updated_at
        end
    from jornada_private.normalize_matchday_live_layout_blocks_v14(
      p_blocks
    ) as desired_row
    where block_row.matchday_id = p_matchday_id
      and block_row.id = desired_row.block_id;
  end if;

  -- From this point on, legacy rows are downstream materialization only. The
  -- transaction-local context is held in a private table and cannot be forged
  -- through a client-controlled GUC.
  perform jornada_private.begin_matchday_live_layout_downstream_v14(
    p_matchday_id
  );

  delete from public.matchday_editorial_profile_manual_overrides
    as override_row
  where override_row.matchday_id = p_matchday_id
    and override_row.profile_key = p_profile_key
    and (
      override_row.placement_target is distinct from 'bank'
      or not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_explicit_bank_item_ids
        ) as explicit_row
        join public.matchday_editorial_bank_items as bank_row
          on bank_row.id = explicit_row.bank_item_id
         and bank_row.matchday_id = p_matchday_id
        where pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
              pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
          and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
              pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
      )
    );

  update public.matchday_editorial_profile_manual_overrides as override_row
  set placement_target = 'bank',
      zone_key = null,
      sort_order = null,
      updated_at = pg_catalog.statement_timestamp()
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_explicit_bank_item_ids
  ) as explicit_row
  join public.matchday_editorial_bank_items as bank_row
    on bank_row.id = explicit_row.bank_item_id
   and bank_row.matchday_id = p_matchday_id
  where override_row.matchday_id = p_matchday_id
    and override_row.profile_key = p_profile_key
    and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
    and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
    and (
      override_row.placement_target is distinct from 'bank'
      or override_row.zone_key is not null
      or override_row.sort_order is not null
    );

  insert into public.matchday_editorial_profile_manual_overrides (
    matchday_id,
    profile_key,
    source_type,
    source_id,
    placement_target,
    zone_key,
    sort_order
  )
  select
    p_matchday_id,
    p_profile_key,
    pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)),
    pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)),
    'bank',
    null,
    null
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_explicit_bank_item_ids
  ) as explicit_row
  join public.matchday_editorial_bank_items as bank_row
    on bank_row.id = explicit_row.bank_item_id
   and bank_row.matchday_id = p_matchday_id
  where not exists (
    select 1
    from public.matchday_editorial_profile_manual_overrides as override_row
    where override_row.matchday_id = p_matchday_id
      and override_row.profile_key = p_profile_key
      and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
          pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
      and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
          pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
  )
  order by explicit_row.operation_order;

  with desired as materialized (
    select *
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    )
  ),
  clear_operations as (
    select
      0 as phase,
      current_row.placement_type,
      current_row.zone_id,
      current_row.slot_position,
      current_row.bank_item_id,
      pg_catalog.jsonb_build_object(
        'action', 'clear',
        'bank_item_id', null,
        'placement_type', current_row.placement_type,
        'zone_id', current_row.zone_id,
        'slot_position', current_row.slot_position
      ) as payload
    from public.matchday_live_layout_placements as current_row
    where current_row.matchday_id = p_matchday_id
      and not exists (
        select 1
        from desired as desired_row
        where desired_row.bank_item_id = current_row.bank_item_id
          and desired_row.placement_type = current_row.placement_type
          and desired_row.zone_id is not distinct from current_row.zone_id
          and desired_row.slot_position = current_row.slot_position
      )
      and not exists (
        select 1
        from desired as desired_row
        where desired_row.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from desired as desired_row
        where desired_row.placement_type = current_row.placement_type
          and desired_row.zone_id is not distinct from current_row.zone_id
          and desired_row.slot_position = current_row.slot_position
      )
  ),
  place_operations as (
    select
      1 as phase,
      desired_row.placement_type,
      desired_row.zone_id,
      desired_row.slot_position,
      desired_row.bank_item_id,
      pg_catalog.jsonb_build_object(
        'action', 'place',
        'bank_item_id', desired_row.bank_item_id,
        'placement_type', desired_row.placement_type,
        'zone_id', desired_row.zone_id,
        'slot_position', desired_row.slot_position
      ) as payload
    from desired as desired_row
    where not exists (
      select 1
      from public.matchday_live_layout_placements as current_row
      where current_row.matchday_id = p_matchday_id
        and current_row.bank_item_id = desired_row.bank_item_id
        and current_row.placement_type = desired_row.placement_type
        and current_row.zone_id is not distinct from desired_row.zone_id
        and current_row.slot_position = desired_row.slot_position
    )
  ),
  operations as (
    select * from clear_operations
    union all
    select * from place_operations
  )
  select coalesce(
    pg_catalog.jsonb_agg(
      operation_row.payload
      order by
        operation_row.phase,
        operation_row.placement_type,
        operation_row.zone_id nulls first,
        operation_row.slot_position,
        operation_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_plan
  from operations as operation_row;

  perform jornada_private.apply_matchday_live_layout_placement_plan(
    p_matchday_id,
    v_plan,
    false
  );

  -- A move that leaves and returns to Faixa is not a new arrival. Preserve its
  -- clock unless the caller explicitly supplied it in the arrival event list.
  with previous as materialized (
    select
      previous_row.bank_item_id,
      previous_row.created_at
    from pg_catalog.jsonb_to_recordset(v_faixa_before) as previous_row(
      bank_item_id uuid,
      created_at timestamptz
    )
  )
  update public.matchday_live_layout_placements as placement_row
  set created_at = previous.created_at
  from previous
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa'
    and placement_row.bank_item_id = previous.bank_item_id
    and placement_row.created_at is distinct from previous.created_at
    and not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_faixa_arrival_bank_item_ids
      ) as arrival_row
      where arrival_row.bank_item_id = placement_row.bank_item_id
    );

  v_faixa_anchor := pg_catalog.clock_timestamp();

  update public.matchday_live_layout_placements as placement_row
  set created_at = v_faixa_anchor
      - ((arrival_row.operation_order - 1) * interval '1 microsecond')
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_faixa_arrival_bank_item_ids
  ) as arrival_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa'
    and placement_row.bank_item_id = arrival_row.bank_item_id;

  delete from public.matchday_live_layout_bank_item_state_memory as memory_row
  where memory_row.matchday_id = p_matchday_id
    and (
      exists (
        select 1
        from public.matchday_live_layout_placements as placement_row
        where placement_row.matchday_id = p_matchday_id
          and placement_row.bank_item_id = memory_row.bank_item_id
      )
      or exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_explicit_bank_item_ids
        ) as explicit_row
        where explicit_row.bank_item_id = memory_row.bank_item_id
      )
      or (
        memory_row.memory_kind = 'displaced'
        and not exists (
          select 1
          from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
            p_displaced_bank_item_ids
          ) as displaced_row
          where displaced_row.bank_item_id = memory_row.bank_item_id
        )
      )
    );

  insert into public.matchday_live_layout_bank_item_state_memory
    as memory_row (
      matchday_id,
      bank_item_id,
      memory_kind,
      recorded_at
    )
  select
    p_matchday_id,
    displaced_row.bank_item_id,
    'displaced',
    pg_catalog.statement_timestamp()
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_displaced_bank_item_ids
  ) as displaced_row
  on conflict (matchday_id, bank_item_id)
  do update
  set memory_kind = 'displaced',
      recorded_at = excluded.recorded_at
  where memory_row.memory_kind is distinct from 'displaced';

  v_displaced_anchor := pg_catalog.clock_timestamp();

  update public.matchday_live_layout_bank_item_state_memory as memory_row
  set memory_kind = 'displaced',
      recorded_at = v_displaced_anchor
        - ((arrival_row.operation_order - 1) * interval '1 microsecond')
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_displaced_arrival_bank_item_ids
  ) as arrival_row
  where memory_row.matchday_id = p_matchday_id
    and memory_row.bank_item_id = arrival_row.bank_item_id;

  update public.matchday_editorial_bank_items as bank_row
  set editorially_worked_at = pg_catalog.statement_timestamp()
  from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
    p_worked_bank_item_ids
  ) as worked_row
  where bank_row.matchday_id = p_matchday_id
    and bank_row.id = worked_row.bank_item_id
    and bank_row.editorially_worked_at is null;

  perform jornada_private.project_matchday_live_layout_workspace_v14(
    p_matchday_id,
    p_profile_key
  );

  perform jornada_private.end_matchday_live_layout_downstream_v14(
    p_matchday_id
  );

  -- Physical postconditions compare the exact requested state. They are
  -- intentionally independent from the five-zone compatibility projection.
  if exists (
    with desired as materialized (
      select
        desired_row.zone_id as id,
        desired_row.public_title,
        desired_row.visual_family
      from jornada_private.normalize_matchday_live_layout_zones_v14(
        p_zones
      ) as desired_row
    ),
    current_state as materialized (
      select zone_row.id, zone_row.public_title, zone_row.visual_family
      from public.matchday_live_layout_zones as zone_row
      where zone_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v14-zone-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select
        desired_row.block_id as id,
        desired_row.block_type,
        desired_row.zone_id,
        desired_row.sort_order
      from jornada_private.normalize_matchday_live_layout_blocks_v14(
        p_blocks
      ) as desired_row
    ),
    current_state as materialized (
      select
        block_row.id,
        block_row.block_type,
        block_row.zone_id,
        block_row.sort_order
      from public.matchday_live_layout_blocks as block_row
      where block_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v14-block-postcondition';
  end if;

  if not exists (
    select 1
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
      and settings_row.faixa_slot_count = p_faixa_slot_count
      and settings_row.headline_title_color is not distinct from case
        when pg_catalog.jsonb_typeof(
          p_presentation -> 'headline_title_color'
        ) = 'null' then null
        else pg_catalog.upper(pg_catalog.btrim(
          p_presentation ->> 'headline_title_color'
        ))
      end
      and settings_row.latest_zone_placement =
          p_presentation ->> 'latest_zone_placement'
      and settings_row.latest_zone_title =
          pg_catalog.btrim(p_presentation ->> 'latest_zone_title')
      and settings_row.video_module_active =
          (p_presentation ->> 'video_module_active')::boolean
  ) then
    raise exception 'matchday-live-layout-physical-v14-settings-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select
        placement_row.bank_item_id,
        placement_row.placement_type,
        placement_row.zone_id,
        placement_row.slot_position
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as placement_row
    ),
    current_state as materialized (
      select
        placement_row.bank_item_id,
        placement_row.placement_type,
        placement_row.zone_id,
        placement_row.slot_position
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v14-placement-postcondition';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_matchday_id
    group by placement_row.bank_item_id
    having pg_catalog.count(*) > 1
  ) or exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_matchday_id
    group by
      placement_row.placement_type,
      placement_row.zone_id,
      placement_row.slot_position
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-physical-v14-unique-postcondition';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    left join public.matchday_live_layout_zones as zone_row
      on zone_row.id = placement_row.zone_id
     and zone_row.matchday_id = placement_row.matchday_id
    where placement_row.matchday_id = p_matchday_id
      and (
        (
          placement_row.placement_type = 'faixa'
          and placement_row.slot_position > p_faixa_slot_count
        )
        or (
          placement_row.placement_type = 'zone'
          and (
            zone_row.id is null
            or placement_row.slot_position > jornada_private
                 .matchday_live_layout_visual_family_capacity_v13(
                   zone_row.visual_family
                 )
          )
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-capacity-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select displaced_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as displaced_row
    ),
    current_state as materialized (
      select memory_row.bank_item_id
      from public.matchday_live_layout_bank_item_state_memory as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.memory_kind = 'displaced'
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v14-displaced-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select explicit_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_explicit_bank_item_ids
      ) as explicit_row
    ),
    current_state as materialized (
      select bank_row.id as bank_item_id
      from public.matchday_editorial_profile_manual_overrides as override_row
      join public.matchday_editorial_bank_items as bank_row
        on bank_row.matchday_id = p_matchday_id
       and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) =
           pg_catalog.lower(pg_catalog.btrim(override_row.source_type))
       and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) =
           pg_catalog.lower(pg_catalog.btrim(override_row.source_id))
      where override_row.matchday_id = p_matchday_id
        and override_row.profile_key = p_profile_key
        and override_row.placement_target = 'bank'
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) or exists (
    select 1
    from public.matchday_editorial_profile_manual_overrides as override_row
    where override_row.matchday_id = p_matchday_id
      and override_row.profile_key = p_profile_key
      and (
        override_row.placement_target is distinct from 'bank'
        or override_row.zone_key is not null
        or override_row.sort_order is not null
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-bank-postcondition';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    where exists (
      select 1
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.bank_item_id = explicit_row.bank_item_id
    )
      or exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = explicit_row.bank_item_id
      )
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    where exists (
      select 1
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.bank_item_id = displaced_row.bank_item_id
    )
      or exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_explicit_bank_item_ids
        ) as explicit_row
        where explicit_row.bank_item_id = displaced_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v14-state-conflict-postcondition';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_to_recordset(v_placements_before) as previous_row(
      id uuid,
      bank_item_id uuid,
      placement_type text,
      zone_id uuid,
      slot_position integer,
      created_at timestamptz,
      updated_at timestamptz
    )
    join public.matchday_live_layout_placements as placement_row
      on placement_row.matchday_id = p_matchday_id
     and placement_row.bank_item_id = previous_row.bank_item_id
     and placement_row.placement_type = previous_row.placement_type
     and placement_row.zone_id is not distinct from previous_row.zone_id
     and placement_row.slot_position = previous_row.slot_position
    where placement_row.id is distinct from previous_row.id
      or placement_row.created_at is distinct from previous_row.created_at
      or placement_row.updated_at is distinct from previous_row.updated_at
  ) then
    raise exception 'matchday-live-layout-physical-v14-unchanged-clock-postcondition';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_to_recordset(v_displaced_before) as previous_row(
      bank_item_id uuid,
      recorded_at timestamptz
    )
    join public.matchday_live_layout_bank_item_state_memory as memory_row
      on memory_row.matchday_id = p_matchday_id
     and memory_row.bank_item_id = previous_row.bank_item_id
     and memory_row.memory_kind = 'displaced'
    where memory_row.recorded_at is distinct from previous_row.recorded_at
  ) then
    raise exception 'matchday-live-layout-physical-v14-displaced-clock-postcondition';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as arrival_row
    left join public.matchday_live_layout_placements as placement_row
      on placement_row.matchday_id = p_matchday_id
     and placement_row.bank_item_id = arrival_row.bank_item_id
     and placement_row.placement_type = 'faixa'
    where placement_row.id is null
      or placement_row.created_at is distinct from
         v_faixa_anchor
         - ((arrival_row.operation_order - 1) * interval '1 microsecond')
  ) then
    raise exception 'matchday-live-layout-physical-v14-faixa-clock-postcondition';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as arrival_row
    left join public.matchday_live_layout_bank_item_state_memory as memory_row
      on memory_row.matchday_id = p_matchday_id
     and memory_row.bank_item_id = arrival_row.bank_item_id
     and memory_row.memory_kind = 'displaced'
    where memory_row.bank_item_id is null
      or memory_row.recorded_at is distinct from
         v_displaced_anchor
         - ((arrival_row.operation_order - 1) * interval '1 microsecond')
  ) then
    raise exception 'matchday-live-layout-physical-v14-displaced-arrival-postcondition';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_worked_bank_item_ids
    ) as worked_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = worked_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where bank_row.editorially_worked_at is null
  ) then
    raise exception 'matchday-live-layout-physical-v14-worked-postcondition';
  end if;

  if v_classification_before is distinct from (
    select pg_catalog.md5(coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', bank_row.id,
          'automatic_eligible', bank_row.automatic_eligible,
          'classification_key', bank_row.classification_key,
          'classification_source', bank_row.classification_source,
          'classified_at', bank_row.classified_at
        ) order by bank_row.id
      ),
      '[]'::jsonb
    )::text)
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_matchday_id
  ) then
    raise exception 'matchday-live-layout-physical-v14-classification-changed';
  end if;

  perform jornada_private.assert_matchday_live_layout_downstream_v14(
    p_matchday_id,
    p_profile_key
  );

  if not exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as marker_row
    where marker_row.matchday_id = p_matchday_id
      and marker_row.profile_key = p_profile_key
  ) then
    raise exception 'matchday-live-layout-physical-v14-marker-postcondition';
  end if;

  select token_row.state_token
  into v_final_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  return query
  select
    v_final_state_token,
    pg_catalog.jsonb_array_length(p_zones),
    pg_catalog.jsonb_array_length(p_blocks),
    pg_catalog.jsonb_array_length(p_placements),
    pg_catalog.jsonb_array_length(p_explicit_bank_item_ids),
    pg_catalog.jsonb_array_length(p_displaced_bank_item_ids),
    pg_catalog.jsonb_array_length(p_worked_bank_item_ids);
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.apply_matchday_live_layout_physical_workspace_v20_core_impl(p_matchday_id uuid, p_profile_key text, p_expected_physical_state_token text, p_zones jsonb, p_blocks jsonb, p_placements jsonb, p_faixa_slot_count integer, p_explicit_bank_item_ids jsonb, p_displaced_bank_item_ids jsonb, p_worked_bank_item_ids jsonb, p_faixa_arrival_bank_item_ids jsonb, p_displaced_arrival_bank_item_ids jsonb, p_presentation jsonb)
 RETURNS TABLE(state_token text, applied_zone_count integer, applied_block_count integer, applied_placement_count integer, explicit_bank_item_count integer, displaced_bank_item_count integer, worked_bank_item_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_assignment_profile_key text;
  v_current_state_token text;
  v_final_state_token text;
  v_plan jsonb := '[]'::jsonb;
  v_faixa_before jsonb := '[]'::jsonb;
  v_blocks_before jsonb := '[]'::jsonb;
  v_classification_before text;
  v_faixa_anchor timestamptz;
  v_displaced_anchor timestamptz;
  v_block_offset integer := 1100000000;
  v_had_cutover boolean;
  v_had_settings boolean;
begin
  -- Envelope validation is read-only and precedes every lock and DML.
  if p_matchday_id is null
    or p_profile_key is null
    or pg_catalog.btrim(p_profile_key) = ''
    or p_expected_physical_state_token is null
    or pg_catalog.btrim(p_expected_physical_state_token) = ''
    or pg_catalog.btrim(p_expected_physical_state_token) !~
       '^[0-9a-f]{32}$'
    or p_zones is null
    or pg_catalog.jsonb_typeof(p_zones) <> 'array'
    or p_blocks is null
    or pg_catalog.jsonb_typeof(p_blocks) <> 'array'
    or p_placements is null
    or pg_catalog.jsonb_typeof(p_placements) <> 'array'
    or p_faixa_slot_count is null
    or p_faixa_slot_count < 0
    or p_explicit_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_explicit_bank_item_ids) <> 'array'
    or p_displaced_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_bank_item_ids) <> 'array'
    or p_worked_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_worked_bank_item_ids) <> 'array'
    or p_faixa_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_faixa_arrival_bank_item_ids) <> 'array'
    or p_displaced_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_arrival_bank_item_ids) <> 'array'
    or p_presentation is null
    or pg_catalog.jsonb_typeof(p_presentation) <> 'object'
  then
    raise exception 'matchday-live-layout-physical-v20-invalid-input';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zones) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
      or (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
      ) <> 3
      or not raw_row.payload ?& array[
        'id', 'public_title', 'visual_family'
      ]
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-shape-invalid';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_blocks) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
      or (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
      ) <> 4
      or not raw_row.payload ?& array[
        'id', 'block_type', 'zone_id', 'sort_order'
      ]
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-shape-invalid';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_placements) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload) <> 'object'
      or (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_object_keys(raw_row.payload) as key_row(key_name)
      ) <> 4
      or not raw_row.payload ?& array[
        'bank_item_id', 'placement_type', 'zone_id', 'slot_position'
      ]
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-shape-invalid';
  end if;

  if not p_presentation ?& array[
    'headline_title_color',
    'latest_zone_placement',
    'latest_zone_title',
    'video_module_active'
  ] or (
    p_presentation - array[
      'headline_title_color',
      'latest_zone_placement',
      'latest_zone_title',
      'video_module_active'
    ]::text[]
  ) <> '{}'::jsonb
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'headline_title_color'
    ) not in ('null', 'string')
    or (
      pg_catalog.jsonb_typeof(
        p_presentation -> 'headline_title_color'
      ) = 'string'
      and pg_catalog.btrim(
        p_presentation ->> 'headline_title_color'
      ) !~ '^#[0-9A-Fa-f]{6}$'
    )
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'latest_zone_placement'
    ) <> 'string'
    or p_presentation ->> 'latest_zone_placement' not in (
      'top', 'four_news', 'hidden'
    )
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'latest_zone_title'
    ) <> 'string'
    or pg_catalog.char_length(
      pg_catalog.btrim(p_presentation ->> 'latest_zone_title')
    ) > 120
    or pg_catalog.jsonb_typeof(
      p_presentation -> 'video_module_active'
    ) <> 'boolean'
  then
    raise exception 'matchday-live-layout-physical-v20-presentation-invalid';
  end if;

  if exists (
    select 1
    from (
      select p_explicit_bank_item_ids as payload
      union all select p_displaced_bank_item_ids
      union all select p_worked_bank_item_ids
      union all select p_faixa_arrival_bank_item_ids
      union all select p_displaced_arrival_bank_item_ids
    ) as list_row
    cross join lateral pg_catalog.jsonb_array_elements(list_row.payload)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or pg_catalog.btrim(raw_row.value #>> '{}') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    raise exception 'matchday-live-layout-physical-v20-bank-list-invalid';
  end if;

  -- Identical lock order to the existing physical writers.
  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-live-layout-physical-v20-matchday-not-found';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as desk_row
    where desk_row.matchday_id = p_matchday_id
      and desk_row.is_managed = true
  ) then
    raise exception 'matchday-live-layout-physical-v20-matchday-not-live';
  end if;

  select assignment_row.profile_key
  into v_assignment_profile_key
  from public.matchday_editorial_profile_assignments as assignment_row
  where assignment_row.matchday_id = p_matchday_id;

  if v_assignment_profile_key is distinct from p_profile_key then
    raise exception 'matchday-live-layout-physical-v20-profile-mismatch';
  end if;

  select token_row.state_token
  into v_current_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  if v_current_state_token is distinct from
     p_expected_physical_state_token
  then
    raise exception 'matchday-live-layout-physical-v20-concurrent-write';
  end if;

  select exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = p_matchday_id
  ) into v_had_cutover;

  select exists (
    select 1
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
  ) into v_had_settings;

  if v_had_cutover is distinct from v_had_settings then
    raise exception 'matchday-live-layout-physical-v20-authority-state-corrupt';
  end if;

  if v_had_cutover and exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = p_matchday_id
      and cutover_row.profile_key is distinct from p_profile_key
  ) then
    raise exception 'matchday-live-layout-physical-v20-cutover-profile-mismatch';
  end if;

  perform jornada_private.validate_matchday_live_layout_legacy_projection_v14(
    p_matchday_id,
    p_profile_key
  );

  -- Final zones may be empty, but every row has a real UUID, title and a
  -- centrally known layout. No classification field participates.
  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
    where zone_row.zone_id is null
      or zone_row.public_title is null
      or pg_catalog.char_length(zone_row.public_title) > 120
      or jornada_private.matchday_live_layout_layout_capacity_v20(
           zone_row.visual_family
         ) is null
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-value-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
  ) <> (
    select pg_catalog.count(distinct zone_row.zone_id)
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-duplicate';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as desired_row
    join public.matchday_live_layout_zones as current_row
      on current_row.id = desired_row.zone_id
    where current_row.matchday_id <> p_matchday_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-owned-by-other-matchday';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_id is null
      or block_row.block_type not in ('zone', 'latest', 'video')
      or block_row.sort_order is null
      or block_row.sort_order <= 0
      or block_row.sort_order > 1000000000
      or not (
        (block_row.block_type = 'zone' and block_row.zone_id is not null)
        or (
          block_row.block_type in ('latest', 'video')
          and block_row.zone_id is null
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-value-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
  ) <> (
    select pg_catalog.count(distinct block_row.block_id)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    group by block_row.sort_order
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-duplicate';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as desired_row
    join public.matchday_live_layout_blocks as current_row
      on current_row.id = desired_row.block_id
    where current_row.matchday_id <> p_matchday_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-owned-by-other-matchday';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as desired_row
    join public.matchday_live_layout_blocks as current_row
      on current_row.id = desired_row.block_id
     and current_row.matchday_id = p_matchday_id
    where current_row.block_type is distinct from desired_row.block_type
      or current_row.zone_id is distinct from desired_row.zone_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-identity-mismatch';
  end if;

  -- Retained zones retain their associated physical block identity. A new
  -- block is valid only for a new zone; deleting a zone deletes its old block.
  if exists (
    select 1
    from public.matchday_live_layout_blocks as current_block
    join public.matchday_live_layout_zones as current_zone
      on current_zone.id = current_block.zone_id
     and current_zone.matchday_id = current_block.matchday_id
    where current_block.matchday_id = p_matchday_id
      and current_block.block_type = 'zone'
      and exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
          as desired_zone
        where desired_zone.zone_id = current_zone.id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
          as desired_block
        where desired_block.block_id = current_block.id
          and desired_block.block_type = 'zone'
          and desired_block.zone_id = current_zone.id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-retained-zone-block-changed';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
    where (
      select pg_catalog.count(*)
      from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
        as block_row
      where block_row.block_type = 'zone'
        and block_row.zone_id = zone_row.zone_id
    ) <> 1
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'zone'
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
          as zone_row
        where zone_row.zone_id = block_row.zone_id
      )
  ) or (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'latest'
  ) <> 1 or (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'video'
  ) > 1 then
    raise exception 'matchday-live-layout-physical-v20-block-topology-invalid';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_placements) as raw_row(payload)
    where pg_catalog.jsonb_typeof(raw_row.payload -> 'bank_item_id') <> 'string'
      or pg_catalog.btrim(raw_row.payload ->> 'bank_item_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      or pg_catalog.jsonb_typeof(raw_row.payload -> 'placement_type') <>
         'string'
      or pg_catalog.lower(
           pg_catalog.btrim(raw_row.payload ->> 'placement_type')
         ) not in ('opening', 'faixa', 'selection', 'video_highlight', 'zone')
      or pg_catalog.jsonb_typeof(raw_row.payload -> 'slot_position') <>
         'number'
      or raw_row.payload ->> 'slot_position' !~ '^[0-9]+$'
      or (raw_row.payload ->> 'slot_position')::numeric > 2147483647
      or not (
        (
          pg_catalog.lower(
            pg_catalog.btrim(raw_row.payload ->> 'placement_type')
          ) = 'zone'
          and pg_catalog.jsonb_typeof(raw_row.payload -> 'zone_id') =
              'string'
          and pg_catalog.btrim(raw_row.payload ->> 'zone_id') ~*
              '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        )
        or (
          pg_catalog.lower(
            pg_catalog.btrim(raw_row.payload ->> 'placement_type')
          ) <> 'zone'
          and pg_catalog.jsonb_typeof(raw_row.payload -> 'zone_id') = 'null'
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-value-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    where placement_row.bank_item_id is null
      or placement_row.slot_position is null
      or placement_row.slot_position <= 0
      or not (
        (
          placement_row.placement_type = 'opening'
          and placement_row.zone_id is null
          and placement_row.slot_position between 1 and 5
        )
        or (
          placement_row.placement_type = 'faixa'
          and placement_row.zone_id is null
          and placement_row.slot_position <= p_faixa_slot_count
        )
        or (
          placement_row.placement_type = 'selection'
          and placement_row.zone_id is null
          and placement_row.slot_position between 1 and 4
        )
        or (
          placement_row.placement_type = 'video_highlight'
          and placement_row.zone_id is null
          and placement_row.slot_position = 1
        )
        or (
          placement_row.placement_type = 'zone'
          and placement_row.zone_id is not null
        )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-target-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    )
  ) <> (
    select pg_catalog.count(distinct placement_row.bank_item_id)
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    group by
      placement_row.placement_type,
      placement_row.zone_id,
      placement_row.slot_position
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-duplicate';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    left join jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
      as zone_row
      on zone_row.zone_id = placement_row.zone_id
    where placement_row.placement_type = 'zone'
      and (
        zone_row.zone_id is null
        or placement_row.slot_position >
           jornada_private.matchday_live_layout_layout_capacity_v20(
             zone_row.visual_family
           )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-capacity-invalid';
  end if;


  if not (p_presentation ->> 'video_module_active')::boolean
    and exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as placement_row
      where placement_row.placement_type = 'video_highlight'
    )
  then
    raise exception 'matchday-live-layout-physical-v20-video-state-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    where placement_row.placement_type = 'video_highlight'
  ) and not exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as block_row
    where block_row.block_type = 'video'
  ) then
    raise exception 'matchday-live-layout-physical-v20-video-block-missing';
  end if;

  if exists (
    select 1
    from (
      select p_explicit_bank_item_ids as payload
      union all select p_displaced_bank_item_ids
      union all select p_worked_bank_item_ids
      union all select p_faixa_arrival_bank_item_ids
      union all select p_displaced_arrival_bank_item_ids
    ) as list_row
    cross join lateral (
      select
        pg_catalog.count(*) as item_count,
        pg_catalog.count(distinct normalized_row.bank_item_id) as unique_count
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        list_row.payload
      ) as normalized_row
    ) as count_row
    where count_row.item_count <> count_row.unique_count
  ) then
    raise exception 'matchday-live-layout-physical-v20-bank-list-duplicate';
  end if;

  if exists (
    with requested as materialized (
      select placement_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as placement_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_explicit_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_worked_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_faixa_arrival_bank_item_ids
      ) as list_row
      union
      select list_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_arrival_bank_item_ids
      ) as list_row
    )
    select 1
    from requested as requested_row
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = requested_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
     and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.status, ''))) =
         'active'
    where bank_row.id is null
  ) then
    raise exception 'matchday-live-layout-physical-v20-bank-item-not-active';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = explicit_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) <>
          'editorial_article'
  ) then
    raise exception 'matchday-live-layout-physical-v20-explicit-bank-unsupported';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as state_row
    join jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
      on placement_row.bank_item_id = state_row.bank_item_id
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as state_row
    join jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
      on placement_row.bank_item_id = state_row.bank_item_id
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
      on displaced_row.bank_item_id = explicit_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-state-conflict';
  end if;

  -- General final-state completeness is retained from v14.
  if exists (
    select 1
    from public.matchday_live_layout_placements as current_row
    where current_row.matchday_id = p_matchday_id
      and (
        current_row.placement_type <> 'zone'
        or exists (
          select 1
          from jornada_private.normalize_matchday_live_layout_zones_v14(
            p_zones
          ) as retained_zone
          where retained_zone.zone_id = current_row.zone_id
        )
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
          p_placements
        ) as desired_row
        where desired_row.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_explicit_bank_item_ids
        ) as explicit_row
        where explicit_row.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_bank_item_ids
        ) as displaced_row
        where displaced_row.bank_item_id = current_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-removed-item-state-missing';
  end if;

  -- Deleted-zone items have a stricter server-side contract. If no final
  -- public destination exists they must be DESALOJADA, never explicit Bank.
  if exists (
    select 1
    from public.matchday_live_layout_placements as current_row
    where current_row.matchday_id = p_matchday_id
      and current_row.placement_type = 'zone'
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
          as desired_zone
        where desired_zone.zone_id = current_row.zone_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
          p_placements
        ) as desired_placement
        where desired_placement.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_bank_item_ids
        ) as displaced_row
        where displaced_row.bank_item_id = current_row.bank_item_id
      )
  ) then
    raise exception
      'matchday-live-layout-physical-v20-deleted-zone-items-not-displaced';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as current_row
    where current_row.matchday_id = p_matchday_id
      and current_row.placement_type = 'zone'
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
          as desired_zone
        where desired_zone.zone_id = current_row.zone_id
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
          p_placements
        ) as desired_placement
        where desired_placement.bank_item_id = current_row.bank_item_id
      )
      and not exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = current_row.bank_item_id
          and memory_row.memory_kind = 'displaced'
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = current_row.bank_item_id
      )
  ) then
    raise exception
      'matchday-live-layout-physical-v20-deleted-zone-displaced-arrival-missing';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_matchday_id
      and bank_row.editorially_worked_at is not null
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_worked_bank_item_ids
        ) as worked_row
        where worked_row.bank_item_id = bank_row.id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-worked-regression';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as faixa_row
    join jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as displaced_row
      on displaced_row.bank_item_id = faixa_row.bank_item_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-event-conflict';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as arrival_row
    where not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as desired_row
      where desired_row.bank_item_id = arrival_row.bank_item_id
        and desired_row.placement_type = 'faixa'
    )
      or exists (
        select 1
        from public.matchday_live_layout_placements as current_row
        where current_row.matchday_id = p_matchday_id
          and current_row.bank_item_id = arrival_row.bank_item_id
          and current_row.placement_type = 'faixa'
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-faixa-event-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as desired_row
    where desired_row.placement_type = 'faixa'
      and not exists (
        select 1
        from public.matchday_live_layout_placements as current_row
        where current_row.matchday_id = p_matchday_id
          and current_row.bank_item_id = desired_row.bank_item_id
          and current_row.placement_type = 'faixa'
      )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_faixa_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = desired_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-faixa-event-incomplete';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as arrival_row
    where not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as displaced_row
      where displaced_row.bank_item_id = arrival_row.bank_item_id
    )
      or exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = arrival_row.bank_item_id
          and memory_row.memory_kind = 'displaced'
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-displaced-event-invalid';
  end if;

  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    where not exists (
      select 1
      from public.matchday_live_layout_bank_item_state_memory as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.bank_item_id = displaced_row.bank_item_id
        and memory_row.memory_kind = 'displaced'
    )
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_displaced_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = displaced_row.bank_item_id
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-displaced-event-incomplete';
  end if;

  -- Only data actually consumed by a legacy surface must satisfy its legacy
  -- identity requirements. Unmapped zones are never rejected here.
  if exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where placement_row.placement_type in (
      'opening', 'faixa', 'video_highlight'
    )
      and nullif(pg_catalog.btrim(bank_row.link_url), '') is null
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where placement_row.placement_type = 'selection'
      and (
        nullif(pg_catalog.btrim(bank_row.source_type), '') is null
        or nullif(pg_catalog.btrim(bank_row.source_id), '') is null
      )
  ) or exists (
    select 1
    from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
      p_placements
    ) as placement_row
    join jornada_private.matchday_live_layout_zone_legacy_projection
      as projection_row
      on projection_row.matchday_id = p_matchday_id
     and projection_row.zone_id = placement_row.zone_id
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where placement_row.placement_type = 'zone'
      and (
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) <>
          'editorial_article'
        or nullif(pg_catalog.btrim(bank_row.source_id), '') is null
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-downstream-input-invalid';
  end if;

  -- Before-images used to preserve event clocks and block timestamps.
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'bank_item_id', placement_row.bank_item_id,
        'created_at', placement_row.created_at
      ) order by placement_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_faixa_before
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa';

  select coalesce(
    pg_catalog.jsonb_agg(pg_catalog.to_jsonb(block_row) order by block_row.id),
    '[]'::jsonb
  )
  into v_blocks_before
  from public.matchday_live_layout_blocks as block_row
  where block_row.matchday_id = p_matchday_id;

  select pg_catalog.md5(coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', bank_row.id,
        'automatic_eligible', bank_row.automatic_eligible,
        'classification_key', bank_row.classification_key,
        'classification_source', bank_row.classification_source,
        'classified_at', bank_row.classified_at
      ) order by bank_row.id
    ),
    '[]'::jsonb
  )::text)
  into v_classification_before
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.matchday_id = p_matchday_id;

  if exists (
    select 1
    from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = p_matchday_id
      and block_row.sort_order > 1000000000
  ) then
    raise exception
      'matchday-live-layout-physical-v20-current-block-order-invalid';
  end if;

  -- FIRST DML. Every topology, displacement and classification validation is
  -- complete; any later error rolls the whole function statement back.
  insert into jornada_private.matchday_live_layout_physical_cutovers (
    matchday_id,
    profile_key
  ) values (
    p_matchday_id,
    p_profile_key
  )
  on conflict (matchday_id) do nothing;

  insert into public.matchday_live_layout_workspace_settings as settings_row (
    matchday_id,
    faixa_slot_count,
    headline_title_color,
    latest_zone_placement,
    latest_zone_title,
    video_module_active
  ) values (
    p_matchday_id,
    p_faixa_slot_count,
    case
      when pg_catalog.jsonb_typeof(
        p_presentation -> 'headline_title_color'
      ) = 'null' then null
      else pg_catalog.upper(pg_catalog.btrim(
        p_presentation ->> 'headline_title_color'
      ))
    end,
    p_presentation ->> 'latest_zone_placement',
    pg_catalog.btrim(p_presentation ->> 'latest_zone_title'),
    (p_presentation ->> 'video_module_active')::boolean
  )
  on conflict (matchday_id) do update
  set faixa_slot_count = excluded.faixa_slot_count,
      headline_title_color = excluded.headline_title_color,
      latest_zone_placement = excluded.latest_zone_placement,
      latest_zone_title = excluded.latest_zone_title,
      video_module_active = excluded.video_module_active,
      updated_at = pg_catalog.statement_timestamp()
  where (
    settings_row.faixa_slot_count,
    settings_row.headline_title_color,
    settings_row.latest_zone_placement,
    settings_row.latest_zone_title,
    settings_row.video_module_active
  ) is distinct from (
    excluded.faixa_slot_count,
    excluded.headline_title_color,
    excluded.latest_zone_placement,
    excluded.latest_zone_title,
    excluded.video_module_active
  );

  insert into public.matchday_live_layout_zones (
    id,
    matchday_id,
    public_title,
    visual_family
  )
  select
    desired_row.zone_id,
    p_matchday_id,
    desired_row.public_title,
    desired_row.visual_family
  from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
    as desired_row
  where not exists (
    select 1
    from public.matchday_live_layout_zones as current_row
    where current_row.id = desired_row.zone_id
  )
  order by desired_row.zone_id;

  update public.matchday_live_layout_zones as zone_row
  set public_title = desired_row.public_title,
      visual_family = desired_row.visual_family,
      updated_at = pg_catalog.statement_timestamp()
  from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
    as desired_row
  where zone_row.matchday_id = p_matchday_id
    and zone_row.id = desired_row.zone_id
    and (
      zone_row.public_title,
      zone_row.visual_family
    ) is distinct from (
      desired_row.public_title,
      desired_row.visual_family
    );

  -- Remove deleted-zone placements explicitly before their FK cascade. This
  -- makes displacement observable and keeps delete semantics independent of
  -- ON DELETE behavior.
  delete from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'zone'
    and not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
        as desired_zone
      where desired_zone.zone_id = placement_row.zone_id
    );

  -- All existing block rows first move into a collision-free range. Exact
  -- final orders are then assigned while original clocks remain available in
  -- v_blocks_before.
  if exists (
    with desired as materialized (
      select
        desired_row.block_id as id,
        desired_row.block_type,
        desired_row.zone_id,
        desired_row.sort_order
      from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
        as desired_row
    ),
    current_state as materialized (
      select block_row.id, block_row.block_type, block_row.zone_id,
             block_row.sort_order
      from public.matchday_live_layout_blocks as block_row
      where block_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    update public.matchday_live_layout_blocks as block_row
    set sort_order = block_row.sort_order + v_block_offset
    where block_row.matchday_id = p_matchday_id;

    delete from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = p_matchday_id
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
          as desired_row
        where desired_row.block_id = block_row.id
      );

    insert into public.matchday_live_layout_blocks (
      id,
      matchday_id,
      block_type,
      zone_id,
      sort_order
    )
    select
      desired_row.block_id,
      p_matchday_id,
      desired_row.block_type,
      desired_row.zone_id,
      desired_row.sort_order
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as desired_row
    where not exists (
      select 1
      from public.matchday_live_layout_blocks as current_row
      where current_row.id = desired_row.block_id
    )
    order by desired_row.sort_order, desired_row.block_id;

    with previous as materialized (
      select previous_row.id, previous_row.sort_order
      from pg_catalog.jsonb_to_recordset(v_blocks_before) as previous_row(
        id uuid,
        matchday_id uuid,
        block_type text,
        zone_id uuid,
        sort_order integer,
        created_at timestamptz,
        updated_at timestamptz
      )
    )
    update public.matchday_live_layout_blocks as block_row
    set sort_order = desired_row.sort_order,
        updated_at = case
          when previous.sort_order is distinct from desired_row.sort_order
            then pg_catalog.statement_timestamp()
          else block_row.updated_at
        end
    from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
      as desired_row
    left join previous on previous.id = desired_row.block_id
    where block_row.matchday_id = p_matchday_id
      and block_row.id = desired_row.block_id;
  end if;

  delete from public.matchday_live_layout_zones as zone_row
  where zone_row.matchday_id = p_matchday_id
    and not exists (
      select 1
      from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
        as desired_row
      where desired_row.zone_id = zone_row.id
    );

  perform jornada_private.begin_matchday_live_layout_downstream_v14(
    p_matchday_id
  );

  begin
    delete from public.matchday_editorial_profile_manual_overrides
      as override_row
    where override_row.matchday_id = p_matchday_id
      and override_row.profile_key = p_profile_key
      and (
        override_row.placement_target is distinct from 'bank'
        or not exists (
          select 1
          from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
            p_explicit_bank_item_ids
          ) as explicit_row
          join public.matchday_editorial_bank_items as bank_row
            on bank_row.id = explicit_row.bank_item_id
           and bank_row.matchday_id = p_matchday_id
          where pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
                pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
            and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
                pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
        )
      );

    update public.matchday_editorial_profile_manual_overrides as override_row
    set placement_target = 'bank',
        zone_key = null,
        sort_order = null,
        updated_at = pg_catalog.statement_timestamp()
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = explicit_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where override_row.matchday_id = p_matchday_id
      and override_row.profile_key = p_profile_key
      and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
          pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
      and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
          pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
      and (
        override_row.placement_target is distinct from 'bank'
        or override_row.zone_key is not null
        or override_row.sort_order is not null
      );

    insert into public.matchday_editorial_profile_manual_overrides (
      matchday_id,
      profile_key,
      source_type,
      source_id,
      placement_target,
      zone_key,
      sort_order
    )
    select
      p_matchday_id,
      p_profile_key,
      pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)),
      pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)),
      'bank',
      null,
      null
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_explicit_bank_item_ids
    ) as explicit_row
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = explicit_row.bank_item_id
     and bank_row.matchday_id = p_matchday_id
    where not exists (
      select 1
      from public.matchday_editorial_profile_manual_overrides as override_row
      where override_row.matchday_id = p_matchday_id
        and override_row.profile_key = p_profile_key
        and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
            pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
        and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
            pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
    )
    order by explicit_row.operation_order;

    with desired as materialized (
      select *
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      )
    ),
    clear_operations as (
      select
        0 as phase,
        current_row.placement_type,
        current_row.zone_id,
        current_row.slot_position,
        current_row.bank_item_id,
        pg_catalog.jsonb_build_object(
          'action', 'clear',
          'bank_item_id', null,
          'placement_type', current_row.placement_type,
          'zone_id', current_row.zone_id,
          'slot_position', current_row.slot_position
        ) as payload
      from public.matchday_live_layout_placements as current_row
      where current_row.matchday_id = p_matchday_id
        and not exists (
          select 1
          from desired as desired_row
          where desired_row.bank_item_id = current_row.bank_item_id
            and desired_row.placement_type = current_row.placement_type
            and desired_row.zone_id is not distinct from current_row.zone_id
            and desired_row.slot_position = current_row.slot_position
        )
        and not exists (
          select 1
          from desired as desired_row
          where desired_row.bank_item_id = current_row.bank_item_id
        )
        and not exists (
          select 1
          from desired as desired_row
          where desired_row.placement_type = current_row.placement_type
            and desired_row.zone_id is not distinct from current_row.zone_id
            and desired_row.slot_position = current_row.slot_position
        )
    ),
    place_operations as (
      select
        1 as phase,
        desired_row.placement_type,
        desired_row.zone_id,
        desired_row.slot_position,
        desired_row.bank_item_id,
        pg_catalog.jsonb_build_object(
          'action', 'place',
          'bank_item_id', desired_row.bank_item_id,
          'placement_type', desired_row.placement_type,
          'zone_id', desired_row.zone_id,
          'slot_position', desired_row.slot_position
        ) as payload
      from desired as desired_row
      where not exists (
        select 1
        from public.matchday_live_layout_placements as current_row
        where current_row.matchday_id = p_matchday_id
          and current_row.bank_item_id = desired_row.bank_item_id
          and current_row.placement_type = desired_row.placement_type
          and current_row.zone_id is not distinct from desired_row.zone_id
          and current_row.slot_position = desired_row.slot_position
      )
    ),
    operations as (
      select * from clear_operations
      union all
      select * from place_operations
    )
    select coalesce(
      pg_catalog.jsonb_agg(
        operation_row.payload
        order by
          operation_row.phase,
          operation_row.placement_type,
          operation_row.zone_id nulls first,
          operation_row.slot_position,
          operation_row.bank_item_id
      ),
      '[]'::jsonb
    )
    into v_plan
    from operations as operation_row;

    perform jornada_private.apply_matchday_live_layout_placement_plan(
      p_matchday_id,
      v_plan,
      false
    );

    -- Re-entry into Faixa preserves its prior clock unless explicitly marked
    -- as a new arrival.
    with previous as materialized (
      select previous_row.bank_item_id, previous_row.created_at
      from pg_catalog.jsonb_to_recordset(v_faixa_before) as previous_row(
        bank_item_id uuid,
        created_at timestamptz
      )
    )
    update public.matchday_live_layout_placements as placement_row
    set created_at = previous.created_at
    from previous
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'faixa'
      and placement_row.bank_item_id = previous.bank_item_id
      and placement_row.created_at is distinct from previous.created_at
      and not exists (
        select 1
        from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
          p_faixa_arrival_bank_item_ids
        ) as arrival_row
        where arrival_row.bank_item_id = placement_row.bank_item_id
      );

    v_faixa_anchor := pg_catalog.clock_timestamp();

    update public.matchday_live_layout_placements as placement_row
    set created_at = v_faixa_anchor
        - ((arrival_row.operation_order - 1) * interval '1 microsecond')
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_faixa_arrival_bank_item_ids
    ) as arrival_row
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'faixa'
      and placement_row.bank_item_id = arrival_row.bank_item_id;

    delete from public.matchday_live_layout_bank_item_state_memory as memory_row
    where memory_row.matchday_id = p_matchday_id
      and (
        exists (
          select 1
          from public.matchday_live_layout_placements as placement_row
          where placement_row.matchday_id = p_matchday_id
            and placement_row.bank_item_id = memory_row.bank_item_id
        )
        or exists (
          select 1
          from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
            p_explicit_bank_item_ids
          ) as explicit_row
          where explicit_row.bank_item_id = memory_row.bank_item_id
        )
        or (
          memory_row.memory_kind = 'displaced'
          and not exists (
            select 1
            from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
              p_displaced_bank_item_ids
            ) as displaced_row
            where displaced_row.bank_item_id = memory_row.bank_item_id
          )
        )
      );

    insert into public.matchday_live_layout_bank_item_state_memory
      as memory_row (
        matchday_id,
        bank_item_id,
        memory_kind,
        recorded_at
      )
    select
      p_matchday_id,
      displaced_row.bank_item_id,
      'displaced',
      pg_catalog.statement_timestamp()
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_bank_item_ids
    ) as displaced_row
    on conflict (matchday_id, bank_item_id)
    do update
    set memory_kind = 'displaced',
        recorded_at = excluded.recorded_at
    where memory_row.memory_kind is distinct from 'displaced';

    v_displaced_anchor := pg_catalog.clock_timestamp();

    update public.matchday_live_layout_bank_item_state_memory as memory_row
    set memory_kind = 'displaced',
        recorded_at = v_displaced_anchor
          - ((arrival_row.operation_order - 1) * interval '1 microsecond')
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_displaced_arrival_bank_item_ids
    ) as arrival_row
    where memory_row.matchday_id = p_matchday_id
      and memory_row.bank_item_id = arrival_row.bank_item_id;

    update public.matchday_editorial_bank_items as bank_row
    set editorially_worked_at = pg_catalog.statement_timestamp()
    from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
      p_worked_bank_item_ids
    ) as worked_row
    where bank_row.matchday_id = p_matchday_id
      and bank_row.id = worked_row.bank_item_id
      and bank_row.editorially_worked_at is null;

    perform
      jornada_private.project_matchday_live_layout_workspace_best_effort_v20(
        p_matchday_id,
        p_profile_key
      );
  exception when others then
    perform jornada_private.end_matchday_live_layout_downstream_v14(
      p_matchday_id
    );
    raise;
  end;

  perform jornada_private.end_matchday_live_layout_downstream_v14(
    p_matchday_id
  );

  -- Exact physical postconditions. Empty zones and missing slot positions are
  -- valid occupancy, so only persisted rows participate.
  if exists (
    with desired as materialized (
      select desired_row.zone_id as id, desired_row.public_title,
             desired_row.visual_family
      from jornada_private.normalize_matchday_live_layout_zones_v14(p_zones)
        as desired_row
    ),
    current_state as materialized (
      select zone_row.id, zone_row.public_title, zone_row.visual_family
      from public.matchday_live_layout_zones as zone_row
      where zone_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-zone-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select desired_row.block_id as id, desired_row.block_type,
             desired_row.zone_id, desired_row.sort_order
      from jornada_private.normalize_matchday_live_layout_blocks_v14(p_blocks)
        as desired_row
    ),
    current_state as materialized (
      select block_row.id, block_row.block_type, block_row.zone_id,
             block_row.sort_order
      from public.matchday_live_layout_blocks as block_row
      where block_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-block-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select placement_row.bank_item_id, placement_row.placement_type,
             placement_row.zone_id, placement_row.slot_position
      from jornada_private.normalize_matchday_live_layout_physical_placements_v13(
        p_placements
      ) as placement_row
    ),
    current_state as materialized (
      select placement_row.bank_item_id, placement_row.placement_type,
             placement_row.zone_id, placement_row.slot_position
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-placement-postcondition';
  end if;

  if not exists (
    select 1
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
      and settings_row.faixa_slot_count = p_faixa_slot_count
      and settings_row.headline_title_color is not distinct from case
        when pg_catalog.jsonb_typeof(
          p_presentation -> 'headline_title_color'
        ) = 'null' then null
        else pg_catalog.upper(pg_catalog.btrim(
          p_presentation ->> 'headline_title_color'
        ))
      end
      and settings_row.latest_zone_placement =
          p_presentation ->> 'latest_zone_placement'
      and settings_row.latest_zone_title =
          pg_catalog.btrim(p_presentation ->> 'latest_zone_title')
      and settings_row.video_module_active =
          (p_presentation ->> 'video_module_active')::boolean
  ) then
    raise exception 'matchday-live-layout-physical-v20-settings-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select displaced_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_displaced_bank_item_ids
      ) as displaced_row
    ),
    current_state as materialized (
      select memory_row.bank_item_id
      from public.matchday_live_layout_bank_item_state_memory as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.memory_kind = 'displaced'
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-displaced-postcondition';
  end if;

  if exists (
    with desired as materialized (
      select explicit_row.bank_item_id
      from jornada_private.normalize_matchday_live_layout_bank_item_ids_v13(
        p_explicit_bank_item_ids
      ) as explicit_row
    ),
    current_state as materialized (
      select bank_row.id as bank_item_id
      from public.matchday_editorial_profile_manual_overrides as override_row
      join public.matchday_editorial_bank_items as bank_row
        on bank_row.matchday_id = p_matchday_id
       and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) =
           pg_catalog.lower(pg_catalog.btrim(override_row.source_type))
       and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) =
           pg_catalog.lower(pg_catalog.btrim(override_row.source_id))
      where override_row.matchday_id = p_matchday_id
        and override_row.profile_key = p_profile_key
        and override_row.placement_target = 'bank'
    ),
    differences as (
      (select * from current_state except select * from desired)
      union all
      (select * from desired except select * from current_state)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-physical-v20-bank-postcondition';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    left join public.matchday_live_layout_zones as zone_row
      on zone_row.id = placement_row.zone_id
     and zone_row.matchday_id = placement_row.matchday_id
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = 'zone'
      and (
        zone_row.id is null
        or placement_row.slot_position >
           jornada_private.matchday_live_layout_layout_capacity_v20(
             zone_row.visual_family
           )
      )
  ) then
    raise exception 'matchday-live-layout-physical-v20-capacity-postcondition';
  end if;

  if v_classification_before is distinct from (
    select pg_catalog.md5(coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', bank_row.id,
          'automatic_eligible', bank_row.automatic_eligible,
          'classification_key', bank_row.classification_key,
          'classification_source', bank_row.classification_source,
          'classified_at', bank_row.classified_at
        ) order by bank_row.id
      ),
      '[]'::jsonb
    )::text)
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_matchday_id
  ) then
    raise exception 'matchday-live-layout-physical-v20-classification-changed';
  end if;

  perform jornada_private.assert_matchday_live_layout_downstream_v14(
    p_matchday_id,
    p_profile_key
  );

  perform
    jornada_private.assert_matchday_live_layout_physical_topology_source_v17(
      p_matchday_id,
      p_profile_key
    );

  select token_row.state_token
  into v_final_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  return query
  select
    v_final_state_token,
    pg_catalog.jsonb_array_length(p_zones),
    pg_catalog.jsonb_array_length(p_blocks),
    pg_catalog.jsonb_array_length(p_placements),
    pg_catalog.jsonb_array_length(p_explicit_bank_item_ids),
    pg_catalog.jsonb_array_length(p_displaced_bank_item_ids),
    pg_catalog.jsonb_array_length(p_worked_bank_item_ids);
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.apply_matchday_live_layout_placement_plan(p_matchday_id uuid, p_plan jsonb, p_project_legacy boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_deleted_count integer:=0; v_inserted_count integer:=0;
begin
  if p_matchday_id is null or p_plan is null or pg_catalog.jsonb_typeof(p_plan)<>'array' then raise exception 'matchday-live-layout-plan-invalid-envelope'; end if;
  if not exists (select 1 from public.matchdays as matchday_row where matchday_row.id=p_matchday_id) then raise exception 'matchday-live-layout-plan-matchday-not-found'; end if;
  perform 1 from public.matchdays as matchday_row where matchday_row.id=p_matchday_id for update;
  if exists (select 1 from pg_catalog.jsonb_array_elements(p_plan) as raw_row(payload) where pg_catalog.jsonb_typeof(raw_row.payload)<>'object') then raise exception 'matchday-live-layout-plan-operation-invalid'; end if;
  if exists (
    select 1 from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan) as plan_row
    where plan_row.action is null or plan_row.action not in ('place','clear') or plan_row.placement_type is null or plan_row.placement_type not in ('opening','faixa','selection','video_highlight','zone') or plan_row.slot_position is null or (plan_row.action='place' and plan_row.bank_item_id is null) or (plan_row.action='clear' and plan_row.bank_item_id is not null)
      or not ((plan_row.placement_type='opening' and plan_row.zone_id is null and plan_row.slot_position between 1 and 5) or (plan_row.placement_type='faixa' and plan_row.zone_id is null and plan_row.slot_position>0) or (plan_row.placement_type='selection' and plan_row.zone_id is null and plan_row.slot_position between 1 and 4) or (plan_row.placement_type='video_highlight' and plan_row.zone_id is null and plan_row.slot_position=1) or (plan_row.placement_type='zone' and plan_row.zone_id is not null and plan_row.slot_position>0))
  ) then raise exception 'matchday-live-layout-plan-target-invalid'; end if;
  if exists (select 1 from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan) as plan_row group by plan_row.placement_type,plan_row.zone_id,plan_row.slot_position having pg_catalog.count(*)>1) then raise exception 'matchday-live-layout-plan-duplicate-target'; end if;
  if exists (select 1 from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan) as plan_row where plan_row.action='place' group by plan_row.bank_item_id having pg_catalog.count(*)>1) then raise exception 'matchday-live-layout-plan-duplicate-bank-item'; end if;
  if exists (select 1 from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan) as plan_row left join public.matchday_editorial_bank_items as bank_row on bank_row.id=plan_row.bank_item_id and bank_row.matchday_id=p_matchday_id where plan_row.action='place' and bank_row.id is null) then raise exception 'matchday-live-layout-plan-bank-context-invalid'; end if;
  if exists (select 1 from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan) as plan_row left join public.matchday_live_layout_zones as zone_row on zone_row.id=plan_row.zone_id and zone_row.matchday_id=p_matchday_id where plan_row.placement_type='zone' and zone_row.id is null) then raise exception 'matchday-live-layout-plan-zone-context-invalid'; end if;
  perform 1 from public.matchday_editorial_bank_items as bank_row where bank_row.matchday_id=p_matchday_id and bank_row.id in (select plan_row.bank_item_id from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan) as plan_row where plan_row.action='place') order by bank_row.id for key share;
  perform 1 from public.matchday_live_layout_placements as placement_row where placement_row.matchday_id=p_matchday_id order by placement_row.id for update;
  if exists (select 1 from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan) as plan_row join public.matchday_live_layout_placements as placement_row on placement_row.matchday_id=p_matchday_id and placement_row.bank_item_id=plan_row.bank_item_id where plan_row.action='place' group by plan_row.bank_item_id having pg_catalog.count(*)>1) then raise exception 'matchday-live-layout-plan-existing-transversal-conflict'; end if;
  with plan_rows as materialized (select * from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan))
  delete from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id=p_matchday_id and (exists (select 1 from plan_rows as plan_row where plan_row.action='place' and plan_row.bank_item_id=placement_row.bank_item_id) or exists (select 1 from plan_rows as plan_row where plan_row.placement_type=placement_row.placement_type and plan_row.slot_position=placement_row.slot_position and plan_row.zone_id is not distinct from placement_row.zone_id));
  get diagnostics v_deleted_count=row_count;
  insert into public.matchday_live_layout_placements (matchday_id,bank_item_id,placement_type,zone_id,slot_position,created_at,updated_at)
  select p_matchday_id,plan_row.bank_item_id,plan_row.placement_type,plan_row.zone_id,plan_row.slot_position,pg_catalog.now(),pg_catalog.now()
  from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan) as plan_row where plan_row.action='place'
  order by plan_row.placement_type,plan_row.zone_id nulls first,plan_row.slot_position,plan_row.bank_item_id;
  get diagnostics v_inserted_count=row_count;
  if exists (select 1 from jornada_private.normalize_matchday_live_layout_placement_plan(p_plan) as plan_row left join lateral (select pg_catalog.count(*) as placement_count from public.matchday_live_layout_placements as placement_row where placement_row.matchday_id=p_matchday_id and placement_row.bank_item_id=plan_row.bank_item_id) as current_row on true where plan_row.action='place' and current_row.placement_count<>1) then raise exception 'matchday-live-layout-plan-postcondition-failed'; end if;
  if p_project_legacy then perform jornada_private.project_matchday_live_layout_placements_to_legacy(array[p_matchday_id]::uuid[]); end if;
  return pg_catalog.jsonb_build_object('matchday_id',p_matchday_id,'operation_count',pg_catalog.jsonb_array_length(p_plan),'deleted_placement_count',v_deleted_count,'inserted_placement_count',v_inserted_count,'legacy_projected',p_project_legacy);
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.apply_profile_workspace_v12_pre_physical_facade(p_matchday_id uuid, p_profile_key text, p_expected_revision bigint, p_expected_state_token text, p_overrides jsonb, p_zone_items jsonb, p_faixa_source_ids jsonb, p_opening jsonb, p_page_controls jsonb, p_selection_bank_item_ids jsonb, p_video_module jsonb, p_worked_source_ids jsonb, p_authoritative_zone_items jsonb, p_authoritative_faixa_items jsonb, p_displaced_bank_item_ids jsonb, p_faixa_arrival_bank_item_ids jsonb, p_displaced_arrival_bank_item_ids jsonb)
 RETURNS TABLE(revision bigint, state_token text, applied_override_count integer, applied_zone_item_count integer, applied_faixa_count integer, applied_opening_count integer, applied_selection_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_apply record;
  v_faixa_before jsonb := '[]'::jsonb;
  v_faixa_anchor timestamptz;
  v_displaced_anchor timestamptz;
  v_final_state_token text;
begin
  if p_matchday_id is null
    or p_displaced_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_bank_item_ids) <> 'array'
    or p_faixa_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_faixa_arrival_bank_item_ids) <> 'array'
    or p_displaced_arrival_bank_item_ids is null
    or pg_catalog.jsonb_typeof(p_displaced_arrival_bank_item_ids) <> 'array'
  then
    raise exception
      'matchday-editorial-profile-workspace-v12-invalid-input';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or (raw_row.value #>> '{}')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) or exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or (raw_row.value #>> '{}')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) or exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
      as raw_row(value)
    where pg_catalog.jsonb_typeof(raw_row.value) <> 'string'
      or (raw_row.value #>> '{}')
        !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-invalid-events';
  end if;

  if (
    select pg_catalog.count(*)
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
  ) <> (
    select pg_catalog.count(distinct pg_catalog.lower(
      pg_catalog.btrim(raw_row.value #>> '{}')
    ))
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
      as raw_row(value)
  ) or (
    select pg_catalog.count(*)
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
  ) <> (
    select pg_catalog.count(distinct pg_catalog.lower(
      pg_catalog.btrim(raw_row.value #>> '{}')
    ))
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
      as raw_row(value)
  ) or (
    select pg_catalog.count(*)
    from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
  ) <> (
    select pg_catalog.count(distinct pg_catalog.lower(
      pg_catalog.btrim(raw_row.value #>> '{}')
    ))
    from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
      as raw_row(value)
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-duplicate-events';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
      as arrival_row(value)
    where not exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
        as displaced_row(value)
      where pg_catalog.lower(pg_catalog.btrim(
              displaced_row.value #>> '{}'
            )) =
            pg_catalog.lower(pg_catalog.btrim(
              arrival_row.value #>> '{}'
            ))
    )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-displaced-event-not-final';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
      as faixa_row(value)
    join pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
      as displaced_row(value)
      on pg_catalog.lower(pg_catalog.btrim(
           faixa_row.value #>> '{}'
         )) =
         pg_catalog.lower(pg_catalog.btrim(
           displaced_row.value #>> '{}'
         ))
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-event-conflict';
  end if;

  perform
    jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  if exists (
    with requested as (
      select pg_catalog.lower(pg_catalog.btrim(
               raw_row.value #>> '{}'
             )) as bank_item_id
      from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
        as raw_row(value)

      union

      select pg_catalog.lower(pg_catalog.btrim(
               raw_row.value #>> '{}'
             ))
      from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
        as raw_row(value)

      union

      select pg_catalog.lower(pg_catalog.btrim(
               raw_row.value #>> '{}'
             ))
      from pg_catalog.jsonb_array_elements(p_displaced_arrival_bank_item_ids)
        as raw_row(value)
    )
    select 1
    from requested as requested_row
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.matchday_id = p_matchday_id
     and bank_row.id::text = requested_row.bank_item_id
     and pg_catalog.lower(
           pg_catalog.btrim(coalesce(bank_row.status, ''))
         ) = 'active'
    where bank_row.id is null
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-event-source-not-active';
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'bank_item_id', placement_row.bank_item_id,
        'created_at', placement_row.created_at
      )
      order by placement_row.bank_item_id
    ),
    '[]'::jsonb
  )
  into v_faixa_before
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa';

  select *
  into v_apply
  from jornada_private.apply_matchday_editorial_profile_workspace_v11_pre_handoff(
    p_matchday_id,
    p_profile_key,
    p_expected_revision,
    p_expected_state_token,
    p_overrides,
    p_zone_items,
    p_faixa_source_ids,
    p_opening,
    p_page_controls,
    p_selection_bank_item_ids,
    p_video_module,
    p_worked_source_ids,
    p_authoritative_zone_items,
    p_authoritative_faixa_items,
    '[]'::jsonb
  );

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
      as displaced_row(value)
    join public.matchday_editorial_bank_items as bank_row
      on bank_row.matchday_id = p_matchday_id
     and bank_row.id::text = pg_catalog.lower(
       pg_catalog.btrim(displaced_row.value #>> '{}')
     )
    where exists (
      select 1
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.bank_item_id = bank_row.id
    )
      or exists (
        select 1
        from public.matchday_editorial_profile_manual_overrides
          as override_row
        where override_row.matchday_id = p_matchday_id
          and override_row.profile_key = p_profile_key
          and override_row.placement_target = 'bank'
          and pg_catalog.lower(
                pg_catalog.btrim(override_row.source_type)
              ) = pg_catalog.lower(
                pg_catalog.btrim(bank_row.source_type)
              )
          and pg_catalog.lower(
                pg_catalog.btrim(override_row.source_id)
              ) = pg_catalog.lower(
                pg_catalog.btrim(bank_row.source_id)
              )
      )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-displaced-placement-conflict';
  end if;

  insert into public.matchday_live_layout_bank_item_state_memory
    as memory_row (
      matchday_id,
      bank_item_id,
      memory_kind,
      recorded_at
    )
  select
    p_matchday_id,
    pg_catalog.lower(
      pg_catalog.btrim(displaced_row.value #>> '{}')
    )::uuid,
    'displaced',
    pg_catalog.statement_timestamp()
  from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
    as displaced_row(value)
  on conflict (matchday_id, bank_item_id)
  do update
  set memory_kind = 'displaced',
      recorded_at = coalesce(
        case
          when memory_row.memory_kind = 'displaced'
            then memory_row.recorded_at
        end,
        excluded.recorded_at
      );

  with previous as materialized (
    select
      (raw_row.value ->> 'bank_item_id')::uuid as bank_item_id,
      (raw_row.value ->> 'created_at')::timestamptz as created_at
    from pg_catalog.jsonb_array_elements(v_faixa_before)
      as raw_row(value)
  )
  update public.matchday_live_layout_placements as placement_row
  set created_at = previous.created_at
  from previous
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa'
    and placement_row.bank_item_id = previous.bank_item_id
    and not exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
        as arrival_row(value)
      where pg_catalog.lower(pg_catalog.btrim(
              arrival_row.value #>> '{}'
            )) = placement_row.bank_item_id::text
    );

  v_faixa_anchor := pg_catalog.clock_timestamp();

  with arrivals as materialized (
    select
      pg_catalog.lower(pg_catalog.btrim(
        raw_row.value #>> '{}'
      ))::uuid as bank_item_id,
      raw_row.ordinality
    from pg_catalog.jsonb_array_elements(
      p_faixa_arrival_bank_item_ids
    ) with ordinality as raw_row(value, ordinality)
  )
  update public.matchday_live_layout_placements as placement_row
  set created_at =
      v_faixa_anchor
      - ((arrivals.ordinality - 1) * interval '1 microsecond')
  from arrivals
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = 'faixa'
    and placement_row.bank_item_id = arrivals.bank_item_id;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_arrival_bank_item_ids)
      as arrival_row(value)
    where not exists (
      select 1
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.placement_type = 'faixa'
        and placement_row.bank_item_id =
          pg_catalog.lower(pg_catalog.btrim(
            arrival_row.value #>> '{}'
          ))::uuid
    )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-faixa-event-not-final';
  end if;

  if exists (
    select 1
    from (
      select
        pg_catalog.count(*) as item_count,
        pg_catalog.min(placement_row.slot_position) as min_position,
        pg_catalog.max(placement_row.slot_position) as max_position
      from public.matchday_live_layout_placements as placement_row
      where placement_row.matchday_id = p_matchday_id
        and placement_row.placement_type = 'faixa'
    ) as faixa_state
    where faixa_state.item_count > 0
      and (
        faixa_state.min_position <> 1
        or faixa_state.max_position <> faixa_state.item_count
      )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-faixa-not-contiguous';
  end if;

  v_displaced_anchor := pg_catalog.clock_timestamp();

  with arrivals as materialized (
    select
      pg_catalog.lower(pg_catalog.btrim(
        raw_row.value #>> '{}'
      ))::uuid as bank_item_id,
      raw_row.ordinality
    from pg_catalog.jsonb_array_elements(
      p_displaced_arrival_bank_item_ids
    ) with ordinality as raw_row(value, ordinality)
  )
  update public.matchday_live_layout_bank_item_state_memory as memory_row
  set memory_kind = 'displaced',
      recorded_at =
        v_displaced_anchor
        - ((arrivals.ordinality - 1) * interval '1 microsecond')
  from arrivals
  where memory_row.matchday_id = p_matchday_id
    and memory_row.bank_item_id = arrivals.bank_item_id;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_displaced_bank_item_ids)
      as displaced_row(value)
    where not exists (
      select 1
      from public.matchday_live_layout_bank_item_state_memory
        as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.bank_item_id =
          pg_catalog.lower(pg_catalog.btrim(
            displaced_row.value #>> '{}'
          ))::uuid
        and memory_row.memory_kind = 'displaced'
    )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-displaced-memory-incomplete';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_bank_item_state_memory as memory_row
    join public.matchday_live_layout_placements as placement_row
      on placement_row.matchday_id = memory_row.matchday_id
     and placement_row.bank_item_id = memory_row.bank_item_id
    where memory_row.matchday_id = p_matchday_id
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v12-memory-placement-conflict';
  end if;

  select token_row.state_token
  into v_final_state_token
  from public.matchday_editorial_profile_workspace_token_uncached(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  return query
  select
    v_apply.revision,
    v_final_state_token,
    v_apply.applied_override_count,
    v_apply.applied_zone_item_count,
    v_apply.applied_faixa_count,
    v_apply.applied_opening_count,
    v_apply.applied_selection_count;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.assert_matchday_live_layout_handoff_companion_v25()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source_zone_id uuid;
  v_expected_target_zone_id uuid;
  v_actual_target_zone_id uuid;
begin
  select companion_row.zone_id
  into v_source_zone_id
  from public.matchday_live_layout_latest_companion as companion_row
  where companion_row.matchday_id = new.source_matchday_id;

  if not found then
    if exists (
      select 1
      from public.matchday_live_layout_latest_companion as companion_row
      where companion_row.matchday_id = new.target_matchday_id
    ) then
      raise exception
        'matchday-live-layout-latest-companion-v25-unexpected-target';
    end if;

    return new;
  end if;

  select map_row.target_zone_id
  into v_expected_target_zone_id
  from jornada_private.matchday_live_layout_physical_zone_maps as map_row
  where map_row.topology_transition_id = new.topology_transition_id
    and map_row.source_zone_id = v_source_zone_id;

  if not found then
    raise exception
      'matchday-live-layout-latest-companion-v25-zone-map-missing';
  end if;

  select companion_row.zone_id
  into v_actual_target_zone_id
  from public.matchday_live_layout_latest_companion as companion_row
  where companion_row.matchday_id = new.target_matchday_id;

  if not found
    or v_actual_target_zone_id is distinct from v_expected_target_zone_id
  then
    raise exception
      'matchday-live-layout-latest-companion-v25-handoff-incomplete';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.assert_matchday_live_layout_historical_physical_archive_v20(p_source_matchday_id uuid, p_target_matchday_id uuid, p_source_composition_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_certificate
    jornada_private
      .matchday_historical_physical_archive_certificates_v20%rowtype;
  v_handoff
    jornada_private.matchday_live_layout_physical_handoffs%rowtype;
  v_carryover
    jornada_private.matchday_live_layout_physical_carryovers%rowtype;
  v_components jsonb;
begin
  if p_source_matchday_id is null
    or p_target_matchday_id is null
    or p_source_composition_id is null
    or p_source_matchday_id = p_target_matchday_id
  then
    raise exception 'matchday-live-layout-historical-v20-invalid-envelope';
  end if;

  select certificate_row.*
  into v_certificate
  from jornada_private
    .matchday_historical_physical_archive_certificates_v20
    as certificate_row
  where certificate_row.source_matchday_id = p_source_matchday_id
    and certificate_row.target_matchday_id = p_target_matchday_id
    and certificate_row.source_composition_id = p_source_composition_id;

  if not found then
    raise exception 'matchday-live-layout-historical-v20-certificate-missing';
  end if;

  select handoff_row.*
  into v_handoff
  from jornada_private.matchday_live_layout_physical_handoffs as handoff_row
  where handoff_row.id = v_certificate.handoff_id
    and handoff_row.source_matchday_id = p_source_matchday_id
    and handoff_row.target_matchday_id = p_target_matchday_id
    and handoff_row.source_composition_id = p_source_composition_id;

  if not found then
    raise exception 'matchday-live-layout-historical-v20-certificate-missing';
  end if;

  if v_certificate.topology_transition_id is distinct from
       v_handoff.topology_transition_id
    or v_certificate.carryover_id is distinct from v_handoff.carryover_id
    or v_certificate.v19_source_archive_hash is distinct from
       v_handoff.source_archive_hash
  then
    raise exception
      'matchday-live-layout-historical-v20-handoff-certificate-invalid';
  end if;

  if not exists (
    select 1
    from jornada_private.matchday_live_layout_physical_topology_transitions
      as topology_row
    join jornada_private.matchday_live_layout_physical_cutovers as cutover_row
      on cutover_row.matchday_id = topology_row.source_matchday_id
     and cutover_row.profile_key = topology_row.profile_key
     and cutover_row.cutover_at = topology_row.source_cutover_at
    where topology_row.id = v_handoff.topology_transition_id
      and topology_row.source_matchday_id = p_source_matchday_id
      and topology_row.target_matchday_id = p_target_matchday_id
      and topology_row.profile_key = v_handoff.profile_key
  ) then
    raise exception
      'matchday-live-layout-historical-v20-topology-certificate-invalid';
  end if;

  select carryover_row.*
  into v_carryover
  from jornada_private.matchday_live_layout_physical_carryovers
    as carryover_row
  where carryover_row.id = v_handoff.carryover_id
    and carryover_row.topology_transition_id =
        v_handoff.topology_transition_id
    and carryover_row.source_matchday_id = p_source_matchday_id
    and carryover_row.target_matchday_id = p_target_matchday_id
    and carryover_row.source_composition_id = p_source_composition_id
    and carryover_row.profile_key = v_handoff.profile_key
    and carryover_row.state_token_after = v_handoff.target_state_token;

  if not found then
    raise exception
      'matchday-live-layout-historical-v20-carryover-certificate-invalid';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_continuity_transitions as transition_row
    where transition_row.source_matchday_id = p_source_matchday_id
      and transition_row.target_matchday_id = p_target_matchday_id
      and transition_row.source_composition_id = p_source_composition_id
      and transition_row.continuity_version = 19
  ) or not exists (
    select 1
    from public.matchday_reference_compositions as composition_row
    where composition_row.id = p_source_composition_id
      and composition_row.matchday_id = p_source_matchday_id
      and composition_row.status = 'published'
  ) then
    raise exception
      'matchday-live-layout-historical-v20-public-transition-invalid';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as source_desk
    where source_desk.matchday_id = p_source_matchday_id
      and not source_desk.is_managed
      and source_desk.carryover_source_composition_id is null
      and source_desk.carryover_snapshot is null
  ) then
    raise exception 'matchday-live-layout-historical-v20-source-not-retired';
  end if;

  if (
    select pg_catalog.count(*)
    from public.matchday_live_layout_zones as zone_row
    where zone_row.matchday_id = p_source_matchday_id
  ) <> (
    select pg_catalog.count(*)
    from jornada_private.matchday_live_layout_physical_zone_maps as map_row
    where map_row.topology_transition_id = v_handoff.topology_transition_id
      and map_row.source_matchday_id = p_source_matchday_id
      and map_row.target_matchday_id = p_target_matchday_id
  ) then
    raise exception 'matchday-live-layout-historical-v20-topology-changed';
  end if;

  if (
    select pg_catalog.count(*)
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_source_matchday_id
  ) <> v_carryover.inherited_placement_count or (
    select pg_catalog.count(*)
    from public.matchday_editorial_profile_manual_overrides as override_row
    where override_row.matchday_id = p_source_matchday_id
      and override_row.placement_target = 'bank'
  ) <> v_carryover.inherited_explicit_bank_count or (
    select pg_catalog.count(*)
    from public.matchday_live_layout_bank_item_state_memory as memory_row
    where memory_row.matchday_id = p_source_matchday_id
  ) <> v_carryover.inherited_memory_count then
    raise exception 'matchday-live-layout-historical-v20-physical-count-changed';
  end if;

  v_components := jornada_private
    .matchday_historical_physical_archive_components_v20(
      p_source_matchday_id
    );

  if v_components ->> 'zones' is distinct from v_certificate.zones_hash then
    raise exception 'matchday-live-layout-historical-v20-zones-changed';
  elsif v_components ->> 'blocks' is distinct from v_certificate.blocks_hash then
    raise exception 'matchday-live-layout-historical-v20-blocks-changed';
  elsif v_components ->> 'settings' is distinct from
        v_certificate.settings_hash then
    raise exception 'matchday-live-layout-historical-v20-settings-changed';
  elsif v_components ->> 'cutover' is distinct from
        v_certificate.cutover_hash then
    raise exception 'matchday-live-layout-historical-v20-cutover-changed';
  elsif v_components ->> 'assignment' is distinct from
        v_certificate.assignment_hash then
    raise exception 'matchday-live-layout-historical-v20-assignment-changed';
  elsif v_components ->> 'placements' is distinct from
        v_certificate.placements_hash then
    raise exception 'matchday-live-layout-historical-v20-placements-changed';
  elsif v_components ->> 'explicit_bank' is distinct from
        v_certificate.explicit_bank_hash then
    raise exception 'matchday-live-layout-historical-v20-explicit-bank-changed';
  elsif v_components ->> 'memory' is distinct from v_certificate.memory_hash then
    raise exception 'matchday-live-layout-historical-v20-memory-changed';
  elsif pg_catalog.md5(v_components::text) is distinct from
        v_certificate.physical_core_hash then
    raise exception 'matchday-live-layout-historical-v20-core-changed';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.assert_matchday_live_layout_historical_republish_v19(p_source_matchday_id uuid, p_target_matchday_id uuid, p_source_composition_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_handoff
    jornada_private.matchday_live_layout_physical_handoffs%rowtype;
begin
  if p_source_matchday_id is null
    or p_target_matchday_id is null
    or p_source_composition_id is null
    or p_source_matchday_id = p_target_matchday_id
  then
    raise exception
      'matchday-live-layout-historical-v19-invalid-envelope';
  end if;

  select handoff_row.*
  into v_handoff
  from jornada_private.matchday_live_layout_physical_handoffs as handoff_row
  where handoff_row.source_matchday_id = p_source_matchday_id
    and handoff_row.target_matchday_id = p_target_matchday_id
    and handoff_row.source_composition_id = p_source_composition_id;

  if not found then
    raise exception
      'matchday-live-layout-historical-v19-certificate-missing';
  end if;

  if not exists (
    select 1
    from jornada_private.matchday_live_layout_physical_topology_transitions
      as topology_row
    where topology_row.id = v_handoff.topology_transition_id
      and topology_row.source_matchday_id = p_source_matchday_id
      and topology_row.target_matchday_id = p_target_matchday_id
      and topology_row.profile_key = v_handoff.profile_key
  ) then
    raise exception
      'matchday-live-layout-historical-v19-topology-certificate-invalid';
  end if;

  if not exists (
    select 1
    from jornada_private.matchday_live_layout_physical_carryovers
      as carryover_row
    where carryover_row.id = v_handoff.carryover_id
      and carryover_row.topology_transition_id =
          v_handoff.topology_transition_id
      and carryover_row.source_matchday_id = p_source_matchday_id
      and carryover_row.target_matchday_id = p_target_matchday_id
      and carryover_row.source_composition_id = p_source_composition_id
      and carryover_row.profile_key = v_handoff.profile_key
      and carryover_row.state_token_after = v_handoff.target_state_token
  ) then
    raise exception
      'matchday-live-layout-historical-v19-carryover-certificate-invalid';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_continuity_transitions as transition_row
    where transition_row.source_matchday_id = p_source_matchday_id
      and transition_row.target_matchday_id = p_target_matchday_id
      and transition_row.source_composition_id = p_source_composition_id
      and transition_row.continuity_version = 19
  ) then
    raise exception
      'matchday-live-layout-historical-v19-public-transition-invalid';
  end if;

  if not exists (
    select 1
    from public.matchday_reference_compositions as composition_row
    where composition_row.id = p_source_composition_id
      and composition_row.matchday_id = p_source_matchday_id
      and composition_row.status = 'published'
  ) then
    raise exception
      'matchday-live-layout-historical-v19-source-composition-invalid';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as source_desk
    where source_desk.matchday_id = p_source_matchday_id
      and not source_desk.is_managed
      and source_desk.carryover_source_composition_id is null
      and source_desk.carryover_snapshot is null
  ) then
    raise exception
      'matchday-live-layout-historical-v19-source-not-retired';
  end if;

  if jornada_private.matchday_live_layout_physical_archive_hash_v19(
       p_source_matchday_id
     ) is distinct from v_handoff.source_archive_hash
  then
    raise exception
      'matchday-live-layout-historical-v19-source-archive-changed';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.assert_matchday_live_layout_legacy_writer_v14(p_matchday_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_matchday_id is null then
    raise exception 'matchday-live-layout-legacy-v14-matchday-required';
  end if;

  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-live-layout-legacy-v14-matchday-not-found';
  end if;

  if exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = p_matchday_id
  ) then
    raise exception 'matchday-live-layout-legacy-writer-after-physical-cutover';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.assert_matchday_live_layout_physical_carryover_v18(p_source_matchday_id uuid, p_target_matchday_id uuid, p_source_composition_id uuid, p_topology_transition_id uuid, p_profile_key text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_source_matchday_id is null
    or p_target_matchday_id is null
    or p_source_composition_id is null
    or p_topology_transition_id is null
    or p_profile_key is null
    or p_source_matchday_id = p_target_matchday_id
  then
    raise exception 'matchday-live-layout-carryover-v18-invalid-envelope';
  end if;

  if not exists (
    select 1
    from jornada_private.matchday_live_layout_physical_topology_transitions as transition_row
    where transition_row.id = p_topology_transition_id
      and transition_row.source_matchday_id = p_source_matchday_id
      and transition_row.target_matchday_id = p_target_matchday_id
      and transition_row.profile_key = p_profile_key
  ) then
    raise exception 'matchday-live-layout-carryover-v18-topology-invalid';
  end if;

  if not exists (
    select 1
    from public.matchday_reference_compositions as composition_row
    where composition_row.id = p_source_composition_id
      and composition_row.matchday_id = p_source_matchday_id
      and composition_row.status = 'published'
      and composition_row.is_current = true
  ) then
    raise exception 'matchday-live-layout-carryover-v18-composition-invalid';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as desk_row
    where desk_row.matchday_id = p_source_matchday_id
      and desk_row.is_managed = true
  ) then
    raise exception 'matchday-live-layout-carryover-v18-source-not-live';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_desk_control as desk_row
    where desk_row.matchday_id = p_target_matchday_id
      and (
        desk_row.is_managed
        or desk_row.carryover_source_composition_id is not null
        or desk_row.carryover_snapshot is not null
      )
  ) then
    raise exception 'matchday-live-layout-carryover-v18-target-desk-conflict';
  end if;

  perform jornada_private.assert_matchday_live_layout_physical_topology_source_v17(
    p_source_matchday_id,
    p_profile_key
  );

  perform jornada_private.assert_matchday_live_layout_physical_topology_source_v17(
    p_target_matchday_id,
    p_profile_key
  );

  perform jornada_private.assert_matchday_live_layout_downstream_v14(
    p_source_matchday_id,
    p_profile_key
  );

  if not exists (
    select 1
    from public.matchday_editorial_profile_assignments as assignment_row
    where assignment_row.matchday_id = p_target_matchday_id
      and assignment_row.profile_key = p_profile_key
  ) then
    raise exception 'matchday-live-layout-carryover-v18-target-profile-invalid';
  end if;

  if (
    select pg_catalog.count(*)
    from jornada_private.matchday_live_layout_physical_zone_maps as map_row
    where map_row.topology_transition_id = p_topology_transition_id
      and map_row.source_matchday_id = p_source_matchday_id
      and map_row.target_matchday_id = p_target_matchday_id
  ) <> (
    select pg_catalog.count(*)
    from public.matchday_live_layout_zones as source_zone
    where source_zone.matchday_id = p_source_matchday_id
  ) or (
    select pg_catalog.count(*)
    from jornada_private.matchday_live_layout_physical_zone_maps as map_row
    where map_row.topology_transition_id = p_topology_transition_id
      and map_row.source_matchday_id = p_source_matchday_id
      and map_row.target_matchday_id = p_target_matchday_id
  ) <> (
    select pg_catalog.count(*)
    from public.matchday_live_layout_zones as target_zone
    where target_zone.matchday_id = p_target_matchday_id
  ) then
    raise exception 'matchday-live-layout-carryover-v18-zone-map-incomplete';
  end if;

  if exists (
    select 1
    from jornada_private.matchday_live_layout_physical_zone_maps as map_row
    join public.matchday_live_layout_zones as source_zone
      on source_zone.id = map_row.source_zone_id
     and source_zone.matchday_id = map_row.source_matchday_id
    join public.matchday_live_layout_zones as target_zone
      on target_zone.id = map_row.target_zone_id
     and target_zone.matchday_id = map_row.target_matchday_id
    where map_row.topology_transition_id = p_topology_transition_id
      and (
        target_zone.public_title is distinct from source_zone.public_title
        or target_zone.visual_family is distinct from source_zone.visual_family
      )
  ) then
    raise exception 'matchday-live-layout-carryover-v18-zone-map-drift';
  end if;

  if exists (
    with desired as materialized (
      select
        source_block.block_type,
        case when source_block.block_type = 'zone'
          then map_row.target_zone_id else null end as zone_id,
        source_block.sort_order
      from public.matchday_live_layout_blocks as source_block
      left join jornada_private.matchday_live_layout_physical_zone_maps as map_row
        on map_row.topology_transition_id = p_topology_transition_id
       and map_row.source_zone_id = source_block.zone_id
      where source_block.matchday_id = p_source_matchday_id
    ),
    current_state as materialized (
      select target_block.block_type, target_block.zone_id, target_block.sort_order
      from public.matchday_live_layout_blocks as target_block
      where target_block.matchday_id = p_target_matchday_id
    ),
    differences as (
      (select * from desired except select * from current_state)
      union all
      (select * from current_state except select * from desired)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-carryover-v18-block-map-drift';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_workspace_settings as source_settings
    cross join public.matchday_live_layout_workspace_settings as target_settings
    where source_settings.matchday_id = p_source_matchday_id
      and target_settings.matchday_id = p_target_matchday_id
      and row(
        source_settings.faixa_slot_count,
        source_settings.headline_title_color,
        source_settings.latest_zone_placement,
        source_settings.latest_zone_title,
        source_settings.latest_zone_mode,
        source_settings.latest_zone_title_color,
        source_settings.video_module_active
      ) is distinct from row(
        target_settings.faixa_slot_count,
        target_settings.headline_title_color,
        target_settings.latest_zone_placement,
        target_settings.latest_zone_title,
        target_settings.latest_zone_mode,
        target_settings.latest_zone_title_color,
        target_settings.video_module_active
      )
  ) then
    raise exception 'matchday-live-layout-carryover-v18-settings-drift';
  end if;

  if exists (
    with desired as materialized (
      select source_projection.legacy_zone_key, map_row.target_zone_id as zone_id
      from jornada_private.matchday_live_layout_zone_legacy_projection as source_projection
      join jornada_private.matchday_live_layout_physical_zone_maps as map_row
        on map_row.topology_transition_id = p_topology_transition_id
       and map_row.source_zone_id = source_projection.zone_id
      where source_projection.matchday_id = p_source_matchday_id
    ),
    current_state as materialized (
      select target_projection.legacy_zone_key, target_projection.zone_id
      from jornada_private.matchday_live_layout_zone_legacy_projection as target_projection
      where target_projection.matchday_id = p_target_matchday_id
    ),
    differences as (
      (select * from desired except select * from current_state)
      union all
      (select * from current_state except select * from desired)
    )
    select 1 from differences
  ) then
    raise exception 'matchday-live-layout-carryover-v18-projection-drift';
  end if;

  if exists (
    select 1
    from jornada_private.matchday_live_layout_physical_carryovers as row_value
    where row_value.topology_transition_id = p_topology_transition_id
       or row_value.source_matchday_id = p_source_matchday_id
       or row_value.target_matchday_id = p_target_matchday_id
  ) then
    raise exception 'matchday-live-layout-carryover-v18-already-materialized';
  end if;

  if exists (select 1 from public.matchday_editorial_bank_items where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_live_layout_placements where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_live_layout_bank_item_state_memory where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_editorial_profile_manual_overrides where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_editorial_profile_state_items where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_editorial_profile_reconcile_control where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_editorial_profile_zone_items where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_editorials where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_highlights where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_horizontal_news where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_latest_news where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_roundup_items where matchday_id = p_target_matchday_id)
  or exists (select 1 from public.matchday_live_layout_items where matchday_id = p_target_matchday_id)
  or exists (
    select 1 from public.matchday_editorial_continuity_transitions
    where source_matchday_id = p_source_matchday_id
       or target_matchday_id = p_target_matchday_id
  ) then
    raise exception 'matchday-live-layout-carryover-v18-target-not-virgin';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_source_matchday_id
      and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
      and (
        nullif(pg_catalog.btrim(bank_row.source_type), '') is null
        or nullif(pg_catalog.btrim(bank_row.source_id), '') is null
      )
  ) or exists (
    select 1
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_source_matchday_id
      and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
    group by
      pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)),
      pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
    having pg_catalog.count(*) <> 1
  ) then
    raise exception 'matchday-live-layout-carryover-v18-source-bank-invalid';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_source_matchday_id
      and (
        pg_catalog.num_nonnulls(
          bank_row.classification_key,
          bank_row.classification_source,
          bank_row.classified_at
        ) not in (0, 3)
        or (
          bank_row.classification_key is not null
          and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) <> 'editorial_article'
        )
      )
  ) then
    raise exception 'matchday-live-layout-carryover-v18-source-classification-invalid';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = placement_row.bank_item_id
     and bank_row.matchday_id = placement_row.matchday_id
    where placement_row.matchday_id = p_source_matchday_id
      and (
        bank_row.id is null
        or pg_catalog.lower(pg_catalog.btrim(bank_row.status)) <> 'active'
      )
  ) then
    raise exception 'matchday-live-layout-carryover-v18-placement-inactive';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    left join jornada_private.matchday_live_layout_physical_zone_maps as map_row
      on map_row.topology_transition_id = p_topology_transition_id
     and map_row.source_zone_id = placement_row.zone_id
    where placement_row.matchday_id = p_source_matchday_id
      and placement_row.placement_type = 'zone'
      and map_row.target_zone_id is null
  ) then
    raise exception 'matchday-live-layout-carryover-v18-placement-zone-unmapped';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_profile_manual_overrides as override_row
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.matchday_id = override_row.matchday_id
     and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) = pg_catalog.lower(pg_catalog.btrim(override_row.source_type))
     and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) = pg_catalog.lower(pg_catalog.btrim(override_row.source_id))
     and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
    where override_row.matchday_id = p_source_matchday_id
      and override_row.profile_key = p_profile_key
      and override_row.placement_target = 'bank'
      and bank_row.id is null
  ) then
    raise exception 'matchday-live-layout-carryover-v18-explicit-bank-inactive';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_bank_items as bank_row
    join public.matchday_editorial_profile_manual_overrides as override_row
      on override_row.matchday_id = bank_row.matchday_id
     and override_row.profile_key = p_profile_key
     and override_row.placement_target = 'bank'
     and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) = pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
     and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) = pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
    where bank_row.matchday_id = p_source_matchday_id
      and (
        exists (
          select 1 from public.matchday_live_layout_placements as placement_row
          where placement_row.matchday_id = bank_row.matchday_id
            and placement_row.bank_item_id = bank_row.id
        )
        or exists (
          select 1 from public.matchday_live_layout_bank_item_state_memory as memory_row
          where memory_row.matchday_id = bank_row.matchday_id
            and memory_row.bank_item_id = bank_row.id
        )
      )
  ) then
    raise exception 'matchday-live-layout-carryover-v18-explicit-bank-conflict';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_bank_item_state_memory as memory_row
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.id = memory_row.bank_item_id
     and bank_row.matchday_id = memory_row.matchday_id
    where memory_row.matchday_id = p_source_matchday_id
      and (
        bank_row.id is null
        or pg_catalog.lower(pg_catalog.btrim(bank_row.status)) <> 'active'
        or exists (
          select 1 from public.matchday_live_layout_placements as placement_row
          where placement_row.matchday_id = memory_row.matchday_id
            and placement_row.bank_item_id = memory_row.bank_item_id
        )
      )
  ) then
    raise exception 'matchday-live-layout-carryover-v18-memory-conflict';
  end if;

  if exists (
    select 1
    from public.matchday_latest_news as latest_row
    join lateral (
      select article_row.id
      from public.editorial_articles as article_row
      where article_row.slug = pg_catalog.substr(
              pg_catalog.regexp_replace(
                pg_catalog.split_part(
                  pg_catalog.split_part(coalesce(pg_catalog.btrim(latest_row.link_url), ''), '?', 1),
                  '#', 1
                ),
                '/$', ''
              ),
              pg_catalog.char_length('/noticias/') + 1
            )
        and article_row.status = 'published'
        and (article_row.matchday_id is null or article_row.matchday_id = p_source_matchday_id)
      order by
        case when article_row.matchday_id = p_source_matchday_id then 0 else 1 end,
        article_row.published_at desc nulls last,
        article_row.updated_at desc nulls last,
        article_row.id
      limit 1
    ) as canonical_row on true
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.matchday_id = p_source_matchday_id
     and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) = 'editorial_article'
     and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) = pg_catalog.lower(canonical_row.id::text)
     and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
    where latest_row.matchday_id = p_source_matchday_id
      and pg_catalog.lower(pg_catalog.btrim(latest_row.status)) = 'published'
      and pg_catalog.regexp_replace(
            pg_catalog.split_part(
              pg_catalog.split_part(coalesce(pg_catalog.btrim(latest_row.link_url), ''), '?', 1), '#', 1
            ), '/$', ''
          ) like '/noticias/%'
      and bank_row.id is null
  ) then
    raise exception 'matchday-live-layout-carryover-v18-latest-provenance-invalid';
  end if;

  if exists (
    select 1
    from public.matchday_latest_news as latest_row
    join lateral (
      select content_row.id
      from public.editorial_contents as content_row
      where content_row.slug = pg_catalog.substr(
              pg_catalog.regexp_replace(
                pg_catalog.split_part(
                  pg_catalog.split_part(coalesce(pg_catalog.btrim(latest_row.link_url), ''), '?', 1),
                  '#', 1
                ),
                '/$', ''
              ),
              pg_catalog.char_length('/conteudos/') + 1
            )
        and content_row.status = 'published'
        and (content_row.matchday_id is null or content_row.matchday_id = p_source_matchday_id)
      order by
        case when content_row.matchday_id = p_source_matchday_id then 0 else 1 end,
        content_row.published_at desc nulls last,
        content_row.updated_at desc nulls last,
        content_row.id
      limit 1
    ) as canonical_row on true
    left join public.matchday_editorial_bank_items as bank_row
      on bank_row.matchday_id = p_source_matchday_id
     and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) = 'editorial_content'
     and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) = pg_catalog.lower(canonical_row.id::text)
     and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
    where latest_row.matchday_id = p_source_matchday_id
      and pg_catalog.lower(pg_catalog.btrim(latest_row.status)) = 'published'
      and pg_catalog.regexp_replace(
            pg_catalog.split_part(
              pg_catalog.split_part(coalesce(pg_catalog.btrim(latest_row.link_url), ''), '?', 1), '#', 1
            ), '/$', ''
          ) like '/conteudos/%'
      and bank_row.id is null
  ) then
    raise exception 'matchday-live-layout-carryover-v18-latest-provenance-invalid';
  end if;

  if exists (
    select 1
    from public.matchday_editorials as editorial_row
    where editorial_row.matchday_id = p_source_matchday_id
      and editorial_row.complementary_roundup_item_id is not null
      and not exists (
        select 1
        from public.matchday_roundup_items as roundup_row
        where roundup_row.id = editorial_row.complementary_roundup_item_id
          and roundup_row.matchday_id = p_source_matchday_id
      )
  ) then
    raise exception 'matchday-live-layout-carryover-v18-roundup-reference-invalid';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.assert_matchday_live_layout_physical_handoff_complete_v19(p_source_matchday_id uuid, p_target_matchday_id uuid, p_source_composition_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_handoff jornada_private.matchday_live_layout_physical_handoffs%rowtype;
  v_current_token text;
begin
  select handoff_row.*
  into v_handoff
  from jornada_private.matchday_live_layout_physical_handoffs as handoff_row
  where handoff_row.source_matchday_id = p_source_matchday_id
    and handoff_row.target_matchday_id = p_target_matchday_id
    and handoff_row.source_composition_id = p_source_composition_id;

  if not found then
    raise exception 'matchday-live-layout-handoff-v19-certificate-missing';
  end if;

  perform jornada_private.assert_matchday_live_layout_physical_handoff_ready_v19(
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id,
    v_handoff.topology_transition_id,
    v_handoff.carryover_id
  );

  if not exists (
    select 1
    from public.matchday_editorial_continuity_transitions as transition_row
    where transition_row.source_matchday_id = p_source_matchday_id
      and transition_row.target_matchday_id = p_target_matchday_id
      and transition_row.source_composition_id = p_source_composition_id
      and transition_row.continuity_version = 19
  ) then
    raise exception 'matchday-live-layout-handoff-v19-public-certificate-invalid';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_desk_control as source_desk
    where source_desk.matchday_id = p_source_matchday_id
      and (
        source_desk.is_managed
        or source_desk.carryover_source_composition_id is not null
        or source_desk.carryover_snapshot is not null
      )
  ) or not exists (
    select 1
    from public.matchday_editorial_desk_control as target_desk
    where target_desk.matchday_id = p_target_matchday_id
      and target_desk.is_managed
      and target_desk.carryover_source_composition_id is null
      and target_desk.carryover_snapshot is null
  ) then
    raise exception 'matchday-live-layout-handoff-v19-desk-postcondition';
  end if;

  if jornada_private.matchday_live_layout_physical_archive_hash_v19(
       p_source_matchday_id
     ) is distinct from v_handoff.source_archive_hash
  then
    raise exception 'matchday-live-layout-handoff-v19-source-archive-changed';
  end if;

  select workspace_row.state_token
  into v_current_token
  from public.read_matchday_live_layout_workspace_v13(
    p_target_matchday_id,
    v_handoff.profile_key
  ) as workspace_row;

  if v_current_token is distinct from v_handoff.target_state_token then
    raise exception 'matchday-live-layout-handoff-v19-final-token-drift';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.assert_matchday_live_layout_physical_topology_source_v17(p_matchday_id uuid, p_profile_key text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_settings public.matchday_live_layout_workspace_settings%rowtype;
begin
  if p_matchday_id is null or p_profile_key is null then
    raise exception 'matchday-live-layout-topology-v17-source-invalid-input';
  end if;

  if not exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as marker_row
    where marker_row.matchday_id = p_matchday_id
      and marker_row.profile_key = p_profile_key
  ) then
    raise exception 'matchday-live-layout-topology-v17-source-not-physical';
  end if;

  select settings_row.*
  into v_settings
  from public.matchday_live_layout_workspace_settings as settings_row
  where settings_row.matchday_id = p_matchday_id;

  if not found then
    raise exception
      'matchday-live-layout-topology-v17-source-authority-incoherent';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_profile_assignments as assignment_row
    where assignment_row.matchday_id = p_matchday_id
      and assignment_row.profile_key = p_profile_key
  ) then
    raise exception 'matchday-live-layout-topology-v17-source-profile-invalid';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_zones as zone_row
    where zone_row.matchday_id = p_matchday_id
      and (
        pg_catalog.char_length(pg_catalog.btrim(zone_row.public_title)) > 120
        or jornada_private.matchday_live_layout_layout_capacity_v20(
             zone_row.visual_family
           ) is null
      )
  ) then
    raise exception 'matchday-live-layout-topology-v17-source-zone-invalid';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = p_matchday_id
      and (
        block_row.block_type not in ('zone', 'latest', 'video')
        or block_row.sort_order <= 0
        or block_row.sort_order > 1000000000
        or not (
          (block_row.block_type = 'zone' and block_row.zone_id is not null)
          or (
            block_row.block_type in ('latest', 'video')
            and block_row.zone_id is null
          )
        )
      )
  ) or exists (
    select 1
    from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = p_matchday_id
    group by block_row.sort_order
    having pg_catalog.count(*) <> 1
  ) or exists (
    select 1
    from public.matchday_live_layout_zones as zone_row
    where zone_row.matchday_id = p_matchday_id
      and (
        select pg_catalog.count(*)
        from public.matchday_live_layout_blocks as block_row
        where block_row.matchday_id = p_matchday_id
          and block_row.block_type = 'zone'
          and block_row.zone_id = zone_row.id
      ) <> 1
  ) or (
    select pg_catalog.count(*)
    from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = p_matchday_id
      and block_row.block_type = 'latest'
  ) <> 1 or (
    select pg_catalog.count(*)
    from public.matchday_live_layout_blocks as block_row
    where block_row.matchday_id = p_matchday_id
      and block_row.block_type = 'video'
  ) > 1 then
    raise exception 'matchday-live-layout-topology-v17-source-blocks-invalid';
  end if;

  if exists (
    select 1
    from public.matchday_live_layout_blocks as block_row
    left join public.matchday_live_layout_zones as zone_row
      on zone_row.id = block_row.zone_id
     and zone_row.matchday_id = block_row.matchday_id
    where block_row.matchday_id = p_matchday_id
      and block_row.block_type = 'zone'
      and zone_row.id is null
  ) then
    raise exception 'matchday-live-layout-topology-v17-source-block-zone-invalid';
  end if;

  -- No legacy projection cardinality is consulted. V18 and the marker-first
  -- v19 dispatcher call this validator and therefore inherit this boundary.
  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    left join public.matchday_live_layout_zones as zone_row
      on zone_row.id = placement_row.zone_id
     and zone_row.matchday_id = placement_row.matchday_id
    where placement_row.matchday_id = p_matchday_id
      and (
        (
          placement_row.placement_type = 'zone'
          and (
            zone_row.id is null
            or placement_row.slot_position >
               jornada_private.matchday_live_layout_layout_capacity_v20(
                 zone_row.visual_family
               )
          )
        )
        or (
          placement_row.placement_type = 'faixa'
          and placement_row.slot_position > v_settings.faixa_slot_count
        )
        or (
          placement_row.placement_type = 'video_highlight'
          and (
            not v_settings.video_module_active
            or not exists (
              select 1
              from public.matchday_live_layout_blocks as video_block
              where video_block.matchday_id = p_matchday_id
                and video_block.block_type = 'video'
            )
          )
        )
      )
  ) or exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_matchday_id
    group by placement_row.bank_item_id
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-live-layout-topology-v17-source-placement-invalid';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.assert_physical_cutover_has_no_selection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = new.matchday_id
      and placement_row.placement_type = 'selection'
  )
  then
    raise exception
      'matchday-live-layout-physical-selection-retired';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.carry_matchday_live_layout_latest_companion_v25()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_transition_id uuid;
  v_source_matchday_id uuid;
  v_source_zone_id uuid;
  v_target_zone_id uuid;
begin
  select
    transition_row.id,
    transition_row.source_matchday_id
  into
    v_transition_id,
    v_source_matchday_id
  from jornada_private.matchday_live_layout_physical_topology_transitions
    as transition_row
  where transition_row.target_matchday_id = new.matchday_id;

  if not found then
    return new;
  end if;

  select companion_row.zone_id
  into v_source_zone_id
  from public.matchday_live_layout_latest_companion as companion_row
  where companion_row.matchday_id = v_source_matchday_id;

  if not found then
    return new;
  end if;

  select map_row.target_zone_id
  into v_target_zone_id
  from jornada_private.matchday_live_layout_physical_zone_maps as map_row
  where map_row.topology_transition_id = v_transition_id
    and map_row.source_zone_id = v_source_zone_id;

  if not found then
    raise exception
      'matchday-live-layout-latest-companion-v25-zone-map-missing';
  end if;

  insert into public.matchday_live_layout_latest_companion (
    matchday_id,
    zone_id,
    created_at,
    updated_at
  )
  values (
    new.matchday_id,
    v_target_zone_id,
    pg_catalog.statement_timestamp(),
    pg_catalog.statement_timestamp()
  )
  on conflict (matchday_id)
  do update
  set zone_id = excluded.zone_id,
      updated_at = excluded.updated_at;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.enqueue_matchday_live_layout_placement_shadow_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_legacy_changed boolean := true;
  v_bank_changed boolean := false;
  v_matchday_id uuid;
begin
  if tg_table_schema = 'public'
    and tg_table_name = 'matchday_editorial_bank_items'
  then
    v_legacy_changed := false;
    v_bank_changed := tg_op = 'DELETE';

    if tg_op in ('INSERT', 'UPDATE') then
      v_bank_changed := v_bank_changed or exists (
        select 1
        from public.matchday_live_layout_placements as placement_row
        where placement_row.matchday_id = new.matchday_id
          and placement_row.bank_item_id = new.id
      );
    end if;

    if tg_op = 'UPDATE' then
      v_bank_changed := v_bank_changed or exists (
        select 1
        from public.matchday_live_layout_placements as placement_row
        where placement_row.matchday_id = old.matchday_id
          and placement_row.bank_item_id = old.id
      );
    end if;

    if not v_bank_changed then
      return null;
    end if;
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    v_matchday_id := old.matchday_id;

    perform jornada_private.assert_matchday_live_layout_projection_write_v14(
      v_matchday_id,
      v_legacy_changed
    );

    if not (
      jornada_private.is_matchday_live_layout_physical_v14(v_matchday_id)
      and jornada_private.is_matchday_live_layout_downstream_v14(v_matchday_id)
    ) then
      insert into jornada_private.matchday_live_layout_placement_shadow_sync_queue (
        backend_pid,
        transaction_id,
        matchday_id,
        legacy_changed,
        bank_changed
      ) values (
        pg_catalog.pg_backend_pid(),
        pg_catalog.pg_current_xact_id(),
        v_matchday_id,
        v_legacy_changed,
        v_bank_changed
      )
      on conflict (backend_pid, transaction_id, matchday_id)
      do update set
        legacy_changed =
          jornada_private.matchday_live_layout_placement_shadow_sync_queue.legacy_changed
          or excluded.legacy_changed,
        bank_changed =
          jornada_private.matchday_live_layout_placement_shadow_sync_queue.bank_changed
          or excluded.bank_changed;
    end if;
  end if;

  if tg_op in ('INSERT', 'UPDATE') then
    v_matchday_id := new.matchday_id;

    perform jornada_private.assert_matchday_live_layout_projection_write_v14(
      v_matchday_id,
      v_legacy_changed
    );

    if not (
      jornada_private.is_matchday_live_layout_physical_v14(v_matchday_id)
      and jornada_private.is_matchday_live_layout_downstream_v14(v_matchday_id)
    ) then
      insert into jornada_private.matchday_live_layout_placement_shadow_sync_queue (
        backend_pid,
        transaction_id,
        matchday_id,
        legacy_changed,
        bank_changed
      ) values (
        pg_catalog.pg_backend_pid(),
        pg_catalog.pg_current_xact_id(),
        v_matchday_id,
        v_legacy_changed,
        v_bank_changed
      )
      on conflict (backend_pid, transaction_id, matchday_id)
      do update set
        legacy_changed =
          jornada_private.matchday_live_layout_placement_shadow_sync_queue.legacy_changed
          or excluded.legacy_changed,
        bank_changed =
          jornada_private.matchday_live_layout_placement_shadow_sync_queue.bank_changed
          or excluded.bank_changed;
    end if;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.enqueue_matchday_live_layout_shadow_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matchday_id uuid;
begin
  if tg_op = 'DELETE' then
    v_matchday_id := old.matchday_id;
  else
    v_matchday_id := new.matchday_id;
  end if;

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = v_matchday_id
  for update;

  if exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = v_matchday_id
  ) then
    if not jornada_private.is_matchday_live_layout_downstream_v14(
      v_matchday_id
    ) then
      raise exception 'matchday-live-layout-legacy-topology-after-physical-cutover';
    end if;

    -- Authorized downstream materialization never queues a reverse sync.
    return null;
  end if;

  insert into jornada_private.matchday_live_layout_shadow_sync_queue (
    backend_pid,
    transaction_id,
    matchday_id
  ) values (
    pg_catalog.pg_backend_pid(),
    pg_catalog.pg_current_xact_id(),
    v_matchday_id
  )
  on conflict (backend_pid, transaction_id, matchday_id)
  do nothing;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.flush_matchday_live_layout_shadow_sync_queue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matchday_ids uuid[];
begin
  select pg_catalog.array_agg(
    queue_row.matchday_id
    order by queue_row.matchday_id
  )
  into v_matchday_ids
  from jornada_private.matchday_live_layout_shadow_sync_queue as queue_row
  where queue_row.backend_pid = pg_catalog.pg_backend_pid()
    and queue_row.transaction_id = pg_catalog.pg_current_xact_id();

  if v_matchday_ids is null
    or pg_catalog.cardinality(v_matchday_ids) = 0
  then
    return null;
  end if;

  perform jornada_private.sync_matchday_live_layout_shadow(
    v_matchday_ids
  );

  delete from jornada_private.matchday_live_layout_shadow_sync_queue
  where backend_pid = pg_catalog.pg_backend_pid()
    and transaction_id = pg_catalog.pg_current_xact_id();

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.materialize_matchday_live_layout_physical_handoff_v19(p_source_matchday_id uuid, p_target_matchday_id uuid, p_source_composition_id uuid, p_operation text DEFAULT 'normal'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation text := pg_catalog.lower(pg_catalog.btrim(p_operation));
  v_source_season_id uuid;
  v_target_season_id uuid;
  v_source_number integer;
  v_target_number integer;
  v_profile_key text;
  v_topology record;
  v_carryover record;
  v_topology_id uuid;
  v_carryover_id uuid;
  v_source_archive_hash text;
  v_target_state_token text;
  v_existing_handoff jornada_private.matchday_live_layout_physical_handoffs%rowtype;
  v_outcome text;
begin
  if p_source_matchday_id is null
    or p_target_matchday_id is null
    or p_source_composition_id is null
    or p_source_matchday_id = p_target_matchday_id
    or v_operation not in ('normal', 'recovery')
  then
    raise exception 'matchday-live-layout-handoff-v19-invalid-envelope';
  end if;

  perform jornada_private.acquire_matchday_live_desk_handoff_lock();
  perform jornada_private.acquire_matchday_live_layout_cutover_core_lock();

  perform 1
  from public.matchdays as lock_row
  where lock_row.id in (p_source_matchday_id, p_target_matchday_id)
  order by lock_row.id
  for update;

  if (
    select pg_catalog.count(*)
    from public.matchdays as matchday_row
    where matchday_row.id in (p_source_matchday_id, p_target_matchday_id)
  ) <> 2 then
    raise exception 'matchday-live-layout-handoff-v19-matchday-not-found';
  end if;

  if jornada_private.matchday_live_layout_continuity_authority_v19(
       p_source_matchday_id
     ) <> 'physical'
  then
    raise exception 'matchday-live-layout-handoff-v19-source-not-physical';
  end if;

  select source_row.season_id, source_row.number,
         target_row.season_id, target_row.number
  into v_source_season_id, v_source_number,
       v_target_season_id, v_target_number
  from public.matchdays as source_row
  cross join public.matchdays as target_row
  where source_row.id = p_source_matchday_id
    and target_row.id = p_target_matchday_id;

  if v_source_season_id is distinct from v_target_season_id
    or v_target_number <> v_source_number + 1
  then
    raise exception 'matchday-live-layout-handoff-v19-target-not-consecutive';
  end if;

  select marker_row.profile_key
  into v_profile_key
  from jornada_private.matchday_live_layout_physical_cutovers as marker_row
  where marker_row.matchday_id = p_source_matchday_id;

  select handoff_row.*
  into v_existing_handoff
  from jornada_private.matchday_live_layout_physical_handoffs as handoff_row
  where handoff_row.source_matchday_id = p_source_matchday_id
     or handoff_row.target_matchday_id = p_target_matchday_id
  for update;

  if found then
    if v_existing_handoff.source_matchday_id <> p_source_matchday_id
      or v_existing_handoff.target_matchday_id <> p_target_matchday_id
      or v_existing_handoff.source_composition_id <> p_source_composition_id
    then
      raise exception 'matchday-live-layout-handoff-v19-certificate-conflict';
    end if;

    if v_operation = 'normal' then
      raise exception 'matchday-live-layout-handoff-v19-already-complete';
    end if;

    perform jornada_private.assert_matchday_live_layout_physical_handoff_complete_v19(
      p_source_matchday_id,
      p_target_matchday_id,
      p_source_composition_id
    );

    select carryover_row.*
    into v_carryover
    from jornada_private.matchday_live_layout_physical_carryovers as carryover_row
    where carryover_row.id = v_existing_handoff.carryover_id;

    return pg_catalog.jsonb_build_object(
      'operation', 'recovery',
      'outcome', 'already_complete',
      'publishedCompositionId', p_source_composition_id,
      'sourceMatchdayId', p_source_matchday_id,
      'nextMatchdayId', p_target_matchday_id,
      'topologyTransitionId', v_existing_handoff.topology_transition_id,
      'carryoverId', v_existing_handoff.carryover_id,
      'handoffId', v_existing_handoff.id,
      'carryoverApplied', true,
      'materialized', true,
      'sourceRetired', true,
      'targetActivated', true,
      'inheritedBankCount', v_carryover.inherited_bank_count,
      'inheritedZoneCount', (
        select pg_catalog.count(*)
        from jornada_private.matchday_live_layout_physical_zone_maps as map_row
        where map_row.topology_transition_id = v_existing_handoff.topology_transition_id
      ),
      'inheritedPlacementCount', v_carryover.inherited_placement_count,
      'inheritedLatestCount', v_carryover.inherited_latest_count,
      'inheritedRoundupCount', v_carryover.inherited_roundup_count,
      'stateToken', v_existing_handoff.target_state_token
    );
  end if;

  if exists (
    select 1
    from public.matchday_editorial_continuity_transitions as transition_row
    where transition_row.source_matchday_id = p_source_matchday_id
       or transition_row.target_matchday_id = p_target_matchday_id
  ) then
    raise exception 'matchday-live-layout-handoff-v19-transition-conflict';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as source_desk
    where source_desk.matchday_id = p_source_matchday_id
      and source_desk.is_managed
  ) then
    raise exception 'matchday-live-layout-handoff-v19-source-not-live';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_desk_control as target_desk
    where target_desk.matchday_id = p_target_matchday_id
      and (
        target_desk.is_managed
        or target_desk.carryover_source_composition_id is not null
        or target_desk.carryover_snapshot is not null
      )
  ) then
    raise exception 'matchday-live-layout-handoff-v19-target-desk-conflict';
  end if;

  if exists (
    select 1
    from public.matchday_reference_compositions as target_composition
    where target_composition.matchday_id = p_target_matchday_id
      and target_composition.status = 'published'
      and target_composition.is_current
  ) then
    raise exception 'matchday-live-layout-handoff-v19-target-published';
  end if;

  if v_operation = 'normal' then
    if exists (
      select 1
      from jornada_private.matchday_live_layout_physical_topology_transitions as topology_row
      where topology_row.source_matchday_id = p_source_matchday_id
         or topology_row.target_matchday_id = p_target_matchday_id
    ) or exists (
      select 1
      from jornada_private.matchday_live_layout_physical_carryovers as carryover_row
      where carryover_row.source_matchday_id = p_source_matchday_id
         or carryover_row.target_matchday_id = p_target_matchday_id
    ) then
      raise exception 'matchday-live-layout-handoff-v19-normal-not-virgin';
    end if;

    p_source_composition_id := public.activate_matchday_reference_composition(
      p_source_matchday_id,
      p_source_composition_id,
      true
    );

    select *
    into v_topology
    from jornada_private.materialize_matchday_live_layout_physical_topology_v17(
      p_source_matchday_id,
      p_target_matchday_id
    );

    v_topology_id := v_topology.topology_transition_id;

    select *
    into v_carryover
    from jornada_private.materialize_matchday_live_layout_physical_carryover_v18(
      p_source_matchday_id,
      p_target_matchday_id,
      p_source_composition_id,
      v_topology_id
    );

    v_carryover_id := v_carryover.carryover_id;
    v_outcome := 'materialized';
  else
    if not exists (
      select 1
      from public.matchday_reference_compositions as composition_row
      where composition_row.id = p_source_composition_id
        and composition_row.matchday_id = p_source_matchday_id
        and composition_row.status = 'published'
        and composition_row.is_current
    ) then
      raise exception 'matchday-live-layout-handoff-v19-recovery-composition-invalid';
    end if;

    select topology_row.id
    into v_topology_id
    from jornada_private.matchday_live_layout_physical_topology_transitions as topology_row
    where topology_row.source_matchday_id = p_source_matchday_id
      and topology_row.target_matchday_id = p_target_matchday_id
      and topology_row.profile_key = v_profile_key;

    if not found then
      raise exception 'matchday-live-layout-handoff-v19-recovery-topology-missing';
    end if;

    select carryover_row.*
    into v_carryover
    from jornada_private.matchday_live_layout_physical_carryovers as carryover_row
    where carryover_row.source_matchday_id = p_source_matchday_id
      and carryover_row.target_matchday_id = p_target_matchday_id;

    if found then
      if v_carryover.topology_transition_id <> v_topology_id
        or v_carryover.source_composition_id <> p_source_composition_id
      then
        raise exception 'matchday-live-layout-handoff-v19-recovery-carryover-conflict';
      end if;
      v_carryover_id := v_carryover.id;
      v_outcome := 'resumed_after_carryover';
    else
      select *
      into v_carryover
      from jornada_private.materialize_matchday_live_layout_physical_carryover_v18(
        p_source_matchday_id,
        p_target_matchday_id,
        p_source_composition_id,
        v_topology_id
      );
      v_carryover_id := v_carryover.carryover_id;
      v_outcome := 'resumed_after_topology';
    end if;
  end if;

  perform jornada_private.assert_matchday_live_layout_physical_handoff_ready_v19(
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id,
    v_topology_id,
    v_carryover_id
  );

  v_source_archive_hash := jornada_private.matchday_live_layout_physical_archive_hash_v19(
    p_source_matchday_id
  );

  perform jornada_private.retire_matchday_live_layout_physical_source_v19(
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id,
    v_topology_id,
    v_carryover_id,
    v_source_archive_hash
  );

  insert into public.matchday_editorial_continuity_transitions (
    source_matchday_id,
    target_matchday_id,
    source_composition_id,
    continuity_version,
    initialized_at,
    updated_at
  ) values (
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id,
    19,
    pg_catalog.statement_timestamp(),
    pg_catalog.statement_timestamp()
  );

  select workspace_row.state_token
  into v_target_state_token
  from public.read_matchday_live_layout_workspace_v13(
    p_target_matchday_id,
    v_profile_key
  ) as workspace_row;

  insert into jornada_private.matchday_live_layout_physical_handoffs (
    topology_transition_id,
    carryover_id,
    source_matchday_id,
    target_matchday_id,
    source_composition_id,
    profile_key,
    source_archive_hash,
    target_state_token
  ) values (
    v_topology_id,
    v_carryover_id,
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id,
    v_profile_key,
    v_source_archive_hash,
    v_target_state_token
  )
  returning id into v_existing_handoff.id;

  perform jornada_private.assert_matchday_live_layout_physical_handoff_complete_v19(
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id
  );

  select carryover_row.*
  into v_carryover
  from jornada_private.matchday_live_layout_physical_carryovers as carryover_row
  where carryover_row.id = v_carryover_id;

  return pg_catalog.jsonb_build_object(
    'operation', v_operation,
    'outcome', v_outcome,
    'publishedCompositionId', p_source_composition_id,
    'sourceMatchdayId', p_source_matchday_id,
    'nextMatchdayId', p_target_matchday_id,
    'topologyTransitionId', v_topology_id,
    'carryoverId', v_carryover_id,
    'handoffId', v_existing_handoff.id,
    'carryoverApplied', true,
    'materialized', true,
    'sourceRetired', true,
    'targetActivated', true,
    'inheritedBankCount', v_carryover.inherited_bank_count,
    'inheritedZoneCount', (
      select pg_catalog.count(*)
      from jornada_private.matchday_live_layout_physical_zone_maps as map_row
      where map_row.topology_transition_id = v_topology_id
    ),
    'inheritedPlacementCount', v_carryover.inherited_placement_count,
    'inheritedLatestCount', v_carryover.inherited_latest_count,
    'inheritedRoundupCount', v_carryover.inherited_roundup_count,
    'stateToken', v_target_state_token
  );
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.materialize_matchday_live_layout_physical_topology_v17_impl(p_source_matchday_id uuid, p_target_matchday_id uuid)
 RETURNS TABLE(topology_transition_id uuid, source_matchday_id uuid, target_matchday_id uuid, profile_key text, zone_count integer, block_count integer, legacy_projection_count integer, state_token text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source_season_id uuid;
  v_target_season_id uuid;
  v_source_number integer;
  v_target_number integer;
  v_profile_key text;
  v_source_cutover_at timestamptz;
  v_transition_id uuid := gen_random_uuid();
  v_zone_count integer;
  v_block_count integer;
  v_projection_count integer;
  v_state_token text;
  v_source_classification_before text;
  v_target_classification_before text;
  v_source_classification_after text;
  v_target_classification_after text;
  v_source_placement_before text;
  v_source_placement_after text;
  v_source_state_items_before text;
  v_target_state_items_before text;
  v_source_state_items_after text;
  v_target_state_items_after text;
begin
  if p_source_matchday_id is null or p_target_matchday_id is null or p_source_matchday_id=p_target_matchday_id then
    raise exception 'matchday-live-layout-topology-v17-invalid-envelope';
  end if;

  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as lock_row
  where lock_row.id in (p_source_matchday_id,p_target_matchday_id)
  order by lock_row.id
  for update;

  select source_row.season_id,target_row.season_id,source_row.number,target_row.number
  into v_source_season_id,v_target_season_id,v_source_number,v_target_number
  from public.matchdays as source_row
  cross join public.matchdays as target_row
  where source_row.id=p_source_matchday_id and target_row.id=p_target_matchday_id;

  if not found then
    raise exception 'matchday-live-layout-topology-v17-matchday-not-found';
  end if;
  if v_source_season_id is distinct from v_target_season_id then
    raise exception 'matchday-live-layout-topology-v17-season-mismatch';
  end if;
  if v_target_number <> v_source_number+1 then
    raise exception 'matchday-live-layout-topology-v17-target-not-consecutive';
  end if;

  select marker_row.profile_key,marker_row.cutover_at
  into v_profile_key,v_source_cutover_at
  from jornada_private.matchday_live_layout_physical_cutovers as marker_row
  where marker_row.matchday_id=p_source_matchday_id;

  if not found then
    if exists (
      select 1 from public.matchday_live_layout_workspace_settings as settings_row
      where settings_row.matchday_id=p_source_matchday_id
    ) or exists (
      select 1 from jornada_private.matchday_live_layout_physical_topology_transitions as transition_row
      where transition_row.target_matchday_id=p_source_matchday_id
    ) then
      raise exception 'matchday-live-layout-topology-v17-source-authority-incoherent';
    end if;
    raise exception 'matchday-live-layout-topology-v17-source-not-physical';
  end if;

  perform jornada_private.assert_matchday_live_layout_physical_topology_source_v17(p_source_matchday_id,v_profile_key);

  if exists (
    select 1 from public.matchday_editorial_profile_assignments as assignment_row
    where assignment_row.matchday_id=p_target_matchday_id
      and assignment_row.profile_key is distinct from v_profile_key
  ) then
    raise exception 'matchday-live-layout-topology-v17-target-profile-conflict';
  end if;

  if exists (
    select 1 from public.matchday_editorial_desk_control as desk_row
    where desk_row.matchday_id=p_target_matchday_id and desk_row.is_managed=true
  ) then
    raise exception 'matchday-live-layout-topology-v17-target-already-live';
  end if;

  if exists (select 1 from jornada_private.matchday_live_layout_physical_cutovers where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_live_layout_workspace_settings where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_live_layout_zones where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_live_layout_blocks where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_live_layout_placements where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_live_layout_bank_item_state_memory where matchday_id=p_target_matchday_id)
    or exists (select 1 from jornada_private.matchday_live_layout_zone_legacy_projection where matchday_id=p_target_matchday_id)
    or exists (select 1 from jornada_private.matchday_live_layout_physical_topology_transitions as row_value where row_value.source_matchday_id=p_source_matchday_id or row_value.target_matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_editorial_continuity_transitions as row_value where row_value.source_matchday_id=p_source_matchday_id or row_value.target_matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_editorial_bank_items where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_editorial_profile_state_items where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_editorial_profile_manual_overrides where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_editorial_profile_reconcile_control where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_editorial_profile_zone_items where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_editorials where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_highlights where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_horizontal_news where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_latest_news where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_roundup_items where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_live_layout_items where matchday_id=p_target_matchday_id)
  then
    raise exception 'matchday-live-layout-topology-v17-target-not-virgin';
  end if;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(
    pg_catalog.concat_ws('|',bank_row.id,bank_row.classification_key,bank_row.classification_source,bank_row.classified_at),
    ',' order by bank_row.id
  ),'')) into v_source_classification_before
  from public.matchday_editorial_bank_items as bank_row where bank_row.matchday_id=p_source_matchday_id;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(
    pg_catalog.concat_ws('|',bank_row.id,bank_row.classification_key,bank_row.classification_source,bank_row.classified_at),
    ',' order by bank_row.id
  ),'')) into v_target_classification_before
  from public.matchday_editorial_bank_items as bank_row where bank_row.matchday_id=p_target_matchday_id;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(
    pg_catalog.concat_ws('|',placement_row.id,placement_row.bank_item_id,placement_row.placement_type,placement_row.zone_id,placement_row.slot_position,placement_row.created_at,placement_row.updated_at),
    ',' order by placement_row.id
  ),'')) into v_source_placement_before
  from public.matchday_live_layout_placements as placement_row where placement_row.matchday_id=p_source_matchday_id;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(pg_catalog.to_jsonb(state_row)::text,',' order by state_row.source_type,state_row.source_id),''))
  into v_source_state_items_before
  from public.matchday_editorial_profile_state_items as state_row where state_row.matchday_id=p_source_matchday_id;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(pg_catalog.to_jsonb(state_row)::text,',' order by state_row.source_type,state_row.source_id),''))
  into v_target_state_items_before
  from public.matchday_editorial_profile_state_items as state_row where state_row.matchday_id=p_target_matchday_id;

  insert into jornada_private.matchday_live_layout_physical_topology_transitions (
    id,source_matchday_id,target_matchday_id,profile_key,source_cutover_at
  ) values (
    v_transition_id,p_source_matchday_id,p_target_matchday_id,v_profile_key,v_source_cutover_at
  );

  insert into jornada_private.matchday_live_layout_physical_zone_maps (
    topology_transition_id,source_matchday_id,target_matchday_id,source_zone_id,target_zone_id
  )
  select v_transition_id,p_source_matchday_id,p_target_matchday_id,source_zone.id,gen_random_uuid()
  from public.matchday_live_layout_zones as source_zone
  where source_zone.matchday_id=p_source_matchday_id
  order by source_zone.id;

  insert into public.matchday_live_layout_zones (id,matchday_id,public_title,visual_family)
  select zone_map.target_zone_id,p_target_matchday_id,source_zone.public_title,source_zone.visual_family
  from jornada_private.matchday_live_layout_physical_zone_maps as zone_map
  join public.matchday_live_layout_zones as source_zone
    on source_zone.id=zone_map.source_zone_id and source_zone.matchday_id=zone_map.source_matchday_id
  where zone_map.topology_transition_id=v_transition_id
  order by source_zone.id;

  insert into public.matchday_live_layout_blocks (id,matchday_id,block_type,zone_id,sort_order)
  select gen_random_uuid(),p_target_matchday_id,source_block.block_type,
    case when source_block.block_type='zone' then zone_map.target_zone_id else null end,
    source_block.sort_order
  from public.matchday_live_layout_blocks as source_block
  left join jornada_private.matchday_live_layout_physical_zone_maps as zone_map
    on zone_map.topology_transition_id=v_transition_id and zone_map.source_zone_id=source_block.zone_id
  where source_block.matchday_id=p_source_matchday_id
  order by source_block.sort_order,source_block.id;

  insert into public.matchday_live_layout_workspace_settings (
    matchday_id,faixa_slot_count,headline_title_color,latest_zone_placement,latest_zone_title,video_module_active,latest_zone_mode,latest_zone_title_color
  )
  select p_target_matchday_id,source_settings.faixa_slot_count,source_settings.headline_title_color,
    source_settings.latest_zone_placement,source_settings.latest_zone_title,source_settings.video_module_active,
    source_settings.latest_zone_mode,source_settings.latest_zone_title_color
  from public.matchday_live_layout_workspace_settings as source_settings
  where source_settings.matchday_id=p_source_matchday_id;

  insert into jornada_private.matchday_live_layout_physical_cutovers (matchday_id,profile_key,cutover_at)
  values (p_target_matchday_id,v_profile_key,pg_catalog.statement_timestamp());

  perform jornada_private.begin_matchday_live_layout_downstream_v14(p_target_matchday_id);
  begin
    insert into jornada_private.matchday_live_layout_zone_legacy_projection (matchday_id,legacy_zone_key,zone_id)
    select p_target_matchday_id,source_projection.legacy_zone_key,zone_map.target_zone_id
    from jornada_private.matchday_live_layout_zone_legacy_projection as source_projection
    join jornada_private.matchday_live_layout_physical_zone_maps as zone_map
      on zone_map.topology_transition_id=v_transition_id and zone_map.source_zone_id=source_projection.zone_id
    where source_projection.matchday_id=p_source_matchday_id
    order by source_projection.legacy_zone_key;
  exception when others then
    perform jornada_private.end_matchday_live_layout_downstream_v14(p_target_matchday_id);
    raise;
  end;
  perform jornada_private.end_matchday_live_layout_downstream_v14(p_target_matchday_id);

  if exists (
    select 1 from jornada_private.matchday_live_layout_placement_shadow_sync_queue as queue_row
    where queue_row.backend_pid=pg_catalog.pg_backend_pid()
      and queue_row.transaction_id=pg_catalog.pg_current_xact_id()
      and queue_row.matchday_id=p_target_matchday_id
  ) then
    raise exception 'matchday-live-layout-topology-v17-reverse-sync-enqueued';
  end if;

  insert into public.matchday_editorial_profile_assignments (matchday_id,profile_key)
  values (p_target_matchday_id,v_profile_key)
  on conflict (matchday_id) do nothing;

  perform jornada_private.validate_matchday_live_layout_legacy_projection_v14(p_target_matchday_id,v_profile_key);

  select pg_catalog.count(*)::integer into v_zone_count
  from jornada_private.matchday_live_layout_physical_zone_maps as zone_map
  where zone_map.topology_transition_id=v_transition_id;

  select pg_catalog.count(*)::integer into v_block_count
  from public.matchday_live_layout_blocks as block_row
  where block_row.matchday_id=p_target_matchday_id;

  select pg_catalog.count(*)::integer into v_projection_count
  from jornada_private.matchday_live_layout_zone_legacy_projection as projection_row
  where projection_row.matchday_id=p_target_matchday_id;

  if v_zone_count <> (
    select pg_catalog.count(*) from public.matchday_live_layout_zones as source_zone where source_zone.matchday_id=p_source_matchday_id
  ) or v_zone_count <> (
    select pg_catalog.count(*) from public.matchday_live_layout_zones as target_zone where target_zone.matchday_id=p_target_matchday_id
  ) or v_block_count <> (
    select pg_catalog.count(*) from public.matchday_live_layout_blocks as source_block where source_block.matchday_id=p_source_matchday_id
  ) then
    raise exception 'matchday-live-layout-topology-v17-copy-postcondition';
  end if;

  if exists (
    select 1
    from jornada_private.matchday_live_layout_physical_zone_maps as zone_map
    join public.matchday_live_layout_zones as source_zone
      on source_zone.id=zone_map.source_zone_id and source_zone.matchday_id=zone_map.source_matchday_id
    join public.matchday_live_layout_zones as target_zone
      on target_zone.id=zone_map.target_zone_id and target_zone.matchday_id=zone_map.target_matchday_id
    where zone_map.topology_transition_id=v_transition_id
      and row(source_zone.public_title,source_zone.visual_family)
          is distinct from row(target_zone.public_title,target_zone.visual_family)
  ) or exists (
    select 1
    from public.matchday_live_layout_blocks as source_block
    left join public.matchday_live_layout_blocks as target_block
      on target_block.matchday_id=p_target_matchday_id
     and target_block.block_type=source_block.block_type
     and target_block.sort_order=source_block.sort_order
    left join jornada_private.matchday_live_layout_physical_zone_maps as zone_map
      on zone_map.topology_transition_id=v_transition_id and zone_map.source_zone_id=source_block.zone_id
    where source_block.matchday_id=p_source_matchday_id
      and (
        target_block.id is null
        or target_block.id=source_block.id
        or target_block.zone_id is distinct from case when source_block.block_type='zone' then zone_map.target_zone_id else null end
      )
  ) then
    raise exception 'matchday-live-layout-topology-v17-shape-postcondition';
  end if;

  if exists (select 1 from public.matchday_live_layout_placements where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_live_layout_bank_item_state_memory where matchday_id=p_target_matchday_id)
    or exists (select 1 from public.matchday_editorial_bank_items where matchday_id=p_target_matchday_id)
  then
    raise exception 'matchday-live-layout-topology-v17-content-postcondition';
  end if;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(
    pg_catalog.concat_ws('|',bank_row.id,bank_row.classification_key,bank_row.classification_source,bank_row.classified_at),
    ',' order by bank_row.id
  ),'')) into v_source_classification_after
  from public.matchday_editorial_bank_items as bank_row where bank_row.matchday_id=p_source_matchday_id;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(
    pg_catalog.concat_ws('|',bank_row.id,bank_row.classification_key,bank_row.classification_source,bank_row.classified_at),
    ',' order by bank_row.id
  ),'')) into v_target_classification_after
  from public.matchday_editorial_bank_items as bank_row where bank_row.matchday_id=p_target_matchday_id;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(
    pg_catalog.concat_ws('|',placement_row.id,placement_row.bank_item_id,placement_row.placement_type,placement_row.zone_id,placement_row.slot_position,placement_row.created_at,placement_row.updated_at),
    ',' order by placement_row.id
  ),'')) into v_source_placement_after
  from public.matchday_live_layout_placements as placement_row where placement_row.matchday_id=p_source_matchday_id;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(pg_catalog.to_jsonb(state_row)::text,',' order by state_row.source_type,state_row.source_id),''))
  into v_source_state_items_after
  from public.matchday_editorial_profile_state_items as state_row where state_row.matchday_id=p_source_matchday_id;

  select pg_catalog.md5(coalesce(pg_catalog.string_agg(pg_catalog.to_jsonb(state_row)::text,',' order by state_row.source_type,state_row.source_id),''))
  into v_target_state_items_after
  from public.matchday_editorial_profile_state_items as state_row where state_row.matchday_id=p_target_matchday_id;

  if row(v_source_classification_after,v_target_classification_after,v_source_placement_after,v_source_state_items_after,v_target_state_items_after)
    is distinct from row(v_source_classification_before,v_target_classification_before,v_source_placement_before,v_source_state_items_before,v_target_state_items_before)
  then
    raise exception 'matchday-live-layout-topology-v17-authority-postcondition';
  end if;

  select token_row.state_token into v_state_token
  from public.matchday_editorial_profile_workspace_token_v13(p_target_matchday_id,v_profile_key) as token_row;

  if v_state_token is null or v_state_token !~ '^[0-9a-f]{32}$' then
    raise exception 'matchday-live-layout-topology-v17-token-postcondition';
  end if;

  return query select v_transition_id,p_source_matchday_id,p_target_matchday_id,v_profile_key,v_zone_count,v_block_count,v_projection_count,v_state_token;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.project_matchday_live_layout_placements_to_legacy(p_matchday_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matchday_id uuid;
  v_profile_key text;
begin
  for v_matchday_id in
    select distinct input_row.matchday_id
    from pg_catalog.unnest(p_matchday_ids) as input_row(matchday_id)
