CREATE OR REPLACE FUNCTION jornada_private.validate_matchday_live_layout_shadow_inputs(p_matchday_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1
    from public.matchday_editorial_profile_reconcile_control as control_row
    where (
      p_matchday_ids is null
      or control_row.matchday_id = any(p_matchday_ids)
    )
      and (
        control_row.profile_key <> 'liga_portugal_v1'
        or pg_catalog.cardinality(control_row.thematic_zone_order) <> 5
        or not (
          control_row.thematic_zone_order <@ array[
            'benfica',
            'sporting',
            'fc_porto',
            'other_liga_clubs',
            'outside_liga_other'
          ]::text[]
          and control_row.thematic_zone_order @> array[
            'benfica',
            'sporting',
            'fc_porto',
            'other_liga_clubs',
            'outside_liga_other'
          ]::text[]
        )
      )
  ) then
    raise exception 'matchday-live-layout-shadow-invalid-zone-order';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_profile_reconcile_control as control_row
    where (
      p_matchday_ids is null
      or control_row.matchday_id = any(p_matchday_ids)
    )
      and (
        pg_catalog.jsonb_typeof(control_row.thematic_zone_layouts) <> 'object'
        or not (
          control_row.thematic_zone_layouts ?& array[
            'benfica',
            'sporting',
            'fc_porto',
            'other_liga_clubs',
            'outside_liga_other'
          ]
        )
        or (
          control_row.thematic_zone_layouts - array[
            'benfica',
            'sporting',
            'fc_porto',
            'other_liga_clubs',
            'outside_liga_other'
          ]::text[]
        ) <> '{}'::jsonb
        or coalesce(
          control_row.thematic_zone_layouts ->> 'benfica',
          ''
        ) not in (
          'six_news', 'six_news_1_2_3',
          'five_news_balanced',
          'five_news_secondary'
        )
        or coalesce(
          control_row.thematic_zone_layouts ->> 'sporting',
          ''
        ) not in (
          'six_news', 'six_news_1_2_3',
          'five_news_balanced',
          'five_news_secondary'
        )
        or coalesce(
          control_row.thematic_zone_layouts ->> 'fc_porto',
          ''
        ) not in (
          'six_news', 'six_news_1_2_3',
          'five_news_balanced',
          'five_news_secondary'
        )
        or coalesce(
          control_row.thematic_zone_layouts ->> 'other_liga_clubs',
          ''
        ) not in (
          'six_news', 'six_news_1_2_3',
          'five_news_balanced',
          'five_news_secondary'
        )
        or coalesce(
          control_row.thematic_zone_layouts ->> 'outside_liga_other',
          ''
        ) not in (
          'six_news', 'six_news_1_2_3',
          'five_news_balanced',
          'five_news_secondary'
        )
      )
  ) then
    raise exception 'matchday-live-layout-shadow-invalid-zone-layouts';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_profile_reconcile_control as control_row
    where (
      p_matchday_ids is null
      or control_row.matchday_id = any(p_matchday_ids)
    )
      and (
        pg_catalog.jsonb_typeof(control_row.thematic_zone_titles) <> 'object'
        or not (
          control_row.thematic_zone_titles ?& array[
            'benfica',
            'sporting',
            'fc_porto',
            'other_liga_clubs',
            'outside_liga_other'
          ]
        )
        or (
          control_row.thematic_zone_titles - array[
            'benfica',
            'sporting',
            'fc_porto',
            'other_liga_clubs',
            'outside_liga_other'
          ]::text[]
        ) <> '{}'::jsonb
        or pg_catalog.jsonb_typeof(
          control_row.thematic_zone_titles -> 'benfica'
        ) <> 'string'
        or pg_catalog.jsonb_typeof(
          control_row.thematic_zone_titles -> 'sporting'
        ) <> 'string'
        or pg_catalog.jsonb_typeof(
          control_row.thematic_zone_titles -> 'fc_porto'
        ) <> 'string'
        or pg_catalog.jsonb_typeof(
          control_row.thematic_zone_titles -> 'other_liga_clubs'
        ) <> 'string'
        or pg_catalog.jsonb_typeof(
          control_row.thematic_zone_titles -> 'outside_liga_other'
        ) <> 'string'
        or pg_catalog.char_length(
          pg_catalog.btrim(control_row.thematic_zone_titles ->> 'benfica')
        ) > 120
        or pg_catalog.char_length(
          pg_catalog.btrim(control_row.thematic_zone_titles ->> 'sporting')
        ) > 120
        or pg_catalog.char_length(
          pg_catalog.btrim(control_row.thematic_zone_titles ->> 'fc_porto')
        ) > 120
        or pg_catalog.char_length(
          pg_catalog.btrim(control_row.thematic_zone_titles ->> 'other_liga_clubs')
        ) > 120
        or pg_catalog.char_length(
          pg_catalog.btrim(control_row.thematic_zone_titles ->> 'outside_liga_other')
        ) > 120
      )
  ) then
    raise exception 'matchday-live-layout-shadow-invalid-zone-titles';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_profile_reconcile_control as control_row
    where (
      p_matchday_ids is null
      or control_row.matchday_id = any(p_matchday_ids)
    )
      and (
        pg_catalog.cardinality(control_row.thematic_block_order) not in (6, 7)
        or not (
          control_row.thematic_block_order <@ array[
            'benfica',
            'sporting',
            'fc_porto',
            'other_liga_clubs',
            'outside_liga_other',
            'latest',
            'video'
          ]::text[]
        )
        or not (
          control_row.thematic_block_order @> array[
            'benfica',
            'sporting',
            'fc_porto',
            'other_liga_clubs',
            'outside_liga_other',
            'latest'
          ]::text[]
        )
        or (
          pg_catalog.cardinality(control_row.thematic_block_order) = 7
          and not control_row.thematic_block_order @> array['video']::text[]
        )
      )
  ) then
    raise exception 'matchday-live-layout-shadow-invalid-block-order';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_profile_reconcile_control as control_row
    where (
      p_matchday_ids is null
      or control_row.matchday_id = any(p_matchday_ids)
    )
      and control_row.thematic_zone_order is distinct from (
        select pg_catalog.array_agg(
          block_row.block_key
          order by block_row.sort_order
        )
        from pg_catalog.unnest(
          control_row.thematic_block_order
        ) with ordinality as block_row(block_key, sort_order)
        where block_row.block_key not in ('latest', 'video')
      )
  ) then
    raise exception 'matchday-live-layout-shadow-zone-block-order-mismatch';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION jornada_private.write_matchday_editorial_bank_contextual_classification(p_bank_item_id uuid, p_classification_key text, p_classification_source text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_bank record;
  v_changed boolean := false;
begin
  if (p_classification_key is null) <> (p_classification_source is null) then
    raise exception 'contextual-classification-incomplete-triplet';
  end if;

  if p_classification_key is not null and p_classification_key not in ('benfica','sporting','fc_porto','other_liga_clubs','outside_liga_other') then
    raise exception 'contextual-classification-invalid-key:%', p_classification_key;
  end if;

  if p_classification_source is not null and p_classification_source not in ('automatic','continuity_assisted','manual') then
    raise exception 'contextual-classification-invalid-source:%', p_classification_source;
  end if;

  select bank_row.* into v_bank
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.id = p_bank_item_id
  for update;

  if not found then return false; end if;

  if pg_catalog.lower(pg_catalog.btrim(coalesce(v_bank.source_type, ''))) <> 'editorial_article'
    and p_classification_key is not null
  then
    raise exception 'contextual-classification-non-article:%', p_bank_item_id;
  end if;

  if v_bank.classification_source = 'manual' and p_classification_source is distinct from 'manual' then
    return false;
  end if;

  if v_bank.classification_source = 'continuity_assisted' and p_classification_source is distinct from 'continuity_assisted' then
    return false;
  end if;

  if v_bank.classification_key is not distinct from p_classification_key
    and v_bank.classification_source is not distinct from p_classification_source
  then
    return false;
  end if;

  perform jornada_private.authorize_matchday_editorial_bank_classification_writes(array[p_bank_item_id]);

  begin
    update public.matchday_editorial_bank_items as bank_row
    set classification_key = p_classification_key,
        classification_source = p_classification_source,
        classified_at = case when p_classification_key is null then null else pg_catalog.statement_timestamp() end
    where bank_row.id = p_bank_item_id;
    v_changed := found;
    perform jornada_private.revoke_matchday_editorial_bank_classification_writes(array[p_bank_item_id]);
  exception when others then
    perform jornada_private.revoke_matchday_editorial_bank_classification_writes(array[p_bank_item_id]);
    raise;
  end;

  return v_changed;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_historical_composition_workspace_plan(p_matchday_id uuid, p_composition_id uuid, p_operations jsonb, p_settings jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_composition public.matchday_reference_compositions%rowtype;
  v_bank public.matchday_editorial_bank_items%rowtype;
  v_article public.editorial_articles%rowtype;
  v_operation jsonb;
  v_kind text;
  v_target text;
  v_slot_key text;
  v_slot_id uuid;
  v_item_id uuid;
  v_bank_id uuid;
  v_article_id uuid;
  v_slot_type text;
  v_sort_order integer;
  v_source_identity text;
  v_rows integer;
  v_remove_editorial boolean := false;
  v_assign_editorial boolean := false;
  v_editorial_title text;
  v_editorial_excerpt text;
  v_editorial_text text;
  v_editorial_author text;
  v_editorial_source_id uuid;
begin
  if p_matchday_id is null or p_composition_id is null then
    raise exception 'historical_composition_workspace_invalid';
  end if;

  if p_operations is null or pg_catalog.jsonb_typeof(p_operations) <> 'array' or pg_catalog.jsonb_array_length(p_operations) > 80 then
    raise exception 'historical_composition_workspace_operations_invalid';
  end if;

  if p_settings is not null and (
    pg_catalog.jsonb_typeof(p_settings) <> 'object'
    or coalesce(p_settings ->> 'headlineTitleColor', '') !~ '^#[0-9A-Fa-f]{6}$'
    or nullif(pg_catalog.btrim(p_settings ->> 'zone1Title'), '') is null
    or pg_catalog.char_length(p_settings ->> 'zone1Title') > 120
    or nullif(pg_catalog.btrim(p_settings ->> 'zone2Title'), '') is null
    or pg_catalog.char_length(p_settings ->> 'zone2Title') > 120
    or pg_catalog.jsonb_typeof(p_settings -> 'blockOrder') <> 'array'
    or pg_catalog.jsonb_array_length(p_settings -> 'blockOrder') <> 5
    or not (p_settings -> 'blockOrder' @> '["opening", "zone_1", "zone_2", "video", "beyond"]'::jsonb)
  ) then
    raise exception 'historical_composition_workspace_settings_invalid';
  end if;

  select composition.* into v_composition
  from public.matchday_reference_compositions as composition
  where composition.id = p_composition_id and composition.matchday_id = p_matchday_id
  for update;

  if v_composition.id is null or v_composition.status <> 'draft' or v_composition.presentation_mode <> 'hierarchical' then
    raise exception 'historical_composition_workspace_not_editable';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_operations) as operation(value)
    where pg_catalog.jsonb_typeof(operation.value) <> 'object'
       or not (coalesce(operation.value ->> 'kind', '') = any(array['unassign_slot','remove_auxiliary','assign_slot','assign_auxiliary','remove_editorial','assign_editorial']))
  ) then
    raise exception 'historical_composition_workspace_operation_invalid';
  end if;

  if (select pg_catalog.count(*) from pg_catalog.jsonb_array_elements(p_operations) as operation(value) where operation.value ->> 'kind' = 'assign_editorial') > 1 then
    raise exception 'historical_composition_workspace_editorial_target_repeated';
  end if;

  select exists (select 1 from pg_catalog.jsonb_array_elements(p_operations) as operation(value) where operation.value ->> 'kind' = 'remove_editorial') into v_remove_editorial;

  if v_remove_editorial or p_settings is not null then
    update public.matchday_reference_compositions as composition
    set hierarchical_editorial_title = case when v_remove_editorial then null else composition.hierarchical_editorial_title end,
        hierarchical_editorial_excerpt = case when v_remove_editorial then null else composition.hierarchical_editorial_excerpt end,
        hierarchical_editorial_text = case when v_remove_editorial then null else composition.hierarchical_editorial_text end,
        hierarchical_editorial_author = case when v_remove_editorial then null else composition.hierarchical_editorial_author end,
        hierarchical_editorial_source_type = case when v_remove_editorial then null else composition.hierarchical_editorial_source_type end,
        hierarchical_editorial_source_id = case when v_remove_editorial then null else composition.hierarchical_editorial_source_id end,
        hierarchical_headline_title_color = case when p_settings is not null then pg_catalog.upper(pg_catalog.btrim(p_settings ->> 'headlineTitleColor')) else composition.hierarchical_headline_title_color end,
        hierarchical_zone_1_title = case when p_settings is not null then pg_catalog.btrim(p_settings ->> 'zone1Title') else composition.hierarchical_zone_1_title end,
        hierarchical_zone_2_title = case when p_settings is not null then pg_catalog.btrim(p_settings ->> 'zone2Title') else composition.hierarchical_zone_2_title end,
        hierarchical_block_order = case when p_settings is not null then p_settings -> 'blockOrder' else composition.hierarchical_block_order end
    where composition.id = p_composition_id
      and composition.matchday_id = p_matchday_id
      and composition.status = 'draft'
      and composition.presentation_mode = 'hierarchical';
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then raise exception 'historical_composition_workspace_changed'; end if;
  end if;

  for v_operation in select operation.value from pg_catalog.jsonb_array_elements(p_operations) as operation(value)
  loop
    v_kind := v_operation ->> 'kind';
    if v_kind = 'unassign_slot' then
      v_slot_id := nullif(pg_catalog.btrim(v_operation ->> 'slotId'), '')::uuid;
      delete from public.matchday_hierarchical_composition_slots as slot where slot.id = v_slot_id and slot.composition_id = p_composition_id;
      get diagnostics v_rows = row_count;
      if v_rows <> 1 then raise exception 'historical_composition_workspace_changed'; end if;
    elsif v_kind = 'remove_auxiliary' then
      v_item_id := nullif(pg_catalog.btrim(v_operation ->> 'itemId'), '')::uuid;
      delete from public.matchday_reference_composition_items as item
      where item.id = v_item_id and item.composition_id = p_composition_id and item.slot_type in ('complement','beyond_matchday','important_item');
      get diagnostics v_rows = row_count;
      if v_rows <> 1 then raise exception 'historical_composition_workspace_changed'; end if;
    end if;
  end loop;

  for v_operation in
    select operation.value from pg_catalog.jsonb_array_elements(p_operations) as operation(value)
    where operation.value ->> 'kind' in ('assign_slot','assign_auxiliary')
  loop
    v_kind := v_operation ->> 'kind';
    v_bank_id := nullif(pg_catalog.btrim(v_operation ->> 'bankItemId'), '')::uuid;

    select bank.* into v_bank
    from public.matchday_editorial_bank_items as bank
    where bank.id = v_bank_id and bank.matchday_id = p_matchday_id and bank.status = 'active'
    for share;

    if not found or pg_catalog.lower(pg_catalog.btrim(coalesce(v_bank.source_type, ''))) <> 'editorial_article' or nullif(pg_catalog.btrim(v_bank.source_id), '') is null then
      raise exception 'historical_composition_workspace_bank_item_invalid';
    end if;

    v_article_id := pg_catalog.btrim(v_bank.source_id)::uuid;
    v_source_identity := 'editorial_article:' || pg_catalog.lower(v_article_id::text);

    if exists (
      select 1 from public.matchday_hierarchical_composition_slots as slot
      where slot.composition_id = p_composition_id and (slot.bank_item_id = v_bank_id or pg_catalog.lower(pg_catalog.btrim(slot.source_identity)) = v_source_identity)
    ) or exists (
      select 1 from public.matchday_reference_composition_items as item
      where item.composition_id = p_composition_id
        and item.slot_type in ('complement','beyond_matchday','important_item')
        and ((pg_catalog.lower(pg_catalog.btrim(item.source_type)) = 'matchday_editorial_bank_item' and item.source_id = v_bank_id)
          or (pg_catalog.lower(pg_catalog.btrim(item.source_type)) = 'editorial_article' and item.source_id = v_article_id))
    ) or (
      not v_remove_editorial and v_composition.hierarchical_editorial_source_type = 'editorial_article' and v_composition.hierarchical_editorial_source_id = v_article_id
    ) then
      raise exception 'historical_composition_workspace_source_repeated';
    end if;

    if v_kind = 'assign_slot' then
      v_slot_key := pg_catalog.btrim(v_operation ->> 'slotKey');
      if v_slot_key is null or v_slot_key not in ('dominant_main','dominant_side_top','dominant_side_bottom','other_chronicle_1','other_chronicle_2','other_chronicle_3','secondary_strong_1','secondary_strong_2','secondary_1','secondary_2','secondary_3','secondary_4','closing_1','closing_2','closing_3') then
        raise exception 'historical_composition_workspace_slot_invalid';
      end if;
      if exists (select 1 from public.matchday_hierarchical_composition_slots as slot where slot.composition_id = p_composition_id and slot.slot_key = v_slot_key) then
        raise exception 'historical_composition_workspace_target_occupied';
      end if;
      insert into public.matchday_hierarchical_composition_slots (
        composition_id,slot_key,bank_item_id,source_identity,label_snapshot,title_snapshot,subtitle_snapshot,image_url_snapshot,link_url_snapshot,media_kind_snapshot,media_embed_url_snapshot,media_video_url_snapshot
      ) values (
        p_composition_id,v_slot_key,v_bank.id,v_source_identity,v_bank.label,v_bank.title,v_bank.subtitle,v_bank.image_url,v_bank.link_url,null,null,null
      );
    else
      v_target := pg_catalog.btrim(v_operation ->> 'target');
      if v_target = 'video_highlight' then
        v_slot_type := 'complement'; v_sort_order := 1;
      elsif v_target ~ '^beyond_matchday_[1-5]$' then
        v_slot_type := 'beyond_matchday'; v_sort_order := pg_catalog.substring(v_target, '([0-9]+)$')::integer;
      elsif v_target ~ '^faixa_([1-9]|10)$' then
        v_slot_type := 'important_item'; v_sort_order := pg_catalog.substring(v_target, '([0-9]+)$')::integer;
      else
        raise exception 'historical_composition_workspace_auxiliary_target_invalid';
      end if;

      if exists (select 1 from public.matchday_reference_composition_items as item where item.composition_id = p_composition_id and item.slot_type = v_slot_type and item.sort_order = v_sort_order) then
        raise exception 'historical_composition_workspace_target_occupied';
      end if;

      select article.* into v_article
      from public.editorial_articles as article
      where article.id = v_article_id and article.status = 'published'
      for share;

      if not found
         or nullif(pg_catalog.btrim(v_article.slug), '') is null
         or nullif(pg_catalog.btrim(v_article.label), '') is null
         or nullif(pg_catalog.btrim(v_article.title), '') is null
         or nullif(pg_catalog.btrim(v_article.subtitle), '') is null
         or nullif(pg_catalog.btrim(v_article.body), '') is null
         or nullif(pg_catalog.btrim(v_article.image_url), '') is null
         or nullif(pg_catalog.btrim(v_article.author), '') is null
         or v_article.published_at is null then
        raise exception 'historical_composition_workspace_article_invalid';
      end if;

      insert into public.matchday_reference_composition_items (
        composition_id,slot_type,source_type,source_id,article_id,sort_order,title_snapshot,subtitle_snapshot,image_url_snapshot,link_url_snapshot,label_snapshot,label_color_snapshot,media_kind_snapshot,media_embed_url_snapshot,media_video_url_snapshot,status
      ) values (
        p_composition_id,v_slot_type,'matchday_editorial_bank_item',v_bank.id,null,v_sort_order,pg_catalog.btrim(v_article.title),pg_catalog.btrim(v_article.subtitle),pg_catalog.btrim(v_article.image_url),'/noticias/' || pg_catalog.btrim(v_article.slug),pg_catalog.btrim(v_article.label),null,null,null,null,'draft'
      );
    end if;
  end loop;

  select nullif(pg_catalog.btrim(operation.value ->> 'bankItemId'), '')::uuid into v_bank_id
  from pg_catalog.jsonb_array_elements(p_operations) as operation(value)
  where operation.value ->> 'kind' = 'assign_editorial'
  limit 1;

  if v_bank_id is not null then
    select bank.* into v_bank
    from public.matchday_editorial_bank_items as bank
    where bank.id = v_bank_id
      and bank.matchday_id = p_matchday_id
      and bank.status = 'active'
      and pg_catalog.lower(pg_catalog.btrim(coalesce(bank.source_type, ''))) = 'editorial_article'
      and nullif(pg_catalog.btrim(bank.source_id), '') is not null
    for share;

    if not found then raise exception 'historical_composition_workspace_editorial_bank_invalid'; end if;

    v_article_id := pg_catalog.btrim(v_bank.source_id)::uuid;
    if (v_composition.hierarchical_editorial_source_id is not null and not v_remove_editorial)
      or exists (
        select 1 from public.matchday_hierarchical_composition_slots as slot
        where slot.composition_id = p_composition_id and (slot.bank_item_id = v_bank_id or pg_catalog.lower(pg_catalog.btrim(slot.source_identity)) = 'editorial_article:' || pg_catalog.lower(v_article_id::text))
      )
      or exists (
        select 1 from public.matchday_reference_composition_items as item
        where item.composition_id = p_composition_id
          and item.slot_type in ('complement','beyond_matchday','important_item')
          and ((pg_catalog.lower(pg_catalog.btrim(item.source_type)) = 'matchday_editorial_bank_item' and item.source_id = v_bank_id)
            or (pg_catalog.lower(pg_catalog.btrim(item.source_type)) = 'editorial_article' and item.source_id = v_article_id))
      ) then
      raise exception 'historical_composition_workspace_source_repeated';
    end if;

    select article.* into v_article
    from public.editorial_articles as article
    where article.id = v_article_id and article.status = 'published'
    for share;

    if not found
       or nullif(pg_catalog.btrim(v_article.label), '') is null
       or nullif(pg_catalog.btrim(v_article.title), '') is null
       or nullif(pg_catalog.btrim(v_article.subtitle), '') is null
       or nullif(pg_catalog.btrim(v_article.body), '') is null
       or nullif(pg_catalog.btrim(v_article.image_url), '') is null
       or nullif(pg_catalog.btrim(v_article.author), '') is null
       or v_article.published_at is null then
      raise exception 'historical_composition_workspace_editorial_article_invalid';
    end if;

    v_assign_editorial := true;
    v_editorial_title := v_article.title;
    v_editorial_excerpt := v_article.subtitle;
    v_editorial_text := v_article.body;
    v_editorial_author := v_article.author;
    v_editorial_source_id := v_article.id;
  end if;

  if v_assign_editorial then
    update public.matchday_reference_compositions as composition
    set hierarchical_editorial_title = v_editorial_title,
        hierarchical_editorial_excerpt = v_editorial_excerpt,
        hierarchical_editorial_text = v_editorial_text,
        hierarchical_editorial_author = v_editorial_author,
        hierarchical_editorial_source_type = 'editorial_article',
        hierarchical_editorial_source_id = v_editorial_source_id
    where composition.id = p_composition_id
      and composition.matchday_id = p_matchday_id
      and composition.status = 'draft'
      and composition.presentation_mode = 'hierarchical';
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then raise exception 'historical_composition_workspace_changed'; end if;
  end if;

  return pg_catalog.jsonb_array_length(p_operations) + case when p_settings is null then 0 else 1 end;
end
$function$

CREATE OR REPLACE FUNCTION public.apply_historical_composition_workspace_plan_v2(p_matchday_id uuid, p_composition_id uuid, p_operations jsonb, p_settings jsonb, p_dynamic_zones jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_base integer;
  v_dynamic integer;
begin
  v_base :=
    public.apply_historical_composition_workspace_plan(
      p_matchday_id,
      p_composition_id,
      p_operations,
      p_settings
    );

  v_dynamic :=
    public.replace_historical_composition_dynamic_zones(
      p_matchday_id,
      p_composition_id,
      p_dynamic_zones
    );

  return
    coalesce(v_base, 0)
    + coalesce(v_dynamic, 0);
end
$function$

CREATE OR REPLACE FUNCTION public.apply_historical_composition_workspace_plan_v3(p_matchday_id uuid, p_composition_id uuid, p_operations jsonb, p_settings jsonb, p_dynamic_zones jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_total integer;
  v_video_position integer;
  v_faixa_title text;
  v_zone_count integer;
  v_has_video_position boolean;
  v_has_faixa_title boolean;
begin
  v_has_video_position :=
    p_settings is not null
    and p_settings ? 'videoPosition';

  v_has_faixa_title :=
    p_settings is not null
    and p_settings ? 'faixaTitle';

  if v_has_video_position then
    if pg_catalog.jsonb_typeof(p_settings -> 'videoPosition') <> 'number'
       or (p_settings ->> 'videoPosition') !~ '^[0-9]+$' then
      raise exception 'historical_video_position_invalid';
    end if;

    v_video_position := (p_settings ->> 'videoPosition')::integer;

    if v_video_position < 0 or v_video_position > 24 then
      raise exception 'historical_video_position_invalid';
    end if;
  end if;

  if v_has_faixa_title then
    if pg_catalog.jsonb_typeof(p_settings -> 'faixaTitle') <> 'string' then
      raise exception 'historical_faixa_title_invalid';
    end if;

    v_faixa_title := pg_catalog.btrim(p_settings ->> 'faixaTitle');

    if pg_catalog.char_length(v_faixa_title) > 120 then
      raise exception 'historical_faixa_title_invalid';
    end if;
  end if;

  v_total := public.apply_historical_composition_workspace_plan_v2(
    p_matchday_id,
    p_composition_id,
    p_operations,
    case
      when p_settings is null then null
      else p_settings - 'videoPosition' - 'faixaTitle'
    end,
    p_dynamic_zones
  );

  if v_has_video_position then
    select pg_catalog.count(*)::integer
    into v_zone_count
    from public.matchday_historical_composition_zones
    where composition_id = p_composition_id;

    if v_video_position > v_zone_count then
      raise exception 'historical_video_position_out_of_range';
    end if;
  end if;

  if v_has_video_position or v_has_faixa_title then
    update public.matchday_reference_compositions as composition
    set
      hierarchical_video_position = case
        when v_has_video_position then v_video_position
        else composition.hierarchical_video_position
      end,
      hierarchical_faixa_title = case
        when v_has_faixa_title then nullif(v_faixa_title, '')
        else composition.hierarchical_faixa_title
      end,
      updated_at = now()
    where composition.id = p_composition_id
      and composition.matchday_id = p_matchday_id
      and composition.status = 'draft'
      and composition.presentation_mode = 'hierarchical';

    if not found then
      raise exception 'historical_workspace_settings_not_editable';
    end if;
  end if;

  return coalesce(v_total, 0)
    + case when v_has_video_position then 1 else 0 end
    + case when v_has_faixa_title then 1 else 0 end;
end
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_agenda_tv_sync_v1(p_matchday_id uuid, p_rows jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expected_count integer;
  v_received_count integer;
  v_updated_count integer;
begin
  if p_matchday_id is null then
    raise exception 'agenda-tv-v1-missing-matchday';
  end if;

  if jsonb_typeof(p_rows) is distinct from 'array' then
    raise exception 'agenda-tv-v1-invalid-payload';
  end if;

  select count(*)
  into v_expected_count
  from public.matches
  where matchday_id = p_matchday_id;

  if v_expected_count = 0 then
    raise exception 'agenda-tv-v1-empty-matchday';
  end if;

  v_received_count := jsonb_array_length(p_rows);

  if v_received_count <> v_expected_count then
    raise exception 'agenda-tv-v1-incomplete-matchday';
  end if;

  if exists (
    select 1
    from (
      select
        (item ->> 'match_id')::uuid as match_id,
        count(*) as occurrences
      from jsonb_array_elements(p_rows) as item
      group by 1
    ) as duplicated
    where duplicated.occurrences <> 1
  ) then
    raise exception 'agenda-tv-v1-duplicate-match';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      nullif(item ->> 'match_id', '') is null
      or nullif(item ->> 'scheduled_date', '') is null
      or nullif(item ->> 'kickoff_at', '') is null
      or nullif(item ->> 'broadcast_channel_id', '') is null
  ) then
    raise exception 'agenda-tv-v1-incomplete-row';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where not exists (
      select 1
      from public.matches as m
      where
        m.id = (item ->> 'match_id')::uuid
        and m.matchday_id = p_matchday_id
    )
  ) then
    raise exception 'agenda-tv-v1-match-outside-matchday';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where not exists (
      select 1
      from public.broadcast_channels as channel
      where
        channel.id =
          (item ->> 'broadcast_channel_id')::uuid
    )
  ) then
    raise exception 'agenda-tv-v1-channel-not-found';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      (
        (
          (item ->> 'kickoff_at')::timestamptz
          at time zone 'Europe/Lisbon'
        )::date
      )
      is distinct from
      (item ->> 'scheduled_date')::date
  ) then
    raise exception 'agenda-tv-v1-date-kickoff-mismatch';
  end if;

  if exists (
    with requested as (
      select
        (item ->> 'match_id')::uuid as match_id,
        nullif(
          item ->> 'expected_scheduled_date',
          ''
        )::date as expected_scheduled_date,
        nullif(
          item ->> 'expected_kickoff_at',
          ''
        )::timestamptz as expected_kickoff_at,
        nullif(
          item ->> 'expected_broadcast_channel_id',
          ''
        )::uuid as expected_broadcast_channel_id
      from jsonb_array_elements(p_rows) as item
    )
    select 1
    from requested
    join public.matches as m
      on m.id = requested.match_id
    where
      m.scheduled_date
        is distinct from
        requested.expected_scheduled_date
      or m.kickoff_at
        is distinct from
        requested.expected_kickoff_at
      or m.broadcast_channel_id
        is distinct from
        requested.expected_broadcast_channel_id
  ) then
    raise exception 'agenda-tv-v1-stale-state';
  end if;

  with requested as (
    select
      (item ->> 'match_id')::uuid as match_id,
      (item ->> 'scheduled_date')::date as scheduled_date,
      (item ->> 'kickoff_at')::timestamptz as kickoff_at,
      (item ->> 'broadcast_channel_id')::uuid as broadcast_channel_id
    from jsonb_array_elements(p_rows) as item
  )
  update public.matches as m
  set
    scheduled_date = requested.scheduled_date,
    kickoff_at = requested.kickoff_at,
    broadcast_channel_id =
      requested.broadcast_channel_id
  from requested
  where
    m.id = requested.match_id
    and m.matchday_id = p_matchday_id
    and (
      m.scheduled_date
        is distinct from
        requested.scheduled_date
      or m.kickoff_at
        is distinct from
        requested.kickoff_at
      or m.broadcast_channel_id
        is distinct from
        requested.broadcast_channel_id
    );

  get diagnostics v_updated_count = row_count;

  return v_updated_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_agenda_tv_sync_v2(p_matchday_id uuid, p_rows jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expected_count integer;
  v_received_count integer;
  v_updated_count integer;
begin
  if p_matchday_id is null then
    raise exception 'agenda-tv-v2-missing-matchday';
  end if;

  if jsonb_typeof(p_rows) is distinct from 'array' then
    raise exception 'agenda-tv-v2-invalid-payload';
  end if;

  select count(*)
  into v_expected_count
  from public.matches
  where matchday_id = p_matchday_id;

  if v_expected_count = 0 then
    raise exception 'agenda-tv-v2-empty-matchday';
  end if;

  v_received_count := jsonb_array_length(p_rows);

  if v_received_count <> v_expected_count then
    raise exception 'agenda-tv-v2-incomplete-matchday';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      item ? 'preserve'
      and jsonb_typeof(item -> 'preserve') is distinct from 'boolean'
  ) then
    raise exception 'agenda-tv-v2-invalid-preserve';
  end if;

  if exists (
    select 1
    from (
      select
        (item ->> 'match_id')::uuid as match_id,
        count(*) as occurrences
      from jsonb_array_elements(p_rows) as item
      group by 1
    ) as duplicated
    where duplicated.occurrences <> 1
  ) then
    raise exception 'agenda-tv-v2-duplicate-match';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      nullif(item ->> 'match_id', '') is null
      or (
        not coalesce((item ->> 'preserve')::boolean, false)
        and (
          nullif(item ->> 'scheduled_date', '') is null
          or nullif(item ->> 'kickoff_at', '') is null
        )
      )
  ) then
    raise exception 'agenda-tv-v2-incomplete-row';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where not exists (
      select 1
      from public.matches as m
      where
        m.id = (item ->> 'match_id')::uuid
        and m.matchday_id = p_matchday_id
    )
  ) then
    raise exception 'agenda-tv-v2-match-outside-matchday';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      not coalesce((item ->> 'preserve')::boolean, false)
      and nullif(item ->> 'broadcast_channel_id', '') is not null
      and not exists (
        select 1
        from public.broadcast_channels as channel
        where
          channel.id =
            (item ->> 'broadcast_channel_id')::uuid
      )
  ) then
    raise exception 'agenda-tv-v2-channel-not-found';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_rows) as item
    where
      not coalesce((item ->> 'preserve')::boolean, false)
      and (
        (
          (item ->> 'kickoff_at')::timestamptz
          at time zone 'Europe/Lisbon'
        )::date
      )
      is distinct from
      (item ->> 'scheduled_date')::date
  ) then
    raise exception 'agenda-tv-v2-date-kickoff-mismatch';
  end if;

  if exists (
    with requested as (
      select
        (item ->> 'match_id')::uuid as match_id,
        nullif(
          item ->> 'expected_scheduled_date',
          ''
        )::date as expected_scheduled_date,
        nullif(
          item ->> 'expected_kickoff_at',
          ''
        )::timestamptz as expected_kickoff_at,
        nullif(
          item ->> 'expected_broadcast_channel_id',
          ''
        )::uuid as expected_broadcast_channel_id
      from jsonb_array_elements(p_rows) as item
    )
    select 1
    from requested
    join public.matches as m
      on m.id = requested.match_id
    where
      m.scheduled_date
        is distinct from
        requested.expected_scheduled_date
      or m.kickoff_at
        is distinct from
        requested.expected_kickoff_at
      or m.broadcast_channel_id
        is distinct from
        requested.expected_broadcast_channel_id
  ) then
    raise exception 'agenda-tv-v2-stale-state';
  end if;

  with requested as (
    select
      (item ->> 'match_id')::uuid as match_id,
      coalesce(
        (item ->> 'preserve')::boolean,
        false
      ) as preserve,
      nullif(
        item ->> 'scheduled_date',
        ''
      )::date as scheduled_date,
      nullif(
        item ->> 'kickoff_at',
        ''
      )::timestamptz as kickoff_at,
      nullif(
        item ->> 'broadcast_channel_id',
        ''
      )::uuid as broadcast_channel_id
    from jsonb_array_elements(p_rows) as item
  )
  update public.matches as m
  set
    scheduled_date = requested.scheduled_date,
    kickoff_at = requested.kickoff_at,
    broadcast_channel_id = case
      when requested.broadcast_channel_id is null
        then m.broadcast_channel_id
      else requested.broadcast_channel_id
    end
  from requested
  where
    m.id = requested.match_id
    and m.matchday_id = p_matchday_id
    and not requested.preserve
    and (
      m.scheduled_date
        is distinct from
        requested.scheduled_date
      or m.kickoff_at
        is distinct from
        requested.kickoff_at
      or (
        requested.broadcast_channel_id is not null
        and m.broadcast_channel_id
          is distinct from
          requested.broadcast_channel_id
      )
    );

  get diagnostics v_updated_count = row_count;

  return v_updated_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_bank_manual_classification_v1(p_matchday_id uuid, p_bank_item_id uuid, p_classification_key text)
 RETURNS TABLE(bank_item_id uuid, classification_key text, classification_source text, classified_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_bank record;
  v_changed boolean;
begin
  if p_matchday_id is null
    or p_bank_item_id is null
    or p_classification_key is null
  then
    raise exception
      'contextual-classification-manual-invalid-input';
  end if;

  if p_classification_key not in (
    'benfica',
    'sporting',
    'fc_porto',
    'other_liga_clubs',
    'outside_liga_other'
  )
  then
    raise exception
      'contextual-classification-manual-invalid-key:%',
      p_classification_key;
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as control_row
    where control_row.matchday_id = p_matchday_id
      and control_row.is_managed = true
  )
  then
    raise exception
      'contextual-classification-manual-not-live';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_profile_assignments as assignment_row
    where assignment_row.matchday_id = p_matchday_id
      and assignment_row.profile_key = 'liga_portugal_v1'
  )
  then
    raise exception
      'contextual-classification-manual-profile-not-supported';
  end if;

  select bank_row.*
  into v_bank
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.id = p_bank_item_id
  for update;

  if not found then
    raise exception
      'contextual-classification-manual-bank-item-not-found';
  end if;

  if v_bank.matchday_id is distinct from p_matchday_id then
    raise exception
      'contextual-classification-manual-matchday-mismatch';
  end if;

  if pg_catalog.lower(
       pg_catalog.btrim(coalesce(v_bank.status, ''))
     ) <> 'active'
  then
    raise exception
      'contextual-classification-manual-bank-item-inactive';
  end if;

  if pg_catalog.lower(
       pg_catalog.btrim(coalesce(v_bank.source_type, ''))
     ) <> 'editorial_article'
  then
    raise exception
      'contextual-classification-manual-non-article';
  end if;

  v_changed :=
    v_bank.classification_key
      is distinct from p_classification_key
    or v_bank.classification_source
      is distinct from 'manual';

  if v_changed then
    perform
      jornada_private
        .authorize_matchday_editorial_bank_classification_writes(
          array[p_bank_item_id]
        );

    begin
      update public.matchday_editorial_bank_items as bank_row
      set
        classification_key = p_classification_key,
        classification_source = 'manual',
        classified_at = pg_catalog.statement_timestamp()
      where bank_row.id = p_bank_item_id;

      perform
        jornada_private
          .revoke_matchday_editorial_bank_classification_writes(
            array[p_bank_item_id]
          );
    exception
      when others then
        perform
          jornada_private
            .revoke_matchday_editorial_bank_classification_writes(
              array[p_bank_item_id]
            );
        raise;
    end;

    perform
      public.refresh_matchday_editorial_profile_distribution(
        p_matchday_id
      );
  end if;

  return query
  select
    bank_row.id,
    bank_row.classification_key,
    bank_row.classification_source,
    bank_row.classified_at
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.id = p_bank_item_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_desk_state_v2(p_matchday_id uuid, p_expected_revision bigint, p_expected_state_token text, p_faixa_visible boolean, p_articles jsonb)
