CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_profile_manual_overrides(p_matchday_id uuid, p_profile_key text, p_overrides jsonb)
 RETURNS TABLE(applied_override_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_assignment_profile_key text;
  v_competition_slug text;
  v_item jsonb;
  v_source_id text;
  v_zone_key text;
  v_sort_order numeric;
  v_zone_capacity integer;
begin
  if p_matchday_id is null or p_profile_key is null or btrim(p_profile_key) = '' then
    raise exception 'matchday-editorial-profile-manual-overrides-invalid-input';
  end if;

  if p_profile_key <> 'liga_portugal_v1' then
    raise exception 'matchday-editorial-profile-manual-overrides-invalid-profile';
  end if;

  if p_overrides is null or jsonb_typeof(p_overrides) <> 'array' then
    raise exception 'matchday-editorial-profile-manual-overrides-invalid-payload';
  end if;

  select competition_row.slug
  into v_competition_slug
  from public.matchdays as matchday_row
  join public.seasons as season_row
    on season_row.id = matchday_row.season_id
  join public.competitions as competition_row
    on competition_row.id = season_row.competition_id
  where matchday_row.id = p_matchday_id
  for update of matchday_row;

  if not found then
    raise exception 'matchday-editorial-profile-manual-overrides-matchday-not-found';
  end if;

  -- The matchday lock serializes controlled assignment changes. Keep this
  -- assignment read unlocked before bank-row locks to avoid assignment -> bank
  -- ordering against the bank trigger's bank -> assignment refresh path.
  select assignment_row.profile_key
  into v_assignment_profile_key
  from public.matchday_editorial_profile_assignments as assignment_row
  where assignment_row.matchday_id = p_matchday_id;

  if not found then
    raise exception 'matchday-editorial-profile-manual-overrides-assignment-not-found';
  end if;

  if v_assignment_profile_key <> p_profile_key then
    raise exception 'matchday-editorial-profile-manual-overrides-assignment-mismatch';
  end if;

  if v_competition_slug <> 'liga-portugal' then
    raise exception 'matchday-editorial-profile-manual-overrides-incompatible-competition';
  end if;

  for v_item in
    select payload_item.value
    from jsonb_array_elements(p_overrides) as payload_item(value)
  loop
    if jsonb_typeof(v_item) <> 'object'
      or not (v_item ?& array['source_type', 'source_id', 'zone_key', 'sort_order'])
      or (v_item - array['source_type', 'source_id', 'zone_key', 'sort_order']) <> '{}'::jsonb
    then
      raise exception 'matchday-editorial-profile-manual-overrides-invalid-payload';
    end if;

    if jsonb_typeof(v_item -> 'source_type') <> 'string'
      or v_item ->> 'source_type' <> 'editorial_article'
      or jsonb_typeof(v_item -> 'source_id') <> 'string'
      or btrim(v_item ->> 'source_id') = ''
    then
      raise exception 'matchday-editorial-profile-manual-overrides-invalid-source';
    end if;

    v_source_id := lower(btrim(v_item ->> 'source_id'));

    if jsonb_typeof(v_item -> 'zone_key') = 'null' then
      v_zone_key := null;
    elsif jsonb_typeof(v_item -> 'zone_key') = 'string' then
      v_zone_key := v_item ->> 'zone_key';
    else
      raise exception 'matchday-editorial-profile-manual-overrides-invalid-zone';
    end if;

    if v_zone_key is not null
      and v_zone_key not in (
        'benfica',
        'sporting',
        'fc_porto',
        'other_liga_clubs',
        'outside_liga_other'
      )
    then
      raise exception 'matchday-editorial-profile-manual-overrides-invalid-zone';
    end if;

    if jsonb_typeof(v_item -> 'sort_order') = 'null' then
      v_sort_order := null;
    elsif jsonb_typeof(v_item -> 'sort_order') = 'number'
      and (v_item ->> 'sort_order') ~ '^[0-9]+$'
    then
      v_sort_order := (v_item ->> 'sort_order')::numeric;
    else
      raise exception 'matchday-editorial-profile-manual-overrides-invalid-sort-order';
    end if;

    if v_zone_key is null and v_sort_order is not null then
      raise exception 'matchday-editorial-profile-manual-overrides-invalid-placement';
    end if;

    if v_zone_key is not null then
      v_zone_capacity := case v_zone_key
        when 'benfica' then 6
        when 'sporting' then 5
        when 'fc_porto' then 5
        when 'other_liga_clubs' then 6
        when 'outside_liga_other' then 5
      end;

      if v_sort_order is not null
        and (v_sort_order <= 0 or v_sort_order > v_zone_capacity)
      then
        raise exception 'matchday-editorial-profile-manual-overrides-invalid-sort-order';
      end if;
    end if;

    perform 1
      from public.matchday_editorial_bank_items as bank_item
      where bank_item.matchday_id = p_matchday_id
        and lower(btrim(bank_item.source_type)) = 'editorial_article'
        and lower(btrim(bank_item.source_id)) = v_source_id
        and lower(btrim(bank_item.status)) = 'active'
      for share;

    if not found then
      raise exception 'matchday-editorial-profile-manual-overrides-source-not-active';
    end if;
  end loop;

  if exists (
    select 1
    from jsonb_array_elements(p_overrides) as payload_item(value)
    group by
      lower(btrim(payload_item.value ->> 'source_type')),
      lower(btrim(payload_item.value ->> 'source_id'))
    having count(*) > 1
  ) then
    raise exception 'matchday-editorial-profile-manual-overrides-duplicate-source';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_overrides) as payload_item(value)
    where jsonb_typeof(payload_item.value -> 'zone_key') = 'string'
      and jsonb_typeof(payload_item.value -> 'sort_order') = 'number'
    group by
      payload_item.value ->> 'zone_key',
      (payload_item.value ->> 'sort_order')::integer
    having count(*) > 1
  ) then
    raise exception 'matchday-editorial-profile-manual-overrides-duplicate-slot';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_overrides) as payload_item(value)
    where jsonb_typeof(payload_item.value -> 'zone_key') = 'string'
    group by payload_item.value ->> 'zone_key'
    having count(*) > case payload_item.value ->> 'zone_key'
      when 'benfica' then 6
      when 'sporting' then 5
      when 'fc_porto' then 5
      when 'other_liga_clubs' then 6
      when 'outside_liga_other' then 5
      else 0
    end
  ) then
    raise exception 'matchday-editorial-profile-manual-overrides-zone-capacity-exceeded';
  end if;

  delete from public.matchday_editorial_profile_manual_overrides
  where matchday_id = p_matchday_id
    and profile_key = p_profile_key;

  insert into public.matchday_editorial_profile_manual_overrides (
    matchday_id,
    profile_key,
    source_type,
    source_id,
    zone_key,
    sort_order
  )
  select
    p_matchday_id,
    p_profile_key,
    'editorial_article',
    lower(btrim(payload_item.value ->> 'source_id')),
    case
      when jsonb_typeof(payload_item.value -> 'zone_key') = 'null' then null
      else payload_item.value ->> 'zone_key'
    end,
    case
      when jsonb_typeof(payload_item.value -> 'sort_order') = 'null' then null
      else (payload_item.value ->> 'sort_order')::integer
    end
  from jsonb_array_elements(p_overrides) as payload_item(value);

  return query
  select jsonb_array_length(p_overrides);
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_profile_reconcile(p_matchday_id uuid, p_profile_key text, p_expected_revision bigint, p_expected_state_token text, p_overrides jsonb, p_zone_items jsonb, p_faixa_source_ids jsonb)
 RETURNS TABLE(revision bigint, state_token text, applied_override_count integer, applied_zone_item_count integer, applied_faixa_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_assignment_profile_key text;
  v_competition_slug text;
  v_current_revision bigint := 0;
  v_current_token text;
  v_next_revision bigint;
  v_now timestamptz := pg_catalog.now();
  v_offset integer;
begin
  if p_matchday_id is null
    or p_profile_key is null
    or pg_catalog.btrim(p_profile_key) = ''
    or p_expected_revision is null
    or p_expected_revision < 0
    or nullif(pg_catalog.btrim(p_expected_state_token), '') is null
    or p_overrides is null
    or pg_catalog.jsonb_typeof(p_overrides) <> 'array'
    or p_zone_items is null
    or pg_catalog.jsonb_typeof(p_zone_items) <> 'array'
    or p_faixa_source_ids is null
    or pg_catalog.jsonb_typeof(p_faixa_source_ids) <> 'array'
  then
    raise exception 'matchday-editorial-profile-reconcile-invalid-input';
  end if;

  if p_profile_key <> 'liga_portugal_v1' then
    raise exception 'matchday-editorial-profile-reconcile-invalid-profile';
  end if;

  select competition_row.slug
  into v_competition_slug
  from public.matchdays as matchday_row
  join public.seasons as season_row
    on season_row.id = matchday_row.season_id
  join public.competitions as competition_row
    on competition_row.id = season_row.competition_id
  where matchday_row.id = p_matchday_id
  for update of matchday_row;

  if not found then
    raise exception 'matchday-editorial-profile-reconcile-matchday-not-found';
  end if;

  -- Shared writers already serialize Faixa rewrites with this table lock.
  -- It is acquired before article and bank locks, matching the protected core
  -- path and avoiding an assignment -> bank inversion with automatic refresh.
  lock table public.matchday_horizontal_news in share row exclusive mode;
  lock table public.editorial_articles in share mode;

  perform 1
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.matchday_id = p_matchday_id
    and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
    and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) = 'editorial_article'
  order by pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)),
           pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
  for share;

  -- Automatic bank writers hold a bank row before the refresh locks the
  -- assignment. Taking these locks in the same bank -> assignment order avoids
  -- the inverse assignment -> bank cycle while keeping assignment/state stable.
  select assignment_row.profile_key
  into v_assignment_profile_key
  from public.matchday_editorial_profile_assignments as assignment_row
  where assignment_row.matchday_id = p_matchday_id
  for share;

  if not found then
    raise exception 'matchday-editorial-profile-reconcile-assignment-not-found';
  end if;
  if v_assignment_profile_key <> p_profile_key then
    raise exception 'matchday-editorial-profile-reconcile-assignment-mismatch';
  end if;
  if v_competition_slug <> 'liga-portugal' then
    raise exception 'matchday-editorial-profile-reconcile-incompatible-competition';
  end if;

  select control_row.revision
  into v_current_revision
  from public.matchday_editorial_profile_reconcile_control as control_row
  where control_row.matchday_id = p_matchday_id
    and control_row.profile_key = p_profile_key
  for update;
  v_current_revision := coalesce(v_current_revision, 0);

  if v_current_revision <> p_expected_revision then
    raise exception 'matchday-editorial-profile-reconcile-revision-conflict';
  end if;

  select token_row.state_token
  into v_current_token
  from public.matchday_editorial_profile_reconcile_token(
    p_matchday_id,
    p_profile_key
  ) as token_row;
  if v_current_token is distinct from p_expected_state_token then
    raise exception 'matchday-editorial-profile-reconcile-state-token-conflict';
  end if;

  if exists (
    select 1
    from public.matchday_horizontal_news as faixa_row
    where faixa_row.matchday_id = p_matchday_id
      and 1 <> (
        select pg_catalog.count(*)
        from public.editorial_articles as article_row
        where article_row.status = 'published'
          and nullif(pg_catalog.btrim(article_row.slug), '') is not null
          and '/noticias/' || pg_catalog.btrim(article_row.slug)
            = pg_catalog.btrim(faixa_row.link_url)
      )
  ) then
    raise exception 'matchday-editorial-profile-reconcile-unresolved-faixa';
  end if;

  if exists (
    select 1
    from public.matchday_horizontal_news as faixa_row
    join public.editorial_articles as article_row
      on article_row.status = 'published'
     and '/noticias/' || pg_catalog.btrim(article_row.slug)
       = pg_catalog.btrim(faixa_row.link_url)
    where faixa_row.matchday_id = p_matchday_id
    group by article_row.id
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-editorial-profile-reconcile-duplicate-faixa-identity';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as payload(value)
    where pg_catalog.jsonb_typeof(payload.value) <> 'object'
      or not (payload.value ?& array[
        'source_type', 'source_id', 'placement_target', 'zone_key', 'sort_order'
      ])
      or (payload.value - array[
        'source_type', 'source_id', 'placement_target', 'zone_key', 'sort_order'
      ]) <> '{}'::jsonb
      or pg_catalog.jsonb_typeof(payload.value -> 'source_type') <> 'string'
      or payload.value ->> 'source_type' <> 'editorial_article'
      or pg_catalog.jsonb_typeof(payload.value -> 'source_id') <> 'string'
      or nullif(pg_catalog.btrim(payload.value ->> 'source_id'), '') is null
      or pg_catalog.jsonb_typeof(payload.value -> 'placement_target') <> 'string'
      or payload.value ->> 'placement_target' not in ('bank', 'zone', 'faixa')
      or (
        payload.value ->> 'placement_target' = 'bank'
        and not (
          pg_catalog.jsonb_typeof(payload.value -> 'zone_key') = 'null'
          and pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'null'
        )
      )
      or (
        payload.value ->> 'placement_target' = 'zone'
        and not (
          pg_catalog.jsonb_typeof(payload.value -> 'zone_key') = 'string'
          and payload.value ->> 'zone_key' in (
            'benfica', 'sporting', 'fc_porto',
            'other_liga_clubs', 'outside_liga_other'
          )
          and (
            pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'null'
            or (
              pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'number'
              and (payload.value ->> 'sort_order') ~ '^[1-9][0-9]*$'
              and (payload.value ->> 'sort_order')::integer <= case payload.value ->> 'zone_key'
                when 'benfica' then 6
                when 'sporting' then 6
                when 'fc_porto' then 6
                when 'other_liga_clubs' then 6
                when 'outside_liga_other' then 6
              end
            )
          )
        )
      )
      or (
        payload.value ->> 'placement_target' = 'faixa'
        and not (
          pg_catalog.jsonb_typeof(payload.value -> 'zone_key') = 'null'
          and (
            pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'null'
            or (
              pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'number'
              and (payload.value ->> 'sort_order') ~ '^[1-9][0-9]*$'
            )
          )
        )
      )
  ) then
    raise exception 'matchday-editorial-profile-reconcile-invalid-overrides';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as payload(value)
    group by pg_catalog.lower(pg_catalog.btrim(payload.value ->> 'source_id'))
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-editorial-profile-reconcile-duplicate-override';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as payload(value)
    where payload.value ->> 'placement_target' = 'zone'
      and pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'number'
    group by payload.value ->> 'zone_key', (payload.value ->> 'sort_order')::integer
    having pg_catalog.count(*) > 1
  ) or exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as payload(value)
    where payload.value ->> 'placement_target' = 'faixa'
      and pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'number'
    group by (payload.value ->> 'sort_order')::integer
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-editorial-profile-reconcile-duplicate-manual-slot';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as payload(value)
    where payload.value ->> 'placement_target' = 'zone'
    group by payload.value ->> 'zone_key'
    having pg_catalog.count(*) > case payload.value ->> 'zone_key'
      when 'benfica' then 6
      when 'sporting' then 6
      when 'fc_porto' then 6
      when 'other_liga_clubs' then 6
      when 'outside_liga_other' then 6
    end
  ) then
    raise exception 'matchday-editorial-profile-reconcile-zone-capacity-exceeded';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as payload(value)
    where not exists (
      select 1
      from public.matchday_editorial_profile_workspace_sources(p_matchday_id) as classified
      where classified.source_type = 'editorial_article'
        and classified.source_id = pg_catalog.lower(pg_catalog.btrim(payload.value ->> 'source_id'))
    )
  ) then
    raise exception 'matchday-editorial-profile-reconcile-source-not-active';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zone_items) as payload(value)
    where pg_catalog.jsonb_typeof(payload.value) <> 'object'
      or not (payload.value ?& array['source_type', 'source_id', 'zone_key', 'sort_order'])
      or (payload.value - array['source_type', 'source_id', 'zone_key', 'sort_order']) <> '{}'::jsonb
      or payload.value ->> 'source_type' <> 'editorial_article'
      or pg_catalog.jsonb_typeof(payload.value -> 'source_id') <> 'string'
      or nullif(pg_catalog.btrim(payload.value ->> 'source_id'), '') is null
      or pg_catalog.jsonb_typeof(payload.value -> 'zone_key') <> 'string'
      or payload.value ->> 'zone_key' not in (
        'benfica', 'sporting', 'fc_porto',
        'other_liga_clubs', 'outside_liga_other'
      )
      or pg_catalog.jsonb_typeof(payload.value -> 'sort_order') <> 'number'
      or (payload.value ->> 'sort_order') !~ '^[1-9][0-9]*$'
      or (payload.value ->> 'sort_order')::integer > case payload.value ->> 'zone_key'
        when 'benfica' then 6
        when 'sporting' then 6
        when 'fc_porto' then 6
        when 'other_liga_clubs' then 6
        when 'outside_liga_other' then 6
      end
  ) then
    raise exception 'matchday-editorial-profile-reconcile-invalid-zone-items';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zone_items) as payload(value)
    group by pg_catalog.lower(pg_catalog.btrim(payload.value ->> 'source_id'))
    having pg_catalog.count(*) > 1
  ) or exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zone_items) as payload(value)
    group by payload.value ->> 'zone_key', (payload.value ->> 'sort_order')::integer
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-editorial-profile-reconcile-duplicate-zone-item';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zone_items) as payload(value)
    where not exists (
      select 1
      from public.matchday_editorial_profile_workspace_sources(p_matchday_id) as classified
      where classified.source_type = 'editorial_article'
        and classified.source_id = pg_catalog.lower(pg_catalog.btrim(payload.value ->> 'source_id'))
    )
  ) then
    raise exception 'matchday-editorial-profile-reconcile-zone-source-not-active';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as override_payload(value)
    where override_payload.value ->> 'placement_target' = 'zone'
      and not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_zone_items) as zone_payload(value)
        where pg_catalog.lower(pg_catalog.btrim(zone_payload.value ->> 'source_id'))
            = pg_catalog.lower(pg_catalog.btrim(override_payload.value ->> 'source_id'))
          and zone_payload.value ->> 'zone_key' = override_payload.value ->> 'zone_key'
          and (
            pg_catalog.jsonb_typeof(override_payload.value -> 'sort_order') = 'null'
            or (zone_payload.value ->> 'sort_order')::integer
              = (override_payload.value ->> 'sort_order')::integer
          )
      )
  ) then
    raise exception 'matchday-editorial-profile-reconcile-manual-zone-mismatch';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_source_ids) with ordinality as desired(value, sort_order)
    where pg_catalog.jsonb_typeof(desired.value) <> 'string'
      or nullif(pg_catalog.btrim(desired.value #>> '{}'), '') is null
  ) then
    raise exception 'matchday-editorial-profile-reconcile-invalid-faixa';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_source_ids) as desired(value)
    group by pg_catalog.lower(pg_catalog.btrim(desired.value #>> '{}'))
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-editorial-profile-reconcile-duplicate-faixa-item';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_source_ids) as desired(value)
    where not exists (
      select 1
      from public.matchday_editorial_profile_workspace_sources(p_matchday_id) as classified
      where classified.source_id = pg_catalog.lower(pg_catalog.btrim(desired.value #>> '{}'))
    )
  ) then
    raise exception 'matchday-editorial-profile-reconcile-faixa-source-not-active';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_faixa_source_ids) as desired(value)
    join pg_catalog.jsonb_array_elements(p_zone_items) as zone_payload(value)
      on pg_catalog.lower(pg_catalog.btrim(zone_payload.value ->> 'source_id'))
       = pg_catalog.lower(pg_catalog.btrim(desired.value #>> '{}'))
  ) then
    raise exception 'matchday-editorial-profile-reconcile-zone-faixa-duplicate';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as override_payload(value)
    where override_payload.value ->> 'placement_target' = 'bank'
      and (
        exists (
          select 1
          from pg_catalog.jsonb_array_elements(p_zone_items) as zone_payload(value)
          where pg_catalog.lower(pg_catalog.btrim(zone_payload.value ->> 'source_id'))
            = pg_catalog.lower(pg_catalog.btrim(override_payload.value ->> 'source_id'))
        )
        or exists (
          select 1
          from pg_catalog.jsonb_array_elements(p_faixa_source_ids) as faixa_payload(value)
          where pg_catalog.lower(pg_catalog.btrim(faixa_payload.value #>> '{}'))
            = pg_catalog.lower(pg_catalog.btrim(override_payload.value ->> 'source_id'))
        )
      )
  ) then
    raise exception 'matchday-editorial-profile-reconcile-explicit-bank-conflict';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as override_payload(value)
    where override_payload.value ->> 'placement_target' = 'faixa'
      and not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_faixa_source_ids) as faixa_payload(value)
        where pg_catalog.lower(pg_catalog.btrim(faixa_payload.value #>> '{}'))
            = pg_catalog.lower(pg_catalog.btrim(override_payload.value ->> 'source_id'))
      )
  ) then
    raise exception 'matchday-editorial-profile-reconcile-manual-faixa-mismatch';
  end if;

  -- An identical full-set Apply is a successful no-op. This comparison happens
  -- after every payload/canonicality check and before the first write, so it
  -- neither changes timestamps nor advances the optimistic revision.
  if exists (
    select 1
    from public.matchday_editorial_profile_reconcile_control as control_row
    where control_row.matchday_id = p_matchday_id
      and control_row.profile_key = p_profile_key
  )
  and not exists (
    select 1
    from public.matchday_editorial_profile_manual_overrides as current_row
    where current_row.matchday_id = p_matchday_id
      and current_row.profile_key = p_profile_key
      and not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_overrides) as desired(value)
        where pg_catalog.lower(pg_catalog.btrim(desired.value ->> 'source_id')) = current_row.source_id
          and desired.value ->> 'source_type' = current_row.source_type
          and desired.value ->> 'placement_target' = current_row.placement_target
          and case when pg_catalog.jsonb_typeof(desired.value -> 'zone_key') = 'null'
            then null else desired.value ->> 'zone_key' end is not distinct from current_row.zone_key
          and case when pg_catalog.jsonb_typeof(desired.value -> 'sort_order') = 'null'
            then null else (desired.value ->> 'sort_order')::integer end is not distinct from current_row.sort_order
      )
  )
  and not exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as desired(value)
    where not exists (
      select 1
      from public.matchday_editorial_profile_manual_overrides as current_row
      where current_row.matchday_id = p_matchday_id
        and current_row.profile_key = p_profile_key
        and current_row.source_id = pg_catalog.lower(pg_catalog.btrim(desired.value ->> 'source_id'))
        and current_row.source_type = desired.value ->> 'source_type'
        and current_row.placement_target = desired.value ->> 'placement_target'
        and current_row.zone_key is not distinct from case
          when pg_catalog.jsonb_typeof(desired.value -> 'zone_key') = 'null' then null
          else desired.value ->> 'zone_key'
        end
        and current_row.sort_order is not distinct from case
          when pg_catalog.jsonb_typeof(desired.value -> 'sort_order') = 'null' then null
          else (desired.value ->> 'sort_order')::integer
        end
    )
  )
  and not exists (
    select 1
    from public.matchday_editorial_profile_zone_items as current_row
    where current_row.matchday_id = p_matchday_id
      and current_row.profile_key = p_profile_key
      and not exists (
        select 1
        from pg_catalog.jsonb_array_elements(p_zone_items) as desired(value)
        where pg_catalog.lower(pg_catalog.btrim(desired.value ->> 'source_id')) = current_row.source_id
          and desired.value ->> 'source_type' = current_row.source_type
          and desired.value ->> 'zone_key' = current_row.zone_key
          and (desired.value ->> 'sort_order')::integer = current_row.sort_order
      )
  )
  and not exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zone_items) as desired(value)
    where not exists (
      select 1
      from public.matchday_editorial_profile_zone_items as current_row
      where current_row.matchday_id = p_matchday_id
        and current_row.profile_key = p_profile_key
        and current_row.source_id = pg_catalog.lower(pg_catalog.btrim(desired.value ->> 'source_id'))
        and current_row.source_type = desired.value ->> 'source_type'
        and current_row.zone_key = desired.value ->> 'zone_key'
        and current_row.sort_order = (desired.value ->> 'sort_order')::integer
    )
  )
  and not exists (
    select 1
    from (
      select
        faixa_row.sort_order,
        pg_catalog.row_number() over (order by faixa_row.sort_order, faixa_row.id) as expected_sort_order
      from public.matchday_horizontal_news as faixa_row
      where faixa_row.matchday_id = p_matchday_id
    ) as ordered_faixa
    where ordered_faixa.sort_order <> ordered_faixa.expected_sort_order
  )
  and array(
    select article_row.id::text
    from public.matchday_horizontal_news as faixa_row
    join public.editorial_articles as article_row
      on article_row.status = 'published'
     and '/noticias/' || pg_catalog.btrim(article_row.slug) = pg_catalog.btrim(faixa_row.link_url)
    where faixa_row.matchday_id = p_matchday_id
    order by faixa_row.sort_order, faixa_row.id
  ) = array(
    select pg_catalog.lower(pg_catalog.btrim(desired.value #>> '{}'))
    from pg_catalog.jsonb_array_elements(p_faixa_source_ids) with ordinality as desired(value, sort_order)
    order by desired.sort_order
  )
  then
    return query
    select
      v_current_revision,
      v_current_token,
      pg_catalog.jsonb_array_length(p_overrides),
      pg_catalog.jsonb_array_length(p_zone_items),
      pg_catalog.jsonb_array_length(p_faixa_source_ids);
    return;
  end if;

  delete from public.matchday_editorial_profile_manual_overrides
  where matchday_id = p_matchday_id
    and profile_key = p_profile_key;

  insert into public.matchday_editorial_profile_manual_overrides (
    matchday_id,
    profile_key,
    source_type,
    source_id,
    placement_target,
    zone_key,
    sort_order
  )
  select
    p_matchday_id,
    p_profile_key,
    'editorial_article',
    pg_catalog.lower(pg_catalog.btrim(payload.value ->> 'source_id')),
    payload.value ->> 'placement_target',
    case
      when pg_catalog.jsonb_typeof(payload.value -> 'zone_key') = 'null' then null
      else payload.value ->> 'zone_key'
    end,
    case
      when pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'null' then null
      when payload.value ->> 'placement_target' = 'faixa' then (
        select faixa_payload.sort_order::integer
        from pg_catalog.jsonb_array_elements(p_faixa_source_ids)
          with ordinality as faixa_payload(value, sort_order)
        where pg_catalog.lower(pg_catalog.btrim(faixa_payload.value #>> '{}'))
          = pg_catalog.lower(pg_catalog.btrim(payload.value ->> 'source_id'))
      )
      else (payload.value ->> 'sort_order')::integer
    end
  from pg_catalog.jsonb_array_elements(p_overrides) as payload(value);

  delete from public.matchday_editorial_profile_zone_items
  where matchday_id = p_matchday_id
    and profile_key = p_profile_key;

  insert into public.matchday_editorial_profile_zone_items (
    matchday_id,
    profile_key,
    source_type,
    source_id,
    zone_key,
    sort_order
  )
  select
    p_matchday_id,
    p_profile_key,
    'editorial_article',
    pg_catalog.lower(pg_catalog.btrim(payload.value ->> 'source_id')),
    payload.value ->> 'zone_key',
    (payload.value ->> 'sort_order')::integer
  from pg_catalog.jsonb_array_elements(p_zone_items) as payload(value);

  select coalesce(pg_catalog.max(faixa_row.sort_order), 0)
    + pg_catalog.jsonb_array_length(p_faixa_source_ids)
    + 1024
  into v_offset
  from public.matchday_horizontal_news as faixa_row
  where faixa_row.matchday_id = p_matchday_id;

  update public.matchday_horizontal_news
  set sort_order = sort_order + v_offset
  where matchday_id = p_matchday_id;

  delete from public.matchday_horizontal_news as faixa_row
  where faixa_row.matchday_id = p_matchday_id
    and not exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_faixa_source_ids) as desired(value)
      join public.editorial_articles as article_row
        on article_row.id::text = pg_catalog.lower(pg_catalog.btrim(desired.value #>> '{}'))
       and article_row.status = 'published'
       and '/noticias/' || pg_catalog.btrim(article_row.slug)
         = pg_catalog.btrim(faixa_row.link_url)
    );

  with desired as (
    select
      pg_catalog.lower(pg_catalog.btrim(payload.value #>> '{}')) as source_id,
      payload.sort_order::integer as sort_order
    from pg_catalog.jsonb_array_elements(p_faixa_source_ids) with ordinality as payload(value, sort_order)
  )
  update public.matchday_horizontal_news as faixa_row
  set sort_order = desired.sort_order,
      updated_at = v_now
  from desired
  join public.editorial_articles as article_row
    on article_row.id::text = desired.source_id
   and article_row.status = 'published'
  where faixa_row.matchday_id = p_matchday_id
    and '/noticias/' || pg_catalog.btrim(article_row.slug)
      = pg_catalog.btrim(faixa_row.link_url);

  with desired as (
    select
      pg_catalog.lower(pg_catalog.btrim(payload.value #>> '{}')) as source_id,
      payload.sort_order::integer as sort_order
    from pg_catalog.jsonb_array_elements(p_faixa_source_ids) with ordinality as payload(value, sort_order)
  )
  insert into public.matchday_horizontal_news (
    matchday_id,
    label,
    label_color,
    title,
    subtitle,
    image_url,
    link_url,
    sort_order,
    status,
    created_at,
    updated_at
  )
  select
    p_matchday_id,
    nullif(pg_catalog.btrim(article_row.label), ''),
    null,
    nullif(pg_catalog.btrim(article_row.title), ''),
    nullif(pg_catalog.btrim(article_row.subtitle), ''),
    nullif(pg_catalog.btrim(article_row.image_url), ''),
    '/noticias/' || pg_catalog.btrim(article_row.slug),
    desired.sort_order,
    'published',
    v_now,
    v_now
  from desired
  join public.editorial_articles as article_row
    on article_row.id::text = desired.source_id
   and article_row.status = 'published'
  where not exists (
    select 1
    from public.matchday_horizontal_news as faixa_row
    where faixa_row.matchday_id = p_matchday_id
      and pg_catalog.btrim(faixa_row.link_url)
        = '/noticias/' || pg_catalog.btrim(article_row.slug)
  )
  order by desired.sort_order;

  v_next_revision := v_current_revision + 1;
  insert into public.matchday_editorial_profile_reconcile_control (
    matchday_id,
    profile_key,
    revision,
    last_applied_at,
    updated_at
  ) values (
    p_matchday_id,
    p_profile_key,
    v_next_revision,
    v_now,
    v_now
  )
  on conflict (matchday_id, profile_key) do update set
    revision = excluded.revision,
    last_applied_at = excluded.last_applied_at,
    updated_at = excluded.updated_at;

  return query
  select
    v_next_revision,
    token_row.state_token,
    pg_catalog.jsonb_array_length(p_overrides),
    pg_catalog.jsonb_array_length(p_zone_items),
    pg_catalog.jsonb_array_length(p_faixa_source_ids)
  from public.matchday_editorial_profile_reconcile_token(
    p_matchday_id,
    p_profile_key
  ) as token_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_profile_workspace(p_matchday_id uuid, p_profile_key text, p_expected_revision bigint, p_expected_state_token text, p_overrides jsonb, p_zone_items jsonb, p_faixa_source_ids jsonb, p_opening jsonb, p_page_controls jsonb)
 RETURNS TABLE(revision bigint, state_token text, applied_override_count integer, applied_zone_item_count integer, applied_faixa_count integer, applied_opening_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_workspace_token text;
  v_base_token text;
  v_competition_slug text;
  v_apply record;
  v_now timestamptz := pg_catalog.now();
  v_requested_opening jsonb;
  v_current_opening jsonb;
  v_requested_controls jsonb;
  v_current_controls jsonb;
  v_headline_changed boolean;
  v_context_changed boolean;
  v_highlight_1_changed boolean;
  v_highlight_2_changed boolean;
  v_highlight_3_changed boolean;
  v_highlights_changed boolean;
  v_headline_color_changed boolean;
  v_latest_placement_changed boolean;
  v_zone_order_changed boolean;
  v_editorial_changed boolean;
  v_workspace_changed boolean;
  v_final_revision bigint;
  v_headline_source_id text;
  v_context_source_id text;
  v_headline public.editorial_articles%rowtype;
  v_context public.editorial_articles%rowtype;
  v_highlight_slot integer;
  v_highlight_key text;
  v_highlight_source_id text;
  v_highlight public.editorial_articles%rowtype;
begin
  if p_matchday_id is null
    or p_profile_key is null
    or pg_catalog.btrim(p_profile_key) = ''
    or p_expected_revision is null
    or p_expected_revision < 0
    or nullif(pg_catalog.btrim(p_expected_state_token), '') is null
    or p_overrides is null
    or pg_catalog.jsonb_typeof(p_overrides) <> 'array'
    or p_zone_items is null
    or pg_catalog.jsonb_typeof(p_zone_items) <> 'array'
    or p_faixa_source_ids is null
    or pg_catalog.jsonb_typeof(p_faixa_source_ids) <> 'array'
    or p_opening is null
    or pg_catalog.jsonb_typeof(p_opening) <> 'object'
    or p_page_controls is null
    or pg_catalog.jsonb_typeof(p_page_controls) <> 'object'
  then
    raise exception 'matchday-editorial-profile-workspace-invalid-input';
  end if;

  if p_profile_key <> 'liga_portugal_v1' then
    raise exception 'matchday-editorial-profile-workspace-invalid-profile';
  end if;

  if not (p_opening ?& array[
    'headline', 'highlight_1', 'highlight_2', 'highlight_3', 'context'
  ]) or (p_opening - array[
    'headline', 'highlight_1', 'highlight_2', 'highlight_3', 'context'
  ]) <> '{}'::jsonb then
    raise exception 'matchday-editorial-profile-workspace-invalid-opening';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_each(p_opening) as opening_row(slot_key, value)
    where pg_catalog.jsonb_typeof(opening_row.value) not in ('null', 'string')
      or (
        pg_catalog.jsonb_typeof(opening_row.value) = 'string'
        and nullif(pg_catalog.btrim(opening_row.value #>> '{}'), '') is null
      )
  ) then
    raise exception 'matchday-editorial-profile-workspace-invalid-opening';
  end if;

  if not (p_page_controls ?& array[
    'headline_title_color', 'latest_zone_placement', 'thematic_zone_order'
  ]) or (p_page_controls - array[
    'headline_title_color', 'latest_zone_placement', 'thematic_zone_order'
  ]) <> '{}'::jsonb then
    raise exception 'matchday-editorial-profile-workspace-invalid-page-controls';
  end if;

  if pg_catalog.jsonb_typeof(p_page_controls -> 'headline_title_color') not in ('null', 'string')
    or (
      pg_catalog.jsonb_typeof(p_page_controls -> 'headline_title_color') = 'string'
      and (p_page_controls ->> 'headline_title_color') !~ '^#[0-9A-Fa-f]{6}$'
    )
    or pg_catalog.jsonb_typeof(p_page_controls -> 'latest_zone_placement') <> 'string'
    or p_page_controls ->> 'latest_zone_placement' not in ('top', 'four_news', 'hidden')
    or pg_catalog.jsonb_typeof(p_page_controls -> 'thematic_zone_order') <> 'array'
  then
    raise exception 'matchday-editorial-profile-workspace-invalid-page-controls';
  end if;

  if pg_catalog.jsonb_array_length(p_page_controls -> 'thematic_zone_order') <> 5
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_page_controls -> 'thematic_zone_order') as zone_row(value)
      where pg_catalog.jsonb_typeof(zone_row.value) <> 'string'
        or zone_row.value #>> '{}' not in (
          'benfica', 'sporting', 'fc_porto', 'other_liga_clubs', 'outside_liga_other'
        )
    )
    or (
      select pg_catalog.count(distinct zone_row.value #>> '{}')
      from pg_catalog.jsonb_array_elements(p_page_controls -> 'thematic_zone_order') as zone_row(value)
    ) <> 5
  then
    raise exception 'matchday-editorial-profile-workspace-invalid-page-controls';
  end if;

  v_requested_opening := pg_catalog.jsonb_build_object(
    'headline', case when pg_catalog.jsonb_typeof(p_opening -> 'headline') = 'string'
      then pg_catalog.lower(pg_catalog.btrim(p_opening ->> 'headline')) else null end,
    'highlight_1', case when pg_catalog.jsonb_typeof(p_opening -> 'highlight_1') = 'string'
      then pg_catalog.lower(pg_catalog.btrim(p_opening ->> 'highlight_1')) else null end,
    'highlight_2', case when pg_catalog.jsonb_typeof(p_opening -> 'highlight_2') = 'string'
      then pg_catalog.lower(pg_catalog.btrim(p_opening ->> 'highlight_2')) else null end,
    'highlight_3', case when pg_catalog.jsonb_typeof(p_opening -> 'highlight_3') = 'string'
      then pg_catalog.lower(pg_catalog.btrim(p_opening ->> 'highlight_3')) else null end,
    'context', case when pg_catalog.jsonb_typeof(p_opening -> 'context') = 'string'
      then pg_catalog.lower(pg_catalog.btrim(p_opening ->> 'context')) else null end
  );
  v_requested_controls := pg_catalog.jsonb_build_object(
    'headline_title_color', case
      when pg_catalog.jsonb_typeof(p_page_controls -> 'headline_title_color') = 'string'
        then pg_catalog.upper(pg_catalog.btrim(p_page_controls ->> 'headline_title_color'))
      else null
    end,
    'latest_zone_placement', p_page_controls ->> 'latest_zone_placement',
    'thematic_zone_order', p_page_controls -> 'thematic_zone_order'
  );

  if exists (
    select 1
    from pg_catalog.jsonb_each(v_requested_opening) as opening_row(slot_key, value)
    where pg_catalog.jsonb_typeof(opening_row.value) = 'string'
    group by pg_catalog.lower(pg_catalog.btrim(opening_row.value #>> '{}'))
    having pg_catalog.count(*) > 1
  ) then
    raise exception 'matchday-editorial-profile-workspace-invalid-opening-duplicate';
  end if;

  select competition_row.slug
  into v_competition_slug
  from public.matchdays as matchday_row
  join public.seasons as season_row
    on season_row.id = matchday_row.season_id
  join public.competitions as competition_row
    on competition_row.id = season_row.competition_id
  where matchday_row.id = p_matchday_id
  for update of matchday_row;

  if not found then
    raise exception 'matchday-editorial-profile-workspace-matchday-not-found';
  end if;
  if v_competition_slug <> 'liga-portugal' then
    raise exception 'matchday-editorial-profile-workspace-incompatible-competition';
  end if;

  lock table public.matchday_editorials in share row exclusive mode;
  lock table public.matchday_highlights in share row exclusive mode;
  lock table public.matchday_horizontal_news in share row exclusive mode;
  lock table public.editorial_articles in share mode;

  perform 1
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.matchday_id = p_matchday_id
    and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
    and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)) = 'editorial_article'
  order by pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)),
           pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
  for share;

  perform 1
  from public.matchday_editorial_profile_assignments as assignment_row
  where assignment_row.matchday_id = p_matchday_id
    and assignment_row.profile_key = p_profile_key
  for share;
  if not found then
    raise exception 'matchday-editorial-profile-workspace-assignment-not-found';
  end if;

  perform 1
  from public.matchday_editorial_profile_reconcile_control as control_row
  where control_row.matchday_id = p_matchday_id
    and control_row.profile_key = p_profile_key
  for update;

  select token_row.state_token
  into v_current_workspace_token
  from public.matchday_editorial_profile_workspace_token(
    p_matchday_id,
    p_profile_key
  ) as token_row;
  if v_current_workspace_token is distinct from p_expected_state_token then
    raise exception 'matchday-editorial-profile-workspace-state-token-conflict';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_each(v_requested_opening) as opening_row(slot_key, value)
    where pg_catalog.jsonb_typeof(opening_row.value) = 'string'
      and not exists (
        select 1
        from public.matchday_editorial_profile_workspace_sources(p_matchday_id) as classified_row
        where classified_row.source_type = 'editorial_article'
          and classified_row.source_id = pg_catalog.lower(pg_catalog.btrim(opening_row.value #>> '{}'))
      )
  ) then
    raise exception 'matchday-editorial-profile-workspace-invalid-opening-source';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_each(v_requested_opening) as opening_row(slot_key, value)
    where pg_catalog.jsonb_typeof(opening_row.value) = 'string'
      and (
        exists (
          select 1
          from pg_catalog.jsonb_array_elements(p_zone_items) as zone_row(value)
          where pg_catalog.lower(pg_catalog.btrim(zone_row.value ->> 'source_id'))
            = pg_catalog.lower(pg_catalog.btrim(opening_row.value #>> '{}'))
        )
        or exists (
          select 1
          from pg_catalog.jsonb_array_elements(p_faixa_source_ids) as faixa_row(value)
          where pg_catalog.lower(pg_catalog.btrim(faixa_row.value #>> '{}'))
            = pg_catalog.lower(pg_catalog.btrim(opening_row.value #>> '{}'))
        )
        or exists (
          select 1
          from pg_catalog.jsonb_array_elements(p_overrides) as override_row(value)
          where pg_catalog.lower(pg_catalog.btrim(override_row.value ->> 'source_id'))
            = pg_catalog.lower(pg_catalog.btrim(opening_row.value #>> '{}'))
        )
      )
  ) then
    raise exception 'matchday-editorial-profile-workspace-exclusive-opening-conflict';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_profile_workspace_sources(p_matchday_id) as classified_row
    where (
      (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_each(v_requested_opening) as opening_row(slot_key, value)
        where pg_catalog.jsonb_typeof(opening_row.value) = 'string'
          and pg_catalog.lower(pg_catalog.btrim(opening_row.value #>> '{}')) = classified_row.source_id
      )
      + (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_array_elements(p_zone_items) as zone_row(value)
        where pg_catalog.lower(pg_catalog.btrim(zone_row.value ->> 'source_id')) = classified_row.source_id
      )
      + (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_array_elements(p_faixa_source_ids) as faixa_row(value)
        where pg_catalog.lower(pg_catalog.btrim(faixa_row.value #>> '{}')) = classified_row.source_id
      )
      + (
        select pg_catalog.count(*)
        from pg_catalog.jsonb_array_elements(p_overrides) as override_row(value)
        where override_row.value ->> 'placement_target' = 'bank'
          and pg_catalog.lower(pg_catalog.btrim(override_row.value ->> 'source_id')) = classified_row.source_id
      )
    ) > 1
  ) then
    raise exception 'matchday-editorial-profile-workspace-exclusive-placement-incomplete';
  end if;

  v_current_opening := pg_catalog.jsonb_build_object(
    'headline', (
      select pg_catalog.min(article_row.id::text)
      from public.matchday_editorials as editorial_row
      join public.editorial_articles as article_row
        on article_row.status = 'published'
       and '/noticias/' || pg_catalog.btrim(article_row.slug)
         = pg_catalog.btrim(editorial_row.headline_link_url)
      where editorial_row.matchday_id = p_matchday_id
        and editorial_row.status = 'published'
    ),
    'highlight_1', (
      select pg_catalog.min(article_row.id::text)
      from public.matchday_highlights as highlight_row
      join public.editorial_articles as article_row
        on article_row.status = 'published'
       and '/noticias/' || pg_catalog.btrim(article_row.slug)
         = pg_catalog.btrim(highlight_row.link_url)
      where highlight_row.matchday_id = p_matchday_id
        and highlight_row.sort_order = 1
        and highlight_row.status = 'published'
    ),
    'highlight_2', (
      select pg_catalog.min(article_row.id::text)
      from public.matchday_highlights as highlight_row
      join public.editorial_articles as article_row
        on article_row.status = 'published'
       and '/noticias/' || pg_catalog.btrim(article_row.slug)
         = pg_catalog.btrim(highlight_row.link_url)
      where highlight_row.matchday_id = p_matchday_id
        and highlight_row.sort_order = 2
        and highlight_row.status = 'published'
    ),
    'highlight_3', (
      select pg_catalog.min(article_row.id::text)
      from public.matchday_highlights as highlight_row
      join public.editorial_articles as article_row
        on article_row.status = 'published'
       and '/noticias/' || pg_catalog.btrim(article_row.slug)
         = pg_catalog.btrim(highlight_row.link_url)
      where highlight_row.matchday_id = p_matchday_id
        and highlight_row.sort_order = 3
        and highlight_row.status = 'published'
    ),
    'context', (
      select pg_catalog.min(article_row.id::text)
      from public.matchday_editorials as editorial_row
      join public.editorial_articles as article_row
        on article_row.status = 'published'
       and '/noticias/' || pg_catalog.btrim(article_row.slug)
         = pg_catalog.btrim(editorial_row.side_block_link_url)
      where editorial_row.matchday_id = p_matchday_id
        and editorial_row.side_block_status = 'published'
    )
  );

  v_current_controls := pg_catalog.jsonb_build_object(
    'headline_title_color', (
      select case
        when editorial_row.title_color ~ '^#[0-9A-Fa-f]{6}$'
          then pg_catalog.upper(editorial_row.title_color)
        else null
      end
      from public.matchday_editorials as editorial_row
      where editorial_row.matchday_id = p_matchday_id
    ),
    'latest_zone_placement', coalesce(
      (
        select case
          when editorial_row.latest_zone_placement in ('top', 'four_news', 'hidden')
            then editorial_row.latest_zone_placement
          else 'top'
        end
        from public.matchday_editorials as editorial_row
        where editorial_row.matchday_id = p_matchday_id
      ),
      'top'
    ),
    'thematic_zone_order', coalesce(
      (
        select pg_catalog.to_jsonb(control_row.thematic_zone_order)
        from public.matchday_editorial_profile_reconcile_control as control_row
        where control_row.matchday_id = p_matchday_id
          and control_row.profile_key = p_profile_key
      ),
      '["benfica","sporting","fc_porto","other_liga_clubs","outside_liga_other"]'::jsonb
    )
  );

  v_headline_changed := (v_current_opening -> 'headline') is distinct from (v_requested_opening -> 'headline');
  v_context_changed := (v_current_opening -> 'context') is distinct from (v_requested_opening -> 'context');
  v_highlight_1_changed := (v_current_opening -> 'highlight_1') is distinct from (v_requested_opening -> 'highlight_1');
  v_highlight_2_changed := (v_current_opening -> 'highlight_2') is distinct from (v_requested_opening -> 'highlight_2');
  v_highlight_3_changed := (v_current_opening -> 'highlight_3') is distinct from (v_requested_opening -> 'highlight_3');
  v_highlights_changed := v_highlight_1_changed or v_highlight_2_changed or v_highlight_3_changed;
  v_headline_color_changed := (v_current_controls -> 'headline_title_color') is distinct from (v_requested_controls -> 'headline_title_color');
  v_latest_placement_changed := (v_current_controls -> 'latest_zone_placement') is distinct from (v_requested_controls -> 'latest_zone_placement');
  v_zone_order_changed := (v_current_controls -> 'thematic_zone_order') is distinct from (v_requested_controls -> 'thematic_zone_order');
  v_editorial_changed := v_headline_changed or v_context_changed or v_headline_color_changed or v_latest_placement_changed;
  v_workspace_changed := v_editorial_changed or v_highlights_changed or v_zone_order_changed;

  if v_headline_changed and exists (
    select 1
    from public.matchday_editorials as editorial_row
    where editorial_row.matchday_id = p_matchday_id
      and editorial_row.status <> 'published'
      and coalesce(
        nullif(pg_catalog.btrim(editorial_row.title), ''),
        nullif(pg_catalog.btrim(editorial_row.summary), ''),
        nullif(pg_catalog.btrim(editorial_row.image_url), ''),
        nullif(pg_catalog.btrim(editorial_row.headline_link_url), '')
      ) is not null
  ) then
    raise exception 'matchday-editorial-profile-workspace-headline-draft-content';
  end if;

  if v_context_changed and exists (
    select 1
    from public.matchday_editorials as editorial_row
    where editorial_row.matchday_id = p_matchday_id
      and editorial_row.side_block_status <> 'published'
      and coalesce(
        nullif(pg_catalog.btrim(editorial_row.side_block_label), ''),
        nullif(pg_catalog.btrim(editorial_row.side_block_title), ''),
        nullif(pg_catalog.btrim(editorial_row.side_block_author), ''),
        nullif(pg_catalog.btrim(editorial_row.side_block_text), ''),
        nullif(pg_catalog.btrim(editorial_row.side_block_image_url), ''),
        nullif(pg_catalog.btrim(editorial_row.side_block_link_url), '')
      ) is not null
  ) then
    raise exception 'matchday-editorial-profile-workspace-context-draft-content';
  end if;

  for v_highlight_slot in 1..3 loop
    v_highlight_key := 'highlight_' || v_highlight_slot::text;
    if (v_current_opening -> v_highlight_key) is distinct from (v_requested_opening -> v_highlight_key) then
      if (
        select pg_catalog.count(*) > 1
        from public.matchday_highlights as highlight_row
        where highlight_row.matchday_id = p_matchday_id
          and highlight_row.sort_order = v_highlight_slot
      ) then
        raise exception 'matchday-editorial-profile-workspace-duplicate-highlight-slot';
      end if;

      if exists (
        select 1
        from public.matchday_highlights as highlight_row
        where highlight_row.matchday_id = p_matchday_id
          and highlight_row.sort_order = v_highlight_slot
          and highlight_row.status <> 'published'
          and coalesce(
            nullif(pg_catalog.btrim(highlight_row.label), ''),
            nullif(pg_catalog.btrim(highlight_row.title), ''),
            nullif(pg_catalog.btrim(highlight_row.subtitle), ''),
            nullif(pg_catalog.btrim(highlight_row.image_url), ''),
            nullif(pg_catalog.btrim(highlight_row.link_url), '')
          ) is not null
      ) then
        raise exception 'matchday-editorial-profile-workspace-highlight-draft-content';
      end if;
    end if;
  end loop;

  select token_row.state_token
  into v_base_token
  from public.matchday_editorial_profile_reconcile_token(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  select *
  into v_apply
  from public.apply_matchday_editorial_profile_reconcile_v2(
    p_matchday_id,
    p_profile_key,
    p_expected_revision,
    v_base_token,
    p_overrides,
    p_zone_items,
    p_faixa_source_ids
  );

  perform pg_catalog.set_config(
    'jornada.thematic_workspace_apply',
    'on',
    true
  );

  if v_editorial_changed then
    v_headline_source_id := v_requested_opening ->> 'headline';
    v_context_source_id := v_requested_opening ->> 'context';

    if v_headline_changed and v_headline_source_id is not null then
      select article_row.* into strict v_headline
      from public.editorial_articles as article_row
      where article_row.id::text = v_headline_source_id
        and article_row.status = 'published';
    end if;

    if v_context_changed and v_context_source_id is not null then
      select article_row.* into strict v_context
      from public.editorial_articles as article_row
      where article_row.id::text = v_context_source_id
        and article_row.status = 'published';
    end if;

    insert into public.matchday_editorials (matchday_id, updated_at)
    values (p_matchday_id, v_now)
    on conflict (matchday_id) do nothing;

    update public.matchday_editorials as editorial_row
    set
      title = case when v_headline_changed
        then nullif(pg_catalog.btrim(v_headline.title), '') else editorial_row.title end,
      summary = case when v_headline_changed
        then nullif(pg_catalog.btrim(v_headline.subtitle), '') else editorial_row.summary end,
      image_url = case when v_headline_changed
        then nullif(pg_catalog.btrim(v_headline.image_url), '') else editorial_row.image_url end,
      headline_link_url = case when v_headline_changed
        then case when v_headline_source_id is null then null
          else '/noticias/' || pg_catalog.btrim(v_headline.slug) end
        else editorial_row.headline_link_url end,
      status = case when v_headline_changed
        then case when v_headline_source_id is null then 'draft' else 'published' end
        else editorial_row.status end,
      side_block_status = case when v_context_changed
        then case when v_context_source_id is null then 'draft' else 'published' end
        else editorial_row.side_block_status end,
      side_block_label = case when v_context_changed
        then nullif(pg_catalog.btrim(v_context.label), '') else editorial_row.side_block_label end,
      side_block_title = case when v_context_changed
        then nullif(pg_catalog.btrim(v_context.title), '') else editorial_row.side_block_title end,
      side_block_author = case when v_context_changed
        then nullif(pg_catalog.btrim(v_context.author), '') else editorial_row.side_block_author end,
      side_block_text = case when v_context_changed
        then pg_catalog.left(nullif(pg_catalog.btrim(v_context.subtitle), ''), 500)
        else editorial_row.side_block_text end,
      side_block_image_url = case when v_context_changed
        then nullif(pg_catalog.btrim(v_context.image_url), '') else editorial_row.side_block_image_url end,
      side_block_link_url = case when v_context_changed
        then case when v_context_source_id is null then null
          else '/noticias/' || pg_catalog.btrim(v_context.slug) end
        else editorial_row.side_block_link_url end,
      title_color = case when v_headline_color_changed
        then v_requested_controls ->> 'headline_title_color' else editorial_row.title_color end,
      latest_zone_placement = case when v_latest_placement_changed
        then v_requested_controls ->> 'latest_zone_placement' else editorial_row.latest_zone_placement end,
      updated_at = v_now
    where editorial_row.matchday_id = p_matchday_id;
  end if;

  if v_highlights_changed then
    for v_highlight_slot in 1..3 loop
      v_highlight_key := 'highlight_' || v_highlight_slot::text;
      if (v_current_opening -> v_highlight_key) is distinct from (v_requested_opening -> v_highlight_key) then
        v_highlight_source_id := v_requested_opening ->> v_highlight_key;

        if v_highlight_source_id is null then
          delete from public.matchday_highlights
          where matchday_id = p_matchday_id
            and sort_order = v_highlight_slot;
        else
          select article_row.* into strict v_highlight
          from public.editorial_articles as article_row
          where article_row.id::text = v_highlight_source_id
            and article_row.status = 'published';

          update public.matchday_highlights as highlight_row
          set
            label = nullif(pg_catalog.btrim(v_highlight.label), ''),
            title = nullif(pg_catalog.btrim(v_highlight.title), ''),
            subtitle = nullif(pg_catalog.btrim(v_highlight.subtitle), ''),
            image_url = nullif(pg_catalog.btrim(v_highlight.image_url), ''),
            link_url = '/noticias/' || pg_catalog.btrim(v_highlight.slug),
            status = 'published',
            updated_at = v_now
          where highlight_row.matchday_id = p_matchday_id
            and highlight_row.sort_order = v_highlight_slot;

          if not found then
            insert into public.matchday_highlights (
              matchday_id,
              label,
              label_color,
              title,
              subtitle,
              image_url,
              link_url,
              sort_order,
              status,
              created_at,
              updated_at
            ) values (
              p_matchday_id,
              nullif(pg_catalog.btrim(v_highlight.label), ''),
              null,
              nullif(pg_catalog.btrim(v_highlight.title), ''),
              nullif(pg_catalog.btrim(v_highlight.subtitle), ''),
              nullif(pg_catalog.btrim(v_highlight.image_url), ''),
              '/noticias/' || pg_catalog.btrim(v_highlight.slug),
              v_highlight_slot,
              'published',
              v_now,
              v_now
            );
          end if;
        end if;
      end if;
    end loop;
  end if;

  if v_zone_order_changed then
    update public.matchday_editorial_profile_reconcile_control as control_row
    set
      thematic_zone_order = array(
        select zone_row.value #>> '{}'
        from pg_catalog.jsonb_array_elements(
          v_requested_controls -> 'thematic_zone_order'
        ) with ordinality as zone_row(value, sort_order)
        order by zone_row.sort_order
      ),
      updated_at = v_now
    where control_row.matchday_id = p_matchday_id
      and control_row.profile_key = p_profile_key;

    if not found then
      raise exception 'matchday-editorial-profile-workspace-reconcile-control-not-found';
    end if;
  end if;

  v_final_revision := v_apply.revision;
  if v_workspace_changed and v_final_revision = p_expected_revision then
    v_final_revision := p_expected_revision + 1;
    insert into public.matchday_editorial_profile_reconcile_control (
      matchday_id,
      profile_key,
      revision,
      last_applied_at,
      updated_at
    ) values (
      p_matchday_id,
      p_profile_key,
      v_final_revision,
      v_now,
      v_now
    )
    on conflict (matchday_id, profile_key) do update set
      revision = excluded.revision,
      last_applied_at = excluded.last_applied_at,
      updated_at = excluded.updated_at;
  end if;

  return query
  select
    v_final_revision,
    token_row.state_token,
    v_apply.applied_override_count,
    v_apply.applied_zone_item_count,
    v_apply.applied_faixa_count,
    (
      select pg_catalog.count(*)::integer
      from pg_catalog.jsonb_each(v_requested_opening) as opening_row(slot_key, value)
      where pg_catalog.jsonb_typeof(opening_row.value) = 'string'
    )
  from public.matchday_editorial_profile_workspace_token(
    p_matchday_id,
    p_profile_key
  ) as token_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_profile_workspace_v10(p_matchday_id uuid, p_profile_key text, p_expected_revision bigint, p_expected_state_token text, p_overrides jsonb, p_zone_items jsonb, p_faixa_source_ids jsonb, p_opening jsonb, p_page_controls jsonb, p_selection_bank_item_ids jsonb, p_video_module jsonb, p_worked_source_ids jsonb)
 RETURNS TABLE(revision bigint, state_token text, applied_override_count integer, applied_zone_item_count integer, applied_faixa_count integer, applied_opening_count integer, applied_selection_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_apply record;
  v_final_state_token text;
begin
  perform pg_catalog.set_config(
    'jornada.thematic_workspace_token_cache',
    '',
    true
  );

  perform pg_catalog.set_config(
    'jornada.thematic_reconcile_token_cache',
    '',
    true
  );

  perform pg_catalog.set_config(
    'jornada.thematic_workspace_sources_cache',
    '',
    true
  );

  perform pg_catalog.set_config(
    'jornada.thematic_workspace_sources_cache_matchday',
    '',
    true
  );

  perform pg_catalog.set_config(
    'jornada.thematic_apply_token_cache_mode',
    'v10',
    true
  );

  select *
  into v_apply
  from public.apply_matchday_editorial_profile_workspace_v9(
    p_matchday_id,
    p_profile_key,
    p_expected_revision,
    p_expected_state_token,
    p_overrides,
    p_zone_items,
    p_faixa_source_ids,
    p_opening,
    p_page_controls,
    p_selection_bank_item_ids,
    p_video_module,
    p_worked_source_ids
  );

  perform pg_catalog.set_config(
    'jornada.thematic_apply_token_cache_mode',
    'off',
    true
  );

  perform pg_catalog.set_config(
    'jornada.thematic_workspace_token_cache',
    '',
    true
  );

  perform pg_catalog.set_config(
    'jornada.thematic_reconcile_token_cache',
    '',
    true
  );

  perform pg_catalog.set_config(
    'jornada.thematic_workspace_sources_cache',
    '',
    true
  );

  perform pg_catalog.set_config(
    'jornada.thematic_workspace_sources_cache_matchday',
    '',
    true
  );

  select token_row.state_token
  into v_final_state_token
  from public.matchday_editorial_profile_workspace_token(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  return query
  select
    v_apply.revision,
    v_final_state_token,
    v_apply.applied_override_count,
    v_apply.applied_zone_item_count,
    v_apply.applied_faixa_count,
    v_apply.applied_opening_count,
    v_apply.applied_selection_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_profile_workspace_v2(p_matchday_id uuid, p_profile_key text, p_expected_revision bigint, p_expected_state_token text, p_overrides jsonb, p_zone_items jsonb, p_faixa_source_ids jsonb, p_opening jsonb, p_page_controls jsonb)
 RETURNS TABLE(revision bigint, state_token text, applied_override_count integer, applied_zone_item_count integer, applied_faixa_count integer, applied_opening_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_requested_layouts jsonb;
  v_requested_block_order text[];
  v_requested_zone_order text[];
  v_derived_zone_order text[];
  v_current_layouts jsonb;
  v_current_block_order text[];
  v_control_changed boolean := false;
  v_apply record;
  v_final_revision bigint;
  v_now timestamptz := pg_catalog.now();
begin
  if p_matchday_id is null
    or p_profile_key is null
    or pg_catalog.btrim(p_profile_key) = ''
    or p_expected_revision is null
    or p_expected_revision < 0
    or nullif(
      pg_catalog.btrim(p_expected_state_token),
      ''
    ) is null
    or p_overrides is null
    or pg_catalog.jsonb_typeof(p_overrides) <> 'array'
    or p_zone_items is null
    or pg_catalog.jsonb_typeof(p_zone_items) <> 'array'
    or p_faixa_source_ids is null
    or pg_catalog.jsonb_typeof(
      p_faixa_source_ids
    ) <> 'array'
    or p_opening is null
    or pg_catalog.jsonb_typeof(p_opening) <> 'object'
    or p_page_controls is null
    or pg_catalog.jsonb_typeof(
      p_page_controls
    ) <> 'object'
  then
    raise exception
      'matchday-editorial-profile-workspace-v2-invalid-input';
  end if;

  if p_profile_key <> 'liga_portugal_v1' then
    raise exception
      'matchday-editorial-profile-workspace-v2-invalid-profile';
  end if;

  if not (
    p_page_controls ?& array[
      'headline_title_color',
      'latest_zone_placement',
      'thematic_zone_order',
      'thematic_zone_layouts',
      'thematic_block_order'
    ]
  )
  or (
    p_page_controls - array[
      'headline_title_color',
      'latest_zone_placement',
      'thematic_zone_order',
      'thematic_zone_layouts',
      'thematic_block_order'
    ]::text[]
  ) <> '{}'::jsonb
  then
    raise exception
      'matchday-editorial-profile-workspace-v2-invalid-page-controls';
  end if;

  v_requested_layouts :=
    p_page_controls -> 'thematic_zone_layouts';

  if pg_catalog.jsonb_typeof(
    v_requested_layouts
  ) <> 'object'
    or not (
      v_requested_layouts ?& array[
        'benfica',
        'sporting',
        'fc_porto',
        'other_liga_clubs',
        'outside_liga_other'
      ]
    )
    or (
      v_requested_layouts - array[
        'benfica',
        'sporting',
        'fc_porto',
        'other_liga_clubs',
        'outside_liga_other'
      ]::text[]
    ) <> '{}'::jsonb
    or v_requested_layouts ->> 'benfica'
      not in ('six_news', 'six_news_1_2_3','five_news_balanced','five_news_secondary')
    or v_requested_layouts ->> 'sporting'
      not in ('six_news', 'six_news_1_2_3','five_news_balanced','five_news_secondary')
    or v_requested_layouts ->> 'fc_porto'
      not in ('six_news', 'six_news_1_2_3','five_news_balanced','five_news_secondary')
    or v_requested_layouts ->> 'other_liga_clubs'
      not in ('six_news', 'six_news_1_2_3','five_news_balanced','five_news_secondary')
    or v_requested_layouts ->> 'outside_liga_other'
      not in ('six_news', 'six_news_1_2_3','five_news_balanced','five_news_secondary')
  then
    raise exception
      'matchday-editorial-profile-workspace-v2-invalid-zone-layouts';
  end if;

  if pg_catalog.jsonb_typeof(
    p_page_controls -> 'thematic_block_order'
  ) <> 'array'
    or pg_catalog.jsonb_array_length(
      p_page_controls -> 'thematic_block_order'
    ) <> 6
  then
    raise exception
      'matchday-editorial-profile-workspace-v2-invalid-block-order';
  end if;

  select pg_catalog.array_agg(
    row_value.value #>> '{}'
    order by row_value.sort_order
  )
  into v_requested_block_order
  from pg_catalog.jsonb_array_elements(
    p_page_controls -> 'thematic_block_order'
  ) with ordinality as row_value(value, sort_order);

  if v_requested_block_order is null
    or pg_catalog.cardinality(v_requested_block_order) <> 6
    or not (
      v_requested_block_order <@ array[
        'benfica','sporting','fc_porto','other_liga_clubs','outside_liga_other','latest'
      ]::text[]
      and v_requested_block_order @> array[
        'benfica','sporting','fc_porto','other_liga_clubs','outside_liga_other','latest'
      ]::text[]
    )
  then
    raise exception
      'matchday-editorial-profile-workspace-v2-invalid-block-order';
  end if;

  if pg_catalog.jsonb_typeof(
    p_page_controls -> 'thematic_zone_order'
  ) <> 'array'
    or pg_catalog.jsonb_array_length(
      p_page_controls -> 'thematic_zone_order'
    ) <> 5
  then
    raise exception
      'matchday-editorial-profile-workspace-v2-invalid-zone-order';
  end if;

  select pg_catalog.array_agg(
    row_value.value #>> '{}'
    order by row_value.sort_order
  )
  into v_requested_zone_order
  from pg_catalog.jsonb_array_elements(
    p_page_controls -> 'thematic_zone_order'
  ) with ordinality as row_value(value, sort_order);

  select pg_catalog.array_agg(
    row_value.block_key
    order by row_value.sort_order
  )
  into v_derived_zone_order
  from pg_catalog.unnest(v_requested_block_order)
    with ordinality as row_value(block_key, sort_order)
  where row_value.block_key <> 'latest';

  if v_requested_zone_order is distinct from v_derived_zone_order then
    raise exception
      'matchday-editorial-profile-workspace-v2-zone-order-mismatch';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as payload(value)
    where payload.value ->> 'placement_target' = 'zone'
      and pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'number'
      and (payload.value ->> 'sort_order') ~ '^[1-9][0-9]*$'
      and (payload.value ->> 'sort_order')::integer >
        case v_requested_layouts ->> (payload.value ->> 'zone_key')
          when 'six_news' then 6 when 'six_news_1_2_3' then 6
          when 'five_news_balanced' then 5
          when 'five_news_secondary' then 5
          else 0
        end
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v2-manual-position-exceeds-layout';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_overrides) as payload(value)
    where payload.value ->> 'placement_target' = 'zone'
    group by payload.value ->> 'zone_key'
    having pg_catalog.count(*) >
      case v_requested_layouts ->> (payload.value ->> 'zone_key')
        when 'six_news' then 6 when 'six_news_1_2_3' then 6
        when 'five_news_balanced' then 5
        when 'five_news_secondary' then 5
        else 0
      end
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v2-manual-zone-exceeds-layout';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zone_items) as payload(value)
    where pg_catalog.jsonb_typeof(payload.value -> 'sort_order') = 'number'
      and (payload.value ->> 'sort_order') ~ '^[1-9][0-9]*$'
      and (payload.value ->> 'sort_order')::integer >
        case v_requested_layouts ->> (payload.value ->> 'zone_key')
          when 'six_news' then 6 when 'six_news_1_2_3' then 6
          when 'five_news_balanced' then 5
          when 'five_news_secondary' then 5
          else 0
        end
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v2-zone-item-exceeds-layout';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_zone_items) as payload(value)
    group by payload.value ->> 'zone_key'
    having pg_catalog.count(*) >
      case v_requested_layouts ->> (payload.value ->> 'zone_key')
        when 'six_news' then 6 when 'six_news_1_2_3' then 6
        when 'five_news_balanced' then 5
        when 'five_news_secondary' then 5
        else 0
      end
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v2-zone-exceeds-layout';
  end if;

  select
    control_row.thematic_zone_layouts,
    control_row.thematic_block_order
  into
    v_current_layouts,
    v_current_block_order
  from public.matchday_editorial_profile_reconcile_control as control_row
  where control_row.matchday_id = p_matchday_id
    and control_row.profile_key = p_profile_key;

  v_control_changed :=
    coalesce(
      v_current_layouts,
      '{"benfica":"six_news","sporting":"five_news_balanced","fc_porto":"five_news_balanced","other_liga_clubs":"six_news","outside_liga_other":"five_news_secondary"}'::jsonb
    ) is distinct from v_requested_layouts
    or coalesce(
      v_current_block_order,
      array[
        'benfica','sporting','fc_porto','other_liga_clubs','outside_liga_other','latest'
      ]::text[]
    ) is distinct from v_requested_block_order;

  select *
  into v_apply
  from public.apply_matchday_editorial_profile_workspace(
    p_matchday_id,
    p_profile_key,
    p_expected_revision,
    p_expected_state_token,
    p_overrides,
    p_zone_items,
    p_faixa_source_ids,
    p_opening,
    pg_catalog.jsonb_build_object(
      'headline_title_color', p_page_controls -> 'headline_title_color',
      'latest_zone_placement', p_page_controls -> 'latest_zone_placement',
      'thematic_zone_order', pg_catalog.to_jsonb(v_requested_zone_order)
    )
  );

  update public.matchday_editorial_profile_reconcile_control as control_row
  set thematic_zone_layouts = v_requested_layouts,
      thematic_block_order = v_requested_block_order,
      updated_at = v_now
  where control_row.matchday_id = p_matchday_id
    and control_row.profile_key = p_profile_key;

  if not found then
    raise exception
      'matchday-editorial-profile-workspace-v2-control-not-found';
  end if;

  v_final_revision := v_apply.revision;

  if v_control_changed
    and v_final_revision = p_expected_revision
  then
    update public.matchday_editorial_profile_reconcile_control as control_row
    set revision = control_row.revision + 1,
        last_applied_at = v_now,
        updated_at = v_now
    where control_row.matchday_id = p_matchday_id
      and control_row.profile_key = p_profile_key
    returning control_row.revision into v_final_revision;
  end if;

  return query
  select
    v_final_revision,
    token_row.state_token,
    v_apply.applied_override_count,
    v_apply.applied_zone_item_count,
    v_apply.applied_faixa_count,
    v_apply.applied_opening_count
  from public.matchday_editorial_profile_workspace_token(
    p_matchday_id,
    p_profile_key
  ) as token_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_profile_workspace_v6(p_matchday_id uuid, p_profile_key text, p_expected_revision bigint, p_expected_state_token text, p_overrides jsonb, p_zone_items jsonb, p_faixa_source_ids jsonb, p_opening jsonb, p_page_controls jsonb, p_selection_bank_item_ids jsonb, p_video_module jsonb)
 RETURNS TABLE(revision bigint, state_token text, applied_override_count integer, applied_zone_item_count integer, applied_faixa_count integer, applied_opening_count integer, applied_selection_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_apply record;
  v_bank public.matchday_editorial_bank_items%rowtype;
  v_current_block_order text[];
  v_requested_block_order text[];
  v_legacy_page_controls jsonb;
  v_highlight_action text;
  v_highlight_bank_item_id uuid;
  v_requested_active boolean;
  v_current_active boolean;
  v_module_changed boolean := false;
  v_block_order_changed boolean := false;
  v_final_revision bigint;
  v_now timestamptz := pg_catalog.now();
begin
  if p_page_controls is null
    or pg_catalog.jsonb_typeof(p_page_controls) <> 'object'
    or pg_catalog.jsonb_typeof(
      p_page_controls -> 'thematic_block_order'
    ) <> 'array'
  then
    raise exception
      'matchday-editorial-profile-workspace-v6-invalid-page-controls';
  end if;

  if pg_catalog.jsonb_array_length(
      p_page_controls -> 'thematic_block_order'
    ) <> 7
    or (
      select count(distinct item.value #>> '{}')
      from pg_catalog.jsonb_array_elements(
        p_page_controls -> 'thematic_block_order'
      ) as item(value)
    ) <> 7
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        p_page_controls -> 'thematic_block_order'
      ) as item(value)
      where pg_catalog.jsonb_typeof(item.value) <> 'string'
        or item.value #>> '{}' not in (
          'benfica',
          'sporting',
          'fc_porto',
          'other_liga_clubs',
          'outside_liga_other',
          'latest',
          'video'
        )
    )
  then
    raise exception
      'matchday-editorial-profile-workspace-v6-invalid-block-order';
  end if;

  if p_video_module is null
    or pg_catalog.jsonb_typeof(p_video_module) <> 'object'
    or not (
      p_video_module ?& array[
        'active',
        'highlight_action',
        'highlight_bank_item_id'
      ]
    )
    or (
      p_video_module - array[
        'active',
        'highlight_action',
        'highlight_bank_item_id'
      ]::text[]
    ) <> '{}'::jsonb
    or pg_catalog.jsonb_typeof(
      p_video_module -> 'active'
    ) <> 'boolean'
    or pg_catalog.jsonb_typeof(
      p_video_module -> 'highlight_action'
    ) <> 'string'
    or p_video_module ->> 'highlight_action'
      not in ('preserve', 'remove', 'replace')
    or pg_catalog.jsonb_typeof(
      p_video_module -> 'highlight_bank_item_id'
    ) not in ('string', 'null')
  then
    raise exception
      'matchday-editorial-profile-workspace-v6-invalid-video-module';
  end if;

  v_requested_active :=
    (p_video_module ->> 'active')::boolean;
  v_highlight_action :=
    p_video_module ->> 'highlight_action';

  if v_highlight_action = 'replace' then
    if coalesce(
      p_video_module ->> 'highlight_bank_item_id',
      ''
    ) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then
      raise exception
        'matchday-editorial-profile-workspace-v6-invalid-highlight-source';
    end if;

    v_highlight_bank_item_id :=
      (p_video_module ->> 'highlight_bank_item_id')::uuid;
  elsif p_video_module ->> 'highlight_bank_item_id'
    is not null
  then
    raise exception
      'matchday-editorial-profile-workspace-v6-unexpected-highlight-source';
  end if;

  select
    control_row.thematic_block_order
  into v_current_block_order
  from public.matchday_editorial_profile_reconcile_control
    as control_row
  where control_row.matchday_id = p_matchday_id
    and control_row.profile_key = p_profile_key;

  select
    coalesce(
      editorial_row.complementary_mode = 'roundup_video',
      false
    )
  into v_current_active
  from public.matchday_editorials as editorial_row
  where editorial_row.matchday_id = p_matchday_id;

  select pg_catalog.array_agg(
    item.value #>> '{}'
    order by item.ordinality
  )
  into v_requested_block_order
  from pg_catalog.jsonb_array_elements(
    p_page_controls -> 'thematic_block_order'
  ) with ordinality as item(value, ordinality);

  v_block_order_changed :=
    v_current_block_order is distinct from v_requested_block_order;
  v_module_changed :=
    v_current_active is distinct from v_requested_active
    or v_highlight_action <> 'preserve';

  select pg_catalog.jsonb_set(
    p_page_controls,
    '{thematic_block_order}',
    coalesce(
      pg_catalog.jsonb_agg(
        item.value
        order by item.ordinality
      ) filter (
        where item.value #>> '{}' <> 'video'
      ),
      '[]'::jsonb
    )
  )
  into v_legacy_page_controls
  from pg_catalog.jsonb_array_elements(
    p_page_controls -> 'thematic_block_order'
  ) with ordinality as item(value, ordinality);

  select *
  into v_apply
  from public.apply_matchday_editorial_profile_workspace_v5(
    p_matchday_id,
    p_profile_key,
    p_expected_revision,
    p_expected_state_token,
    p_overrides,
    p_zone_items,
    p_faixa_source_ids,
    p_opening,
    v_legacy_page_controls,
    p_selection_bank_item_ids
  );

  if v_highlight_action = 'replace' then
    select bank_row.*
    into v_bank
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.id = v_highlight_bank_item_id
      and bank_row.matchday_id = p_matchday_id
      and pg_catalog.lower(
        pg_catalog.btrim(
          coalesce(bank_row.status, '')
        )
      ) = 'active'
      and pg_catalog.lower(
        pg_catalog.btrim(
          coalesce(bank_row.source_type, '')
        )
      ) in ('editorial_article', 'editorial_content')
      and nullif(
        pg_catalog.btrim(bank_row.title),
        ''
      ) is not null
      and nullif(
        pg_catalog.btrim(bank_row.link_url),
        ''
      ) is not null
    for share;

    if not found then
      raise exception
        'matchday-editorial-profile-workspace-v6-highlight-source-not-found';
    end if;
  end if;

  update public.matchday_editorial_profile_reconcile_control
    as control_row
  set thematic_block_order = v_requested_block_order,
      updated_at = case
        when v_block_order_changed
          then v_now
        else control_row.updated_at
      end
  where control_row.matchday_id = p_matchday_id
    and control_row.profile_key = p_profile_key;

  if not found then
    raise exception
      'matchday-editorial-profile-workspace-v6-reconcile-control-not-found';
  end if;

  if v_module_changed then
    update public.matchday_editorials as editorial_row
    set complementary_mode = case
          when v_requested_active
            then 'roundup_video'
          else 'none'
        end,
        complementary_status = case
          when v_highlight_action = 'remove'
            then 'draft'
          when v_highlight_action = 'replace'
            then 'published'
          else editorial_row.complementary_status
        end,
        complementary_label = case
          when v_highlight_action = 'remove'
            then null
          when v_highlight_action = 'replace'
            then nullif(pg_catalog.btrim(v_bank.label), '')
          else editorial_row.complementary_label
        end,
        complementary_title = case
          when v_highlight_action = 'remove'
            then null
          when v_highlight_action = 'replace'
            then pg_catalog.btrim(v_bank.title)
          else editorial_row.complementary_title
        end,
        complementary_text = case
          when v_highlight_action = 'remove'
            then null
          when v_highlight_action = 'replace'
            then nullif(pg_catalog.btrim(v_bank.subtitle), '')
          else editorial_row.complementary_text
        end,
        complementary_image_url = case
          when v_highlight_action = 'remove'
            then null
          when v_highlight_action = 'replace'
            then nullif(pg_catalog.btrim(v_bank.image_url), '')
          else editorial_row.complementary_image_url
        end,
        complementary_link_url = case
          when v_highlight_action = 'remove'
            then null
          when v_highlight_action = 'replace'
            then pg_catalog.btrim(v_bank.link_url)
          else editorial_row.complementary_link_url
        end,
        updated_at = v_now
    where editorial_row.matchday_id = p_matchday_id;

    if not found then
      raise exception
        'matchday-editorial-profile-workspace-v6-editorial-not-found';
    end if;
  end if;

  if v_requested_active then
    if not exists (
      select 1
      from public.matchday_roundup_items as roundup_row
      where roundup_row.matchday_id = p_matchday_id
        and pg_catalog.lower(
          pg_catalog.btrim(
            coalesce(roundup_row.status, '')
          )
        ) = 'published'
        and nullif(
          pg_catalog.btrim(roundup_row.video_url),
          ''
        ) is not null
    ) then
      raise exception
        'matchday-editorial-profile-workspace-v6-video-required';
    end if;

    if not exists (
      select 1
      from public.matchday_editorials as editorial_row
      where editorial_row.matchday_id = p_matchday_id
        and editorial_row.complementary_status = 'published'
        and pg_catalog.num_nonnulls(
          nullif(pg_catalog.btrim(editorial_row.complementary_title), ''),
          nullif(pg_catalog.btrim(editorial_row.complementary_text), ''),
          nullif(pg_catalog.btrim(editorial_row.complementary_image_url), ''),
          nullif(pg_catalog.btrim(editorial_row.complementary_link_url), '')
        ) > 0
    ) then
      raise exception
        'matchday-editorial-profile-workspace-v6-highlight-required';
    end if;
  end if;

  v_final_revision := v_apply.revision;

  if (
      v_block_order_changed
      or v_module_changed
    )
    and v_final_revision = p_expected_revision
  then
    update public.matchday_editorial_profile_reconcile_control
      as control_row
    set revision = control_row.revision + 1,
        last_applied_at = v_now,
        updated_at = v_now
    where control_row.matchday_id = p_matchday_id
      and control_row.profile_key = p_profile_key
    returning control_row.revision
    into v_final_revision;
  end if;

  return query
  select
    v_final_revision,
    token_row.state_token,
    v_apply.applied_override_count,
    v_apply.applied_zone_item_count,
    v_apply.applied_faixa_count,
    v_apply.applied_opening_count,
    v_apply.applied_selection_count
  from public.matchday_editorial_profile_workspace_token(
    p_matchday_id,
    p_profile_key
  ) as token_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_profile_workspace_v8(p_matchday_id uuid, p_profile_key text, p_expected_revision bigint, p_expected_state_token text, p_overrides jsonb, p_zone_items jsonb, p_faixa_source_ids jsonb, p_opening jsonb, p_page_controls jsonb, p_selection_bank_item_ids jsonb, p_video_module jsonb, p_worked_source_ids jsonb)
 RETURNS TABLE(revision bigint, state_token text, applied_override_count integer, applied_zone_item_count integer, applied_faixa_count integer, applied_opening_count integer, applied_selection_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_apply record;
begin
  if p_worked_source_ids is null
    or pg_catalog.jsonb_typeof(p_worked_source_ids) <> 'array'
    or exists (
      select 1
      from pg_catalog.jsonb_array_elements(p_worked_source_ids)
        as worked_row(value)
      where pg_catalog.jsonb_typeof(worked_row.value) <> 'string'
        or nullif(pg_catalog.btrim(worked_row.value #>> '{}'), '') is null
    )
    or (
      select pg_catalog.count(*)
      from pg_catalog.jsonb_array_elements(p_worked_source_ids)
    ) <> (
      select pg_catalog.count(distinct pg_catalog.lower(
        pg_catalog.btrim(worked_row.value #>> '{}')
      ))
      from pg_catalog.jsonb_array_elements(p_worked_source_ids)
        as worked_row(value)
    )
  then
    raise exception
      'matchday-editorial-profile-workspace-v8-invalid-worked-sources';
  end if;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_worked_source_ids)
      as worked_row(value)
    where not exists (
      select 1
      from public.matchday_editorial_profile_workspace_sources(
        p_matchday_id
      ) as source_row
      where source_row.source_type = 'editorial_article'
        and source_row.source_id = pg_catalog.lower(
          pg_catalog.btrim(worked_row.value #>> '{}')
        )
    )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v8-worked-source-not-active';
  end if;

  if exists (
    with selected_sources as (
      select
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
          as source_type,
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
          as source_id
      from pg_catalog.jsonb_array_elements(p_selection_bank_item_ids)
        as selection_row(value)
      join public.matchday_editorial_bank_items as bank_row
        on bank_row.id::text = pg_catalog.btrim(
          selection_row.value #>> '{}'
        )
       and bank_row.matchday_id = p_matchday_id
      where pg_catalog.jsonb_typeof(selection_row.value) = 'string'
    )
    select 1
    from selected_sources as selected_row
    where selected_row.source_type = 'editorial_article'
      and (
        exists (
          select 1
          from pg_catalog.jsonb_each(p_opening) as opening_row(slot_key, value)
          where pg_catalog.jsonb_typeof(opening_row.value) = 'string'
            and pg_catalog.lower(pg_catalog.btrim(opening_row.value #>> '{}'))
              = selected_row.source_id
        )
        or exists (
          select 1
          from pg_catalog.jsonb_array_elements(p_zone_items) as zone_row(value)
          where pg_catalog.lower(pg_catalog.btrim(zone_row.value ->> 'source_type'))
              = selected_row.source_type
            and pg_catalog.lower(pg_catalog.btrim(zone_row.value ->> 'source_id'))
              = selected_row.source_id
        )
        or exists (
          select 1
          from pg_catalog.jsonb_array_elements(p_faixa_source_ids) as faixa_row(value)
          where pg_catalog.lower(pg_catalog.btrim(faixa_row.value #>> '{}'))
              = selected_row.source_id
        )
      )
  ) then
    raise exception
      'matchday-editorial-profile-workspace-v8-duplicate-public-placement';
  end if;

  select *
  into v_apply
  from public.apply_matchday_editorial_profile_workspace_v7(
    p_matchday_id,
    p_profile_key,
    p_expected_revision,
    p_expected_state_token,
    p_overrides,
    p_zone_items,
    p_faixa_source_ids,
    p_opening,
    p_page_controls,
    p_selection_bank_item_ids,
    p_video_module
  );

  update public.matchday_editorial_bank_items as bank_row
  set editorially_worked_at = coalesce(
    bank_row.editorially_worked_at,
    pg_catalog.statement_timestamp()
  )
  where bank_row.matchday_id = p_matchday_id
    and pg_catalog.lower(pg_catalog.btrim(bank_row.status)) = 'active'
    and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
      = 'editorial_article'
    and bank_row.editorially_worked_at is null
    and (
      pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)) in (
        select pg_catalog.lower(pg_catalog.btrim(worked_row.value #>> '{}'))
        from pg_catalog.jsonb_array_elements(p_worked_source_ids)
          as worked_row(value)
      )
      or bank_row.id::text in (
        select pg_catalog.btrim(selection_row.value #>> '{}')
        from pg_catalog.jsonb_array_elements(p_selection_bank_item_ids)
          as selection_row(value)
        where pg_catalog.jsonb_typeof(selection_row.value) = 'string'
      )
    );

  return query
  select
    v_apply.revision,
    v_apply.state_token,
    v_apply.applied_override_count,
    v_apply.applied_zone_item_count,
    v_apply.applied_faixa_count,
    v_apply.applied_opening_count,
    v_apply.applied_selection_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_editorial_profile_workspace_v9(p_matchday_id uuid, p_profile_key text, p_expected_revision bigint, p_expected_state_token text, p_overrides jsonb, p_zone_items jsonb, p_faixa_source_ids jsonb, p_opening jsonb, p_page_controls jsonb, p_selection_bank_item_ids jsonb, p_video_module jsonb, p_worked_source_ids jsonb)
 RETURNS TABLE(revision bigint, state_token text, applied_override_count integer, applied_zone_item_count integer, applied_faixa_count integer, applied_opening_count integer, applied_selection_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_apply record;
begin
  if not exists (select 1 from public.matchday_editorial_desk_control as desk_row where desk_row.matchday_id=p_matchday_id and desk_row.is_managed=true) then
    raise exception 'matchday-editorial-profile-workspace-v9-matchday-not-live';
  end if;
  perform pg_catalog.set_config('jornada.live_layout_cutover_adapter','on',true);
  select * into v_apply
  from jornada_private.apply_matchday_editorial_profile_workspace_v9_pre_cutover(
    p_matchday_id,p_profile_key,p_expected_revision,p_expected_state_token,p_overrides,p_zone_items,p_faixa_source_ids,p_opening,p_page_controls,p_selection_bank_item_ids,p_video_module,p_worked_source_ids
  );
  perform jornada_private.reconcile_matchday_live_layout_from_legacy_adapter(p_matchday_id);
  return query select v_apply.revision,v_apply.state_token,v_apply.applied_override_count,v_apply.applied_zone_item_count,v_apply.applied_faixa_count,v_apply.applied_opening_count,v_apply.applied_selection_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_live_layout_legacy_slot(p_matchday_id uuid, p_action text, p_placement_type text, p_zone_id uuid, p_slot_position integer, p_source_link_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_normalized_link text;
  v_bank_item_id uuid;
  v_bank_item_ids uuid[];
  v_candidate_count bigint;
begin
  if p_action = 'clear' then
    return public.apply_matchday_live_layout_movement(
      p_matchday_id,
      'clear',
      null,
      p_placement_type,
      p_zone_id,
      p_slot_position,
      null,
      false
    );
  end if;

  if p_action <> 'place'
    or nullif(pg_catalog.btrim(p_source_link_url), '') is null
  then
    raise exception 'matchday-live-layout-legacy-slot-invalid-envelope';
  end if;

  v_normalized_link := nullif(
    pg_catalog.lower(
      pg_catalog.regexp_replace(
        pg_catalog.split_part(
          pg_catalog.split_part(pg_catalog.btrim(p_source_link_url), '#', 1),
          '?',
          1
        ),
        '/+$',
        ''
      )
    ),
    ''
  );

  select
    pg_catalog.count(*),
    pg_catalog.array_agg(bank_row.id order by bank_row.id)
  into v_candidate_count, v_bank_item_ids
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.matchday_id = p_matchday_id
    and nullif(
      pg_catalog.lower(
        pg_catalog.regexp_replace(
          pg_catalog.split_part(
            pg_catalog.split_part(pg_catalog.btrim(bank_row.link_url), '#', 1),
            '?',
            1
          ),
          '/+$',
          ''
        )
      ),
      ''
    ) = v_normalized_link;

  if v_candidate_count <> 1 then
    raise exception 'matchday-live-layout-legacy-slot-bank-resolution-failed';
  end if;

  v_bank_item_id := v_bank_item_ids[1];

  return public.apply_matchday_live_layout_movement(
    p_matchday_id,
    'place',
    v_bank_item_id,
    p_placement_type,
    p_zone_id,
    p_slot_position,
    null,
    false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_live_layout_movement(p_matchday_id uuid, p_action text, p_bank_item_id uuid, p_placement_type text, p_zone_id uuid, p_slot_position integer, p_expected_target_bank_item_id uuid, p_expect_target_empty boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_current_target_bank_item_id uuid;
  v_result jsonb;
begin
  perform jornada_private.acquire_matchday_live_layout_cutover_core_lock();

  if p_matchday_id is null
    or p_action not in ('place', 'clear')
    or p_placement_type is null
    or p_slot_position is null
    or p_expect_target_empty is null
  then
    raise exception 'matchday-live-layout-movement-invalid-envelope';
  end if;

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-live-layout-movement-matchday-not-found';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as desk_row
    where desk_row.matchday_id = p_matchday_id
      and desk_row.is_managed = true
  ) then
    raise exception 'matchday-live-layout-movement-matchday-not-live';
  end if;

  select placement_row.bank_item_id
  into v_current_target_bank_item_id
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.placement_type = p_placement_type
    and placement_row.zone_id is not distinct from p_zone_id
    and placement_row.slot_position = p_slot_position;

  if p_expect_target_empty and found then
    raise exception 'matchday-live-layout-movement-target-changed';
  end if;

  if p_expected_target_bank_item_id is not null
    and v_current_target_bank_item_id is distinct from p_expected_target_bank_item_id
  then
    raise exception 'matchday-live-layout-movement-target-changed';
  end if;

  if p_action = 'place' and p_bank_item_id is null then
    raise exception 'matchday-live-layout-movement-bank-required';
  end if;

  if p_action = 'clear' and p_bank_item_id is not null then
    raise exception 'matchday-live-layout-movement-clear-bank-forbidden';
  end if;

  select jornada_private.apply_matchday_live_layout_placement_plan(
    p_matchday_id,
    pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'action', p_action,
        'bank_item_id', p_bank_item_id,
        'placement_type', p_placement_type,
        'zone_id', p_zone_id,
        'slot_position', p_slot_position
      )
    ),
    true
  ) into v_result;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_live_layout_physical_v29(p_matchday_id uuid, p_profile_key text, p_expected_physical_state_token text, p_latest_companion_zone_id uuid, p_zones jsonb, p_blocks jsonb, p_placements jsonb, p_faixa_slot_count integer, p_explicit_bank_item_ids jsonb, p_displaced_bank_item_ids jsonb, p_worked_bank_item_ids jsonb, p_faixa_arrival_bank_item_ids jsonb, p_displaced_arrival_bank_item_ids jsonb, p_presentation jsonb)
 RETURNS TABLE(state_token text, applied_zone_count integer, applied_block_count integer, applied_placement_count integer, explicit_bank_item_count integer, displaced_bank_item_count integer, worked_bank_item_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_faixa_public_title text;
  v_latest_zone_placement text;
  v_roundup_video_heading text;
  v_video_highlight_section_title text;
  v_final_state_token text;
  v_previous_workspace_apply text;
  v_applied record;
begin
  if pg_catalog.jsonb_typeof(p_presentation) is distinct from 'object'
    or (
      select pg_catalog.array_agg(key_name order by key_name)
      from pg_catalog.jsonb_object_keys(p_presentation) as keys(key_name)
    ) is distinct from array[
      'faixa_public_title',
      'headline_title_color',
      'latest_zone_placement',
      'latest_zone_title',
      'roundup_video_heading',
      'video_highlight_section_title',
      'video_module_active'
    ]::text[]
  then
    raise exception
      'matchday-live-layout-video-section-titles-presentation-invalid';
  end if;

  v_latest_zone_placement :=
    p_presentation ->> 'latest_zone_placement';
  v_faixa_public_title :=
    p_presentation ->> 'faixa_public_title';
  v_roundup_video_heading :=
    p_presentation ->> 'roundup_video_heading';
  v_video_highlight_section_title :=
    p_presentation ->> 'video_highlight_section_title';

  if v_faixa_public_title is null
    or v_faixa_public_title <> pg_catalog.btrim(v_faixa_public_title)
    or pg_catalog.char_length(v_faixa_public_title) > 120
    or v_roundup_video_heading is null
    or v_roundup_video_heading <> pg_catalog.btrim(v_roundup_video_heading)
    or pg_catalog.char_length(v_roundup_video_heading) > 120
    or v_video_highlight_section_title is null
    or v_video_highlight_section_title <>
       pg_catalog.btrim(v_video_highlight_section_title)
    or pg_catalog.char_length(v_video_highlight_section_title) > 120
  then
    raise exception
      'matchday-live-layout-video-section-titles-value-invalid';
  end if;

  if (
    (
      v_latest_zone_placement in ('top', 'hidden')
      and p_latest_companion_zone_id is null
    )
    or (
      v_latest_zone_placement = 'four_news'
      and p_latest_companion_zone_id is not null
    )
  ) is not true then
    raise exception
      'matchday-live-layout-latest-destination-v29-incomplete';
  end if;

  select *
  into v_applied
  from public.apply_matchday_live_layout_physical_v22(
    p_matchday_id,
    p_profile_key,
    p_expected_physical_state_token,
    p_latest_companion_zone_id,
    p_zones,
    p_blocks,
    p_placements,
    p_faixa_slot_count,
    p_explicit_bank_item_ids,
    p_displaced_bank_item_ids,
    p_worked_bank_item_ids,
    p_faixa_arrival_bank_item_ids,
    p_displaced_arrival_bank_item_ids,
    p_presentation
      - 'faixa_public_title'
      - 'roundup_video_heading'
      - 'video_highlight_section_title'
  );

  if not found then
    raise exception
      'matchday-live-layout-video-section-titles-apply-result-missing';
  end if;

  v_previous_workspace_apply := pg_catalog.current_setting(
    'jornada.thematic_workspace_apply',
    true
  );
  perform pg_catalog.set_config(
    'jornada.thematic_workspace_apply',
    'on',
    true
  );

  update public.matchday_editorials as editorial_row
  set roundup_video_heading = nullif(v_roundup_video_heading, ''),
      video_highlight_section_title =
        nullif(v_video_highlight_section_title, ''),
      updated_at = pg_catalog.statement_timestamp()
  where editorial_row.matchday_id = p_matchday_id
    and row(
      editorial_row.roundup_video_heading,
      editorial_row.video_highlight_section_title
    ) is distinct from row(
      nullif(v_roundup_video_heading, ''),
      nullif(v_video_highlight_section_title, '')
    );

  if not exists (
    select 1
    from public.matchday_editorials as editorial_row
    where editorial_row.matchday_id = p_matchday_id
  ) then
    raise exception
      'matchday-live-layout-video-section-titles-editorial-missing';
  end if;

  update public.matchday_live_layout_workspace_settings as settings_row
  set faixa_public_title = nullif(v_faixa_public_title, ''),
      updated_at = pg_catalog.statement_timestamp()
  where settings_row.matchday_id = p_matchday_id
    and settings_row.faixa_public_title is distinct from
      nullif(v_faixa_public_title, '');

  if not exists (
    select 1
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
  ) then
    raise exception
      'matchday-live-layout-faixa-public-title-settings-missing';
  end if;

  perform pg_catalog.set_config(
    'jornada.thematic_workspace_apply',
    coalesce(v_previous_workspace_apply, ''),
    true
  );

  select jornada_private.matchday_live_layout_workspace_token_v22(
    p_matchday_id,
    p_profile_key
  ) into v_final_state_token;

  if v_final_state_token is null
    or v_final_state_token !~ '^[0-9a-f]{32}$'
  then
    raise exception
      'matchday-live-layout-video-section-titles-token-invalid';
  end if;

  return query
  select
    v_final_state_token,
    v_applied.applied_zone_count,
    v_applied.applied_block_count,
    v_applied.applied_placement_count,
    v_applied.explicit_bank_item_count,
    v_applied.displaced_bank_item_count,
    v_applied.worked_bank_item_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_matchday_live_layout_single_placement_v15(p_matchday_id uuid, p_expected_physical_state_token text, p_action text, p_bank_item_id uuid, p_placement_type text DEFAULT NULL::text, p_zone_id uuid DEFAULT NULL::uuid, p_slot_position integer DEFAULT NULL::integer, p_expected_target_bank_item_id uuid DEFAULT NULL::uuid, p_expect_target_empty boolean DEFAULT false)
 RETURNS TABLE(state_token text, no_op boolean, placement_id uuid, displaced_bank_item_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_action text := pg_catalog.lower(pg_catalog.btrim(p_action));
  v_profile_key text;
  v_current_state_token text;
  v_final_state_token text;
  v_classification_before text;
  v_current_placement public.matchday_live_layout_placements%rowtype;
  v_target_occupant uuid;
  v_final_placement_id uuid;
  v_is_no_op boolean := false;
  v_plan jsonb;
begin
  if p_matchday_id is null
    or p_bank_item_id is null
    or p_action is null
    or p_expected_physical_state_token is null
    or pg_catalog.btrim(p_expected_physical_state_token) !~ '^[0-9a-f]{32}$'
    or v_action not in ('place', 'displace', 'bank')
    or p_expect_target_empty is null
  then
    raise exception 'matchday-live-layout-single-v15-invalid-input';
  end if;

  if (v_action = 'place' and p_placement_type is null)
    or (
      v_action <> 'place'
      and p_placement_type is null
      and (p_zone_id is not null or p_slot_position is not null)
    )
    or (p_placement_type is not null and (
      p_placement_type not in (
      'opening', 'faixa', 'selection', 'video_highlight', 'zone'
      )
      or p_slot_position is null
      or not (
        (p_placement_type = 'opening' and p_zone_id is null
          and p_slot_position between 1 and 5)
        or (p_placement_type = 'faixa' and p_zone_id is null
          and p_slot_position > 0)
        or (p_placement_type = 'selection' and p_zone_id is null
          and p_slot_position between 1 and 4)
        or (p_placement_type = 'video_highlight' and p_zone_id is null
          and p_slot_position = 1)
        or (p_placement_type = 'zone' and p_zone_id is not null
          and p_slot_position > 0)
      )
    ))
  then
    raise exception 'matchday-live-layout-single-v15-target-invalid';
  end if;

  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-live-layout-single-v15-matchday-not-found';
  end if;

  select marker_row.profile_key
  into v_profile_key
  from jornada_private.matchday_live_layout_physical_cutovers as marker_row
  where marker_row.matchday_id = p_matchday_id;

  if v_profile_key is null then
    raise exception 'matchday-live-layout-single-v15-physical-cutover-required';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_desk_control as desk_row
    where desk_row.matchday_id = p_matchday_id
      and desk_row.is_managed = true
  ) then
    raise exception 'matchday-live-layout-single-v15-matchday-not-live';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_profile_assignments as assignment_row
    where assignment_row.matchday_id = p_matchday_id
      and assignment_row.profile_key = v_profile_key
  ) or not exists (
    select 1
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
  ) then
    raise exception 'matchday-live-layout-single-v15-physical-state-incoherent';
  end if;

  select token_row.state_token
  into v_current_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    v_profile_key
  ) as token_row;

  if v_current_state_token is distinct from
     pg_catalog.btrim(p_expected_physical_state_token)
  then
    raise exception 'matchday-live-layout-single-v15-stale';
  end if;

  perform 1
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.id = p_bank_item_id
    and bank_row.matchday_id = p_matchday_id
    and pg_catalog.lower(pg_catalog.btrim(coalesce(bank_row.status, ''))) =
        'active'
  for update;

  if not found then
    raise exception 'matchday-live-layout-single-v15-bank-item-not-active';
  end if;

  if p_placement_type = 'zone' and not exists (
    select 1
    from public.matchday_live_layout_zones as zone_row
    where zone_row.id = p_zone_id
      and zone_row.matchday_id = p_matchday_id
  ) then
    raise exception 'matchday-live-layout-single-v15-zone-invalid';
  end if;

  if p_placement_type = 'faixa' and p_slot_position > (
    select settings_row.faixa_slot_count
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
  ) then
    raise exception 'matchday-live-layout-single-v15-faixa-slot-invalid';
  end if;

  if p_placement_type = 'video_highlight' and not (
    select settings_row.video_module_active
    from public.matchday_live_layout_workspace_settings as settings_row
    where settings_row.matchday_id = p_matchday_id
  ) then
    raise exception 'matchday-live-layout-single-v15-video-inactive';
  end if;

  perform 1
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
  order by placement_row.id
  for update;

  select placement_row.*
  into v_current_placement
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.bank_item_id = p_bank_item_id;

  if found and v_action in ('displace', 'bank')
    and p_placement_type is not null
    and (
    v_current_placement.placement_type is distinct from p_placement_type
    or v_current_placement.zone_id is distinct from p_zone_id
    or v_current_placement.slot_position is distinct from p_slot_position
  ) then
    raise exception 'matchday-live-layout-single-v15-source-stale';
  end if;

  if v_action = 'place' then
    select placement_row.bank_item_id
    into v_target_occupant
    from public.matchday_live_layout_placements as placement_row
    where placement_row.matchday_id = p_matchday_id
      and placement_row.placement_type = p_placement_type
      and placement_row.zone_id is not distinct from p_zone_id
      and placement_row.slot_position = p_slot_position;

    if p_expect_target_empty
      and v_target_occupant is not null
      and v_target_occupant is distinct from p_bank_item_id
    then
      raise exception 'matchday-live-layout-single-v15-target-changed';
    end if;

    if p_expected_target_bank_item_id is not null
      and v_target_occupant is distinct from p_expected_target_bank_item_id
    then
      raise exception 'matchday-live-layout-single-v15-target-changed';
    end if;

    v_is_no_op := v_current_placement.id is not null
      and v_current_placement.placement_type = p_placement_type
      and v_current_placement.zone_id is not distinct from p_zone_id
      and v_current_placement.slot_position = p_slot_position
      and not exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = p_bank_item_id
      )
      and not exists (
        select 1
        from public.matchday_editorial_bank_items as bank_row
        join public.matchday_editorial_profile_manual_overrides as override_row
          on override_row.matchday_id = bank_row.matchday_id
         and override_row.profile_key = v_profile_key
         and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
             pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
         and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
             pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
        where bank_row.id = p_bank_item_id
          and bank_row.matchday_id = p_matchday_id
          and override_row.placement_target = 'bank'
      );
  elsif v_action = 'bank' then
    v_is_no_op := v_current_placement.id is null
      and not exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = p_bank_item_id
      )
      and exists (
        select 1
        from public.matchday_editorial_bank_items as bank_row
        join public.matchday_editorial_profile_manual_overrides as override_row
          on override_row.matchday_id = bank_row.matchday_id
         and override_row.profile_key = v_profile_key
         and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
             pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
         and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
             pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
        where bank_row.id = p_bank_item_id
          and bank_row.matchday_id = p_matchday_id
          and override_row.placement_target = 'bank'
      );
  else
    v_is_no_op := v_current_placement.id is null
      and exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as memory_row
        where memory_row.matchday_id = p_matchday_id
          and memory_row.bank_item_id = p_bank_item_id
          and memory_row.memory_kind = 'displaced'
      )
      and not exists (
        select 1
        from public.matchday_editorial_bank_items as bank_row
        join public.matchday_editorial_profile_manual_overrides as override_row
          on override_row.matchday_id = bank_row.matchday_id
         and override_row.profile_key = v_profile_key
         and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
             pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
         and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
             pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
        where bank_row.id = p_bank_item_id
          and bank_row.matchday_id = p_matchday_id
          and override_row.placement_target = 'bank'
      );
  end if;

  if v_is_no_op then
    return query select
      v_current_state_token,
      true,
      v_current_placement.id,
      null::uuid;
    return;
  end if;

  select pg_catalog.md5(coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', bank_row.id,
        'automatic_eligible', bank_row.automatic_eligible,
        'classification_key', bank_row.classification_key,
        'classification_source', bank_row.classification_source,
        'classified_at', bank_row.classified_at
      ) order by bank_row.id
    ),
    '[]'::jsonb
  )::text)
  into v_classification_before
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.matchday_id = p_matchday_id;

  perform jornada_private.begin_matchday_live_layout_downstream_v14(
    p_matchday_id
  );

  begin
    if v_action = 'bank' then
      if coalesce(pg_catalog.lower(pg_catalog.btrim((
        select bank_row.source_type
        from public.matchday_editorial_bank_items as bank_row
        where bank_row.id = p_bank_item_id
      ))), '') <> 'editorial_article' then
        raise exception 'matchday-live-layout-single-v15-explicit-bank-unsupported';
      end if;

      insert into public.matchday_editorial_profile_manual_overrides
        as override_row (
          matchday_id,
          profile_key,
          source_type,
          source_id,
          placement_target,
          zone_key,
          sort_order
        )
      select
        p_matchday_id,
        v_profile_key,
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_type)),
        pg_catalog.lower(pg_catalog.btrim(bank_row.source_id)),
        'bank',
        null,
        null
      from public.matchday_editorial_bank_items as bank_row
      where bank_row.id = p_bank_item_id
        and bank_row.matchday_id = p_matchday_id
      on conflict (matchday_id, profile_key, source_type, source_id)
      do update
      set placement_target = 'bank',
          zone_key = null,
          sort_order = null,
          updated_at = pg_catalog.statement_timestamp()
      where override_row.placement_target is distinct from 'bank'
        or override_row.zone_key is not null
        or override_row.sort_order is not null;
    else
      delete from public.matchday_editorial_profile_manual_overrides
        as override_row
      using public.matchday_editorial_bank_items as bank_row
      where bank_row.id = p_bank_item_id
        and bank_row.matchday_id = p_matchday_id
        and override_row.matchday_id = p_matchday_id
        and override_row.profile_key = v_profile_key
        and override_row.placement_target = 'bank'
        and pg_catalog.lower(pg_catalog.btrim(override_row.source_type)) =
            pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
        and pg_catalog.lower(pg_catalog.btrim(override_row.source_id)) =
            pg_catalog.lower(pg_catalog.btrim(bank_row.source_id));
    end if;

    if v_action = 'place' then
      v_plan := pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'action', 'place',
          'bank_item_id', p_bank_item_id,
          'placement_type', p_placement_type,
          'zone_id', p_zone_id,
          'slot_position', p_slot_position
        )
      );
    elsif v_current_placement.id is not null then
      v_plan := pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'action', 'clear',
          'bank_item_id', null,
          'placement_type', v_current_placement.placement_type,
          'zone_id', v_current_placement.zone_id,
          'slot_position', v_current_placement.slot_position
        )
      );
    else
      v_plan := '[]'::jsonb;
    end if;

    perform jornada_private.apply_matchday_live_layout_placement_plan(
      p_matchday_id,
      v_plan,
      false
    );

    if v_action = 'bank' then
      delete from public.matchday_live_layout_bank_item_state_memory
        as memory_row
      where memory_row.matchday_id = p_matchday_id
        and memory_row.bank_item_id = p_bank_item_id;
    elsif v_action = 'displace' then
      insert into public.matchday_live_layout_bank_item_state_memory
        as memory_row (
          matchday_id,
          bank_item_id,
          memory_kind,
          recorded_at
        ) values (
          p_matchday_id,
          p_bank_item_id,
          'displaced',
          pg_catalog.statement_timestamp()
        )
      on conflict (matchday_id, bank_item_id) do update
      set memory_kind = 'displaced',
          recorded_at = excluded.recorded_at
      where memory_row.memory_kind is distinct from 'displaced';
    end if;

    update public.matchday_editorial_bank_items as bank_row
    set editorially_worked_at = pg_catalog.statement_timestamp()
    where bank_row.id = p_bank_item_id
      and bank_row.matchday_id = p_matchday_id
      and bank_row.editorially_worked_at is null;

    perform jornada_private.project_matchday_live_layout_placements_downstream_v14(
      p_matchday_id,
      v_profile_key
    );

  exception when others then
    perform jornada_private.end_matchday_live_layout_downstream_v14(
      p_matchday_id
    );
    raise;
  end;

  perform jornada_private.end_matchday_live_layout_downstream_v14(
    p_matchday_id
  );

  if v_classification_before is distinct from (
    select pg_catalog.md5(coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', bank_row.id,
          'automatic_eligible', bank_row.automatic_eligible,
          'classification_key', bank_row.classification_key,
          'classification_source', bank_row.classification_source,
          'classified_at', bank_row.classified_at
        ) order by bank_row.id
      ),
      '[]'::jsonb
    )::text)
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_matchday_id
  ) then
    raise exception 'matchday-live-layout-single-v15-classification-changed';
  end if;

  perform jornada_private.assert_matchday_live_layout_downstream_v14(
    p_matchday_id,
    v_profile_key
  );

  select placement_row.id
  into v_final_placement_id
  from public.matchday_live_layout_placements as placement_row
  where placement_row.matchday_id = p_matchday_id
    and placement_row.bank_item_id = p_bank_item_id;

  select token_row.state_token
  into v_final_state_token
  from public.matchday_editorial_profile_workspace_token_v13(
    p_matchday_id,
    v_profile_key
  ) as token_row;

  return query select
    v_final_state_token,
    false,
    v_final_placement_id,
    case when v_action = 'place' and v_target_occupant is distinct from
      p_bank_item_id then v_target_occupant else null end;
end;
$function$

CREATE OR REPLACE FUNCTION public.clear_matchday_editorial_selection_item(p_matchday_id uuid, p_position integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_deleted integer := 0;
begin
  if p_matchday_id is null
    or p_position not between 1 and 4
  then
    raise exception 'matchday-editorial-selection-invalid-input';
  end if;

  if not exists (
    select 1
    from public.matchday_editorial_profile_assignments as assignment_row
    where assignment_row.matchday_id = p_matchday_id
      and assignment_row.profile_key = 'liga_portugal_v1'
  ) then
    raise exception 'matchday-editorial-selection-profile-required';
  end if;

  delete from public.matchday_live_layout_items as live_row
  where live_row.matchday_id = p_matchday_id
    and live_row.slot_type = 'live_four_news:' || p_position::text;

  get diagnostics v_deleted = row_count;
  return v_deleted > 0;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_matchday_editorial_bank_contextual_classification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_internal boolean;
  v_old_source_type text;
  v_new_source_type text;
  v_old_source_id text;
  v_new_source_id text;
begin
  v_internal := exists (
    select 1
    from jornada_private.matchday_editorial_bank_classification_authorizations as authorization_row
    where authorization_row.backend_pid = pg_catalog.pg_backend_pid()
      and authorization_row.transaction_id = pg_catalog.pg_current_xact_id()
      and authorization_row.bank_item_id = new.id
  );

  v_new_source_type := pg_catalog.lower(pg_catalog.btrim(coalesce(new.source_type, '')));
  v_new_source_id := pg_catalog.lower(pg_catalog.btrim(coalesce(new.source_id, '')));

  if tg_op = 'INSERT' then
    if v_new_source_type <> 'editorial_article' or not v_internal then
      new.classification_key := null;
      new.classification_source := null;
      new.classified_at := null;
    end if;
    return new;
  end if;

  v_old_source_type := pg_catalog.lower(pg_catalog.btrim(coalesce(old.source_type, '')));
  v_old_source_id := pg_catalog.lower(pg_catalog.btrim(coalesce(old.source_id, '')));

  if v_new_source_type <> 'editorial_article' then
    new.classification_key := null;
    new.classification_source := null;
    new.classified_at := null;
    return new;
  end if;

  if old.id is distinct from new.id
    or old.matchday_id is distinct from new.matchday_id
    or v_old_source_type is distinct from v_new_source_type
    or v_old_source_id is distinct from v_new_source_id
  then
    new.classification_key := null;
    new.classification_source := null;
    new.classified_at := null;
    return new;
  end if;

  if old.classification_source = 'manual' and not v_internal then
    new.classification_key := old.classification_key;
    new.classification_source := old.classification_source;
    new.classified_at := old.classified_at;
    return new;
  end if;

  if not v_internal and (
      old.automatic_eligible is distinct from new.automatic_eligible
      or old.continuity_source_matchday_id is distinct from new.continuity_source_matchday_id
      or old.continuity_source_composition_id is distinct from new.continuity_source_composition_id
    )
  then
    new.classification_key := null;
    new.classification_source := null;
    new.classified_at := null;
    return new;
  end if;

  if not v_internal and (
      new.classification_key is distinct from old.classification_key
      or new.classification_source is distinct from old.classification_source
      or new.classified_at is distinct from old.classified_at
    )
  then
    new.classification_key := old.classification_key;
    new.classification_source := old.classification_source;
    new.classified_at := old.classified_at;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.initialize_matchday_editorial_thematic_continuity_v3(p_source_matchday_id uuid, p_target_matchday_id uuid, p_source_composition_id uuid)
 RETURNS TABLE(initialized boolean, source_matchday_id uuid, target_matchday_id uuid, source_composition_id uuid, inherited_bank_count integer, inherited_zone_item_count integer, inherited_faixa_count integer, inherited_opening_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source_season_id uuid;
  v_target_season_id uuid;
  v_source_number integer;
  v_target_number integer;
  v_source_profile_key text;
  v_target_profile_key text;
  v_source_control record;
  v_source_editorial public.matchday_editorials%rowtype;
  v_article public.editorial_articles%rowtype;
  v_required_source_ids text[];
  v_required_source_id text;
  v_existing_bank_id uuid;
  v_existing_automatic_eligible boolean;
  v_existing_continuity_matchday_id uuid;
  v_existing_continuity_composition_id uuid;
  v_target_has_own_latest boolean := false;
  v_transition_inserted integer := 0;
  v_source_zone_count integer := 0;
  v_source_faixa_count integer := 0;
  v_now timestamptz := pg_catalog.now();
begin
  if p_source_matchday_id is null
    or p_target_matchday_id is null
    or p_source_composition_id is null
  then
    raise exception
      'matchday-editorial-thematic-continuity-v3-invalid-input';
  end if;

  if p_source_matchday_id = p_target_matchday_id then
    raise exception
      'matchday-editorial-thematic-continuity-v3-same-matchday';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_continuity_transitions as transition_row
    where transition_row.source_matchday_id = p_source_matchday_id
       or transition_row.target_matchday_id = p_target_matchday_id
  ) then
    return query
    select
      false,
      p_source_matchday_id,
      p_target_matchday_id,
      p_source_composition_id,
      0,
      0,
      0,
      0;
    return;
  end if;

  select
    source_matchday.season_id,
    target_matchday.season_id,
    source_matchday.number,
    target_matchday.number
  into
    v_source_season_id,
    v_target_season_id,
    v_source_number,
    v_target_number
  from public.matchdays as source_matchday
  cross join public.matchdays as target_matchday
  where source_matchday.id = p_source_matchday_id
    and target_matchday.id = p_target_matchday_id;

  if not found then
    raise exception
      'matchday-editorial-thematic-continuity-v3-matchday-not-found';
  end if;

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id in (
    p_source_matchday_id,
    p_target_matchday_id
  )
  order by matchday_row.id
  for update;

  lock table public.matchday_editorials in share row exclusive mode;
  lock table public.matchday_highlights in share row exclusive mode;
  lock table public.matchday_horizontal_news in share row exclusive mode;
  lock table public.editorial_articles in share mode;
  lock table public.matchday_editorial_bank_items in share row exclusive mode;
  lock table public.matchday_editorial_profile_assignments in share row exclusive mode;
  lock table public.matchday_editorial_profile_reconcile_control in share row exclusive mode;
  lock table public.matchday_editorial_profile_zone_items in share row exclusive mode;
  lock table public.matchday_editorial_profile_manual_overrides in share row exclusive mode;
  lock table public.matchday_editorial_desk_control in share row exclusive mode;
  lock table public.matchday_reference_compositions in share mode;
  lock table public.matchday_live_layout_items in share mode;
  lock table public.matchday_latest_news in share mode;

  if exists (
    select 1
    from public.matchday_editorial_continuity_transitions as transition_row
    where transition_row.source_matchday_id = p_source_matchday_id
       or transition_row.target_matchday_id = p_target_matchday_id
  ) then
    return query
    select
      false,
      p_source_matchday_id,
      p_target_matchday_id,
      p_source_composition_id,
      0,
      0,
      0,
      0;
    return;
  end if;

  if v_source_season_id <> v_target_season_id then
    raise exception
      'matchday-editorial-thematic-continuity-v3-season-mismatch';
  end if;

  if v_target_number <> v_source_number + 1 then
    raise exception
      'matchday-editorial-thematic-continuity-v3-target-not-consecutive';
  end if;

  select assignment_row.profile_key
  into v_source_profile_key
  from public.matchday_editorial_profile_assignments as assignment_row
  where assignment_row.matchday_id = p_source_matchday_id
  for share;

  if not found then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-assignment-invalid';
  end if;

  if v_source_profile_key <> 'liga_portugal_v1' then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-assignment-invalid';
  end if;

  select assignment_row.profile_key
  into v_target_profile_key
  from public.matchday_editorial_profile_assignments as assignment_row
  where assignment_row.matchday_id = p_target_matchday_id
  for share;

  if not found then
    raise exception
      'matchday-editorial-thematic-continuity-v3-target-assignment-mismatch';
  end if;

  if v_target_profile_key <> v_source_profile_key then
    raise exception
      'matchday-editorial-thematic-continuity-v3-target-assignment-mismatch';
  end if;

  select control_row.*
  into v_source_control
  from public.matchday_editorial_profile_reconcile_control as control_row
  where control_row.matchday_id = p_source_matchday_id
    and control_row.profile_key = v_source_profile_key
  for share;

  if not found then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-not-applied';
  end if;

  if v_source_control.last_applied_at is null
    or v_source_control.revision < 1
  then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-not-applied';
  end if;

  perform 1
  from public.matchday_reference_compositions as composition_row
  where composition_row.id = p_source_composition_id
    and composition_row.matchday_id = p_source_matchday_id
    and composition_row.status = 'published'
    and composition_row.is_current = true
  for share;

  if not found then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-composition-invalid';
  end if;

  perform 1
  from public.matchday_editorial_desk_control as desk_row
  where desk_row.matchday_id = p_source_matchday_id
    and desk_row.is_managed = false
  for update;

  if not found then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-still-managed';
  end if;

  perform 1
  from public.matchday_editorial_desk_control as desk_row
  where desk_row.matchday_id = p_target_matchday_id
    and desk_row.is_managed = true
  for update;

  if not found then
    raise exception
      'matchday-editorial-thematic-continuity-v3-target-not-managed';
  end if;

  if exists (
    select 1
    from public.matchday_editorial_profile_reconcile_control as control_row
    where control_row.matchday_id = p_target_matchday_id
  ) or exists (
    select 1
    from public.matchday_editorial_profile_zone_items as zone_row
    where zone_row.matchday_id = p_target_matchday_id
  ) or exists (
    select 1
    from public.matchday_editorial_profile_manual_overrides as override_row
    where override_row.matchday_id = p_target_matchday_id
  ) then
    raise exception
      'matchday-editorial-thematic-continuity-v3-target-already-applied';
  end if;

  if exists (
    select 1
    from public.matchday_editorials as editorial_row
    where editorial_row.matchday_id = p_target_matchday_id
      and (
        coalesce(
          nullif(pg_catalog.btrim(editorial_row.title), ''),
          nullif(pg_catalog.btrim(editorial_row.summary), ''),
          nullif(pg_catalog.btrim(editorial_row.image_url), ''),
          nullif(pg_catalog.btrim(editorial_row.headline_link_url), '')
        ) is not null
        or coalesce(
          nullif(pg_catalog.btrim(editorial_row.side_block_label), ''),
          nullif(pg_catalog.btrim(editorial_row.side_block_title), ''),
          nullif(pg_catalog.btrim(editorial_row.side_block_author), ''),
          nullif(pg_catalog.btrim(editorial_row.side_block_text), ''),
          nullif(pg_catalog.btrim(editorial_row.side_block_image_url), ''),
          nullif(pg_catalog.btrim(editorial_row.side_block_link_url), '')
        ) is not null
      )
  ) or exists (
    select 1
    from public.matchday_highlights as highlight_row
    where highlight_row.matchday_id = p_target_matchday_id
      and coalesce(
        nullif(pg_catalog.btrim(highlight_row.label), ''),
        nullif(pg_catalog.btrim(highlight_row.title), ''),
        nullif(pg_catalog.btrim(highlight_row.subtitle), ''),
        nullif(pg_catalog.btrim(highlight_row.image_url), ''),
        nullif(pg_catalog.btrim(highlight_row.link_url), '')
      ) is not null
  ) then
    raise exception
      'matchday-editorial-thematic-continuity-v3-target-opening-not-empty';
  end if;

  if exists (
    select 1
    from public.matchday_horizontal_news as faixa_row
    where faixa_row.matchday_id = p_target_matchday_id
  ) then
    raise exception
      'matchday-editorial-thematic-continuity-v3-target-faixa-not-empty';
  end if;

  select editorial_row.*
  into v_source_editorial
  from public.matchday_editorials as editorial_row
  where editorial_row.matchday_id = p_source_matchday_id
    and editorial_row.status = 'published'
    and editorial_row.side_block_status = 'published';

  if not found then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-opening-incomplete';
  end if;

  if nullif(pg_catalog.btrim(v_source_editorial.headline_link_url), '') is null
    or nullif(pg_catalog.btrim(v_source_editorial.side_block_link_url), '') is null
  then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-opening-incomplete';
  end if;

  if 1 <> (
    select pg_catalog.count(*)
    from public.editorial_articles as article_row
    where article_row.status = 'published'
      and nullif(pg_catalog.btrim(article_row.slug), '') is not null
      and '/noticias/' || pg_catalog.btrim(article_row.slug)
        = pg_catalog.btrim(v_source_editorial.headline_link_url)
  ) or 1 <> (
    select pg_catalog.count(*)
    from public.editorial_articles as article_row
    where article_row.status = 'published'
      and nullif(pg_catalog.btrim(article_row.slug), '') is not null
      and '/noticias/' || pg_catalog.btrim(article_row.slug)
        = pg_catalog.btrim(v_source_editorial.side_block_link_url)
  ) then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-opening-unresolved';
  end if;

  if 3 <> (
    select pg_catalog.count(*)
    from public.matchday_highlights as highlight_row
    where highlight_row.matchday_id = p_source_matchday_id
      and highlight_row.status = 'published'
      and highlight_row.sort_order between 1 and 3
  ) or 3 <> (
    select pg_catalog.count(distinct highlight_row.sort_order)
    from public.matchday_highlights as highlight_row
    where highlight_row.matchday_id = p_source_matchday_id
      and highlight_row.status = 'published'
      and highlight_row.sort_order between 1 and 3
  ) or exists (
    select 1
    from public.matchday_highlights as highlight_row
    where highlight_row.matchday_id = p_source_matchday_id
      and highlight_row.status = 'published'
      and highlight_row.sort_order between 1 and 3
      and (
        nullif(pg_catalog.btrim(highlight_row.link_url), '') is null
        or 1 <> (
          select pg_catalog.count(*)
          from public.editorial_articles as article_row
          where article_row.status = 'published'
            and nullif(pg_catalog.btrim(article_row.slug), '') is not null
            and '/noticias/' || pg_catalog.btrim(article_row.slug)
              = pg_catalog.btrim(highlight_row.link_url)
        )
      )
  ) then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-highlights-incomplete';
  end if;

  select pg_catalog.count(*)::integer
  into v_source_zone_count
  from public.matchday_editorial_profile_zone_items as zone_row
  where zone_row.matchday_id = p_source_matchday_id
    and zone_row.profile_key = v_source_profile_key;

  if v_source_zone_count = 0 or exists (
    select 1
    from public.matchday_editorial_profile_zone_items as zone_row
    where zone_row.matchday_id = p_source_matchday_id
      and zone_row.profile_key = v_source_profile_key
      and (
        pg_catalog.lower(pg_catalog.btrim(zone_row.source_type))
          <> 'editorial_article'
        or not exists (
          select 1
          from public.editorial_articles as article_row
          where article_row.id::text = pg_catalog.lower(
              pg_catalog.btrim(zone_row.source_id)
            )
            and article_row.status = 'published'
        )
      )
  ) then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-zones-invalid';
  end if;

  select pg_catalog.count(*)::integer
  into v_source_faixa_count
  from public.matchday_horizontal_news as faixa_row
  where faixa_row.matchday_id = p_source_matchday_id
    and faixa_row.status = 'published';

  if exists (
    select 1
    from public.matchday_horizontal_news as faixa_row
    where faixa_row.matchday_id = p_source_matchday_id
      and faixa_row.status = 'published'
      and 1 <> (
        select pg_catalog.count(*)
        from public.editorial_articles as article_row
        where article_row.status = 'published'
          and nullif(pg_catalog.btrim(article_row.slug), '') is not null
          and '/noticias/' || pg_catalog.btrim(article_row.slug)
            = pg_catalog.btrim(faixa_row.link_url)
      )
  ) or exists (
    select 1
    from public.matchday_horizontal_news as faixa_row
    join public.editorial_articles as article_row
      on article_row.status = 'published'
     and '/noticias/' || pg_catalog.btrim(article_row.slug)
       = pg_catalog.btrim(faixa_row.link_url)
    where faixa_row.matchday_id = p_source_matchday_id
      and faixa_row.status = 'published'
    group by article_row.id
    having pg_catalog.count(*) > 1
  ) then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-faixa-invalid';
  end if;

  select
    exists (
      select 1
      from public.matchday_live_layout_items as live_row
      where live_row.matchday_id = p_target_matchday_id
        and pg_catalog.lower(pg_catalog.btrim(live_row.slot_type))
          like 'live_four_news:%'
    ) or exists (
      select 1
      from public.matchday_latest_news as latest_row
      where latest_row.matchday_id = p_target_matchday_id
    )
  into v_target_has_own_latest;

  with required_sources as (
    select pg_catalog.lower(pg_catalog.btrim(zone_row.source_id)) as source_id
    from public.matchday_editorial_profile_zone_items as zone_row
    where zone_row.matchday_id = p_source_matchday_id
      and zone_row.profile_key = v_source_profile_key

    union

    select article_row.id::text
    from public.editorial_articles as article_row
    where article_row.status = 'published'
      and '/noticias/' || pg_catalog.btrim(article_row.slug) in (
        pg_catalog.btrim(v_source_editorial.headline_link_url),
        pg_catalog.btrim(v_source_editorial.side_block_link_url)
      )

    union

    select article_row.id::text
    from public.matchday_highlights as highlight_row
    join public.editorial_articles as article_row
      on article_row.status = 'published'
     and '/noticias/' || pg_catalog.btrim(article_row.slug)
       = pg_catalog.btrim(highlight_row.link_url)
    where highlight_row.matchday_id = p_source_matchday_id
      and highlight_row.status = 'published'
      and highlight_row.sort_order between 1 and 3

    union

    select article_row.id::text
    from public.matchday_horizontal_news as faixa_row
    join public.editorial_articles as article_row
      on article_row.status = 'published'
     and '/noticias/' || pg_catalog.btrim(article_row.slug)
       = pg_catalog.btrim(faixa_row.link_url)
    where faixa_row.matchday_id = p_source_matchday_id
      and faixa_row.status = 'published'
  )
  select pg_catalog.array_agg(
    required_row.source_id
    order by required_row.source_id
  )
  into v_required_source_ids
  from required_sources as required_row;

  if v_required_source_ids is null or exists (
    select 1
    from pg_catalog.unnest(v_required_source_ids) as required_row(source_id)
    join public.editorial_articles as article_row
      on article_row.id::text = required_row.source_id
    where article_row.status <> 'published'
      or nullif(pg_catalog.btrim(article_row.title), '') is null
      or nullif(pg_catalog.btrim(article_row.slug), '') is null
  ) then
    raise exception
      'matchday-editorial-thematic-continuity-v3-source-bank-invalid';
  end if;

  insert into public.matchday_editorial_continuity_transitions (
    source_matchday_id,
    target_matchday_id,
    source_composition_id,
    continuity_version
  ) values (
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id,
    3
  )
  on conflict do nothing;

  get diagnostics v_transition_inserted = row_count;

  if v_transition_inserted = 0 then
    return query
    select
      false,
      p_source_matchday_id,
      p_target_matchday_id,
      p_source_composition_id,
      0,
      0,
      0,
      0;
    return;
  end if;

  perform pg_catalog.set_config(
    'jornada.thematic_continuity_initialize',
    'on',
    true
  );
  perform pg_catalog.set_config(
    'jornada.thematic_workspace_apply',
    'on',
    true
  );
  perform pg_catalog.set_config(
    'jornada.thematic_faixa_reconcile',
    'on',
    true
  );

  foreach v_required_source_id in array v_required_source_ids
  loop
    select article_row.*
    into strict v_article
    from public.editorial_articles as article_row
    where article_row.id::text = v_required_source_id
      and article_row.status = 'published';

    v_existing_bank_id := null;
    v_existing_automatic_eligible := null;
    v_existing_continuity_matchday_id := null;
    v_existing_continuity_composition_id := null;

    select
      bank_row.id,
      bank_row.automatic_eligible,
      bank_row.continuity_source_matchday_id,
      bank_row.continuity_source_composition_id
    into
      v_existing_bank_id,
      v_existing_automatic_eligible,
      v_existing_continuity_matchday_id,
      v_existing_continuity_composition_id
    from public.matchday_editorial_bank_items as bank_row
    where bank_row.matchday_id = p_target_matchday_id
      and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
        = 'editorial_article'
      and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
        = v_required_source_id
    order by bank_row.created_at, bank_row.id
    limit 1
    for update;

    if v_existing_bank_id is not null then
      if (
        v_existing_continuity_matchday_id is not null
        and v_existing_continuity_matchday_id <> p_source_matchday_id
      ) or (
        v_existing_continuity_composition_id is not null
        and v_existing_continuity_composition_id <> p_source_composition_id
      ) then
        raise exception
          'matchday-editorial-thematic-continuity-v3-bank-provenance-conflict';
      end if;

      if v_existing_continuity_matchday_id is null then
        update public.matchday_editorial_bank_items as bank_row
        set continuity_source_matchday_id = p_source_matchday_id,
            continuity_source_composition_id = p_source_composition_id
        where bank_row.id = v_existing_bank_id;
      end if;
    else
      if exists (
        select 1
        from public.matchday_editorial_bank_items as bank_row
        where bank_row.matchday_id = p_target_matchday_id
          and pg_catalog.lower(
            pg_catalog.regexp_replace(
              pg_catalog.split_part(
                pg_catalog.split_part(coalesce(bank_row.link_url, ''), '?', 1),
                '#',
                1
              ),
              '/$',
              ''
            )
          ) = pg_catalog.lower('/noticias/' || pg_catalog.btrim(v_article.slug))
      ) then
        raise exception
          'matchday-editorial-thematic-continuity-v3-bank-link-conflict';
      end if;

      insert into public.matchday_editorial_bank_items (
        matchday_id,
        label,
        label_color,
        title,
        subtitle,
        image_url,
        link_url,
        source_type,
        source_id,
        source_slug,
        origin_slot_type,
        sort_order,
        status,
        automatic_eligible,
        continuity_source_matchday_id,
        continuity_source_composition_id
      ) values (
        p_target_matchday_id,
        nullif(pg_catalog.btrim(v_article.label), ''),
        null,
        pg_catalog.btrim(v_article.title),
        nullif(pg_catalog.btrim(v_article.subtitle), ''),
        nullif(pg_catalog.btrim(v_article.image_url), ''),
        '/noticias/' || pg_catalog.btrim(v_article.slug),
        'editorial_article',
        v_required_source_id,
        pg_catalog.btrim(v_article.slug),
        null,
        null,
        'active',
        false,
        p_source_matchday_id,
        p_source_composition_id
      );
    end if;
  end loop;

  insert into public.matchday_editorials (
    matchday_id,
    updated_at
  ) values (
    p_target_matchday_id,
    v_now
  )
  on conflict (matchday_id) do nothing;

  update public.matchday_editorials as target_editorial
  set title = v_source_editorial.title,
      summary = v_source_editorial.summary,
      title_color = v_source_editorial.title_color,
      image_url = v_source_editorial.image_url,
      headline_link_url = v_source_editorial.headline_link_url,
      status = 'published',
      side_block_status = 'published',
      side_block_type = v_source_editorial.side_block_type,
      side_block_label = v_source_editorial.side_block_label,
      side_block_label_color = v_source_editorial.side_block_label_color,
      side_block_title = v_source_editorial.side_block_title,
      side_block_title_color = v_source_editorial.side_block_title_color,
      side_block_author = v_source_editorial.side_block_author,
      side_block_text = v_source_editorial.side_block_text,
      side_block_image_url = v_source_editorial.side_block_image_url,
      side_block_link_url = v_source_editorial.side_block_link_url,
      complementary_mode = 'none',
      complementary_status = 'draft',
      complementary_roundup_item_id = null,
      complementary_label = null,
      complementary_title = null,
      complementary_text = null,
      complementary_image_url = null,
      complementary_link_url = null,
      complementary_text_color = null,
      roundup_video_heading = null,
      roundup_video_heading_color = null,
      latest_zone_placement = case
        when v_target_has_own_latest then target_editorial.latest_zone_placement
        else v_source_editorial.latest_zone_placement
      end,
      latest_zone_title = case
        when v_target_has_own_latest then target_editorial.latest_zone_title
        else v_source_editorial.latest_zone_title
      end,
      latest_zone_title_color = case
        when v_target_has_own_latest then target_editorial.latest_zone_title_color
        else v_source_editorial.latest_zone_title_color
      end,
      updated_at = v_now
  where target_editorial.matchday_id = p_target_matchday_id;

  delete from public.matchday_highlights as target_highlight
  where target_highlight.matchday_id = p_target_matchday_id;

  insert into public.matchday_highlights (
    matchday_id,
    label,
    label_color,
    title,
    subtitle,
    image_url,
    link_url,
    sort_order,
    status,
    created_at,
    updated_at
  )
  select
    p_target_matchday_id,
    source_highlight.label,
    source_highlight.label_color,
    source_highlight.title,
    source_highlight.subtitle,
    source_highlight.image_url,
    source_highlight.link_url,
    source_highlight.sort_order,
    'published',
    v_now,
    v_now
  from public.matchday_highlights as source_highlight
  where source_highlight.matchday_id = p_source_matchday_id
    and source_highlight.status = 'published'
    and source_highlight.sort_order between 1 and 3
  order by source_highlight.sort_order;

  insert into public.matchday_editorial_profile_reconcile_control (
    matchday_id,
    profile_key,
    revision,
    last_applied_at,
    thematic_zone_order,
    thematic_zone_layouts,
    thematic_zone_titles,
    thematic_block_order,
    updated_at
  ) values (
    p_target_matchday_id,
    v_source_profile_key,
    1,
    v_now,
    v_source_control.thematic_zone_order,
    v_source_control.thematic_zone_layouts,
    v_source_control.thematic_zone_titles,
    v_source_control.thematic_block_order,
    v_now
  );

  insert into public.matchday_editorial_profile_zone_items (
    matchday_id,
    profile_key,
    source_type,
    source_id,
    zone_key,
    sort_order,
    created_at,
    updated_at
  )
  select
    p_target_matchday_id,
    source_zone.profile_key,
    source_zone.source_type,
    source_zone.source_id,
    source_zone.zone_key,
    source_zone.sort_order,
    v_now,
    v_now
  from public.matchday_editorial_profile_zone_items as source_zone
  where source_zone.matchday_id = p_source_matchday_id
    and source_zone.profile_key = v_source_profile_key
  order by source_zone.zone_key, source_zone.sort_order;

  insert into public.matchday_horizontal_news (
    matchday_id,
    label,
    label_color,
    title,
    subtitle,
    image_url,
    link_url,
    sort_order,
    status,
    created_at,
    updated_at
  )
  select
    p_target_matchday_id,
    source_faixa.label,
    source_faixa.label_color,
    source_faixa.title,
    source_faixa.subtitle,
    source_faixa.image_url,
    source_faixa.link_url,
    source_faixa.sort_order,
    'published',
    v_now,
    v_now
  from public.matchday_horizontal_news as source_faixa
  where source_faixa.matchday_id = p_source_matchday_id
    and source_faixa.status = 'published'
  order by source_faixa.sort_order;

  update public.matchday_editorial_desk_control as desk_row
  set carryover_source_composition_id = null,
      carryover_snapshot = null
  where desk_row.matchday_id = p_target_matchday_id
    and desk_row.is_managed = true;

  return query
  select
    true,
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id,
    pg_catalog.cardinality(v_required_source_ids)::integer,
    v_source_zone_count,
    v_source_faixa_count,
    5;
end;
$function$

CREATE OR REPLACE FUNCTION public.manage_team_creation_batch(p_country_id uuid, p_rows jsonb, p_apply boolean, p_confirmed_preview_fingerprint text, p_confirmed_complete_existing_lines jsonb, p_actor_type text, p_actor_reference text, p_source text, p_request_reference text)
 RETURNS TABLE(line_number integer, result_status text, reason_code text, reason_message text, proposed_identity jsonb, resolved_team_id uuid, existing_identity jsonb, conflicts jsonb, normalized_aliases jsonb, proposed_action text, final_team_id uuid, changed boolean, batch_applied boolean, batch_total_count integer, batch_create_count integer, batch_existing_count integer, batch_complete_existing_count integer, batch_probable_count integer, batch_ambiguous_count integer, batch_conflict_count integer, batch_invalid_count integer, batch_blocking_count integer, batch_can_apply boolean, batch_created_count integer, batch_completed_existing_count integer, batch_existing_result_count integer, batch_aliases_created_count integer, batch_aliases_unchanged_count integer, batch_public_names_changed_count integer, batch_integrally_applied boolean, preview_fingerprint text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_actor_type text := btrim(p_actor_type);
  v_actor_reference text := btrim(p_actor_reference);
  v_source text := btrim(p_source);
  v_request_reference text := btrim(p_request_reference);
  v_country_active boolean;
  v_input record;
  v_row jsonb;
  v_input_ordinal integer;
  v_line_number integer;
  v_name text;
  v_public_name text;
  v_short_name text;
  v_code text;
  v_slug text;
  v_logo_url text;
  v_primary_color text;
  v_normalized_name text;
  v_normalized_short_name text;
  v_normalized_code text;
  v_identity_keys text[];
  v_aliases jsonb;
  v_alias_keys text[];
  v_valid boolean;
  v_status text;
  v_reason_code text;
  v_reason_message text;
  v_conflicts jsonb;
  v_proposed_action text;
  v_candidate_ids uuid[];
  v_exact_ids uuid[];
  v_candidate_count integer;
  v_exact_count integer;
  v_ambiguous_key_count integer;
  v_resolved_team_id uuid;
  v_conflict_team_id uuid;
  v_slug_team_id uuid;
  v_existing public.teams%rowtype;
  v_existing_identity jsonb;
  v_structural_compatible boolean;
  v_optional_compatible boolean;
  v_aliases_all_active boolean;
  v_plan jsonb := '[]'::jsonb;
  v_preview_fingerprint text;
  v_confirmed_lines integer[] := array[]::integer[];
  v_total_count integer := 0;
  v_create_count integer := 0;
  v_existing_count integer := 0;
  v_complete_existing_count integer := 0;
  v_probable_count integer := 0;
  v_ambiguous_count integer := 0;
  v_conflict_count integer := 0;
  v_invalid_count integer := 0;
  v_blocking_count integer := 0;
  v_created_count integer := 0;
  v_completed_existing_count integer := 0;
  v_aliases_created_count integer := 0;
  v_aliases_unchanged_count integer := 0;
  v_public_names_changed_count integer := 0;
  v_final_ids jsonb := '{}'::jsonb;
  v_changed_rows jsonb := '{}'::jsonb;
  v_plan_row record;
  v_alias_row record;
  v_alias_result record;
  v_public_name_result record;
  v_final_id uuid;
begin
  if p_country_id is null then
    raise exception 'team_creation_batch_country_id_required'
      using errcode = '22023';
  end if;

  if p_apply is null then
    raise exception 'team_creation_batch_apply_required'
      using errcode = '22023';
  end if;

  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'team_creation_batch_rows_must_be_array'
      using errcode = '22023';
  end if;

  if jsonb_array_length(p_rows) = 0 then
    raise exception 'team_creation_batch_rows_required'
      using errcode = '22023';
  end if;

  if jsonb_array_length(p_rows) > 500 then
    raise exception 'team_creation_batch_rows_limit_exceeded'
      using errcode = '22023';
  end if;

  if v_actor_type is null or v_actor_type = '' then
    raise exception 'team_creation_batch_actor_type_required'
      using errcode = '22023';
  end if;

  if v_actor_reference is null or v_actor_reference = '' then
    raise exception 'team_creation_batch_actor_reference_required'
      using errcode = '22023';
  end if;

  if v_source is null or v_source = '' then
    raise exception 'team_creation_batch_source_required'
      using errcode = '22023';
  end if;

  if v_request_reference is null or v_request_reference = '' then
    raise exception 'team_creation_batch_request_reference_required'
      using errcode = '22023';
  end if;

  if p_confirmed_complete_existing_lines is not null
     and jsonb_typeof(p_confirmed_complete_existing_lines) <> 'array' then
    raise exception 'team_creation_batch_confirmed_lines_must_be_array'
      using errcode = '22023';
  end if;

  if p_confirmed_complete_existing_lines is not null and exists (
    select 1
      from jsonb_array_elements(p_confirmed_complete_existing_lines) e(value)
      where case
        when jsonb_typeof(e.value) = 'number'
         and (e.value #>> '{}') ~ '^[1-9][0-9]*$'
        then (e.value #>> '{}')::numeric <= 2147483647
        else false
      end is not true
  ) then
    raise exception 'team_creation_batch_confirmed_line_invalid'
      using errcode = '22023';
  end if;

  if p_confirmed_complete_existing_lines is not null then
    select coalesce(array_agg((e.value #>> '{}')::integer), array[]::integer[])
    into v_confirmed_lines
    from jsonb_array_elements(p_confirmed_complete_existing_lines) e(value);

    if cardinality(v_confirmed_lines) <>
       cardinality(array(select distinct unnest(v_confirmed_lines))) then
      raise exception 'team_creation_batch_confirmed_lines_duplicated'
        using errcode = '22023';
    end if;
  end if;

  if p_apply then
    if nullif(btrim(p_confirmed_preview_fingerprint), '') is null then
      raise exception 'team_creation_batch_preview_fingerprint_required'
        using errcode = '22023';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('team_creation_batch:v1', 0)
    );

    select c.is_active
    into v_country_active
    from public.countries c
    where c.id = p_country_id
    for key share;

    if not found then
      raise exception 'team_creation_batch_country_not_found'
        using errcode = '23503';
    end if;

    if not v_country_active then
      raise exception 'team_creation_batch_country_inactive'
        using errcode = '22023';
    end if;

    -- A ordem coincide com manage_team_alias: teams antes de team_aliases.
    lock table public.teams in share row exclusive mode;
    lock table public.team_aliases in share row exclusive mode;
  else
    select c.is_active
    into v_country_active
    from public.countries c
    where c.id = p_country_id;

    if not found then
      raise exception 'team_creation_batch_country_not_found'
        using errcode = '23503';
    end if;

    if not v_country_active then
      raise exception 'team_creation_batch_country_inactive'
        using errcode = '22023';
    end if;
  end if;

  for v_input in
    select e.value as row_value, e.ordinality::integer as input_ordinal
    from jsonb_array_elements(p_rows) with ordinality e(value, ordinality)
    order by e.ordinality
  loop
    v_row := v_input.row_value;
    v_input_ordinal := v_input.input_ordinal;
    v_line_number := v_input_ordinal;
    v_name := null;
    v_public_name := null;
    v_short_name := null;
    v_code := null;
    v_slug := null;
    v_logo_url := null;
    v_primary_color := null;
    v_normalized_name := null;
    v_normalized_short_name := null;
    v_normalized_code := null;
    v_identity_keys := array[]::text[];
    v_aliases := '[]'::jsonb;
    v_alias_keys := array[]::text[];
    v_valid := true;
    v_status := 'invalid';
    v_reason_code := 'invalid_row';
    v_reason_message := 'A linha nao respeita o contrato estruturado.';
    v_conflicts := '[]'::jsonb;
    v_proposed_action := 'block';
    v_candidate_ids := array[]::uuid[];
    v_exact_ids := array[]::uuid[];
    v_candidate_count := 0;
    v_exact_count := 0;
    v_ambiguous_key_count := 0;
    v_resolved_team_id := null;
    v_conflict_team_id := null;
    v_slug_team_id := null;
    v_existing := null;
    v_existing_identity := null;

    if jsonb_typeof(v_row) <> 'object' then
      v_valid := false;
      v_reason_code := 'invalid_object_shape';
      v_reason_message := 'A linha deve conter exatamente os nove campos suportados.';
    elsif not (v_row ?& array[
      'lineNumber', 'canonicalName', 'publicName', 'shortName', 'code',
      'slug', 'aliases', 'logoUrl', 'primaryColor'
    ]::text[]) or exists (
      select 1
      from jsonb_object_keys(v_row) k(key_name)
      where k.key_name not in (
        'lineNumber', 'canonicalName', 'publicName', 'shortName', 'code',
        'slug', 'aliases', 'logoUrl', 'primaryColor'
      )
    ) then
      v_valid := false;
      v_reason_code := 'invalid_object_shape';
      v_reason_message := 'A linha deve conter exatamente os nove campos suportados.';
    end if;

    if v_valid then
      if jsonb_typeof(v_row -> 'lineNumber') <> 'number'
         or (v_row ->> 'lineNumber') !~ '^[1-9][0-9]*$' then
        v_valid := false;
        v_reason_code := 'invalid_line_number';
        v_reason_message := 'lineNumber deve ser um inteiro positivo unico.';
      elsif (v_row ->> 'lineNumber')::numeric > 2147483647 then
        v_valid := false;
        v_reason_code := 'invalid_line_number';
        v_reason_message := 'lineNumber deve ser um inteiro positivo unico.';
      else
        v_line_number := (v_row ->> 'lineNumber')::integer;
      end if;
    end if;

    if v_valid and (
      jsonb_typeof(v_row -> 'canonicalName') <> 'string'
      or jsonb_typeof(v_row -> 'shortName') <> 'string'
      or jsonb_typeof(v_row -> 'slug') <> 'string'
      or jsonb_typeof(v_row -> 'aliases') <> 'array'
      or jsonb_typeof(v_row -> 'publicName') not in ('string', 'null')
      or jsonb_typeof(v_row -> 'code') not in ('string', 'null')
      or jsonb_typeof(v_row -> 'logoUrl') not in ('string', 'null')
      or jsonb_typeof(v_row -> 'primaryColor') not in ('string', 'null')
    ) then
      v_valid := false;
      v_reason_code := 'invalid_field_type';
      v_reason_message := 'Um ou mais campos tem um tipo JSON invalido.';
    end if;

    if v_valid then
      v_name := btrim(v_row ->> 'canonicalName');
      v_public_name := nullif(btrim(v_row ->> 'publicName'), '');
      v_short_name := btrim(v_row ->> 'shortName');
      v_code := case
        when jsonb_typeof(v_row -> 'code') = 'null' then null
        else btrim(v_row ->> 'code')
      end;
      v_slug := btrim(v_row ->> 'slug');
      v_logo_url := nullif(btrim(v_row ->> 'logoUrl'), '');
      v_primary_color := nullif(upper(btrim(v_row ->> 'primaryColor')), '');

      if v_name = '' or v_name ~ '[[:cntrl:]]' then
        v_valid := false;
        v_reason_code := 'canonical_name_invalid';
        v_reason_message := 'canonicalName e obrigatorio e nao pode conter controlos.';
      elsif v_short_name = '' or char_length(v_short_name) > 6
            or v_short_name ~ '[[:cntrl:]]' then
        v_valid := false;
        v_reason_code := 'short_name_invalid';
        v_reason_message := 'shortName e obrigatorio, sem controlos, com no maximo seis caracteres.';
      elsif v_public_name is not null and (
        char_length(v_public_name) > 80 or v_public_name ~ '[[:cntrl:]]'
      ) then
        v_valid := false;
        v_reason_code := 'public_name_invalid';
        v_reason_message := 'publicName viola a policy auditavel existente.';
      elsif jsonb_typeof(v_row -> 'code') = 'string'
            and (v_code = '' or v_code ~ '[[:cntrl:]]') then
        v_valid := false;
        v_reason_code := 'code_invalid';
        v_reason_message := 'code deve ser nulo ou texto normalizavel nao vazio.';
      elsif v_slug = ''
            or v_slug is distinct from public.normalize_team_identity_v1(v_slug) then
        v_valid := false;
        v_reason_code := 'slug_invalid';
        v_reason_message := 'slug e obrigatorio e deve estar na forma normalizada oficial.';
      elsif v_logo_url is not null
            and v_logo_url !~* '^https?://[^[:space:]]+$' then
        v_valid := false;
        v_reason_code := 'logo_url_invalid';
        v_reason_message := 'logoUrl deve ser nulo ou um URL HTTP/HTTPS sem espacos.';
      elsif v_primary_color is not null
            and v_primary_color !~ '^#[0-9A-F]{6}$' then
        v_valid := false;
        v_reason_code := 'primary_color_invalid';
        v_reason_message := 'primaryColor deve ser nula ou usar #RRGGBB.';
      end if;
    end if;

    if v_valid and exists (
      select 1
      from jsonb_array_elements(v_row -> 'aliases') a(value)
      where jsonb_typeof(a.value) <> 'string'
    ) then
      v_valid := false;
      v_reason_code := 'aliases_invalid_type';
      v_reason_message := 'aliases deve conter apenas strings.';
    end if;

    if v_valid then
      select
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'alias', parsed.alias_text,
              'normalized_alias', parsed.normalized_alias
            ) order by parsed.ordinality
          ),
          '[]'::jsonb
        ),
        coalesce(
          array_agg(parsed.normalized_alias order by parsed.ordinality),
          array[]::text[]
        )
      into v_aliases, v_alias_keys
      from (
        select
          a.ordinality,
          btrim(a.value #>> '{}') as alias_text,
          public.normalize_team_identity_v1(btrim(a.value #>> '{}')) as normalized_alias
        from jsonb_array_elements(v_row -> 'aliases')
          with ordinality a(value, ordinality)
      ) parsed;

      if exists (
        select 1
        from jsonb_array_elements(v_aliases) a(value)
        where a.value ->> 'alias' = ''
           or char_length(a.value ->> 'alias') > 160
           or a.value ->> 'alias' ~ '[[:cntrl:]]'
           or coalesce(a.value ->> 'normalized_alias', '') = ''
      ) then
        v_valid := false;
        v_reason_code := 'alias_invalid';
        v_reason_message := 'Cada alias deve ser nao vazio, normalizavel e ter no maximo 160 caracteres.';
      elsif cardinality(v_alias_keys) <>
            cardinality(array(select distinct unnest(v_alias_keys))) then
        v_valid := false;
        v_reason_code := 'duplicate_alias_in_row';
        v_reason_message := 'A linha contem aliases duplicados pela normalizacao oficial.';
      end if;
    end if;

    if v_valid then
      v_normalized_name := public.normalize_team_identity_v1(v_name);
      v_normalized_short_name := public.normalize_team_identity_v1(v_short_name);
      v_normalized_code := case
        when v_code is null then null
        else public.normalize_team_identity_v1(v_code)
      end;

      if v_normalized_name = '' or v_normalized_short_name = ''
         or (v_code is not null and coalesce(v_normalized_code, '') = '') then
        v_valid := false;
        v_reason_code := 'identity_not_normalizable';
        v_reason_message := 'Um identificador nao produz uma identidade normalizada valida.';
      else
        select array_agg(identity_key order by identity_key)
        into v_identity_keys
        from (
          select distinct identity_key
          from unnest(array[
            v_normalized_name,
            v_normalized_short_name,
            v_slug,
            v_normalized_code
          ]) identity(identity_key)
          where identity_key is not null and identity_key <> ''
        ) requested;
      end if;
    end if;

    if v_valid and v_alias_keys && v_identity_keys then
      v_valid := false;
      v_reason_code := 'alias_redundant_with_proposed_identity';
      v_reason_message := 'Um alias repete uma identidade proposta na mesma linha.';
    end if;

    if v_valid then
      with requested as (
        select unnest(v_identity_keys) as identity_key
      ), candidate_scores as (
        select
          t.id,
          t.code,
          count(*) filter (
            where exists (
              select 1
              from (values (t.name), (t.short_name), (t.slug), (t.code))
                identity(field_value)
              where identity.field_value is not null
                and public.normalize_team_identity_v1(identity.field_value) =
                  requested.identity_key
            ) or exists (
              select 1
              from public.team_aliases ta
              where ta.team_id = t.id
                and ta.status = 'active'
                and ta.normalized_alias = requested.identity_key
            )
          )::integer as matched_key_count
        from public.teams t
        cross join requested
        where t.country_id = p_country_id or t.country_id is null
        group by t.id, t.code
      ), classified_candidates as (
        select
          cs.id,
          cs.matched_key_count,
          cs.matched_key_count = cardinality(v_identity_keys)
          or (
            v_code is not null
            and cs.code is null
            and v_normalized_code <> all(array[
              v_normalized_name,
              v_normalized_short_name,
              v_slug
            ])
            and cs.matched_key_count = cardinality(v_identity_keys) - 1
          ) as is_exact
        from candidate_scores cs
      )
      select
        coalesce(
          array_agg(cs.id order by cs.id) filter (where cs.matched_key_count > 0),
          array[]::uuid[]
        ),
        coalesce(
          array_agg(cs.id order by cs.id) filter (where cs.is_exact),
          array[]::uuid[]
        )
      into v_candidate_ids, v_exact_ids
      from classified_candidates cs;

      v_candidate_count := cardinality(v_candidate_ids);
      v_exact_count := cardinality(v_exact_ids);

      with requested as (
        select unnest(v_identity_keys) as identity_key
      )
      select count(*)::integer
      into v_ambiguous_key_count
      from requested r
      where (
        select count(distinct t.id)
        from public.teams t
        where (t.country_id = p_country_id or t.country_id is null)
          and (
            exists (
              select 1
              from (values (t.name), (t.short_name), (t.slug), (t.code))
                identity(field_value)
              where identity.field_value is not null
                and public.normalize_team_identity_v1(identity.field_value) = r.identity_key
            ) or exists (
              select 1
              from public.team_aliases ta
              where ta.team_id = t.id
                and ta.status = 'active'
                and ta.normalized_alias = r.identity_key
            )
          )
      ) > 1;

      if v_exact_count = 1 then
        v_resolved_team_id := v_exact_ids[1];
        v_status := 'candidate';
      end if;

      select t.id
      into v_slug_team_id
      from public.teams t
      where t.slug = v_slug;

      select ta.team_id
      into v_conflict_team_id
      from public.team_aliases ta
      where ta.normalized_alias = any(v_identity_keys)
        and (v_resolved_team_id is null or ta.team_id <> v_resolved_team_id)
      order by ta.team_id
      limit 1;

      if v_slug_team_id is not null
         and (v_resolved_team_id is null or v_slug_team_id <> v_resolved_team_id) then
        v_status := 'conflict';
        v_reason_code := 'slug_conflict';
        v_reason_message := 'O slug global ja pertence a outro clube.';
        v_conflicts := jsonb_build_array(jsonb_build_object(
          'type', 'slug', 'team_id', v_slug_team_id, 'value', v_slug
        ));
      elsif v_conflict_team_id is not null then
        v_status := 'conflict';
        v_reason_code := 'canonical_identity_conflicts_with_alias';
        v_reason_message := 'Uma identidade proposta esta reservada como alias de outro clube.';
        v_conflicts := jsonb_build_array(jsonb_build_object(
          'type', 'identity_alias', 'team_id', v_conflict_team_id
        ));
      elsif v_exact_count = 1 and v_candidate_count > 1 then
        v_status := 'conflict';
        v_reason_code := 'identifiers_point_to_different_teams';
        v_reason_message := 'Apesar de existir um candidato integral, outro identificador aponta para outro clube.';
        v_conflicts := to_jsonb(v_candidate_ids);
      elsif v_exact_count > 1 then
        v_status := 'ambiguous';
        v_reason_code := 'multiple_exact_candidates';
        v_reason_message := 'Mais de um clube satisfaz integralmente a identidade proposta.';
        v_conflicts := to_jsonb(v_exact_ids);
      elsif v_exact_count = 0 and v_candidate_count > 1 then
        if v_ambiguous_key_count > 0 then
          v_status := 'ambiguous';
          v_reason_code := 'identity_ambiguous';
          v_reason_message := 'Pelo menos um identificador corresponde a varios clubes.';
        else
          v_status := 'conflict';
          v_reason_code := 'identifiers_point_to_different_teams';
          v_reason_message := 'Os identificadores propostos apontam para clubes diferentes.';
        end if;
        v_conflicts := to_jsonb(v_candidate_ids);
      elsif v_exact_count = 0 and v_candidate_count = 1 then
        v_resolved_team_id := v_candidate_ids[1];
        v_status := 'probable';
        v_reason_code := 'partial_identity_match';
        v_reason_message := 'Existe uma correspondencia parcial forte que exige decisao humana.';
      elsif v_exact_count = 0 then
        v_status := 'create';
        v_reason_code := 'new_team';
        v_reason_message := 'Nao foi encontrada identidade existente compativel.';
        v_proposed_action := 'create';
      end if;

      if v_resolved_team_id is not null then
        select t.*
        into v_existing
        from public.teams t
        where t.id = v_resolved_team_id;

        v_existing_identity := jsonb_build_object(
          'team_id', v_existing.id,
          'country_id', v_existing.country_id,
          'canonical_name', v_existing.name,
          'public_name', v_existing.public_name,
          'short_name', v_existing.short_name,
          'code', v_existing.code,
          'slug', v_existing.slug,
          'logo_url', v_existing.logo_url,
          'primary_color', v_existing.primary_color
        );
      end if;

      if v_status not in ('conflict', 'ambiguous') then
        select ta.team_id
        into v_conflict_team_id
        from public.team_aliases ta
        where ta.normalized_alias = any(v_alias_keys)
          and (
            v_resolved_team_id is null
            or ta.team_id <> v_resolved_team_id
            or ta.status <> 'active'
          )
        order by ta.team_id
        limit 1;

        if v_conflict_team_id is null then
          select t.id
          into v_conflict_team_id
          from public.teams t
          cross join lateral (values (t.name), (t.short_name), (t.slug), (t.code))
            identity(field_value)
          where identity.field_value is not null
            and public.normalize_team_identity_v1(identity.field_value) = any(v_alias_keys)
          order by t.id
          limit 1;
        end if;

        if v_conflict_team_id is not null then
          v_status := 'conflict';
          v_reason_code := 'alias_conflict';
          v_reason_message := 'Um alias proposto colide com uma identidade ja reservada.';
          v_conflicts := v_conflicts || jsonb_build_array(jsonb_build_object(
            'type', 'alias', 'team_id', v_conflict_team_id
          ));
        end if;
      end if;

      if v_status not in ('conflict', 'ambiguous', 'probable', 'create')
         and v_resolved_team_id is not null then
        v_structural_compatible :=
          public.normalize_team_identity_v1(v_existing.name) = v_normalized_name
          and public.normalize_team_identity_v1(v_existing.short_name) =
            v_normalized_short_name
          and v_existing.slug = v_slug
          and (
            v_code is null
            or (
              v_existing.code is not null
              and public.normalize_team_identity_v1(v_existing.code) = v_normalized_code
            )
          );

        v_optional_compatible :=
          (v_public_name is null or v_existing.public_name is not distinct from v_public_name)
          and (v_logo_url is null or v_existing.logo_url is not distinct from v_logo_url)
          and (
            v_primary_color is null
            or upper(v_existing.primary_color) is not distinct from v_primary_color
          );

        select not exists (
          select 1
          from unnest(v_alias_keys) requested_alias(normalized_alias)
          where not exists (
            select 1
            from public.team_aliases ta
            where ta.team_id = v_resolved_team_id
              and ta.status = 'active'
              and ta.normalized_alias = requested_alias.normalized_alias
          )
        )
        into v_aliases_all_active;

        if v_existing.country_id = p_country_id then
          if not v_optional_compatible then
            v_status := 'conflict';
            v_reason_code := 'existing_fields_conflict';
            v_reason_message := 'O clube existente tem campos opcionais diferentes; o lote nao os altera.';
          elsif not v_structural_compatible or not v_aliases_all_active then
            v_status := 'probable';
            v_reason_code := 'existing_requires_human_decision';
            v_reason_message := 'O candidato existe, mas a identidade ou os aliases nao permitem um no-op exato.';
          else
            v_status := 'existing';
            v_reason_code := 'existing_compatible';
            v_reason_message := 'O clube ja existe com identidade compativel; o apply sera no-op.';
            v_proposed_action := 'noop';
          end if;
        elsif v_existing.country_id is null then
          v_structural_compatible :=
            public.normalize_team_identity_v1(v_existing.name) = v_normalized_name
            and public.normalize_team_identity_v1(v_existing.short_name) =
              v_normalized_short_name
            and v_existing.slug = v_slug;

          v_optional_compatible :=
            (v_existing.code is null or v_code is null
              or public.normalize_team_identity_v1(v_existing.code) = v_normalized_code)
            and (v_existing.public_name is null or v_public_name is null
              or v_existing.public_name = v_public_name)
            and (v_existing.logo_url is null or v_logo_url is null
              or v_existing.logo_url = v_logo_url)
            and (v_existing.primary_color is null or v_primary_color is null
              or upper(v_existing.primary_color) = v_primary_color);

          if not v_optional_compatible then
            v_status := 'conflict';
            v_reason_code := 'legacy_fields_conflict';
            v_reason_message := 'O clube legacy tem campos preenchidos incompatíveis com a proposta.';
          elsif not v_structural_compatible then
            v_status := 'probable';
            v_reason_code := 'legacy_identity_requires_human_decision';
            v_reason_message := 'O candidato legacy e parcial e nao pode ser completado automaticamente.';
          else
            v_status := 'complete_existing';
            v_reason_code := 'legacy_team_can_be_completed';
            v_reason_message := 'O clube legacy pode receber country_id e apenas campos nulos confirmados.';
            v_proposed_action := 'complete';
          end if;
        else
          v_status := 'conflict';
          v_reason_code := 'team_belongs_to_other_country';
          v_reason_message := 'O candidato resolvido pertence a outro pais.';
        end if;
      end if;
    end if;

    if not v_valid then
      v_status := 'invalid';
      v_proposed_action := 'block';
    elsif v_status in ('probable', 'ambiguous') then
      v_proposed_action := 'review';
    elsif v_status = 'conflict' then
      v_proposed_action := 'block';
    end if;

    v_plan := v_plan || jsonb_build_array(jsonb_build_object(
      'input_ordinal', v_input_ordinal,
      'line_number', v_line_number,
      'status', v_status,
      'reason_code', v_reason_code,
      'reason_message', v_reason_message,
      'proposed_identity', jsonb_build_object(
        'canonical_name', v_name,
        'normalized_canonical_name', v_normalized_name,
        'public_name', v_public_name,
        'short_name', v_short_name,
        'normalized_short_name', v_normalized_short_name,
        'code', v_code,
        'normalized_code', v_normalized_code,
        'slug', v_slug,
        'country_id', p_country_id,
        'logo_url', v_logo_url,
        'primary_color', v_primary_color
      ),
      'resolved_team_id', v_resolved_team_id,
      'existing_identity', v_existing_identity,
      'conflicts', v_conflicts,
      'aliases', v_aliases,
      'identity_keys', to_jsonb(v_identity_keys),
      'proposed_action', v_proposed_action
    ));
  end loop;

  -- Conflitos internos sao avaliados sem escolher arbitrariamente uma linha.
  with plan_rows as (
    select e.value as row_value, e.ordinality
    from jsonb_array_elements(v_plan) with ordinality e(value, ordinality)
  ), marked as (
    select
      p.ordinality,
      p.row_value,
      (
        select count(*) > 1
        from plan_rows q
        where q.row_value ->> 'line_number' = p.row_value ->> 'line_number'
      ) as duplicated_line,
      exists (
        select 1
        from plan_rows q
        where q.ordinality <> p.ordinality
          and (
            exists (
              select 1
              from jsonb_array_elements_text(p.row_value -> 'identity_keys') pi(value)
              join jsonb_array_elements_text(q.row_value -> 'identity_keys') qi(value)
                on qi.value = pi.value
            )
            or exists (
              select 1
              from jsonb_array_elements(p.row_value -> 'aliases') pa(value)
              join jsonb_array_elements(q.row_value -> 'aliases') qa(value)
                on qa.value ->> 'normalized_alias' = pa.value ->> 'normalized_alias'
            )
            or exists (
              select 1
              from jsonb_array_elements(p.row_value -> 'aliases') pa(value)
              join jsonb_array_elements_text(q.row_value -> 'identity_keys') qi(value)
                on qi.value = pa.value ->> 'normalized_alias'
            )
            or exists (
              select 1
              from jsonb_array_elements_text(p.row_value -> 'identity_keys') pi(value)
              join jsonb_array_elements(q.row_value -> 'aliases') qa(value)
                on qa.value ->> 'normalized_alias' = pi.value
            )
          )
      ) as cross_row_conflict
    from plan_rows p
  )
  select jsonb_agg(
    case
      when m.duplicated_line then
        m.row_value || jsonb_build_object(
          'status', 'invalid',
          'reason_code', 'duplicate_line_number',
          'reason_message', 'lineNumber repete-se dentro do lote.',
          'proposed_action', 'block',
          'conflicts', (m.row_value -> 'conflicts') ||
            jsonb_build_array(jsonb_build_object('type', 'line_number'))
        )
      when m.cross_row_conflict and m.row_value ->> 'status' <> 'invalid' then
        m.row_value || jsonb_build_object(
          'status', 'conflict',
          'reason_code', 'batch_identity_conflict',
          'reason_message', 'A identidade ou um alias colide com outra linha do lote.',
          'proposed_action', 'block',
          'conflicts', (m.row_value -> 'conflicts') ||
            jsonb_build_array(jsonb_build_object('type', 'batch_identity'))
        )
      else m.row_value
    end
    order by m.ordinality
  )
  into v_plan
  from marked m;

  v_preview_fingerprint := 'v1:' || pg_catalog.md5(v_plan::text);

  select
    count(*)::integer,
    count(*) filter (where p.value ->> 'status' = 'create')::integer,
    count(*) filter (where p.value ->> 'status' = 'existing')::integer,
    count(*) filter (where p.value ->> 'status' = 'complete_existing')::integer,
    count(*) filter (where p.value ->> 'status' = 'probable')::integer,
    count(*) filter (where p.value ->> 'status' = 'ambiguous')::integer,
    count(*) filter (where p.value ->> 'status' = 'conflict')::integer,
    count(*) filter (where p.value ->> 'status' = 'invalid')::integer
  into
    v_total_count,
    v_create_count,
    v_existing_count,
    v_complete_existing_count,
    v_probable_count,
    v_ambiguous_count,
    v_conflict_count,
    v_invalid_count
  from jsonb_array_elements(v_plan) p(value);

  if p_apply and p_confirmed_preview_fingerprint <> v_preview_fingerprint then
    raise exception 'team_creation_batch_preview_stale'
      using errcode = '40001',
            detail = format(
              'confirmed=%s recalculated=%s',
              p_confirmed_preview_fingerprint,
              v_preview_fingerprint
            );
  end if;

  if p_apply and exists (
    select 1
    from unnest(v_confirmed_lines) confirmed(line_number)
    where not exists (
      select 1
      from jsonb_array_elements(v_plan) p(value)
      where (p.value ->> 'line_number')::integer = confirmed.line_number
        and p.value ->> 'status' = 'complete_existing'
    )
  ) then
    raise exception 'team_creation_batch_complete_confirmation_invalid'
      using errcode = '22023';
  end if;

  select count(*)::integer
  into v_blocking_count
  from jsonb_array_elements(v_plan) p(value)
  where p.value ->> 'status' in ('probable', 'ambiguous', 'conflict', 'invalid')
     or (
       p.value ->> 'status' = 'complete_existing'
       and (
         not p_apply
         or not ((p.value ->> 'line_number')::integer = any(v_confirmed_lines))
       )
     );

  if p_apply and v_blocking_count > 0 then
    raise exception 'team_creation_batch_blocking_rows'
      using errcode = '22023',
            detail = format('blocking_count=%s', v_blocking_count);
  end if;

  if p_apply then
    for v_plan_row in
      select p.value as row_value
      from jsonb_array_elements(v_plan) p(value)
      order by (p.value ->> 'input_ordinal')::integer
    loop
      v_status := v_plan_row.row_value ->> 'status';
      v_line_number := (v_plan_row.row_value ->> 'line_number')::integer;
      v_name := v_plan_row.row_value #>> '{proposed_identity,canonical_name}';
      v_public_name := v_plan_row.row_value #>> '{proposed_identity,public_name}';
      v_short_name := v_plan_row.row_value #>> '{proposed_identity,short_name}';
      v_code := v_plan_row.row_value #>> '{proposed_identity,code}';
      v_slug := v_plan_row.row_value #>> '{proposed_identity,slug}';
      v_logo_url := v_plan_row.row_value #>> '{proposed_identity,logo_url}';
      v_primary_color := v_plan_row.row_value #>> '{proposed_identity,primary_color}';
      v_resolved_team_id := nullif(
        v_plan_row.row_value ->> 'resolved_team_id', ''
      )::uuid;
      v_final_id := v_resolved_team_id;

      if v_status = 'create' then
        insert into public.teams (
          name,
          short_name,
          code,
          slug,
          country_id,
          logo_url,
          primary_color
        ) values (
          v_name,
          v_short_name,
          v_code,
          v_slug,
          p_country_id,
          v_logo_url,
          v_primary_color
        )
        returning id into v_final_id;

        v_created_count := v_created_count + 1;
        v_changed_rows := v_changed_rows ||
          jsonb_build_object(
            (v_plan_row.row_value ->> 'input_ordinal'), true
          );
      elsif v_status = 'complete_existing' then
        update public.teams t
        set country_id = p_country_id,
            code = coalesce(t.code, v_code),
            logo_url = coalesce(t.logo_url, v_logo_url),
            primary_color = coalesce(t.primary_color, v_primary_color)
        where t.id = v_resolved_team_id
          and t.country_id is null
        returning t.id into v_final_id;

        if not found then
          raise exception 'team_creation_batch_legacy_state_changed'
            using errcode = '40001';
        end if;

        v_completed_existing_count := v_completed_existing_count + 1;
        v_changed_rows := v_changed_rows ||
          jsonb_build_object(
            (v_plan_row.row_value ->> 'input_ordinal'), true
          );
      else
        v_changed_rows := v_changed_rows ||
          jsonb_build_object(
            (v_plan_row.row_value ->> 'input_ordinal'), false
          );

        if v_status = 'existing' then
          v_aliases_unchanged_count := v_aliases_unchanged_count +
            jsonb_array_length(v_plan_row.row_value -> 'aliases');
        end if;
      end if;

      if v_status in ('create', 'complete_existing') then
        if v_public_name is not null then
          select *
          into v_public_name_result
          from public.manage_team_public_name(
            v_final_id,
            v_public_name,
            v_actor_type,
            v_actor_reference,
            v_source,
            v_request_reference || ':line:' || v_line_number::text
          );

          if v_public_name_result.result_changed then
            v_public_names_changed_count := v_public_names_changed_count + 1;
          end if;
        end if;

        for v_alias_row in
          select a.value ->> 'alias' as alias_text
          from jsonb_array_elements(v_plan_row.row_value -> 'aliases') a(value)
          order by a.value ->> 'normalized_alias'
        loop
          select *
          into v_alias_result
          from public.manage_team_alias(
            'create',
            v_actor_type,
            v_actor_reference,
            v_source,
            null,
            v_final_id,
            v_alias_row.alias_text,
            v_request_reference || ':line:' || v_line_number::text
          );

          if v_alias_result.result_code = 'created'
             and v_alias_result.result_status = 'active'
             and v_alias_result.result_changed then
            v_aliases_created_count := v_aliases_created_count + 1;
          elsif v_alias_result.result_code = 'noop_existing_active'
                and v_alias_result.result_status = 'active'
                and not v_alias_result.result_changed then
            v_aliases_unchanged_count := v_aliases_unchanged_count + 1;
          else
            raise exception 'team_creation_batch_alias_result_unexpected: %',
              v_alias_result.result_code
              using errcode = '55000';
          end if;
        end loop;
      end if;

      v_final_ids := v_final_ids ||
        jsonb_build_object(
          (v_plan_row.row_value ->> 'input_ordinal'), v_final_id
        );
    end loop;
  end if;

  return query
  select
    (p.value ->> 'line_number')::integer,
    p.value ->> 'status',
    p.value ->> 'reason_code',
    p.value ->> 'reason_message',
    p.value -> 'proposed_identity',
    nullif(p.value ->> 'resolved_team_id', '')::uuid,
    p.value -> 'existing_identity',
    p.value -> 'conflicts',
    coalesce((
      select jsonb_agg(a.value ->> 'normalized_alias' order by a.value ->> 'normalized_alias')
      from jsonb_array_elements(p.value -> 'aliases') a(value)
    ), '[]'::jsonb),
    p.value ->> 'proposed_action',
    coalesce(
      nullif(v_final_ids ->> (p.value ->> 'input_ordinal'), '')::uuid,
      nullif(p.value ->> 'resolved_team_id', '')::uuid
    ),
    coalesce(
      (v_changed_rows ->> (p.value ->> 'input_ordinal'))::boolean,
      false
    ),
    p_apply,
    v_total_count,
    v_create_count,
    v_existing_count,
    v_complete_existing_count,
    v_probable_count,
    v_ambiguous_count,
    v_conflict_count,
    v_invalid_count,
    v_blocking_count,
    v_blocking_count = 0,
    v_created_count,
    v_completed_existing_count,
    v_existing_count,
    v_aliases_created_count,
    v_aliases_unchanged_count,
    v_public_names_changed_count,
    p_apply and v_blocking_count = 0,
    v_preview_fingerprint
  from jsonb_array_elements(v_plan) p(value)
  order by (p.value ->> 'input_ordinal')::integer;
end
$function$

CREATE OR REPLACE FUNCTION public.manage_team_public_name(p_team_id uuid, p_public_name text, p_actor_type text, p_actor_reference text, p_source text, p_request_reference text)
 RETURNS TABLE(result_team_id uuid, result_public_name text, result_changed boolean, result_audit_event_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_public_name text := nullif(btrim(p_public_name), '');
  v_actor_type text := btrim(p_actor_type);
  v_actor_reference text := btrim(p_actor_reference);
  v_source text := btrim(p_source);
  v_request_reference text := btrim(p_request_reference);
  v_before public.teams%rowtype;
  v_after public.teams%rowtype;
  v_action text;
  v_audit_event_id uuid;
begin
  if p_team_id is null then
    raise exception 'team_public_name_team_id_required' using errcode = '22023';
  end if;

  if v_actor_type is null or v_actor_type = '' then
    raise exception 'team_public_name_actor_type_required' using errcode = '22023';
  end if;

  if v_actor_reference is null or v_actor_reference = '' then
    raise exception 'team_public_name_actor_reference_required' using errcode = '22023';
  end if;

  if v_source is null or v_source = '' then
    raise exception 'team_public_name_source_required' using errcode = '22023';
  end if;

  if v_request_reference is null or v_request_reference = '' then
    raise exception 'team_public_name_request_reference_required' using errcode = '22023';
  end if;

  if v_public_name is not null
     and (char_length(v_public_name) > 80 or v_public_name ~ '[[:cntrl:]]') then
    raise exception 'team_public_name_value_invalid' using errcode = '22023';
  end if;

  select t.*
  into v_before
  from public.teams t
  where t.id = p_team_id
  for update;

  if not found then
    raise exception 'team_public_name_team_not_found' using errcode = 'P0002';
  end if;

  if v_before.public_name is not distinct from v_public_name then
    return query
    select v_before.id, v_before.public_name, false, null::uuid;
    return;
  end if;

  v_action := case
    when v_before.public_name is null then 'set'
    when v_public_name is null then 'clear'
    else 'update'
  end;

  update public.teams t
  set public_name = v_public_name
  where t.id = v_before.id
  returning t.* into v_after;

  insert into public.team_public_name_audit_events (
    team_id,
    action,
    actor_type,
    actor_reference,
    source,
    before_state,
    after_state,
    request_reference
  ) values (
    v_after.id,
    v_action,
    v_actor_type,
    v_actor_reference,
    v_source,
    jsonb_build_object(
      'team_id', v_before.id,
      'name', v_before.name,
      'public_name', v_before.public_name
    ),
    jsonb_build_object(
      'team_id', v_after.id,
      'name', v_after.name,
      'public_name', v_after.public_name
    ),
    v_request_reference
  )
  returning id into v_audit_event_id;

  return query
  select v_after.id, v_after.public_name, true, v_audit_event_id;
end
$function$

CREATE OR REPLACE FUNCTION public.manage_team_safe_deletion(p_team_id uuid, p_apply boolean, p_confirmed_preview_fingerprint text, p_confirmed_action text, p_actor_type text, p_actor_reference text, p_source text, p_request_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_contract_version constant text := 'v1';
  v_expected_fks constant text[] := array[
    'public.goals(team_id)',
    'public.match_events(team_id)',
    'public.matches(away_team_id)',
    'public.matches(home_team_id)',
    'public.players(team_id)',
    'public.season_teams(team_id)',
    'public.standing_rows(team_id)',
    'public.team_aliases(team_id)',
    'public.team_public_name_audit_events(team_id)'
  ];
  v_actual_fks text[];
  v_team public.teams%rowtype;
  v_country jsonb;
  v_team_snapshot jsonb;
  v_active_aliases jsonb;
  v_inactive_aliases jsonb;
  v_aliases_snapshot jsonb;
  v_dependencies jsonb;
  v_plan jsonb;
  v_response jsonb;
  v_status text;
  v_proposed_action text;
  v_reason_code text;
  v_reason_message text;
  v_fingerprint text;
  v_actor_type text := nullif(pg_catalog.btrim(p_actor_type), '');
  v_actor_reference text := nullif(pg_catalog.btrim(p_actor_reference), '');
  v_source text := nullif(pg_catalog.btrim(p_source), '');
  v_request_reference text := nullif(pg_catalog.btrim(p_request_reference), '');
  v_confirmed_fingerprint text := nullif(pg_catalog.btrim(p_confirmed_preview_fingerprint), '');
  v_confirmed_action text := nullif(pg_catalog.btrim(p_confirmed_action), '');
  v_season_teams_count bigint;
  v_matches_home_count bigint;
  v_matches_away_count bigint;
  v_standing_rows_count bigint;
  v_goals_count bigint;
  v_players_count bigint;
  v_match_events_count bigint;
  v_active_alias_count bigint;
  v_inactive_alias_count bigint;
  v_alias_count bigint;
  v_alias_audit_count bigint;
  v_public_name_audit_count bigint;
  v_blocking_count bigint;
  v_rows_deleted integer;
  v_alias_audit_ids uuid[] := array[]::uuid[];
  v_public_name_audit_ids uuid[] := array[]::uuid[];
  v_deletion_audit_event_id uuid;
begin
  if p_team_id is null then
    raise exception 'invalid_confirmation: team_id_required'
      using errcode = '22023';
  end if;

  if p_apply is null then
    raise exception 'invalid_confirmation: apply_mode_required'
      using errcode = '22023';
  end if;

  if p_apply then
    if v_confirmed_fingerprint is null
       or v_confirmed_fingerprint !~ '^v1:[0-9a-f]{32}$' then
      raise exception 'invalid_confirmation: preview_fingerprint_required'
        using errcode = '22023';
    end if;

    if v_confirmed_action is null
       or v_confirmed_action not in ('delete_team', 'delete_team_and_aliases', 'none') then
      raise exception 'invalid_action'
        using errcode = '22023';
    end if;

    if v_actor_type is null
       or v_actor_reference is null
       or v_source is null
       or v_request_reference is null then
      raise exception 'invalid_confirmation: audit_metadata_required'
        using errcode = '22023';
    end if;

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'team_safe_deletion:v1:' || p_team_id::text,
        0
      )
    );
  elsif v_confirmed_fingerprint is not null or v_confirmed_action is not null then
    raise exception 'invalid_confirmation: preview_must_not_confirm_deletion'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from pg_catalog.pg_constraint c
    where c.contype = 'f'
      and c.confrelid = 'public.teams'::regclass
      and (
        pg_catalog.cardinality(c.conkey) <> 1
        or pg_catalog.cardinality(c.confkey) <> 1
      )
  ) then
    raise exception 'unknown_dependency: composite_team_foreign_key'
      using errcode = '55000';
  end if;

  if exists (
    select 1
    from pg_catalog.pg_trigger t
    where t.tgrelid = 'public.teams'::regclass
      and not t.tgisinternal
  ) then
    raise exception 'unknown_dependency: teams_trigger_requires_review'
      using errcode = '55000';
  end if;

  select coalesce(array_agg(fk.signature order by fk.signature), array[]::text[])
  into v_actual_fks
  from (
    select pg_catalog.format(
      '%I.%I(%I)',
      child_ns.nspname,
      child.relname,
      child_column.attname
    ) as signature
    from pg_catalog.pg_constraint c
    join pg_catalog.pg_class child on child.oid = c.conrelid
    join pg_catalog.pg_namespace child_ns on child_ns.oid = child.relnamespace
    join pg_catalog.pg_attribute child_column
      on child_column.attrelid = c.conrelid
     and child_column.attnum = c.conkey[1]
    join pg_catalog.pg_attribute parent_column
      on parent_column.attrelid = c.confrelid
     and parent_column.attnum = c.confkey[1]
    where c.contype = 'f'
      and c.confrelid = 'public.teams'::regclass
      and parent_column.attname = 'id'
  ) fk;

  if exists (
    select 1
    from unnest(v_actual_fks) actual(signature)
    where not (actual.signature = any(v_expected_fks))
  ) then
    raise exception 'unknown_dependency'
      using errcode = '55000',
            detail = pg_catalog.array_to_string(v_actual_fks, ', ');
  end if;

  if exists (
    select 1
    from unnest(v_expected_fks) expected(signature)
    where not (expected.signature = any(v_actual_fks))
  ) then
    raise exception 'schema_incompatible: expected_team_foreign_key_missing'
      using errcode = '55000',
            detail = pg_catalog.array_to_string(v_actual_fks, ', ');
  end if;

  if p_apply then
    select t.*
    into v_team
    from public.teams t
    where t.id = p_team_id
    for update;
  else
    select t.*
    into v_team
    from public.teams t
    where t.id = p_team_id;
  end if;

  if not found then
    raise exception 'team_not_found'
      using errcode = 'P0002';
  end if;

  if p_apply then
    perform a.id
    from public.team_aliases a
    where a.team_id = p_team_id
    order by a.id
    for update;
  end if;

  if exists (
    select 1
    from public.team_aliases a
    where a.team_id = p_team_id
      and a.status not in ('active', 'inactive')
  ) then
    raise exception 'schema_incompatible: unsupported_alias_status'
      using errcode = '55000';
  end if;

  select pg_catalog.jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'slug', c.slug,
    'iso2', c.iso2
  )
  into v_country
  from public.countries c
  where c.id = v_team.country_id;

  v_team_snapshot := pg_catalog.jsonb_build_object(
    'id', v_team.id,
    'name', v_team.name,
    'public_name', v_team.public_name,
    'short_name', v_team.short_name,
    'code', v_team.code,
    'slug', v_team.slug,
    'country_id', v_team.country_id,
    'country', v_country,
    'logo_url', v_team.logo_url,
    'primary_color', v_team.primary_color
  );

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', a.id,
        'alias', a.alias,
        'normalized_alias', a.normalized_alias,
        'status', a.status
      ) order by a.normalized_alias, a.id
    ),
    '[]'::jsonb
  )
  into v_active_aliases
  from public.team_aliases a
  where a.team_id = p_team_id
    and a.status = 'active';

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', a.id,
        'alias', a.alias,
        'normalized_alias', a.normalized_alias,
        'status', a.status
      ) order by a.normalized_alias, a.id
    ),
    '[]'::jsonb
  )
  into v_inactive_aliases
  from public.team_aliases a
  where a.team_id = p_team_id
    and a.status = 'inactive';

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', a.id,
        'alias', a.alias,
        'normalized_alias', a.normalized_alias,
        'status', a.status
      ) order by a.status, a.normalized_alias, a.id
    ),
    '[]'::jsonb
  )
  into v_aliases_snapshot
  from public.team_aliases a
  where a.team_id = p_team_id;

  select count(*) into v_season_teams_count
  from public.season_teams st where st.team_id = p_team_id;
  select count(*) into v_matches_home_count
  from public.matches m where m.home_team_id = p_team_id;
  select count(*) into v_matches_away_count
  from public.matches m where m.away_team_id = p_team_id;
  select count(*) into v_standing_rows_count
  from public.standing_rows sr where sr.team_id = p_team_id;
  select count(*) into v_goals_count
  from public.goals g where g.team_id = p_team_id;
  select count(*) into v_players_count
  from public.players p where p.team_id = p_team_id;
  select count(*) into v_match_events_count
  from public.match_events me where me.team_id = p_team_id;
  select count(*) filter (where a.status = 'active'),
         count(*) filter (where a.status = 'inactive')
  into v_active_alias_count, v_inactive_alias_count
  from public.team_aliases a
  where a.team_id = p_team_id;

  v_active_alias_count := coalesce(v_active_alias_count, 0);
  v_inactive_alias_count := coalesce(v_inactive_alias_count, 0);
  v_alias_count := v_active_alias_count + v_inactive_alias_count;

  select count(*), coalesce(array_agg(e.id order by e.id), array[]::uuid[])
  into v_alias_audit_count, v_alias_audit_ids
  from public.team_alias_audit_events e
  join public.team_aliases a on a.id = e.team_alias_id
  where a.team_id = p_team_id;

  select count(*), coalesce(array_agg(e.id order by e.id), array[]::uuid[])
  into v_public_name_audit_count, v_public_name_audit_ids
  from public.team_public_name_audit_events e
  where e.team_id = p_team_id;

  v_blocking_count :=
    v_season_teams_count +
    v_matches_home_count +
    v_matches_away_count +
    v_standing_rows_count +
    v_goals_count +
    v_players_count +
    v_match_events_count;

  v_dependencies := pg_catalog.jsonb_build_array(
    pg_catalog.jsonb_build_object('key', 'season_teams', 'table', 'season_teams', 'column', 'team_id', 'count', v_season_teams_count, 'blocking', true, 'reason', 'O clube participa em epocas.'),
    pg_catalog.jsonb_build_object('key', 'matches_home', 'table', 'matches', 'column', 'home_team_id', 'count', v_matches_home_count, 'blocking', true, 'reason', 'O clube participa em jogos como equipa da casa.'),
    pg_catalog.jsonb_build_object('key', 'matches_away', 'table', 'matches', 'column', 'away_team_id', 'count', v_matches_away_count, 'blocking', true, 'reason', 'O clube participa em jogos como equipa visitante.'),
    pg_catalog.jsonb_build_object('key', 'standing_rows', 'table', 'standing_rows', 'column', 'team_id', 'count', v_standing_rows_count, 'blocking', true, 'reason', 'O clube tem classificacoes.'),
    pg_catalog.jsonb_build_object('key', 'goals', 'table', 'goals', 'column', 'team_id', 'count', v_goals_count, 'blocking', true, 'reason', 'O clube tem golos registados.'),
    pg_catalog.jsonb_build_object('key', 'players', 'table', 'players', 'column', 'team_id', 'count', v_players_count, 'blocking', true, 'reason', 'O clube tem jogadores associados.'),
    pg_catalog.jsonb_build_object('key', 'match_events', 'table', 'match_events', 'column', 'team_id', 'count', v_match_events_count, 'blocking', true, 'reason', 'O clube tem eventos de jogo associados.'),
    pg_catalog.jsonb_build_object('key', 'aliases_active', 'table', 'team_aliases', 'column', 'team_id', 'count', v_active_alias_count, 'blocking', false, 'reason', 'Aliases ativos serao removidos na mesma transacao.'),
    pg_catalog.jsonb_build_object('key', 'aliases_inactive', 'table', 'team_aliases', 'column', 'team_id', 'count', v_inactive_alias_count, 'blocking', false, 'reason', 'Aliases inativos serao removidos na mesma transacao.'),
    pg_catalog.jsonb_build_object('key', 'alias_audit_events', 'table', 'team_alias_audit_events', 'column', 'team_alias_id', 'count', v_alias_audit_count, 'blocking', false, 'reason', 'A auditoria dos aliases sera preservada.'),
    pg_catalog.jsonb_build_object('key', 'public_name_audit_events', 'table', 'team_public_name_audit_events', 'column', 'team_id', 'count', v_public_name_audit_count, 'blocking', false, 'reason', 'A auditoria de nomes publicos sera preservada.')
  );

  if v_blocking_count > 0 then
    v_status := 'blocked';
    v_proposed_action := 'none';
    v_reason_code := 'blocking_dependencies_found';
    v_reason_message := 'O clube nao pode ser removido porque tem dependencias estruturais.';
  elsif v_alias_count > 0 then
    v_status := 'removable_with_aliases';
    v_proposed_action := 'delete_team_and_aliases';
    v_reason_code := 'aliases_will_be_deleted';
    v_reason_message := 'O clube pode ser removido juntamente com os aliases ativos e inativos.';
  else
    v_status := 'removable';
    v_proposed_action := 'delete_team';
    v_reason_code := 'no_blocking_dependencies';
    v_reason_message := 'O clube nao tem dependencias bloqueantes e pode ser removido.';
  end if;

  v_plan := pg_catalog.jsonb_build_object(
    'contract_version', v_contract_version,
    'team', v_team_snapshot,
    'aliases', v_aliases_snapshot,
    'dependencies', v_dependencies,
    'status', v_status,
    'proposed_action', v_proposed_action
  );
  v_fingerprint := 'v1:' || pg_catalog.md5(v_plan::text);

  v_response := pg_catalog.jsonb_build_object(
    'contract_version', v_contract_version,
    'mode', case when p_apply then 'apply' else 'preview' end,
    'applied', false,
    'team_id', v_team.id,
    'name', v_team.name,
    'public_name', v_team.public_name,
    'short_name', v_team.short_name,
    'code', v_team.code,
    'slug', v_team.slug,
    'country', v_country,
    'active_aliases', v_active_aliases,
    'inactive_aliases', v_inactive_aliases,
    'alias_count', v_alias_count,
    'alias_audit_count', v_alias_audit_count,
    'public_name_audit_count', v_public_name_audit_count,
    'dependencies', v_dependencies,
    'status', v_status,
    'can_delete', v_status <> 'blocked',
    'proposed_action', v_proposed_action,
    'reason_code', v_reason_code,
    'reason_message', v_reason_message,
    'preview_fingerprint', v_fingerprint,
    'deleted_team_id', null,
    'aliases_deleted_count', 0,
    'alias_audit_events_preserved_count', 0,
    'public_name_audit_events_preserved_count', 0,
    'deletion_audit_event_id', null
  );

  if not p_apply then
    return v_response;
  end if;

  if v_confirmed_fingerprint <> v_fingerprint then
    raise exception 'preview_stale'
      using errcode = '40001',
            detail = pg_catalog.format(
              'confirmed=%s recalculated=%s',
              v_confirmed_fingerprint,
              v_fingerprint
            );
  end if;

  if v_confirmed_action <> v_proposed_action then
    raise exception 'invalid_confirmation'
      using errcode = '22023',
            detail = pg_catalog.format(
              'confirmed=%s proposed=%s',
              v_confirmed_action,
              v_proposed_action
            );
  end if;

  if v_status = 'blocked' then
    return v_response;
  end if;

  insert into public.team_deletion_audit_events (
    deleted_team_id,
    team_snapshot,
    aliases_snapshot,
    dependency_snapshot,
    confirmed_action,
    confirmed_preview_fingerprint,
    actor_type,
    actor_reference,
    source,
    request_reference,
    contract_version
  ) values (
    v_team.id,
    v_team_snapshot,
    v_aliases_snapshot,
    v_dependencies,
    v_confirmed_action,
    v_fingerprint,
    v_actor_type,
    v_actor_reference,
    v_source,
    v_request_reference,
    v_contract_version
  )
  returning id into v_deletion_audit_event_id;

  if v_status = 'removable_with_aliases' then
    delete from public.team_aliases a
    where a.team_id = p_team_id;

    get diagnostics v_rows_deleted = row_count;
    if v_rows_deleted <> v_alias_count then
      raise exception 'schema_incompatible: alias_delete_count_mismatch'
        using errcode = '55000';
    end if;
  end if;

  delete from public.teams t
  where t.id = p_team_id;

  get diagnostics v_rows_deleted = row_count;
  if v_rows_deleted <> 1 then
    raise exception 'schema_incompatible: team_delete_count_mismatch'
      using errcode = '55000';
  end if;

  if exists (
    select 1
    from unnest(v_alias_audit_ids) expected(id)
    where not exists (
      select 1
      from public.team_alias_audit_events e
      where e.id = expected.id
        and e.team_alias_id is null
    )
  ) then
    raise exception 'schema_incompatible: alias_audit_not_preserved'
      using errcode = '55000';
  end if;

  if exists (
    select 1
    from unnest(v_public_name_audit_ids) expected(id)
    where not exists (
      select 1
      from public.team_public_name_audit_events e
      where e.id = expected.id
        and e.team_id is null
    )
  ) then
    raise exception 'schema_incompatible: public_name_audit_not_preserved'
      using errcode = '55000';
  end if;

  return v_response || pg_catalog.jsonb_build_object(
    'applied', true,
    'can_delete', false,
    'reason_code', 'team_deleted',
    'reason_message', 'O clube foi removido integralmente.',
    'deleted_team_id', v_team.id,
    'aliases_deleted_count', v_alias_count,
    'alias_audit_events_preserved_count', v_alias_audit_count,
    'public_name_audit_events_preserved_count', v_public_name_audit_count,
    'deletion_audit_event_id', v_deletion_audit_event_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.match_video_summary_consume_automation_token_v1(p_token text)
 RETURNS TABLE(authorized boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hash text;
  v_deleted bigint := 0;
begin
  if p_token is null or p_token !~ '^[0-9a-f]{64}$' then
    return query select false;
    return;
  end if;

  v_hash := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(p_token, 'UTF8'), 'sha256'),
    'hex'
  );

  delete from jornada_private.match_video_summary_automation_tokens as token_row
  where token_row.token_hash = v_hash
    and token_row.expires_at >= pg_catalog.statement_timestamp();
  get diagnostics v_deleted = row_count;

  delete from jornada_private.match_video_summary_automation_tokens as token_row
  where token_row.expires_at < pg_catalog.statement_timestamp();

  return query select v_deleted = 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.matchday_editorial_profile_reconcile_token(p_matchday_id uuid, p_profile_key text)
 RETURNS TABLE(state_token text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cache_enabled boolean :=
    pg_catalog.current_setting(
      'jornada.thematic_apply_token_cache_mode',
      true
    ) = 'v10';
  v_token text;
begin
  if v_cache_enabled then
    v_token := nullif(
      pg_catalog.current_setting(
        'jornada.thematic_reconcile_token_cache',
        true
      ),
      ''
    );

    if v_token is not null then
      return query select v_token;
      return;
    end if;
  end if;

  select token_row.state_token
  into v_token
  from public.matchday_editorial_profile_reconcile_token_uncached(
    p_matchday_id,
    p_profile_key
  ) as token_row;

  if v_cache_enabled then
    perform pg_catalog.set_config(
      'jornada.thematic_reconcile_token_cache',
      v_token,
      true
    );
  end if;

  return query select v_token;
end;
$function$

CREATE OR REPLACE FUNCTION public.matchday_editorial_profile_workspace_sources(p_matchday_id uuid)
 RETURNS TABLE(source_type text, source_id text, automatic_eligible boolean, continuity_source_matchday_id uuid, continuity_source_composition_id uuid, is_continuity boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cache_enabled boolean :=
    pg_catalog.current_setting(
      'jornada.thematic_apply_token_cache_mode',
      true
    ) = 'v10';

  v_cached_matchday_id text;
  v_cached_sources text;
begin
  if v_cache_enabled then
    v_cached_matchday_id := nullif(
      pg_catalog.current_setting(
        'jornada.thematic_workspace_sources_cache_matchday',
        true
      ),
      ''
    );

    v_cached_sources := nullif(
      pg_catalog.current_setting(
        'jornada.thematic_workspace_sources_cache',
        true
      ),
      ''
    );

    if v_cached_matchday_id = p_matchday_id::text
      and v_cached_sources is not null
    then
      return query
      select
        cached_row.source_type,
        cached_row.source_id,
        cached_row.automatic_eligible,
        cached_row.continuity_source_matchday_id,
        cached_row.continuity_source_composition_id,
        cached_row.is_continuity
      from pg_catalog.jsonb_to_recordset(
        v_cached_sources::jsonb
      ) as cached_row(
        source_type text,
        source_id text,
        automatic_eligible boolean,
        continuity_source_matchday_id uuid,
        continuity_source_composition_id uuid,
        is_continuity boolean
      )
      order by cached_row.source_type, cached_row.source_id;

      return;
    end if;
  end if;

  if v_cache_enabled then
    select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(source_row)
        order by source_row.source_type, source_row.source_id
      ),
      '[]'::jsonb
    )::text
    into v_cached_sources
    from public.matchday_editorial_profile_workspace_sources_uncached(
      p_matchday_id
    ) as source_row;

    perform pg_catalog.set_config(
      'jornada.thematic_workspace_sources_cache_matchday',
      p_matchday_id::text,
      true
    );

    perform pg_catalog.set_config(
      'jornada.thematic_workspace_sources_cache',
      v_cached_sources,
      true
    );

    return query
    select
      cached_row.source_type,
      cached_row.source_id,
      cached_row.automatic_eligible,
      cached_row.continuity_source_matchday_id,
      cached_row.continuity_source_composition_id,
      cached_row.is_continuity
    from pg_catalog.jsonb_to_recordset(
      v_cached_sources::jsonb
    ) as cached_row(
      source_type text,
      source_id text,
      automatic_eligible boolean,
      continuity_source_matchday_id uuid,
      continuity_source_composition_id uuid,
      is_continuity boolean
    )
    order by cached_row.source_type, cached_row.source_id;

    return;
  end if;

  return query
  select *
  from public.matchday_editorial_profile_workspace_sources_uncached(
    p_matchday_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.matchday_editorial_profile_workspace_token(p_matchday_id uuid, p_profile_key text)
 RETURNS TABLE(state_token text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cache_enabled boolean := pg_catalog.current_setting('jornada.thematic_apply_token_cache_mode', true) = 'v10';
  v_token text;
begin
  if exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = p_matchday_id
  ) then
    return query
    select physical_row.state_token
    from public.matchday_editorial_profile_workspace_token_v13(p_matchday_id, p_profile_key) as physical_row;
    return;
  end if;

  if v_cache_enabled then
    v_token := nullif(pg_catalog.current_setting('jornada.thematic_workspace_token_cache', true), '');
    if v_token is not null then
      return query select v_token;
      return;
    end if;
  end if;

  select token_row.state_token
  into v_token
  from public.matchday_editorial_profile_workspace_token_uncached(p_matchday_id, p_profile_key) as token_row;

  if v_cache_enabled then
    perform pg_catalog.set_config('jornada.thematic_workspace_token_cache', v_token, true);
  end if;

  return query select v_token;
end;
$function$

CREATE OR REPLACE FUNCTION public.matchday_live_layout_single_placement_authority_v15(p_matchday_id uuid)
 RETURNS TABLE(is_physical boolean, profile_key text, state_token text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_profile_key text;
  v_has_marker boolean;
begin
  if p_matchday_id is null then
    raise exception 'matchday-live-layout-single-v15-invalid-matchday';
  end if;

  select marker_row.profile_key
  into v_profile_key
  from jornada_private.matchday_live_layout_physical_cutovers as marker_row
  where marker_row.matchday_id = p_matchday_id;

  v_has_marker := v_profile_key is not null;

  if v_has_marker and (
    not exists (
      select 1
      from public.matchday_editorial_profile_assignments as assignment_row
      where assignment_row.matchday_id = p_matchday_id
        and assignment_row.profile_key = v_profile_key
    )
    or not exists (
      select 1
      from public.matchday_live_layout_workspace_settings as settings_row
      where settings_row.matchday_id = p_matchday_id
    )
  ) then
    raise exception 'matchday-live-layout-single-v15-physical-state-incoherent';
  end if;

  return query
  select
    v_has_marker,
    v_profile_key,
    case when v_has_marker then (
      select token_row.state_token
      from public.matchday_editorial_profile_workspace_token_v13(
        p_matchday_id,
        v_profile_key
      ) as token_row
    ) else null end;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_abandon_mesa_production_v2(p_dossier_id uuid)
 RETURNS TABLE(abandonment_action text, restored_theme_membership_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_publications integer; v_removed integer:=0; v_snapshot jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-abandon:'||p_dossier_id::text,0));
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id=p_dossier_id for update;
  if not found then raise exception 'mesa-production-not-found'; end if;
  if v_context.workspace_state='consolidated' then raise exception 'mesa-production-already-published'; end if;
  if v_context.workspace_state='abandoned' then return query select 'reused'::text,0; return; end if;
  select publication_count into v_publications
    from public.newsroom_preview_abandon_mesa_production_v2(p_dossier_id);
  if v_publications>0 then raise exception 'mesa-production-already-published'; end if;
  select jsonb_build_object(
    'context',to_jsonb(v_context),
    'themeMemberships',removable_theme_memberships,
    'capturedAt',now()
  ) into v_snapshot from public.newsroom_preview_abandon_mesa_production_v2(p_dossier_id);
  delete from public.newsroom_editorial_theme_sources m
    where m.theme_id=v_context.theme_id and m.added_at=v_context.created_at
      and exists(select 1 from jsonb_array_elements(v_context.source_refs) r
        where lower(r->>'newsroomArticleId')=m.newsroom_article_id::text)
      and not exists(select 1 from public.newsroom_mesa_theme_materials tm
        join public.newsroom_mesa_version_source_refs vs on vs.version_id=tm.version_id
        where tm.theme_id=m.theme_id and vs.newsroom_article_id=m.newsroom_article_id);
  get diagnostics v_removed=row_count;
  update public.newsroom_mesa_production_contexts set
    workspace_role='technical',workspace_state='abandoned',abandoned_at=now(),
    consolidated_at=null,abandonment_snapshot=v_snapshot
    where dossier_id=p_dossier_id;
  return query select 'abandoned'::text,v_removed;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_activate_editorial_profile_version(p_profile_id uuid, p_version_id uuid, p_expected_active_version_id uuid, p_event_type text, p_reason text, p_created_by_actor_type text, p_created_by_actor_id text)
 RETURNS TABLE(activation_event_id uuid, previous_version_id uuid, active_version_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_profile public.newsroom_editorial_profiles%rowtype;
  v_current_number integer;
  v_target_number integer;
  v_event_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_profile_id is null
     or p_version_id is null
     or p_expected_active_version_id is null
     or p_event_type not in ('activate', 'rollback')
     or p_created_by_actor_type <> 'admin_session'
     or (
       p_reason is not null
       and (btrim(p_reason) = '' or char_length(btrim(p_reason)) > 1000)
     )
     or (
       p_created_by_actor_id is not null
       and (
         btrim(p_created_by_actor_id) = ''
         or char_length(p_created_by_actor_id) > 180
       )
     ) then
    raise exception 'editorial_profile_activation_input_invalid'
      using errcode = '23514';
  end if;

  select profile_row.*
  into v_profile
  from public.newsroom_editorial_profiles profile_row
  where profile_row.id = p_profile_id
  for update;

  if not found then
    raise exception 'editorial_profile_not_found'
      using errcode = 'P0002';
  end if;

  if v_profile.active_version_id is distinct from p_expected_active_version_id then
    raise exception 'editorial_profile_active_conflict'
      using errcode = '40001';
  end if;

  if v_profile.active_version_id = p_version_id then
    raise exception 'editorial_profile_version_already_active'
      using errcode = '23505';
  end if;

  select version_row.version_number
  into v_target_number
  from public.newsroom_editorial_profile_versions version_row
  where version_row.profile_id = p_profile_id
    and version_row.id = p_version_id;

  if not found then
    raise exception 'editorial_profile_version_not_found'
      using errcode = 'P0002';
  end if;

  select version_row.version_number
  into v_current_number
  from public.newsroom_editorial_profile_versions version_row
  where version_row.profile_id = p_profile_id
    and version_row.id = v_profile.active_version_id;

  if (p_event_type = 'rollback' and v_target_number >= v_current_number)
     or (p_event_type = 'activate' and v_target_number <= v_current_number) then
    raise exception 'editorial_profile_activation_direction_invalid'
      using errcode = '23514';
  end if;

  insert into public.newsroom_editorial_profile_activation_events (
    id,
    profile_id,
    previous_version_id,
    activated_version_id,
    event_type,
    reason,
    created_by_actor_type,
    created_by_actor_id
  ) values (
    v_event_id,
    p_profile_id,
    v_profile.active_version_id,
    p_version_id,
    p_event_type,
    nullif(btrim(coalesce(p_reason, '')), ''),
    p_created_by_actor_type,
    nullif(btrim(coalesce(p_created_by_actor_id, '')), '')
  );

  update public.newsroom_editorial_profiles profile_row
  set active_version_id = p_version_id
  where profile_row.id = p_profile_id
    and profile_row.active_version_id = p_expected_active_version_id;

  if not found then
    raise exception 'editorial_profile_active_conflict'
      using errcode = '40001';
  end if;

  return query
  select v_event_id, v_profile.active_version_id, p_version_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_apply_editorial_review(p_action text, p_items jsonb)
 RETURNS TABLE(applied_action text, review_batch_id uuid, affected_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_item jsonb;
  v_article_id uuid;
  v_snapshot_id uuid;
  v_batch_id uuid;
  v_count integer := 0;
  v_decision text;
begin
  if v_action not in ('working', 'seen', 'dismissed', 'reopen', 'close_block')
     or p_items is null
     or jsonb_typeof(p_items) <> 'array'
     or jsonb_array_length(p_items) < 1
     or jsonb_array_length(p_items) > 100
     or (v_action <> 'close_block' and jsonb_array_length(p_items) <> 1) then
    raise exception 'input_invalid' using errcode = 'P0001';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_items) item(value)
    where jsonb_typeof(item.value) <> 'object'
       or not (item.value ? 'articleId')
       or not (item.value ? 'snapshotId')
       or jsonb_typeof(item.value -> 'articleId') <> 'string'
       or jsonb_typeof(item.value -> 'snapshotId') <> 'string'
       or item.value ->> 'articleId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or item.value ->> 'snapshotId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  ) or exists (
    select 1
    from jsonb_array_elements(p_items) item(value)
    group by lower(item.value ->> 'articleId')
    having count(*) > 1
  ) then
    raise exception 'input_invalid' using errcode = 'P0001';
  end if;

  if v_action = 'close_block' then
    insert into public.newsroom_editorial_review_batches default values
    returning id into v_batch_id;
  end if;

  for v_item in
    select value
    from jsonb_array_elements(p_items)
  loop
    v_article_id := (v_item ->> 'articleId')::uuid;
    v_snapshot_id := (v_item ->> 'snapshotId')::uuid;

    if not exists (
      select 1
      from public.newsroom_article_snapshots snapshot
      where snapshot.article_id = v_article_id
        and snapshot.id = v_snapshot_id
        and not exists (
          select 1
          from public.newsroom_article_snapshots newer
          where newer.article_id = snapshot.article_id
            and (newer.extracted_at, newer.created_at, newer.id)
              > (snapshot.extracted_at, snapshot.created_at, snapshot.id)
        )
    ) then
      raise exception 'snapshot_stale' using errcode = 'P0001';
    end if;

    if v_action = 'reopen' then
      delete from public.newsroom_editorial_review_states state
      where state.newsroom_article_id = v_article_id;
    else
      v_decision := case
        when v_action = 'close_block' then 'seen'
        else v_action
      end;

      insert into public.newsroom_editorial_review_states (
        newsroom_article_id,
        decision,
        reviewed_snapshot_id,
        reviewed_at,
        last_batch_id
      ) values (
        v_article_id,
        v_decision,
        v_snapshot_id,
        now(),
        v_batch_id
      )
      on conflict (newsroom_article_id) do update
      set
        decision = excluded.decision,
        reviewed_snapshot_id = excluded.reviewed_snapshot_id,
        reviewed_at = excluded.reviewed_at,
        last_batch_id = excluded.last_batch_id;

      if v_action = 'close_block' then
        insert into public.newsroom_editorial_review_batch_items (
          batch_id,
          newsroom_article_id,
          snapshot_id,
          decision
        ) values (
          v_batch_id,
          v_article_id,
          v_snapshot_id,
          'seen'
        );
      end if;
    end if;

    v_count := v_count + 1;
  end loop;

  if v_batch_id is not null then
    update public.newsroom_editorial_review_batches batch
    set item_count = v_count
    where batch.id = v_batch_id;
  end if;

  return query
  select v_action, v_batch_id, v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_apply_generated_article(p_dossier_id uuid, p_article_plan_id uuid, p_editorial_article_id uuid, p_expected_article_updated_at timestamp with time zone, p_generated_title text, p_generated_post_title text, p_image_url text, p_generated_body text, p_provider text, p_model text, p_prompt_version text, p_provider_response_id text, p_input_hash text, p_input_snapshot jsonb, p_input_tokens integer, p_output_tokens integer, p_total_tokens integer)
 RETURNS TABLE(generation_id uuid, editorial_article_id uuid, generation_action text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_result record;
  v_title text := btrim(coalesce(p_generated_title, ''));
  v_post_title text := btrim(coalesce(p_generated_post_title, ''));
begin
  if char_length(v_title) not between 8 and 180 then
    raise exception 'editorial_generation_title_invalid'
      using errcode = '23514';
  end if;

  if char_length(v_post_title) not between 20 and 600 then
    raise exception 'editorial_generation_post_title_invalid'
      using errcode = '23514';
  end if;

  if p_image_url is not null and btrim(p_image_url) <> '' then
    raise exception 'editorial_generation_image_must_be_selected_manually'
      using errcode = '23514';
  end if;

  select result.*
  into v_result
  from public.newsroom_apply_editorial_dossier_article_plan_generation(
    p_dossier_id,
    p_article_plan_id,
    p_editorial_article_id,
    p_expected_article_updated_at,
    p_generated_body,
    p_provider,
    p_model,
    p_prompt_version,
    p_provider_response_id,
    p_input_hash,
    p_input_snapshot,
    p_input_tokens,
    p_output_tokens,
    p_total_tokens
  ) as result;

  if v_result.generation_action = 'applied' then
    update public.editorial_articles as article
    set title = v_title,
        subtitle = v_post_title,
        updated_at = now()
    where article.id = p_editorial_article_id
      and article.status = 'draft'
      and btrim(coalesce(article.body, '')) = btrim(coalesce(p_generated_body, ''));

    if not found then
      raise exception 'editorial_generation_complete_article_conflict'
        using errcode = '55000';
    end if;
  end if;

  return query
  select
    v_result.generation_id,
    v_result.editorial_article_id,
    v_result.generation_action;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_apply_output_classification_to_bank_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_matchday_id uuid;
  v_bank_item_id uuid;
begin
  select article_row.matchday_id
  into v_matchday_id
  from public.editorial_articles as article_row
  where article_row.id = new.editorial_article_id
  for share;

  if v_matchday_id is null then
    return new;
  end if;

  select bank_row.id
  into v_bank_item_id
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.matchday_id = v_matchday_id
    and pg_catalog.lower(pg_catalog.btrim(bank_row.source_type))
      = 'editorial_article'
    and pg_catalog.lower(pg_catalog.btrim(bank_row.source_id))
      = new.editorial_article_id::text
  order by bank_row.created_at, bank_row.id
  limit 1
  for update;

  if v_bank_item_id is null then
    raise exception 'article_plan_classification_bank_item_missing'
      using errcode = '23514';
  end if;

  perform jornada_private.authorize_matchday_editorial_bank_classification_writes(
    array[v_bank_item_id]
  );
  begin
    update public.matchday_editorial_bank_items as bank_row
    set classification_key = new.classification_key,
        classification_source = 'manual',
        classified_at = pg_catalog.statement_timestamp(),
        automatic_eligible = false
    where bank_row.id = v_bank_item_id;

    perform jornada_private.revoke_matchday_editorial_bank_classification_writes(
      array[v_bank_item_id]
    );
  exception when others then
    perform jornada_private.revoke_matchday_editorial_bank_classification_writes(
      array[v_bank_item_id]
    );
    raise;
  end;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_assert_mesa_context_item_sources_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_dossier_id uuid;
  v_context_id uuid;
begin
  if tg_table_name = 'newsroom_mesa_production_context_items' then
    v_dossier_id := new.dossier_id;
    v_context_id := new.id;
  else
    v_dossier_id := new.dossier_id;
    v_context_id := new.production_context_id;
  end if;
  if not coalesce(public.newsroom_mesa_context_item_sources_valid_v1(v_dossier_id, v_context_id), false) then
    raise exception 'mesa-production-context-source-set-invalid' using errcode = '23514';
  end if;
  return null;
end;
$function$

