CREATE OR REPLACE FUNCTION public.newsroom_assert_mesa_plan_context_sources_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_dossier_id uuid;
  v_article_plan_id uuid;
  v_assignment public.newsroom_mesa_article_plan_contexts%rowtype;
begin
  v_dossier_id := case when tg_op = 'DELETE' then old.dossier_id else new.dossier_id end;
  v_article_plan_id := case when tg_op = 'DELETE' then old.article_plan_id else new.article_plan_id end;
  for v_assignment in
    select assignment.* from public.newsroom_mesa_article_plan_contexts assignment
    where assignment.dossier_id = v_dossier_id and assignment.article_plan_id = v_article_plan_id
  loop
