      raise exception 'mesa-article-plan-context-sources-invalid' using errcode = '23514';
    end if;
  end loop;
  if tg_op = 'UPDATE' and (
    old.dossier_id is distinct from new.dossier_id
    or old.article_plan_id is distinct from new.article_plan_id
  ) then
    for v_assignment in
      select assignment.* from public.newsroom_mesa_article_plan_contexts assignment
      where assignment.dossier_id = old.dossier_id and assignment.article_plan_id = old.article_plan_id
    loop
      if not public.newsroom_mesa_plan_context_sources_valid_v1(v_assignment.dossier_id, v_assignment.article_plan_id, v_assignment.production_context_id) then
        raise exception 'mesa-article-plan-context-sources-invalid' using errcode = '23514';
      end if;
    end loop;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_assign_mesa_article_plan_context_v1(p_dossier_id uuid, p_article_plan_id uuid, p_production_context_id uuid)
 RETURNS TABLE(assignment_action text, context_source_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.newsroom_mesa_article_plan_contexts%rowtype;
  v_source_count integer;
begin
  if p_dossier_id is null or p_article_plan_id is null or p_production_context_id is null then
    raise exception 'mesa-article-plan-context-input-invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-plan-context:' || p_dossier_id::text || ':' || p_article_plan_id::text,0));
  perform 1
  from public.newsroom_mesa_production_contexts workspace
  where workspace.dossier_id = p_dossier_id
    and workspace.workspace_role = 'technical'
    and workspace.workspace_contract_version = 2
    and workspace.workspace_state = 'active'
  for update;
  if not found then raise exception 'mesa-article-plan-context-workspace-invalid'; end if;
  perform 1
  from public.newsroom_editorial_dossier_article_plans plan
  where plan.dossier_id = p_dossier_id
    and plan.id = p_article_plan_id
    and plan.status <> 'cancelled'
    and plan.editorial_article_id is null
  for update;
  if not found then raise exception 'mesa-article-plan-context-plan-invalid'; end if;
  select count(*)::integer into v_source_count
  from public.newsroom_mesa_production_context_sources context_source
  where context_source.dossier_id = p_dossier_id
    and context_source.production_context_id = p_production_context_id;
  if v_source_count < 1
    or not public.newsroom_mesa_plan_context_sources_valid_v1(p_dossier_id,p_article_plan_id,p_production_context_id) then
    raise exception 'mesa-article-plan-context-sources-invalid';
  end if;
  select assignment.* into v_existing
  from public.newsroom_mesa_article_plan_contexts assignment
  where assignment.dossier_id = p_dossier_id and assignment.article_plan_id = p_article_plan_id
  for update;
  if found then
    if v_existing.production_context_id = p_production_context_id then
      return query select 'reused'::text,v_source_count;
      return;
    end if;
    update public.newsroom_mesa_article_plan_contexts assignment
    set production_context_id = p_production_context_id, assigned_at = now()
    where assignment.dossier_id = p_dossier_id and assignment.article_plan_id = p_article_plan_id;
    return query select 'updated'::text,v_source_count;
    return;
  end if;
  insert into public.newsroom_mesa_article_plan_contexts(dossier_id,article_plan_id,production_context_id)
  values(p_dossier_id,p_article_plan_id,p_production_context_id);
  return query select 'created'::text,v_source_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_attach_dossier_to_theme_v1(p_dossier_id uuid, p_theme_id uuid)
 RETURNS TABLE(dossier_id uuid, theme_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing uuid;
  v_source_id uuid;
begin
  if p_dossier_id is null or p_theme_id is null then
    raise exception 'mesa-organization-invalid-input';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('newsroom-mesa-organization-v1', 0));
  perform 1 from public.newsroom_editorial_themes t where t.id = p_theme_id and t.status = 'open' for update;
  if not found then raise exception 'mesa-organization-theme-unavailable'; end if;
  perform 1 from public.newsroom_editorial_dossiers d where d.id = p_dossier_id for update;
  if not found then raise exception 'mesa-organization-dossier-not-found'; end if;
  select m.theme_id into v_existing from public.newsroom_editorial_theme_dossiers m
    where m.dossier_id = p_dossier_id;
  if found and v_existing <> p_theme_id then
    raise exception 'mesa-organization-dossier-already-linked';
  end if;
  insert into public.newsroom_editorial_theme_dossiers(dossier_id,theme_id)
    values(p_dossier_id,p_theme_id) on conflict on constraint newsroom_editorial_theme_dossiers_pkey do nothing;
  for v_source_id in
    select distinct s.newsroom_article_id from public.newsroom_editorial_dossier_sources s
    where s.dossier_id = p_dossier_id and s.included
  loop
    perform public.newsroom_set_editorial_theme_source_membership_v1(p_theme_id,v_source_id,true);
  end loop;
  return query select p_dossier_id,p_theme_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_change_mesa_new_output_groups_v2(p_dossier_id uuid, p_action text, p_group_ids uuid[], p_target_count integer, p_theme_id uuid, p_expected_revision integer, p_command_id uuid)
 RETURNS TABLE(revision integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_header public.newsroom_mesa_new_output_groupings%rowtype;
  v_command public.newsroom_mesa_new_output_grouping_commands%rowtype;
  v_fingerprint text;
  v_keep uuid;
  v_source record;
  v_position integer;
  v_new_group uuid;
  v_current_count integer;
  v_add_index integer;
  v_theme public.newsroom_mesa_new_output_theme_targets%rowtype;
  v_total_after integer;
begin
  if p_dossier_id is null or p_command_id is null
    or p_action not in ('target','theme_target','merge','split')
    or p_expected_revision is null or p_expected_revision < 1
    or p_group_ids is null or array_position(p_group_ids,null) is not null
    or (select count(distinct id) from unnest(p_group_ids) id)<>cardinality(p_group_ids)
  then raise exception 'mesa-grouping-change-input-invalid'; end if;
  v_fingerprint := encode(sha256(convert_to(jsonb_build_object(
    'action',p_action,'groupIds',p_group_ids,'targetCount',p_target_count,
    'themeId',p_theme_id,'expectedRevision',p_expected_revision
  )::text,'UTF8')),'hex');
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-new-output-groups:'||p_dossier_id::text,0));
  select * into v_command from public.newsroom_mesa_new_output_grouping_commands
  where dossier_id=p_dossier_id and command_id=p_command_id;
  if found then
    if v_command.payload_fingerprint is distinct from v_fingerprint then
      raise exception 'mesa-grouping-command-conflict';
    end if;
    return query select v_command.result_revision;
    return;
  end if;
  select * into v_header from public.newsroom_mesa_new_output_groupings
  where dossier_id=p_dossier_id for update;
  if not found or v_header.state<>'planned' then raise exception 'mesa-grouping-structure-locked'; end if;
  if v_header.revision<>p_expected_revision then raise exception 'mesa-grouping-revision-stale'; end if;

  if p_action='target' then
    if p_theme_id is not null or cardinality(p_group_ids)<>0 or p_target_count is null
      or p_target_count not between 0 and least(30,cardinality(v_header.loose_source_ids))
    then raise exception 'mesa-grouping-target-invalid'; end if;
    if p_target_count=0 then
      delete from public.newsroom_mesa_new_output_groups
      where dossier_id=p_dossier_id and seed_kind='selection';
    elsif not exists (
      select 1 from public.newsroom_mesa_new_output_groups
      where dossier_id=p_dossier_id and seed_kind='selection'
    ) then
      v_position := coalesce((select max(position) from public.newsroom_mesa_new_output_groups where dossier_id=p_dossier_id),0);
      for v_source in
        select dossier_source.id as dossier_source_id
        from unnest(v_header.loose_source_ids) with ordinality loose(newsroom_article_id,position)
        join public.newsroom_editorial_dossier_sources dossier_source
          on dossier_source.dossier_id=p_dossier_id
          and dossier_source.newsroom_article_id=loose.newsroom_article_id
          and dossier_source.included
        order by loose.position
      loop
        v_position:=v_position+1;
        v_new_group:=gen_random_uuid();
        insert into public.newsroom_mesa_new_output_groups(
          id,dossier_id,production_context_id,seed_kind,seed_theme_id,position
        ) values(v_new_group,p_dossier_id,v_header.production_context_id,'selection',null,v_position);
        insert into public.newsroom_mesa_new_output_group_sources(dossier_id,group_id,dossier_source_id,sort_order)
        values(p_dossier_id,v_new_group,v_source.dossier_source_id,1);
      end loop;
    end if;
    update public.newsroom_mesa_new_output_groupings as grouping
    set target_count=p_target_count,revision=grouping.revision+1,updated_at=clock_timestamp()
    where grouping.dossier_id=p_dossier_id returning grouping.revision into v_position;
  elsif p_action='theme_target' then
    if p_theme_id is null or cardinality(p_group_ids)<>0 or p_target_count is null
      or p_target_count not between 0 and 30
    then raise exception 'mesa-grouping-theme-target-invalid'; end if;
    select * into v_theme from public.newsroom_mesa_new_output_theme_targets
    where dossier_id=p_dossier_id and theme_id=p_theme_id for update;
    if not found then raise exception 'mesa-grouping-theme-invalid'; end if;
    select count(*)::integer into v_current_count
    from public.newsroom_mesa_new_output_groups
    where dossier_id=p_dossier_id and seed_kind='theme' and seed_theme_id=p_theme_id;
    select count(*)::integer - v_current_count + p_target_count into v_total_after
    from public.newsroom_mesa_new_output_groups where dossier_id=p_dossier_id;
    if v_total_after + jsonb_array_length(v_header.existing_outputs) > 30
    then raise exception 'mesa-grouping-output-limit'; end if;
    if p_target_count < v_current_count then
      delete from public.newsroom_mesa_new_output_groups
      where id in (
        select id from public.newsroom_mesa_new_output_groups
        where dossier_id=p_dossier_id and seed_kind='theme' and seed_theme_id=p_theme_id
        order by position desc,id desc limit (v_current_count-p_target_count)
      );
    elsif p_target_count > v_current_count then
      for v_add_index in (v_current_count+1)..p_target_count loop
        v_position:=coalesce((select max(position) from public.newsroom_mesa_new_output_groups where dossier_id=p_dossier_id),0)+1;
        v_new_group:=gen_random_uuid();
        insert into public.newsroom_mesa_new_output_groups(
          id,dossier_id,production_context_id,seed_kind,seed_theme_id,position
        ) values(v_new_group,p_dossier_id,v_header.production_context_id,'theme',p_theme_id,v_position);
        insert into public.newsroom_mesa_new_output_group_sources(dossier_id,group_id,dossier_source_id,sort_order)
        select p_dossier_id,v_new_group,dossier_source.id,seed.position::smallint
        from unnest(v_theme.seed_source_ids) with ordinality seed(newsroom_article_id,position)
        join public.newsroom_editorial_dossier_sources dossier_source
          on dossier_source.dossier_id=p_dossier_id
          and dossier_source.newsroom_article_id=seed.newsroom_article_id
          and dossier_source.included
        order by seed.position;
        if not found then raise exception 'mesa-grouping-theme-source-missing'; end if;
      end loop;
    end if;
    update public.newsroom_mesa_new_output_theme_targets
    set target_count=p_target_count,updated_at=clock_timestamp()
    where dossier_id=p_dossier_id and theme_id=p_theme_id;
    update public.newsroom_mesa_new_output_groupings as grouping
    set revision=grouping.revision+1,updated_at=clock_timestamp()
    where grouping.dossier_id=p_dossier_id returning grouping.revision into v_position;
  else
    if p_target_count is not null or p_theme_id is not null then raise exception 'mesa-grouping-change-input-invalid'; end if;
    if exists(
      select 1 from unnest(p_group_ids) selected(group_id)
      left join public.newsroom_mesa_new_output_groups grouped
        on grouped.id=selected.group_id and grouped.dossier_id=p_dossier_id
        and grouped.state='planned' and grouped.seed_kind='selection'
      where grouped.id is null
    ) then raise exception 'mesa-grouping-group-invalid'; end if;
    if p_action='merge' then
      if cardinality(p_group_ids)<2 then raise exception 'mesa-grouping-merge-invalid'; end if;
      select id into strict v_keep from public.newsroom_mesa_new_output_groups
      where dossier_id=p_dossier_id and id=any(p_group_ids) order by position,id limit 1;
      v_position:=coalesce((select max(sort_order) from public.newsroom_mesa_new_output_group_sources where group_id=v_keep),0);
      for v_source in
        select * from public.newsroom_mesa_new_output_group_sources
        where dossier_id=p_dossier_id and group_id=any(p_group_ids) and group_id<>v_keep
        order by group_id,sort_order
      loop
        v_position:=v_position+1;
        update public.newsroom_mesa_new_output_group_sources
        set group_id=v_keep,sort_order=v_position
        where group_id=v_source.group_id and dossier_source_id=v_source.dossier_source_id;
      end loop;
      delete from public.newsroom_mesa_new_output_groups
      where dossier_id=p_dossier_id and id=any(p_group_ids) and id<>v_keep;
    else
      if cardinality(p_group_ids)<>1
        or (select count(*) from public.newsroom_mesa_new_output_group_sources where group_id=p_group_ids[1])<2
      then raise exception 'mesa-grouping-split-invalid'; end if;
      if (select count(*) from public.newsroom_mesa_new_output_groups where dossier_id=p_dossier_id)
        +(select count(*)-1 from public.newsroom_mesa_new_output_group_sources where group_id=p_group_ids[1])
        +jsonb_array_length(v_header.existing_outputs)>30
      then raise exception 'mesa-grouping-output-limit'; end if;
      select position into strict v_position from public.newsroom_mesa_new_output_groups
      where id=p_group_ids[1] and dossier_id=p_dossier_id;
      for v_source in
        select * from public.newsroom_mesa_new_output_group_sources
        where group_id=p_group_ids[1] order by sort_order offset 1
      loop
        v_new_group:=gen_random_uuid();
        v_position:=v_position+1;
        update public.newsroom_mesa_new_output_groups set position=position+1
        where dossier_id=p_dossier_id and position>=v_position;
        insert into public.newsroom_mesa_new_output_groups(
          id,dossier_id,production_context_id,seed_kind,seed_theme_id,position
        ) values(v_new_group,p_dossier_id,v_header.production_context_id,'selection',null,v_position);
        update public.newsroom_mesa_new_output_group_sources set group_id=v_new_group,sort_order=1
        where group_id=p_group_ids[1] and dossier_source_id=v_source.dossier_source_id;
      end loop;
    end if;
    update public.newsroom_mesa_new_output_groupings as grouping
    set revision=grouping.revision+1,updated_at=clock_timestamp()
    where grouping.dossier_id=p_dossier_id returning grouping.revision into v_position;
  end if;

  with ordered as (
    select grouped.id,row_number() over(order by
      case when grouped.seed_kind='theme' then 0 else 1 end,
      coalesce(target.position,32767),grouped.position,grouped.id
    ) next_position
    from public.newsroom_mesa_new_output_groups grouped
    left join public.newsroom_mesa_new_output_theme_targets target
      on target.dossier_id=grouped.dossier_id and target.theme_id=grouped.seed_theme_id
    where grouped.dossier_id=p_dossier_id
  )
  update public.newsroom_mesa_new_output_groups grouped
  set position=ordered.next_position,updated_at=clock_timestamp()
  from ordered where grouped.id=ordered.id;

  insert into public.newsroom_mesa_new_output_grouping_commands(
    dossier_id,command_id,payload_fingerprint,result_revision
  ) values(p_dossier_id,p_command_id,v_fingerprint,v_position);
  return query select v_position;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_claim_editorial_compose_generation(p_submission_id uuid, p_request_fingerprint text, p_claim_token uuid)
 RETURNS TABLE(claim_action text, editorial_article_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.newsroom_editorial_compose_requests%rowtype;
  v_now timestamptz := now();
begin
  if p_submission_id is null
     or p_claim_token is null
     or p_request_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'compose_generation_claim_input_invalid'
      using errcode = '23514';
  end if;

  select request_row.*
  into v_request
  from public.newsroom_editorial_compose_requests request_row
  where request_row.submission_id = p_submission_id
  for update;

  if not found or v_request.editorial_article_id is null then
    raise exception 'compose_request_not_found'
      using errcode = 'P0002';
  end if;
  if v_request.request_fingerprint <> p_request_fingerprint then
    raise exception 'compose_payload_conflict'
      using errcode = '23505';
  end if;

  if exists (
    select 1
    from public.newsroom_editorial_dossier_article_plan_generations generation
    where generation.article_plan_id = v_request.article_plan_id
      and generation.editorial_article_id = v_request.editorial_article_id
  ) then
    update public.newsroom_editorial_compose_requests request_row
    set generation_status = 'completed',
        generation_claim_token = null,
        generation_claimed_at = null,
        last_error_code = null,
        updated_at = v_now
    where request_row.submission_id = p_submission_id;

    return query select 'completed'::text, v_request.editorial_article_id;
    return;
  end if;

  if v_request.generation_status = 'completed' then
    raise exception 'compose_generation_completed_record_missing'
      using errcode = '55000';
  end if;

  if v_request.generation_status = 'in_progress'
     and v_request.generation_claim_token <> p_claim_token
     and v_request.generation_claimed_at > v_now - interval '2 minutes' then
    return query select 'in_progress'::text, v_request.editorial_article_id;
    return;
  end if;

  update public.newsroom_editorial_compose_requests request_row
  set generation_status = 'in_progress',
      generation_claim_token = p_claim_token,
      generation_claimed_at = v_now,
      last_error_code = null,
      updated_at = v_now
  where request_row.submission_id = p_submission_id;

  return query select 'claimed'::text, v_request.editorial_article_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_clear_article_classification_v1(p_newsroom_article_id uuid)
 RETURNS TABLE(newsroom_article_id uuid, classification_key text, classification_source text, classified_at timestamp with time zone, updated_at timestamp with time zone, classified boolean, applied boolean, changed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row_count bigint := 0;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'newsroom-theme-source-classification-v1',
      0
    )
  );

  if p_newsroom_article_id is null then
    raise exception 'newsroom_article_classification_invalid_input'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.newsroom_articles as article_row
    where article_row.id = p_newsroom_article_id
  )
  then
    raise exception 'newsroom_article_classification_source_not_found'
      using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.newsroom_editorial_theme_sources as membership_row
    where membership_row.newsroom_article_id = p_newsroom_article_id
  )
  then
    raise exception 'newsroom_article_classification_theme_conflict'
      using errcode = '23514';
  end if;

  delete from public.newsroom_editorial_article_classifications
    as classification_row
  where classification_row.newsroom_article_id = p_newsroom_article_id;

  get diagnostics v_row_count = row_count;

  return query
  select
    p_newsroom_article_id,
    null::text,
    null::text,
    null::timestamptz,
    null::timestamptz,
    false,
    true,
    v_row_count > 0;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_consume_automatic_feed_token_v1(p_token text)
 RETURNS TABLE(authorized boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_hash text;
  v_deleted bigint := 0;
begin
  if p_token is null or p_token !~ '^[0-9a-f]{64}$' then
    return query select false;
    return;
  end if;

  v_hash := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(p_token, 'UTF8'), 'sha256'),
    'hex'
  );

  delete from jornada_private.newsroom_automatic_feed_tokens as token_row
  where token_row.token_hash = v_hash
    and token_row.expires_at >= pg_catalog.statement_timestamp();

  get diagnostics v_deleted = row_count;

  delete from jornada_private.newsroom_automatic_feed_tokens as token_row
  where token_row.expires_at < pg_catalog.statement_timestamp();

  return query select v_deleted = 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_create_complete_manual_entry(p_submission_id uuid, p_request_fingerprint text, p_ante_title text, p_title text, p_post_title text, p_author text, p_body jsonb, p_published_date text, p_published_time text, p_image_url text, p_content_hash text)
 RETURNS TABLE(submission_id uuid, request_fingerprint text, newsroom_article_id uuid, newsroom_snapshot_id uuid, entry_action text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.newsroom_manual_entry_requests%rowtype;
  v_article_id uuid;
  v_snapshot_id uuid;
  v_published_date date;
  v_published_time time without time zone;
  v_published_at timestamptz;
  v_now timestamptz := pg_catalog.now();
  v_body_length integer;
  v_source_metadata jsonb;
begin
  if p_submission_id is null
     or p_request_fingerprint is null
     or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or p_ante_title is null
     or btrim(p_ante_title) = ''
     or length(btrim(p_ante_title)) > 240
     or p_title is null
     or btrim(p_title) = ''
     or length(btrim(p_title)) > 180
     or p_post_title is null
     or btrim(p_post_title) = ''
     or length(btrim(p_post_title)) > 600
     or p_author is null
     or btrim(p_author) = ''
     or length(btrim(p_author)) > 200
     or p_body is null
     or jsonb_typeof(p_body) <> 'array'
     or jsonb_array_length(p_body) = 0
     or p_published_date is null
     or p_published_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or p_published_time is null
     or p_published_time !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
     or p_image_url is null
     or btrim(p_image_url) = ''
     or length(p_image_url) > 2048
     or p_image_url !~ '^https?://'
     or p_content_hash is null
     or p_content_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'manual_entry_input_invalid' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_body) body_item(value)
    where jsonb_typeof(body_item.value) is distinct from 'object'
      or jsonb_typeof(body_item.value -> 'type') is distinct from 'string'
      or (body_item.value ->> 'type') is distinct from 'paragraph'
      or jsonb_typeof(body_item.value -> 'text') is distinct from 'string'
      or nullif(btrim(coalesce(body_item.value ->> 'text', '')), '') is null
      or exists (
        select 1
        from jsonb_object_keys(
          case when jsonb_typeof(body_item.value) = 'object'
            then body_item.value else '{}'::jsonb end
        ) body_key(key)
        where body_key.key not in ('type', 'text')
      )
  ) then
    raise exception 'manual_entry_body_invalid' using errcode = '22023';
  end if;

  select coalesce(sum(length(body_item.value ->> 'text')), 0)::integer
  into v_body_length
  from jsonb_array_elements(p_body) body_item(value);

  if v_body_length < 1 or v_body_length > 50000 then
    raise exception 'manual_entry_body_invalid' using errcode = '22023';
  end if;

  begin
    v_published_date := p_published_date::date;
    v_published_time := p_published_time::time;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      raise exception 'manual_entry_published_at_invalid' using errcode = '22007';
  end;

  if to_char(v_published_date, 'YYYY-MM-DD') <> p_published_date
     or to_char(v_published_time, 'HH24:MI') <> p_published_time then
    raise exception 'manual_entry_published_at_invalid' using errcode = '22007';
  end if;

  v_published_at := (
    p_published_date || ' ' || p_published_time
  )::timestamp without time zone at time zone 'Europe/Lisbon';

  if to_char(
       v_published_at at time zone 'Europe/Lisbon',
       'YYYY-MM-DD HH24:MI'
     ) <> (p_published_date || ' ' || p_published_time) then
    raise exception 'manual_entry_published_at_invalid' using errcode = '22007';
  end if;

  if v_published_at > v_now then
    raise exception 'manual_entry_published_at_future' using errcode = '22007';
  end if;

  insert into public.newsroom_manual_entry_requests (
    submission_id,
    request_fingerprint
  ) values (
    p_submission_id,
    p_request_fingerprint
  )
  on conflict on constraint newsroom_manual_entry_requests_pkey do nothing;

  select request_row.*
  into v_request
  from public.newsroom_manual_entry_requests request_row
  where request_row.submission_id = p_submission_id
  for update;

  if not found then
    raise exception 'manual_entry_request_unavailable' using errcode = '55000';
  end if;
  if v_request.request_fingerprint <> p_request_fingerprint then
    raise exception 'manual_entry_payload_conflict' using errcode = 'P0001';
  end if;

  if v_request.newsroom_article_id is not null
     and v_request.newsroom_snapshot_id is not null then
    if not exists (
      select 1
      from public.newsroom_articles article
      join public.newsroom_article_snapshots snapshot
        on snapshot.id = v_request.newsroom_snapshot_id
       and snapshot.article_id = article.id
      where article.id = v_request.newsroom_article_id
        and article.source_code = 'manual_entry'
        and article.title = btrim(p_title)
        and article.subtitle = btrim(p_post_title)
        and article.author = btrim(p_author)
        and article.published_at = v_published_at
        and article.image_url = btrim(p_image_url)
        and snapshot.content_hash = p_content_hash
        and snapshot.source_metadata ->> 'origin' = 'manual'
        and snapshot.source_metadata ->> 'manualSubmissionId' = p_submission_id::text
        and snapshot.source_metadata ->> 'anteTitle' = btrim(p_ante_title)
        and snapshot.source_metadata ->> 'publishedAtPrecision' = 'instant'
    ) then
      raise exception 'manual_entry_request_inconsistent' using errcode = '55000';
    end if;

    return query
    select p_submission_id, p_request_fingerprint,
      v_request.newsroom_article_id, v_request.newsroom_snapshot_id,
      'reused'::text;
    return;
  end if;

  if v_request.newsroom_article_id is not null
     or v_request.newsroom_snapshot_id is not null then
    raise exception 'manual_entry_request_incomplete' using errcode = '55000';
  end if;

  v_article_id := pg_catalog.gen_random_uuid();
  v_snapshot_id := pg_catalog.gen_random_uuid();
  v_source_metadata := jsonb_strip_nulls(jsonb_build_object(
    'origin', 'manual',
    'sourceCode', 'manual_entry',
    'sourceName', 'Entrada manual',
    'manualSubmissionId', p_submission_id::text,
    'anteTitle', btrim(p_ante_title),
    'title', btrim(p_title),
    'postTitle', btrim(p_post_title),
    'author', btrim(p_author),
    'publishedAt', to_char(
      v_published_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    ),
    'publishedAtPrecision', 'instant',
    'imageUrl', btrim(p_image_url),
    'introducedAt', to_char(
      v_now at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    )
  ));

  insert into public.newsroom_articles (
    id, source_code, original_url, normalized_url, external_id,
    title, subtitle, summary, author, published_at, modified_at,
    detected_at, image_url, processing_status, first_detected_at,
    last_detected_at, created_at, updated_at
  ) values (
    v_article_id, 'manual_entry', null, null, null,
    btrim(p_title), btrim(p_post_title), null, btrim(p_author),
    v_published_at, null, v_now, btrim(p_image_url), 'ready_for_review',
    v_now, v_now, v_now, v_now
  );

  insert into public.newsroom_article_snapshots (
    id, article_id, content_hash, body, source_metadata, extracted_at, created_at
  ) values (
    v_snapshot_id, v_article_id, p_content_hash, p_body,
    v_source_metadata, v_now, v_now
  );

  update public.newsroom_manual_entry_requests request_row
  set newsroom_article_id = v_article_id,
      newsroom_snapshot_id = v_snapshot_id
  where request_row.submission_id = p_submission_id;

  return query
  select p_submission_id, p_request_fingerprint,
    v_article_id, v_snapshot_id, 'created'::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_create_editorial_profile_version(p_profile_id uuid, p_based_on_version_id uuid, p_expected_latest_version_number integer, p_document_text text, p_content_hash text, p_change_summary text, p_created_by_actor_type text, p_created_by_actor_id text)
 RETURNS TABLE(version_id uuid, version_number integer, content_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_profile public.newsroom_editorial_profiles%rowtype;
  v_latest_version_number integer;
  v_document_text text;
  v_content_hash text;
  v_version_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_profile_id is null
     or p_expected_latest_version_number is null
     or p_expected_latest_version_number < 1
     or p_created_by_actor_type <> 'admin_session'
     or (
       p_created_by_actor_id is not null
       and (
         btrim(p_created_by_actor_id) = ''
         or char_length(p_created_by_actor_id) > 180
       )
     ) then
    raise exception 'editorial_profile_version_input_invalid'
      using errcode = '23514';
  end if;

  v_document_text := btrim(
    replace(replace(coalesce(p_document_text, ''), E'\r\n', E'\n'), E'\r', E'\n')
  );
  if v_document_text = ''
     or char_length(v_document_text) > 20000
     or btrim(coalesce(p_change_summary, '')) = ''
     or char_length(btrim(p_change_summary)) > 1000 then
    raise exception 'editorial_profile_version_input_invalid'
      using errcode = '23514';
  end if;

  v_content_hash := encode(
    extensions.digest(convert_to(v_document_text, 'UTF8'), 'sha256'),
    'hex'
  );
  if p_content_hash is distinct from v_content_hash then
    raise exception 'editorial_profile_content_hash_invalid'
      using errcode = '23514';
  end if;

  select profile_row.*
  into v_profile
  from public.newsroom_editorial_profiles profile_row
  where profile_row.id = p_profile_id
  for update;

  if not found then
    raise exception 'editorial_profile_not_found'
      using errcode = 'P0002';
  end if;

  select coalesce(max(version_row.version_number), 0)
  into v_latest_version_number
  from public.newsroom_editorial_profile_versions version_row
  where version_row.profile_id = p_profile_id;

  if v_latest_version_number <> p_expected_latest_version_number then
    raise exception 'editorial_profile_version_conflict'
      using errcode = '40001';
  end if;

  if p_based_on_version_id is not null
     and not exists (
       select 1
       from public.newsroom_editorial_profile_versions base_version
       where base_version.profile_id = p_profile_id
         and base_version.id = p_based_on_version_id
     ) then
    raise exception 'editorial_profile_version_not_found'
      using errcode = 'P0002';
  end if;

  insert into public.newsroom_editorial_profile_versions (
    id,
    profile_id,
    version_number,
    document_text,
    content_hash,
    change_summary,
    based_on_version_id,
    approval_state,
    created_by_actor_type,
    created_by_actor_id
  ) values (
    v_version_id,
    p_profile_id,
    v_latest_version_number + 1,
    v_document_text,
    v_content_hash,
    btrim(p_change_summary),
    p_based_on_version_id,
    'approved',
    p_created_by_actor_type,
    nullif(btrim(coalesce(p_created_by_actor_id, '')), '')
  );

  return query
  select
    v_version_id,
    v_latest_version_number + 1,
    v_content_hash;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_create_manual_source(p_submission_id uuid, p_request_fingerprint text, p_title text, p_body jsonb, p_image_url text, p_published_date text, p_source_url text, p_source_page_title text, p_source_host text, p_content_hash text)
 RETURNS TABLE(submission_id uuid, request_fingerprint text, newsroom_article_id uuid, newsroom_snapshot_id uuid, entry_action text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.newsroom_manual_entry_requests%rowtype;
  v_article_id uuid;
  v_snapshot_id uuid;
  v_published_date date;
  v_published_at timestamptz;
  v_now timestamptz := pg_catalog.now();
  v_body_length integer;
  v_source_metadata jsonb;
begin
  if p_submission_id is null
     or p_request_fingerprint is null
     or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or p_title is null
     or btrim(p_title) = ''
     or length(btrim(p_title)) > 180
     or p_body is null
     or jsonb_typeof(p_body) <> 'array'
     or jsonb_array_length(p_body) = 0
     or p_image_url is null
     or btrim(p_image_url) = ''
     or length(p_image_url) > 2048
     or p_image_url !~* '^https?://[^[:space:]]+$'
     or p_image_url ~* '^https?://[^/?#]*@'
     or p_content_hash is null
     or p_content_hash !~ '^[0-9a-f]{64}$'
     or (
       p_published_date is not null
       and p_published_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     )
     or (
       p_source_url is not null
       and (
         btrim(p_source_url) = ''
         or length(p_source_url) > 4096
         or p_source_url !~* '^https?://[^[:space:]]+$'
         or p_source_url ~* '^https?://[^/?#]*@'
       )
     )
     or (p_source_page_title is not null and length(p_source_page_title) > 500)
     or (p_source_host is not null and length(p_source_host) > 255) then
    raise exception 'manual_source_input_invalid' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_body) body_item(value)
    where jsonb_typeof(body_item.value) is distinct from 'object'
      or jsonb_typeof(body_item.value -> 'type') is distinct from 'string'
      or (body_item.value ->> 'type') is distinct from 'paragraph'
      or jsonb_typeof(body_item.value -> 'text') is distinct from 'string'
      or nullif(btrim(coalesce(body_item.value ->> 'text', '')), '') is null
      or exists (
        select 1
        from jsonb_object_keys(
          case when jsonb_typeof(body_item.value) = 'object'
            then body_item.value else '{}'::jsonb end
        ) body_key(key)
        where body_key.key not in ('type', 'text')
      )
  ) then
    raise exception 'manual_source_body_invalid' using errcode = '22023';
  end if;

  select coalesce(sum(length(body_item.value ->> 'text')), 0)::integer
  into v_body_length
  from jsonb_array_elements(p_body) body_item(value);

  if v_body_length < 1 or v_body_length > 50000 then
    raise exception 'manual_source_body_invalid' using errcode = '22023';
  end if;

  if p_published_date is not null then
    begin
      v_published_date := p_published_date::date;
    exception
      when invalid_datetime_format or datetime_field_overflow then
        raise exception 'manual_source_published_date_invalid' using errcode = '22007';
    end;
    if to_char(v_published_date, 'YYYY-MM-DD') <> p_published_date
       or v_published_date > (v_now at time zone 'Europe/Lisbon')::date then
      raise exception 'manual_source_published_date_invalid' using errcode = '22007';
    end if;
    v_published_at := (p_published_date || 'T00:00:00.000Z')::timestamptz;
  end if;

  insert into public.newsroom_manual_entry_requests (
    submission_id,
    request_fingerprint
  ) values (
    p_submission_id,
    p_request_fingerprint
  )
  on conflict on constraint newsroom_manual_entry_requests_pkey do nothing;

  select request_row.*
  into v_request
  from public.newsroom_manual_entry_requests request_row
  where request_row.submission_id = p_submission_id
  for update;

  if not found then
    raise exception 'manual_source_request_unavailable' using errcode = '55000';
  end if;
  if v_request.request_fingerprint <> p_request_fingerprint then
    raise exception 'manual_source_payload_conflict' using errcode = 'P0001';
  end if;

  if v_request.newsroom_article_id is not null
     and v_request.newsroom_snapshot_id is not null then
    if not exists (
      select 1
      from public.newsroom_articles article
      join public.newsroom_article_snapshots snapshot
        on snapshot.id = v_request.newsroom_snapshot_id
       and snapshot.article_id = article.id
      where article.id = v_request.newsroom_article_id
        and article.source_code = 'manual_entry'
        and snapshot.content_hash = p_content_hash
        and snapshot.source_metadata ->> 'origin' = 'manual'
        and snapshot.source_metadata ->> 'manualSubmissionId' = p_submission_id::text
    ) then
      raise exception 'manual_source_request_inconsistent' using errcode = '55000';
    end if;

    return query
    select p_submission_id, p_request_fingerprint,
      v_request.newsroom_article_id, v_request.newsroom_snapshot_id,
      'reused'::text;
    return;
  end if;

  if v_request.newsroom_article_id is not null
     or v_request.newsroom_snapshot_id is not null then
    raise exception 'manual_source_request_incomplete' using errcode = '55000';
  end if;

  v_article_id := pg_catalog.gen_random_uuid();
  v_snapshot_id := pg_catalog.gen_random_uuid();
  v_source_metadata := jsonb_strip_nulls(jsonb_build_object(
    'origin', 'manual',
    'sourceCode', 'manual_entry',
    'sourceName', 'Entrada manual',
    'manualSubmissionId', p_submission_id::text,
    'title', btrim(p_title),
    'publishedAt', case when v_published_at is null then null else to_char(
      v_published_at at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    ) end,
    'publishedAtPrecision', case when v_published_at is null then null else 'date' end,
    'imageUrl', btrim(p_image_url),
    'sourceUrl', p_source_url,
    'sourcePageTitle', p_source_page_title,
    'sourceHost', p_source_host,
    'introducedAt', to_char(
      v_now at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    )
  ));

  insert into public.newsroom_articles (
    id, source_code, original_url, normalized_url, external_id,
    title, subtitle, summary, author, published_at, modified_at,
    detected_at, image_url, processing_status, first_detected_at,
    last_detected_at, created_at, updated_at
  ) values (
    v_article_id, 'manual_entry', p_source_url, p_source_url, null,
    btrim(p_title), null, null, null, v_published_at, null,
    v_now, btrim(p_image_url), 'ready_for_review', v_now,
    v_now, v_now, v_now
  );

  insert into public.newsroom_article_snapshots (
    id, article_id, content_hash, body, source_metadata, extracted_at, created_at
  ) values (
    v_snapshot_id, v_article_id, p_content_hash, p_body,
    v_source_metadata, v_now, v_now
  );

  update public.newsroom_manual_entry_requests request_row
  set newsroom_article_id = v_article_id,
      newsroom_snapshot_id = v_snapshot_id
  where request_row.submission_id = p_submission_id;

  return query
  select p_submission_id, p_request_fingerprint,
    v_article_id, v_snapshot_id, 'created'::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_editorial_source_package_manifest_v5_context_valid(p_id uuid, p_package_year text, p_package_month text, p_manifest jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO ''
AS $function$
declare
  v_output jsonb;
  v_source_id jsonb;
  v_context_source_ids text[];
  v_transformed_outputs jsonb;
  v_workspace_manifest jsonb;
  v_uuid_pattern constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  if jsonb_typeof(p_manifest -> 'outputs') is distinct from 'array'
    or jsonb_array_length(p_manifest -> 'outputs') not between 1 and 30 then
    return false;
  end if;
  for v_output in select output.value from jsonb_array_elements(p_manifest -> 'outputs') output(value)
  loop
    if jsonb_typeof(v_output -> 'articlePlan') is distinct from 'object'
      or v_output -> 'articlePlan' ->> 'sourceScope' is distinct from 'context'
      or jsonb_typeof(v_output -> 'articlePlan' -> 'contextId') is distinct from 'string'
      or lower(v_output -> 'articlePlan' ->> 'contextId') !~ v_uuid_pattern
      or jsonb_typeof(v_output -> 'contextSourceIds') is distinct from 'array'
      or jsonb_array_length(v_output -> 'contextSourceIds') not between 1 and 20 then
      return false;
    end if;
    v_context_source_ids := '{}'::text[];
    for v_source_id in select source_id.value from jsonb_array_elements(v_output -> 'contextSourceIds') source_id(value)
    loop
      if jsonb_typeof(v_source_id) is distinct from 'string'
        or lower(v_source_id #>> '{}') !~ v_uuid_pattern
        or lower(v_source_id #>> '{}') = any(v_context_source_ids)
        or not exists (
          select 1 from jsonb_array_elements(p_manifest -> 'entries') entry(value)
          where entry.value ->> 'status' = 'prepared'
            and lower(entry.value ->> 'provenanceSourceId') = lower(v_source_id #>> '{}')
        ) then
        return false;
      end if;
      v_context_source_ids := v_context_source_ids || lower(v_source_id #>> '{}');
    end loop;
  end loop;
  select jsonb_agg(
    jsonb_set(output.value - 'contextSourceIds','{articlePlan}',((output.value -> 'articlePlan') - 'contextId') || jsonb_build_object('sourceScope', 'workspace'))
    order by output.ordinality
  ) into v_transformed_outputs
  from jsonb_array_elements(p_manifest -> 'outputs') with ordinality output(value, ordinality);
  v_workspace_manifest := jsonb_set(p_manifest,'{outputs}',v_transformed_outputs);
  return public.newsroom_editorial_source_package_manifest_v5_valid(p_id,p_package_year,p_package_month,v_workspace_manifest);
exception when others then return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_editorial_source_package_manifest_v5_valid(p_id uuid, p_package_year text, p_package_month text, p_manifest jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO ''
AS $function$
declare
  v_entries jsonb;
  v_outputs jsonb;
  v_entry jsonb;
  v_output jsonb;
  v_plan jsonb;
  v_item jsonb;
  v_ordinality bigint;
  v_selected_count integer;
  v_article_count integer;
  v_prepared_count integer;
  v_failed_count integer;
  v_image_count integer;
  v_actual_prepared integer := 0;
  v_actual_failed integer := 0;
  v_position integer;
  v_article_position integer;
  v_output_id text;
  v_dossier_id text;
  v_first_dossier_id text;
  v_provenance_source_id text;
  v_newsroom_snapshot_id text;
  v_published_context_id text;
  v_output_ids text[] := '{}'::text[];
  v_provenance_source_ids text[] := '{}'::text[];
  v_snapshot_ids text[] := '{}'::text[];
  v_published_context_ids text[] := '{}'::text[];
  v_uuid_pattern constant text :=
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  if pg_catalog.jsonb_typeof(p_manifest) is distinct from 'object'
    or pg_catalog.jsonb_typeof(p_manifest -> 'version') is distinct from 'number'
    or p_manifest ->> 'version' is distinct from '5'
    or pg_catalog.jsonb_typeof(p_manifest -> 'provenanceContract') is distinct from 'string'
    or p_manifest ->> 'provenanceContract' is distinct from 'mesa-v2'
    or pg_catalog.jsonb_typeof(p_manifest -> 'packageId') is distinct from 'string'
    or p_manifest ->> 'packageId' is distinct from p_id::text
    or pg_catalog.jsonb_typeof(p_manifest -> 'year') is distinct from 'string'
    or p_manifest ->> 'year' is distinct from p_package_year
    or pg_catalog.jsonb_typeof(p_manifest -> 'month') is distinct from 'string'
    or p_manifest ->> 'month' is distinct from p_package_month
    or pg_catalog.jsonb_typeof(p_manifest -> 'createdAt') is distinct from 'string'
    or nullif(pg_catalog.btrim(p_manifest ->> 'createdAt'), '') is null
    or pg_catalog.jsonb_typeof(p_manifest -> 'markdownFileName') is distinct from 'string'
    or nullif(pg_catalog.btrim(p_manifest ->> 'markdownFileName'), '') is null
    or pg_catalog.length(p_manifest ->> 'markdownFileName') > 240
    or p_manifest ->> 'markdownFileName' !~ '\.md$'
    or pg_catalog.jsonb_typeof(p_manifest -> 'genre') is distinct from 'string'
    or p_manifest ->> 'genre' not in ('news', 'brief', 'analysis', 'editorial')
    or pg_catalog.jsonb_typeof(p_manifest -> 'genreLabel') is distinct from 'string'
    or nullif(pg_catalog.btrim(p_manifest ->> 'genreLabel'), '') is null
    or pg_catalog.length(p_manifest ->> 'genreLabel') > 80
    or not (p_manifest ? 'suggestedTitle')
    or not coalesce(
      pg_catalog.jsonb_typeof(p_manifest -> 'suggestedTitle') in ('string', 'null'),
      false
    )
    or (
      pg_catalog.jsonb_typeof(p_manifest -> 'suggestedTitle') = 'string'
      and (
        nullif(pg_catalog.btrim(p_manifest ->> 'suggestedTitle'), '') is null
        or pg_catalog.length(p_manifest ->> 'suggestedTitle') > 240
      )
    )
    or not (p_manifest ? 'additionalInstructions')
    or not coalesce(
      pg_catalog.jsonb_typeof(p_manifest -> 'additionalInstructions') in ('string', 'null'),
      false
    )
    or (
      pg_catalog.jsonb_typeof(p_manifest -> 'additionalInstructions') = 'string'
      and (
        nullif(pg_catalog.btrim(p_manifest ->> 'additionalInstructions'), '') is null
        or pg_catalog.length(p_manifest ->> 'additionalInstructions') > 4000
      )
    )
    or pg_catalog.jsonb_typeof(p_manifest -> 'selectedCount') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p_manifest -> 'articleCount') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p_manifest -> 'preparedCount') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p_manifest -> 'failedCount') is distinct from 'number'
    or pg_catalog.jsonb_typeof(p_manifest -> 'imageCount') is distinct from 'number'
    or not (p_manifest ? 'localDirectory')
    or not coalesce(
      pg_catalog.jsonb_typeof(p_manifest -> 'localDirectory') in ('string', 'null'),
      false
    )
    or (
      pg_catalog.jsonb_typeof(p_manifest -> 'localDirectory') = 'string'
      and nullif(pg_catalog.btrim(p_manifest ->> 'localDirectory'), '') is null
    )
    or pg_catalog.jsonb_typeof(p_manifest -> 'entries') is distinct from 'array'
    or pg_catalog.jsonb_typeof(p_manifest -> 'outputs') is distinct from 'array'
  then
    return false;
  end if;

  perform (p_manifest ->> 'createdAt')::timestamptz;
  v_selected_count := (p_manifest ->> 'selectedCount')::integer;
  v_article_count := (p_manifest ->> 'articleCount')::integer;
  v_prepared_count := (p_manifest ->> 'preparedCount')::integer;
  v_failed_count := (p_manifest ->> 'failedCount')::integer;
  v_image_count := (p_manifest ->> 'imageCount')::integer;
  v_entries := p_manifest -> 'entries';
  v_outputs := p_manifest -> 'outputs';

  if pg_catalog.jsonb_array_length(v_entries) not between 1 and 20
    or pg_catalog.jsonb_array_length(v_outputs) not between 1 and 30
    or v_selected_count is distinct from pg_catalog.jsonb_array_length(v_entries)
    or v_article_count is distinct from pg_catalog.jsonb_array_length(v_outputs)
    or v_prepared_count < 0
    or v_failed_count < 0
    or v_image_count < 0
    or v_prepared_count + v_failed_count <> v_selected_count
  then
    return false;
  end if;

  for v_entry, v_ordinality in
    select item.value, item.ordinality
    from pg_catalog.jsonb_array_elements(v_entries)
      with ordinality as item(value, ordinality)
  loop
    if pg_catalog.jsonb_typeof(v_entry) is distinct from 'object'
      or pg_catalog.jsonb_typeof(v_entry -> 'position') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_entry -> 'articlePosition') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_entry -> 'newsroomArticleId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_entry -> 'newsroomSnapshotId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_entry -> 'provenanceSourceId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_entry -> 'status') is distinct from 'string'
      or v_entry ->> 'status' not in ('prepared', 'failed')
      or not (v_entry ? 'sourceCode')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'sourceCode') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'sourceName')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'sourceName') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'title')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'title') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'errorCode')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'errorCode') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'imageUrl')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'imageUrl') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'publishedAt')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'publishedAt') in ('string', 'null'),
        false
      )
      or not (v_entry ? 'publishedAtPrecision')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_entry -> 'publishedAtPrecision') in ('string', 'null'),
        false
      )
      or (
        v_entry ? 'imagePreferred'
        and pg_catalog.jsonb_typeof(v_entry -> 'imagePreferred') is distinct from 'boolean'
      )
    then
      return false;
    end if;

    v_position := (v_entry ->> 'position')::integer;
    v_article_position := (v_entry ->> 'articlePosition')::integer;
    v_provenance_source_id := pg_catalog.lower(v_entry ->> 'provenanceSourceId');
    v_newsroom_snapshot_id := pg_catalog.lower(v_entry ->> 'newsroomSnapshotId');
    if v_position is distinct from v_ordinality::integer
      or v_article_position is distinct from 1
      or pg_catalog.lower(v_entry ->> 'newsroomArticleId') !~ v_uuid_pattern
      or v_newsroom_snapshot_id !~ v_uuid_pattern
      or v_provenance_source_id !~ v_uuid_pattern
      or v_provenance_source_id = any(v_provenance_source_ids)
      or v_newsroom_snapshot_id = any(v_snapshot_ids)
    then
      return false;
    end if;
    v_provenance_source_ids := v_provenance_source_ids || v_provenance_source_id;
    v_snapshot_ids := v_snapshot_ids || v_newsroom_snapshot_id;

    if v_entry ->> 'status' = 'prepared' then
      v_actual_prepared := v_actual_prepared + 1;
      if pg_catalog.jsonb_typeof(v_entry -> 'sourceCode') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_entry ->> 'sourceCode'), '') is null
        or pg_catalog.jsonb_typeof(v_entry -> 'sourceName') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_entry ->> 'sourceName'), '') is null
        or pg_catalog.jsonb_typeof(v_entry -> 'title') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_entry ->> 'title'), '') is null
        or pg_catalog.jsonb_typeof(v_entry -> 'errorCode') is distinct from 'null'
        or not coalesce(
          pg_catalog.jsonb_typeof(v_entry -> 'publishedAtPrecision') in ('null', 'string'),
          false
        )
        or (
          pg_catalog.jsonb_typeof(v_entry -> 'publishedAtPrecision') = 'string'
          and v_entry ->> 'publishedAtPrecision' not in ('date', 'instant')
        )
      then
        return false;
      end if;
    else
      v_actual_failed := v_actual_failed + 1;
      if pg_catalog.jsonb_typeof(v_entry -> 'errorCode') is distinct from 'string'
        or v_entry ->> 'errorCode' not in (
          'source_not_found',
          'snapshot_not_found',
          'snapshot_mismatch',
          'source_body_unavailable'
        )
      then
        return false;
      end if;
    end if;
  end loop;

  if v_actual_prepared is distinct from v_prepared_count
    or v_actual_failed is distinct from v_failed_count
  then
    return false;
  end if;

  for v_output, v_ordinality in
    select item.value, item.ordinality
    from pg_catalog.jsonb_array_elements(v_outputs)
      with ordinality as item(value, ordinality)
  loop
    if pg_catalog.jsonb_typeof(v_output) is distinct from 'object'
      or pg_catalog.jsonb_typeof(v_output -> 'position') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_output -> 'outputId') is distinct from 'string'
      or pg_catalog.jsonb_typeof(v_output -> 'sourceArticlePosition') is distinct from 'number'
      or pg_catalog.jsonb_typeof(v_output -> 'focus') is distinct from 'string'
      or nullif(pg_catalog.btrim(v_output ->> 'focus'), '') is null
      or pg_catalog.length(v_output ->> 'focus') > 240
      or not (v_output ? 'imageNewsroomArticleId')
      or not coalesce(
        pg_catalog.jsonb_typeof(v_output -> 'imageNewsroomArticleId') in ('string', 'null'),
        false
      )
      or pg_catalog.jsonb_typeof(v_output -> 'articlePlan') is distinct from 'object'
    then
      return false;
    end if;

    v_position := (v_output ->> 'position')::integer;
    v_article_position := (v_output ->> 'sourceArticlePosition')::integer;
    v_output_id := pg_catalog.lower(v_output ->> 'outputId');
    v_plan := v_output -> 'articlePlan';
    v_dossier_id := pg_catalog.lower(v_plan ->> 'dossierId');

    if v_position is distinct from v_ordinality::integer
      or v_output_id !~ v_uuid_pattern
      or v_output_id = any(v_output_ids)
      or v_article_position is distinct from 1
      or not exists (
        select 1
        from pg_catalog.jsonb_array_elements(v_entries) as entry_item(value)
        where (entry_item.value ->> 'articlePosition')::integer = v_article_position
      )
      or pg_catalog.jsonb_typeof(v_plan -> 'dossierId') is distinct from 'string'
      or v_dossier_id !~ v_uuid_pattern
      or pg_catalog.jsonb_typeof(v_plan -> 'articlePlanId') is distinct from 'string'
      or pg_catalog.lower(v_plan ->> 'articlePlanId') is distinct from v_output_id
      or pg_catalog.jsonb_typeof(v_plan -> 'workingTitle') is distinct from 'string'
      or nullif(pg_catalog.btrim(v_plan ->> 'workingTitle'), '') is null
      or pg_catalog.length(v_plan ->> 'workingTitle') > 180
      or pg_catalog.jsonb_typeof(v_plan -> 'articleKind') is distinct from 'string'
      or v_plan ->> 'articleKind' not in ('news', 'analysis', 'preview', 'summary')
      or pg_catalog.jsonb_typeof(v_plan -> 'articleKindLabel') is distinct from 'string'
      or nullif(pg_catalog.btrim(v_plan ->> 'articleKindLabel'), '') is null
      or pg_catalog.length(v_plan ->> 'articleKindLabel') > 80
      or pg_catalog.jsonb_typeof(v_plan -> 'lengthMode') is distinct from 'string'
      or v_plan ->> 'lengthMode' not in ('brief', 'standard', 'developed')
      or pg_catalog.jsonb_typeof(v_plan -> 'lengthModeLabel') is distinct from 'string'
      or nullif(pg_catalog.btrim(v_plan ->> 'lengthModeLabel'), '') is null
      or pg_catalog.length(v_plan ->> 'lengthModeLabel') > 80
      or pg_catalog.jsonb_typeof(v_plan -> 'editorialInstructions') is distinct from 'string'
      or pg_catalog.length(v_plan ->> 'editorialInstructions') > 12000
      or pg_catalog.jsonb_typeof(v_plan -> 'destination') is distinct from 'string'
      or v_plan ->> 'destination' not in ('new', 'update')
      or pg_catalog.jsonb_typeof(v_plan -> 'workspaceContractVersion') is distinct from 'number'
      or (v_plan ->> 'workspaceContractVersion')::integer is distinct from 2
      or pg_catalog.jsonb_typeof(v_plan -> 'sourceScope') is distinct from 'string'
      or v_plan ->> 'sourceScope' is distinct from 'workspace'
      or v_plan ? 'origin'
    then
      return false;
    end if;

    if v_first_dossier_id is null then
      v_first_dossier_id := v_dossier_id;
    elsif v_dossier_id is distinct from v_first_dossier_id then
      return false;
    end if;
    v_output_ids := v_output_ids || v_output_id;

    if pg_catalog.jsonb_typeof(v_output -> 'imageNewsroomArticleId') = 'string' then
      if pg_catalog.lower(v_output ->> 'imageNewsroomArticleId') !~ v_uuid_pattern
        or not exists (
          select 1
          from pg_catalog.jsonb_array_elements(v_entries) as entry_item(value)
          where (entry_item.value ->> 'articlePosition')::integer = v_article_position
            and entry_item.value ->> 'status' = 'prepared'
            and pg_catalog.lower(entry_item.value ->> 'newsroomArticleId') =
              pg_catalog.lower(v_output ->> 'imageNewsroomArticleId')
            and pg_catalog.jsonb_typeof(entry_item.value -> 'imageUrl') = 'string'
            and nullif(pg_catalog.btrim(entry_item.value ->> 'imageUrl'), '') is not null
        )
      then
        return false;
      end if;
    end if;

    if v_output ? 'externalImage' then
      if pg_catalog.jsonb_typeof(v_output -> 'externalImage') is distinct from 'object'
        or pg_catalog.jsonb_typeof(v_output -> 'externalImage' -> 'url') is distinct from 'string'
        or (v_output -> 'externalImage' ->> 'url') !~ '^https?://'
        or pg_catalog.jsonb_typeof(v_output -> 'externalImage' -> 'fileName') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_output -> 'externalImage' ->> 'fileName'), '') is null
        or pg_catalog.length(v_output -> 'externalImage' ->> 'fileName') > 240
        or pg_catalog.jsonb_typeof(v_output -> 'imageNewsroomArticleId') is distinct from 'null'
      then
        return false;
      end if;
    end if;

    if (v_output ? 'publishedArticleId') or (v_output ? 'publishedSlug') then
      if pg_catalog.jsonb_typeof(v_output -> 'publishedArticleId') is distinct from 'string'
        or pg_catalog.lower(v_output ->> 'publishedArticleId') !~ v_uuid_pattern
        or pg_catalog.jsonb_typeof(v_output -> 'publishedSlug') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_output ->> 'publishedSlug'), '') is null
      then
        return false;
      end if;
    end if;

    if v_output ? 'usedAt' then
      if pg_catalog.jsonb_typeof(v_output -> 'usedAt') is distinct from 'string'
        or nullif(pg_catalog.btrim(v_output ->> 'usedAt'), '') is null
      then
        return false;
      end if;
      perform (v_output ->> 'usedAt')::timestamptz;
    end if;
  end loop;

  if p_manifest ? 'publishedContextArticleIds' then
    if pg_catalog.jsonb_typeof(p_manifest -> 'publishedContextArticleIds') is distinct from 'array'
      or pg_catalog.jsonb_array_length(p_manifest -> 'publishedContextArticleIds') > 20
    then
      return false;
    end if;
    for v_item in
      select item.value
      from pg_catalog.jsonb_array_elements(p_manifest -> 'publishedContextArticleIds') as item(value)
    loop
      if pg_catalog.jsonb_typeof(v_item) is distinct from 'string' then
        return false;
      end if;
      v_published_context_id := pg_catalog.lower(v_item #>> '{}');
      if v_published_context_id !~ v_uuid_pattern
        or v_published_context_id = any(v_published_context_ids)
      then
        return false;
      end if;
      v_published_context_ids := v_published_context_ids || v_published_context_id;
    end loop;
  end if;

  return true;
exception
  when others then
    return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_finalize_mesa_intents_v1(p_dossier_id uuid, p_package_id uuid, p_no_change_output_ids uuid[])
 RETURNS TABLE(result jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_plan jsonb; v_output jsonb; v_context jsonb; v_article jsonb; v_article_id uuid;
  v_written public.newsroom_mesa_output_publications%rowtype;
  v_final public.newsroom_mesa_intent_finalizations%rowtype;
  v_no_change uuid[]; v_receipts jsonb:='[]'; v_decisions jsonb:='[]';
  v_decision text; v_fingerprint text; v_event uuid; v_payload jsonb;
  v_updated integer:=0; v_new integer:=0; v_unchanged integer:=0;
  v_group record; v_version uuid; v_key text; v_completed timestamptz;
begin
  if p_dossier_id is null or p_package_id is null or p_no_change_output_ids is null
    or cardinality(p_no_change_output_ids)>30 or array_position(p_no_change_output_ids,null) is not null
    or (select count(distinct x) from unnest(p_no_change_output_ids) x)<>cardinality(p_no_change_output_ids) then
    raise exception 'mesa-intent-finalization-input-invalid';
  end if;
  select coalesce(array_agg(x order by x),'{}'::uuid[]) into v_no_change from unnest(p_no_change_output_ids) x;
  -- Completed replay is a historical fact, not a request to overwrite a later
  -- edit. Lock the same workspace as the writer before checking it.
  perform 1 from public.newsroom_mesa_production_contexts w where w.dossier_id=p_dossier_id for update;
  select * into v_final from public.newsroom_mesa_intent_finalizations f where f.dossier_id=p_dossier_id;
  if found then
    if v_final.package_id<>p_package_id or v_final.no_change_output_ids is distinct from v_no_change then
      raise exception 'mesa-intent-finalization-conflict';
    end if;
    return query select jsonb_build_object('action','reused','publicationEventId',v_final.publication_event_id,
      'updatedCount',v_final.updated_count,'newCount',v_final.new_count,'noChangeCount',v_final.no_change_count);
    return;
  end if;
  v_plan:=public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id,p_package_id);
  if exists (select 1 from public.newsroom_mesa_production_contexts w
    where w.dossier_id=p_dossier_id and w.workspace_state<>'active') then
    raise exception 'mesa-intent-finalization-state-invalid';
  end if;
  if exists (select 1 from unnest(v_no_change) id where not exists (
      select 1 from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'outputId'=id::text and o ->> 'kind'='existing'))
    or exists (select 1 from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id and not exists (
      select 1 from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'outputId'=p.article_plan_id::text)) then
    raise exception 'mesa-intent-finalization-decision-invalid';
  end if;
  perform 1 from public.editorial_articles a where a.id in (
    select (o -> 'target' ->> 'editorialArticleId')::uuid from jsonb_array_elements(v_plan -> 'outputs') o where o ->> 'kind'='existing'
    union select p.editorial_article_id from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id
  ) order by a.id for update;
  for v_output in select value from jsonb_array_elements(v_plan -> 'outputs') loop
    select c into strict v_context from jsonb_array_elements(v_plan -> 'contexts') c where c ->> 'key'=v_output ->> 'contextKey';
    if (v_output ->> 'outputId')::uuid=any(v_no_change) then
      if exists (select 1 from public.newsroom_mesa_output_publications p where p.dossier_id=p_dossier_id and p.article_plan_id=(v_output ->> 'outputId')::uuid) then
        raise exception 'mesa-intent-no-change-already-published';
      end if;
      v_article_id:=(v_output -> 'target' ->> 'editorialArticleId')::uuid;
      select to_jsonb(a) into v_article from public.editorial_articles a where a.id=v_article_id and a.status='published';
      if not found or encode(sha256(convert_to(v_article::text,'UTF8')),'hex')
          is distinct from v_output -> 'target' ->> 'contentFingerprint' then
        raise exception 'mesa-intent-no-change-target-stale';
      end if;
      v_decision:='SEM_ALTERAÇÃO'; v_unchanged:=v_unchanged+1;
    else
      select * into v_written from public.newsroom_mesa_output_publications p
        where p.dossier_id=p_dossier_id and p.article_plan_id=(v_output ->> 'outputId')::uuid;
      if not found then raise exception 'mesa-intent-publication-incomplete'; end if;
      if v_written.package_id<>p_package_id or v_written.source_scope is distinct from 'context'
        or v_written.production_context_id is distinct from (v_context ->> 'productionContextId')::uuid
        or (v_output ->> 'kind'='existing' and v_written.editorial_article_id is distinct from (v_output -> 'target' ->> 'editorialArticleId')::uuid) then
        raise exception 'mesa-intent-publication-output-invalid';
      end if;
      v_article_id:=v_written.editorial_article_id;
      select to_jsonb(a) into v_article from public.editorial_articles a where a.id=v_article_id and a.status='published';
      if not found or encode(sha256(convert_to(v_article::text,'UTF8')),'hex') is distinct from v_written.payload ->> 'intentResultFingerprint' then
        raise exception 'mesa-intent-published-result-stale';
      end if;
      if not exists (
        select 1
        from public.newsroom_editorial_dossier_article_plans p
        where p.id=v_written.article_plan_id
          and p.dossier_id=p_dossier_id
          and (
            (
              v_output ->> 'kind'='existing'
              and p.destination='update'
              and p.update_target_editorial_article_id=v_article_id
              and (p.editorial_article_id is null or p.editorial_article_id=v_article_id)
            )
            or (
              v_output ->> 'kind'='new'
              and p.destination='new'
              and p.update_target_editorial_article_id is null
              and p.editorial_article_id=v_article_id
            )
          )
      ) then
        raise exception 'mesa-intent-publication-output-invalid';
      end if;
      v_decision:=case when v_output ->> 'kind'='existing' then 'UPDATE' else 'NEW' end;
      if v_decision='UPDATE' then v_updated:=v_updated+1; else v_new:=v_new+1; end if;
    end if;
    v_fingerprint:=encode(sha256(convert_to(v_article::text,'UTF8')),'hex');
    v_decisions:=v_decisions||jsonb_build_array(jsonb_build_object('slot',v_output -> 'slot',
      'outputId',v_output -> 'outputId','contextKey',v_output -> 'contextKey',
      'decision',v_decision,'articleId',v_article_id,'resultFingerprint',v_fingerprint));
    v_receipts:=v_receipts||jsonb_build_array(jsonb_build_object(
      'contextKey',v_context -> 'key','themeId',v_context -> 'themeId',
      'articleId',v_article_id,'outputId',v_output -> 'outputId','slot',v_output -> 'slot',
      'decision',v_decision,'sources',v_context -> 'sources','resultFingerprint',v_fingerprint));
  end loop;
  v_payload:=jsonb_build_object('contractVersion',1,'kind','mesa_production_intents',
    'packageId',p_package_id,'authorityFingerprint',v_plan -> 'authorityFingerprint',
    'capturedAt',v_plan -> 'capturedAt','decisions',v_decisions);
  insert into public.newsroom_mesa_publication_events(dossier_id,fingerprint,payload)
    values(p_dossier_id,md5(v_payload::text),v_payload) returning id into v_event;
  v_completed:=clock_timestamp();
  insert into public.newsroom_mesa_intent_finalizations(dossier_id,package_id,publication_event_id,
    no_change_output_ids,updated_count,new_count,no_change_count,completed_at)
    values(p_dossier_id,p_package_id,v_event,v_no_change,v_updated,v_new,v_unchanged,v_completed);
  insert into public.newsroom_mesa_intent_article_receipts(
    dossier_id,output_id,context_key,theme_id,editorial_article_id,
    slot,decision,captured_at,completed_at,sources,result_fingerprint
  )
    select p_dossier_id,(r ->> 'outputId')::uuid,r ->> 'contextKey',(r ->> 'themeId')::uuid,(r ->> 'articleId')::uuid,
      r ->> 'slot',r ->> 'decision',(v_plan ->> 'capturedAt')::timestamptz,v_completed,r -> 'sources',r ->> 'resultFingerprint'
    from jsonb_array_elements(v_receipts) r;
  -- Preserve technical material projection, but group by context as well as
  -- sources. Equal source sets in different Themes must never merge their work.
  for v_group in
    select x.production_context_id,x.source_refs,array_agg(x.article_id order by x.article_id) article_ids,
      min(x.article_plan_id::text)::uuid key_plan_id
    from (
      select p.production_context_id,u.article_plan_id,min(u.editorial_article_id::text)::uuid article_id,
        public.newsroom_mesa_normalize_refs_v2(jsonb_agg(jsonb_build_object(
          'newsroomArticleId',u.newsroom_article_id,'newsroomSnapshotId',u.newsroom_snapshot_id)
          order by u.newsroom_article_id,u.newsroom_snapshot_id)) source_refs
      from public.newsroom_mesa_output_source_usage u
      join public.newsroom_mesa_output_publications p on p.dossier_id=u.dossier_id and p.article_plan_id=u.article_plan_id
      where u.dossier_id=p_dossier_id group by p.production_context_id,u.article_plan_id having count(*)>=2
    ) x group by x.production_context_id,x.source_refs
  loop
    select c into strict v_context from jsonb_array_elements(v_plan -> 'contexts') c
      where c ->> 'productionContextId'=v_group.production_context_id::text;
    v_key:='output:'||v_group.key_plan_id::text;
    insert into public.newsroom_mesa_material_versions(material_key,title,source_refs,article_ids,production_dossier_id,publication_event_id)
      values(v_key,v_context ->> 'title',v_group.source_refs,v_group.article_ids,p_dossier_id,v_event) returning id into v_version;
    if v_context ->> 'themeId' is not null then
      insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
        values((v_context ->> 'themeId')::uuid,v_key,v_version) on conflict do nothing;
    end if;
  end loop;
  insert into public.newsroom_editorial_theme_articles(theme_id,editorial_article_id)
    select (r ->> 'themeId')::uuid,(r ->> 'articleId')::uuid
    from jsonb_array_elements(v_receipts) r
    where r ->> 'themeId' is not null
    on conflict(theme_id,editorial_article_id) do nothing;
  update public.newsroom_mesa_production_contexts set workspace_state='consolidated',consolidated_at=v_completed where dossier_id=p_dossier_id;
  return query select jsonb_build_object('action','consolidated','publicationEventId',v_event,
    'updatedCount',v_updated,'newCount',v_new,'noChangeCount',v_unchanged);
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_finalize_theme_continuity_v1(p_dossier_id uuid, p_package_id uuid, p_no_change_output_ids uuid[])
 RETURNS TABLE(finalization_action text, publication_event_id uuid, updated_count integer, new_count integer, no_change_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_contract jsonb;
  v_manifest jsonb;
  v_slots jsonb;
  v_slot jsonb;
  v_theme_id uuid;
  v_context_id uuid;
  v_no_change_ids uuid[];
  v_payload jsonb;
  v_fingerprint text;
  v_event uuid;
  v_title text;
  v_group record;
  v_version uuid;
  v_key text;
  v_was_consolidated boolean;
  v_updated_count integer;
  v_new_count integer;
  v_no_change_count integer;
begin
  if p_dossier_id is null or p_package_id is null or p_no_change_output_ids is null
    or cardinality(p_no_change_output_ids) > 30
    or array_position(p_no_change_output_ids, null) is not null
    or (select count(distinct id) from unnest(p_no_change_output_ids) id)
      <> cardinality(p_no_change_output_ids)
  then
    raise exception 'theme-continuity-finalization-input-invalid';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('newsroom-mesa-theme-continuity:' || p_dossier_id::text, 0)
  );
  select workspace.* into v_context
  from public.newsroom_mesa_production_contexts workspace
  where workspace.dossier_id = p_dossier_id
  for update;
  if not found or v_context.workspace_role <> 'technical'
    or v_context.workspace_contract_version <> 2
    or v_context.workspace_state not in ('active', 'consolidated')
    or v_context.selection_payload ->> 'contractVersion' <> '3'
    or v_context.selection_payload ->> 'contextContractVersion' <> '1'
    or jsonb_typeof(v_context.selection_payload -> 'themeContinuity') <> 'object'
  then
    raise exception 'theme-continuity-finalization-workspace-invalid';
  end if;

  v_was_consolidated := v_context.workspace_state = 'consolidated';
  v_contract := v_context.selection_payload -> 'themeContinuity';
  v_slots := v_contract -> 'slots';
  if v_contract ->> 'contractVersion' <> '1'
    or jsonb_typeof(v_slots) <> 'array'
    or jsonb_array_length(v_slots) not between 1 and 30
  then
    raise exception 'theme-continuity-finalization-contract-invalid';
  end if;
  begin
    v_theme_id := (v_contract ->> 'themeId')::uuid;
  exception when others then
    raise exception 'theme-continuity-finalization-contract-invalid';
  end;

  select context_item.id into strict v_context_id
  from public.newsroom_mesa_production_context_items context_item
  where context_item.dossier_id = p_dossier_id
    and context_item.context_kind = 'theme'
    and context_item.theme_id = v_theme_id;

  select package.manifest into v_manifest
  from public.newsroom_editorial_source_packages package
  where package.id = p_package_id
  for share;
  if not found or v_manifest ->> 'version' <> '5'
    or v_manifest ->> 'provenanceContract' <> 'mesa-v2'
    or jsonb_typeof(v_manifest -> 'themeContinuity') <> 'object'
    or v_manifest -> 'themeContinuity' ->> 'contractVersion' <> '1'
    or v_manifest -> 'themeContinuity' ->> 'themeId' <> v_theme_id::text
    or v_manifest -> 'themeContinuity' ->> 'authorityFingerprint'
      is distinct from v_contract ->> 'authorityFingerprint'
    or jsonb_array_length(v_manifest -> 'outputs') <> jsonb_array_length(v_slots)
  then
    raise exception 'theme-continuity-finalization-package-invalid';
  end if;

  select coalesce(array_agg(id order by id), '{}'::uuid[])
  into v_no_change_ids
  from unnest(p_no_change_output_ids) id;

  if exists (
    select 1
    from jsonb_array_elements(v_slots) slot(value)
    full join jsonb_array_elements(v_manifest -> 'outputs') output(value)
      on lower(output.value ->> 'outputId') = lower(slot.value ->> 'outputId')
    where slot.value is null or output.value is null
      or lower(output.value -> 'articlePlan' ->> 'articlePlanId')
        <> lower(slot.value ->> 'outputId')
      or lower(output.value -> 'articlePlan' ->> 'dossierId') <> p_dossier_id::text
      or output.value -> 'articlePlan' ->> 'sourceScope' <> 'context'
      or lower(output.value -> 'articlePlan' ->> 'contextId') <> v_context_id::text
  ) then
    raise exception 'theme-continuity-finalization-package-invalid';
  end if;

  for v_slot in select slot.value from jsonb_array_elements(v_slots) slot(value)
  loop
    if coalesce(v_slot ->> 'slot', '') !~ '^(EXISTING|NEW)_[0-9]{2}$'
      or coalesce(v_slot ->> 'outputId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or v_slot ->> 'kind' not in ('existing', 'new')
      or not exists (
        select 1
        from public.newsroom_editorial_dossier_article_plans plan
        join public.newsroom_mesa_article_plan_contexts assignment
          on assignment.dossier_id = plan.dossier_id
          and assignment.article_plan_id = plan.id
          and assignment.production_context_id = v_context_id
        where plan.dossier_id = p_dossier_id
          and plan.id = (v_slot ->> 'outputId')::uuid
          and plan.status <> 'cancelled'
          and public.newsroom_mesa_plan_context_sources_valid_v1(
            plan.dossier_id, plan.id, v_context_id
          )
          and (
            (v_slot ->> 'kind' = 'new' and plan.destination = 'new'
              and plan.update_target_editorial_article_id is null)
            or
            (v_slot ->> 'kind' = 'existing' and plan.destination = 'update'
              and plan.update_target_editorial_article_id =
                (v_slot ->> 'targetEditorialArticleId')::uuid)
          )
      )
    then
      raise exception 'theme-continuity-finalization-slot-invalid';
    end if;

    if (v_slot ->> 'outputId')::uuid = any(v_no_change_ids) then
      if v_slot ->> 'kind' <> 'existing'
        or exists (
          select 1 from public.newsroom_mesa_output_publications publication
          where publication.dossier_id = p_dossier_id
            and publication.article_plan_id = (v_slot ->> 'outputId')::uuid
        )
        or not exists (
          select 1 from public.editorial_articles article
          where article.id = (v_slot ->> 'targetEditorialArticleId')::uuid
            and article.status = 'published'
        )
      then
        raise exception 'theme-continuity-finalization-no-change-invalid';
      end if;
    elsif not exists (
      select 1
      from public.newsroom_mesa_output_publications publication
      join public.editorial_articles article
        on article.id = publication.editorial_article_id
        and article.status = 'published'
      where publication.dossier_id = p_dossier_id
        and publication.article_plan_id = (v_slot ->> 'outputId')::uuid
        and publication.package_id = p_package_id
        and publication.production_context_id = v_context_id
        and (
          v_slot ->> 'kind' = 'new'
          or publication.editorial_article_id =
            (v_slot ->> 'targetEditorialArticleId')::uuid
        )
    ) then
      raise exception 'theme-continuity-finalization-output-missing';
    end if;
  end loop;

  if exists (
    select 1 from unnest(v_no_change_ids) requested(id)
    where not exists (
      select 1 from jsonb_array_elements(v_slots) slot(value)
      where slot.value ->> 'kind' = 'existing'
        and lower(slot.value ->> 'outputId') = requested.id::text
    )
  ) or exists (
    select 1 from public.newsroom_mesa_output_publications publication
    where publication.dossier_id = p_dossier_id
      and not exists (
        select 1 from jsonb_array_elements(v_slots) slot(value)
        where lower(slot.value ->> 'outputId') = publication.article_plan_id::text
      )
  ) then
    raise exception 'theme-continuity-finalization-output-invalid';
  end if;

  select count(*) filter (where slot.value ->> 'kind' = 'existing'
      and not ((slot.value ->> 'outputId')::uuid = any(v_no_change_ids)))::integer,
    count(*) filter (where slot.value ->> 'kind' = 'new')::integer,
    cardinality(v_no_change_ids)
  into v_updated_count, v_new_count, v_no_change_count
  from jsonb_array_elements(v_slots) slot(value);

  select jsonb_build_object(
    'contractVersion', 1,
    'kind', 'theme_continuity',
    'themeId', v_theme_id,
    'authorityFingerprint', v_contract ->> 'authorityFingerprint',
    'baselineDossierId', v_contract ->> 'baselineDossierId',
    'packageId', p_package_id,
    'decisions', jsonb_agg(jsonb_build_object(
      'slot', slot.value ->> 'slot',
      'outputId', slot.value ->> 'outputId',
      'decision', case
        when (slot.value ->> 'outputId')::uuid = any(v_no_change_ids)
          then 'SEM_ALTERAÇÃO'
        when slot.value ->> 'kind' = 'existing' then 'UPDATE'
        else 'NEW'
      end,
      'targetEditorialArticleId', slot.value ->> 'targetEditorialArticleId',
      'publishedArticleId', publication.editorial_article_id,
      'sources', coalesce((
        select jsonb_agg(jsonb_build_object(
          'dossierSourceId', usage.dossier_source_id,
          'newsroomArticleId', usage.newsroom_article_id,
          'newsroomSnapshotId', usage.newsroom_snapshot_id
        ) order by usage.dossier_source_id)
        from public.newsroom_mesa_output_source_usage usage
        where usage.dossier_id = p_dossier_id
          and usage.article_plan_id = (slot.value ->> 'outputId')::uuid
      ), '[]'::jsonb)
    ) order by slot.ordinality)
  ) into v_payload
  from jsonb_array_elements(v_slots) with ordinality slot(value, ordinality)
  left join public.newsroom_mesa_output_publications publication
    on publication.dossier_id = p_dossier_id
    and publication.article_plan_id = (slot.value ->> 'outputId')::uuid;

  v_fingerprint := md5(v_payload::text);
  select event.id into v_event
  from public.newsroom_mesa_publication_events event
  where event.dossier_id = p_dossier_id and event.fingerprint = v_fingerprint;
  if found then
    return query select 'reused'::text, v_event, v_updated_count,
      v_new_count, v_no_change_count;
    return;
  end if;

  insert into public.newsroom_mesa_publication_events(dossier_id, fingerprint, payload)
    values(p_dossier_id, v_fingerprint, v_payload)
    returning id into v_event;

  if not v_was_consolidated then
    select dossier.title into strict v_title
    from public.newsroom_editorial_dossiers dossier
    where dossier.id = p_dossier_id;

    -- Preserve the existing material/provenance projection for materialized
    -- outputs; SEM_ALTERAÇÃO has no output usage and intentionally adds none.
    for v_group in
      select standalone.source_ids, standalone.source_refs,
        array_agg(distinct standalone.article_id order by standalone.article_id) article_ids,
        min(standalone.article_plan_id::text)::uuid key_plan_id
      from (
        select usage.article_plan_id,
          min(usage.editorial_article_id::text)::uuid article_id,
          array_agg(usage.dossier_source_id order by usage.dossier_source_id) source_ids,
          public.newsroom_mesa_normalize_refs_v2(jsonb_agg(jsonb_build_object(
            'newsroomArticleId', usage.newsroom_article_id,
            'newsroomSnapshotId', usage.newsroom_snapshot_id
          ) order by usage.newsroom_article_id, usage.newsroom_snapshot_id)) source_refs
        from public.newsroom_mesa_output_source_usage usage
        where usage.dossier_id = p_dossier_id
        group by usage.article_plan_id
        having count(*) >= 2
      ) standalone
      group by standalone.source_ids, standalone.source_refs
    loop
      v_key := 'output:' || v_group.key_plan_id::text;
      insert into public.newsroom_mesa_material_versions(
        material_key, title, source_refs, article_ids,
        production_dossier_id, publication_event_id
      ) values (
        v_key, v_title, v_group.source_refs, v_group.article_ids,
        p_dossier_id, v_event
      ) returning id into v_version;
      insert into public.newsroom_mesa_theme_materials(theme_id, material_key, version_id)
        values(v_theme_id, v_key, v_version)
        on conflict do nothing;
    end loop;

    insert into public.newsroom_editorial_theme_articles(theme_id, editorial_article_id)
      select v_theme_id, publication.editorial_article_id
      from public.newsroom_mesa_output_publications publication
      where publication.dossier_id = p_dossier_id
      on conflict(theme_id, editorial_article_id) do nothing;

    update public.newsroom_mesa_production_contexts workspace
    set workspace_state = 'consolidated', consolidated_at = now()
    where workspace.dossier_id = p_dossier_id
      and workspace.workspace_state = 'active';
    if not found then
      raise exception 'theme-continuity-finalization-state-conflict';
    end if;
  end if;

  return query select case when v_was_consolidated then 'recorded' else 'consolidated' end,
    v_event, v_updated_count, v_new_count, v_no_change_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_freeze_output_classification_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_plan public.newsroom_editorial_dossier_article_plans%rowtype;
  v_manifest jsonb;
  v_output jsonb;
  v_classification_key text := nullif(
    pg_catalog.lower(
      pg_catalog.btrim(
        pg_catalog.current_setting(
          'jornada.output_classification_key',
          true
        )
      )
    ),
    ''
  );
  v_fingerprint text;
begin
  select *
  into v_plan
  from public.newsroom_editorial_dossier_article_plans as plan_row
  where plan_row.dossier_id = new.dossier_id
    and plan_row.id = new.article_plan_id
  for update;

  if not found then
    raise exception 'mesa-publication-output-invalid'
      using errcode = '23514';
  end if;
  if v_classification_key is null
    or v_classification_key not in (
      'benfica',
      'sporting',
      'fc_porto',
      'other_liga_clubs',
      'outside_liga_other'
    )
  then
    raise exception 'mesa-publication-classification-required'
      using errcode = '23514';
  end if;

  select package_row.manifest
  into v_manifest
  from public.newsroom_editorial_source_packages as package_row
  where package_row.id = new.package_id
  for share;

  select output_row.value
  into v_output
  from pg_catalog.jsonb_array_elements(
    coalesce(v_manifest -> 'outputs', '[]'::jsonb)
  ) as output_row(value)
  where output_row.value ->> 'outputId' = new.article_plan_id::text;

  if not found then
    raise exception 'mesa-publication-package-invalid'
      using errcode = '23514';
  end if;

  v_fingerprint := pg_catalog.encode(
    pg_catalog.sha256(
      pg_catalog.convert_to(
        pg_catalog.jsonb_build_object(
          'dossierId', new.dossier_id,
          'articlePlanId', new.article_plan_id,
          'packageId', new.package_id,
          'publicationFingerprint', new.fingerprint,
          'classificationKey', v_classification_key
        )::text,
        'UTF8'
      )
    ),
    'hex'
  );

  update public.newsroom_editorial_dossier_article_plans as plan_row
  set classification_key = v_classification_key,
      classification_mode = 'manual'
  where plan_row.dossier_id = new.dossier_id
    and plan_row.id = new.article_plan_id
    and (plan_row.classification_key is distinct from v_classification_key
      or plan_row.classification_mode is distinct from 'manual');

  new.classification_key := v_classification_key;
  new.classification_fingerprint := v_fingerprint;
  new.payload := pg_catalog.jsonb_set(
    pg_catalog.jsonb_set(
      pg_catalog.jsonb_set(
        new.payload,
        '{article,classificationKey}',
        pg_catalog.to_jsonb(v_classification_key),
        true
      ),
      '{classificationKey}',
      pg_catalog.to_jsonb(v_classification_key),
      true
    ),
    '{classificationFingerprint}',
    pg_catalog.to_jsonb(v_fingerprint),
    true
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_materialize_mesa_new_output_groups_v2(p_dossier_id uuid, p_expected_revision integer, p_command_id uuid)
 RETURNS TABLE(result jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_header public.newsroom_mesa_new_output_groupings%rowtype;
  v_preparation public.newsroom_mesa_new_output_grouping_preparations%rowtype;
  v_group record;
  v_item jsonb;
  v_context jsonb;
  v_request jsonb;
  v_authority_outputs jsonb:='[]';
  v_outputs jsonb:='[]';
  v_authority_contexts jsonb:='[]';
  v_contexts jsonb:='[]';
  v_plan_ids uuid[]:='{}';
  v_all_source_ids uuid[];
  v_focus_source_ids uuid[];
  v_existing_focus_source_ids uuid[];
  v_theme_source_ids uuid[];
  v_selected_theme_id uuid;
  v_touches_selected_theme boolean;
  v_plan_id uuid;
  v_image_id uuid;
  v_titles text;
  v_i integer:=0;
  v_existing jsonb;
  v_material jsonb;
  v_frozen jsonb;
  v_authority text;
  v_new_count integer;
  v_next_revision integer;
  v_command_fingerprint text;
begin
  if p_dossier_id is null or p_command_id is null or p_expected_revision is null or p_expected_revision<1
  then raise exception 'mesa-grouping-materialization-input-invalid'; end if;
  v_command_fingerprint:=encode(sha256(convert_to(jsonb_build_object(
    'action','materialize','expectedRevision',p_expected_revision
  )::text,'UTF8')),'hex');
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-new-output-groups:'||p_dossier_id::text,0));
  select * into v_header from public.newsroom_mesa_new_output_groupings
  where dossier_id=p_dossier_id for update;
  if not found then raise exception 'mesa-grouping-not-found'; end if;
  if v_header.state='materialized' then
    return query select jsonb_build_object(
      'dossierId',p_dossier_id,'materializationAction','reused',
      'newArticleCount',(select count(*) from public.newsroom_mesa_new_output_groups where dossier_id=p_dossier_id)
    );
    return;
  end if;
  if v_header.revision<>p_expected_revision then raise exception 'mesa-grouping-revision-stale'; end if;
  if v_header.target_count is null
    or v_header.target_count<>(select count(*) from public.newsroom_mesa_new_output_groups where dossier_id=p_dossier_id and seed_kind='selection')
    or exists (
      select 1 from public.newsroom_mesa_new_output_theme_targets target
      where target.dossier_id=p_dossier_id and (
        target.target_count is null
        or target.target_count<>(select count(*) from public.newsroom_mesa_new_output_groups grouped
          where grouped.dossier_id=p_dossier_id and grouped.seed_kind='theme' and grouped.seed_theme_id=target.theme_id)
      )
    )
  then raise exception 'mesa-grouping-target-unresolved'; end if;
  select count(*)::integer into v_new_count
  from public.newsroom_mesa_new_output_groups where dossier_id=p_dossier_id;
  if v_new_count+jsonb_array_length(v_header.existing_outputs) not between 1 and 30
  then raise exception 'mesa-grouping-output-limit'; end if;
  if exists(select 1 from public.newsroom_mesa_output_publications where dossier_id=p_dossier_id)
  then raise exception 'mesa-grouping-structure-locked'; end if;
  select * into strict v_preparation
  from public.newsroom_mesa_new_output_grouping_preparations where dossier_id=p_dossier_id for update;
  select array_agg(dossier_source_id order by sort_order) into v_all_source_ids
  from public.newsroom_mesa_production_context_sources
  where dossier_id=p_dossier_id and production_context_id=v_header.production_context_id;
  for v_existing in select value from jsonb_array_elements(v_header.existing_outputs) value loop
    v_plan_ids:=v_plan_ids||(v_existing ->> 'outputId')::uuid;
  end loop;

  -- Only Article Plans are created here. No source lifecycle, Theme membership,
  -- classification, snapshot or newsroom_mesa_output_source_usage row is touched.
  for v_group in
    select grouped.*,target.title_snapshot theme_title
    from public.newsroom_mesa_new_output_groups grouped
    left join public.newsroom_mesa_new_output_theme_targets target
      on target.dossier_id=grouped.dossier_id and target.theme_id=grouped.seed_theme_id
    where grouped.dossier_id=p_dossier_id order by grouped.position,grouped.id for update of grouped
  loop
    v_i:=v_i+1;
    select string_agg(coalesce(nullif(btrim(source.title_snapshot),''),'Fonte'), ' + ' order by membership.sort_order)
    into v_titles
    from public.newsroom_mesa_new_output_group_sources membership
    join public.newsroom_editorial_dossier_sources source
      on source.dossier_id=membership.dossier_id and source.id=membership.dossier_source_id
    where membership.group_id=v_group.id;
    select dossier_image.id into v_image_id
    from public.newsroom_mesa_new_output_group_sources membership
    join public.newsroom_editorial_dossier_sources source
      on source.dossier_id=membership.dossier_id and source.id=membership.dossier_source_id
    join public.newsroom_editorial_dossier_images dossier_image
      on dossier_image.dossier_id=source.dossier_id and dossier_image.origin_kind='newsroom'
      and dossier_image.newsroom_article_id=source.newsroom_article_id
    where membership.group_id=v_group.id
    order by membership.sort_order,dossier_image.created_at,dossier_image.id limit 1;
    select array_agg(source.newsroom_article_id order by membership.sort_order)
    into v_focus_source_ids
    from public.newsroom_mesa_new_output_group_sources membership
    join public.newsroom_editorial_dossier_sources source
      on source.dossier_id=membership.dossier_id and source.id=membership.dossier_source_id
    where membership.group_id=v_group.id;
    if cardinality(v_focus_source_ids) not between 1 and 20 then raise exception 'mesa-grouping-seed-invalid'; end if;
    select saved.article_plan_id into strict v_plan_id
    from public.newsroom_save_mesa_context_article_plan_v1(
      p_dossier_id,null,
      left('Artigo '||lpad(v_i::text,2,'0')||' — '||coalesce(v_group.theme_title,v_titles),180),
      'planned',(jsonb_array_length(v_header.existing_outputs)+v_i)*10,'news','standard',
      left(case when v_group.seed_kind='theme'
        then 'Partir do Tema «'||v_group.theme_title||'». Escolher automaticamente o foco mais relevante ainda não coberto, salvo instrução editorial posterior.'
        else 'Sintetizar o assunto comum das fontes agrupadas. Todo o material congelado desta Produção permanece disponível como contexto.' end,12000),
      v_all_source_ids,v_header.production_context_id
    ) saved;
    perform public.newsroom_save_dossier_article_plan_state_v1(
      p_dossier_id,v_plan_id,'new',null,'{}',
      case when v_image_id is null then 'unselected' else 'dossier_image' end,v_image_id
    );
    update public.newsroom_mesa_new_output_groups
    set article_plan_id=v_plan_id,state='materialized',updated_at=clock_timestamp()
    where id=v_group.id;
    v_plan_ids:=v_plan_ids||v_plan_id;
    v_item:=jsonb_build_object(
      'slot','NEW_'||lpad(v_i::text,2,'0'),'contextKey','selection:'||v_preparation.preparation_key,
      'kind','new','target',null,'focusSourceIds',to_jsonb(v_focus_source_ids)
    );
    v_authority_outputs:=v_authority_outputs||jsonb_build_array(v_item);
    v_outputs:=v_outputs||jsonb_build_array(v_item||jsonb_build_object(
      'outputId',v_plan_id,'productionContextId',v_header.production_context_id
    ));
  end loop;

  v_request:=jsonb_set(
    public.newsroom_mesa_grouping_request_v1(v_preparation.request),
    '{selection,newArticleCount}',to_jsonb(v_new_count)
  );
  for v_context in select value from jsonb_array_elements(v_preparation.base_preview -> 'contexts') value loop
    v_authority_contexts:=v_authority_contexts||jsonb_build_array(jsonb_set(v_context,'{newArticleCount}',to_jsonb(v_new_count)));
    v_contexts:=v_contexts||jsonb_build_array(
      jsonb_set(v_context,'{newArticleCount}',to_jsonb(v_new_count))
      ||jsonb_build_object('productionContextId',v_header.production_context_id)
    );
  end loop;
  for v_item in
    select item.value
    from jsonb_array_elements(v_preparation.base_preview -> 'outputs') with ordinality item(value, ordinality)
    where item.value ->> 'kind'='existing'
    order by item.ordinality desc
  loop
    select value into strict v_existing from jsonb_array_elements(v_header.existing_outputs) value
    where value ->> 'slot'=v_item ->> 'slot';
    select coalesce(array_agg((evidence_source.value #>> '{}')::uuid order by evidence_source.value #>> '{}'),'{}'::uuid[])
    into v_existing_focus_source_ids
    from jsonb_array_elements(coalesce(v_item #> '{target,evidence,sourceIds}','[]'::jsonb)) evidence_source(value)
    where exists (
      select 1 from jsonb_array_elements(v_context -> 'sources') captured(value)
      where captured.value ->> 'newsroomArticleId'=evidence_source.value #>> '{}'
    );
    if jsonb_array_length(v_request -> 'selection' -> 'themeIds')=1 then
      v_selected_theme_id:=(v_request -> 'selection' -> 'themeIds' ->> 0)::uuid;
      select coalesce(array_agg((captured.value ->> 'newsroomArticleId')::uuid order by captured.value ->> 'newsroomArticleId'),'{}'::uuid[])
      into v_theme_source_ids
      from jsonb_array_elements(v_context -> 'sources') captured(value)
      where not exists (
        select 1 from jsonb_array_elements(v_request -> 'selection' -> 'sourceIds') explicit(value)
        where explicit.value #>> '{}'=captured.value ->> 'newsroomArticleId'
      );
      v_touches_selected_theme:=exists (
        select 1 from jsonb_array_elements(coalesce(v_item #> '{target,evidence,themeIds}','[]'::jsonb)) evidence_theme(value)
        where evidence_theme.value #>> '{}'=v_selected_theme_id::text
      ) or v_existing_focus_source_ids&&v_theme_source_ids;
      if v_touches_selected_theme and cardinality(v_theme_source_ids)>0 then
        select array_agg(source_id order by source_id) into v_existing_focus_source_ids
        from (select distinct source_id
          from unnest(v_existing_focus_source_ids||v_theme_source_ids) focused_source(source_id)) focused;
      end if;
    end if;
    if cardinality(v_existing_focus_source_ids)>0 then
      v_item:=v_item||jsonb_build_object('focusSourceIds',to_jsonb(v_existing_focus_source_ids));
    end if;
    v_authority_outputs:=jsonb_build_array(v_item)||v_authority_outputs;
    v_outputs:=jsonb_build_array(v_item||jsonb_build_object(
      'outputId',v_existing -> 'outputId','productionContextId',v_header.production_context_id
    ))||v_outputs;
  end loop;
  v_material:=(v_preparation.base_preview-'capturedAt'-'authorityFingerprint'-'request'-'contexts'-'outputs'-'totals')
    ||jsonb_build_object(
      'request',v_request,'contexts',v_authority_contexts,'outputs',v_authority_outputs,
      'totals',jsonb_build_object(
        'contexts',1,
        'sources',jsonb_array_length(v_preparation.base_preview -> 'contexts' -> 0 -> 'sources'),
        'reviews',jsonb_array_length(v_header.existing_outputs),
        'newArticles',v_new_count
      )
    );
  v_authority:=encode(sha256(convert_to(v_material::text,'UTF8')),'hex');
  v_frozen:=v_material||jsonb_build_object(
    'dossierId',p_dossier_id,
    'capturedAt',v_preparation.base_preview -> 'capturedAt',
    'authorityFingerprint',v_authority,
    'contexts',v_contexts,
    'outputs',v_outputs
  );
  insert into public.newsroom_mesa_intent_preparations(
    preparation_key,dossier_id,request,authority_fingerprint,captured_at,frozen_plan
  ) values(
    v_preparation.preparation_key,p_dossier_id,v_request,v_authority,
    (v_frozen ->> 'capturedAt')::timestamptz,v_frozen
  );
  perform public.newsroom_set_mesa_shared_outputs_v2(p_dossier_id,v_plan_ids);
  update public.newsroom_mesa_new_output_groupings
  set state='materialized',revision=revision+1,updated_at=clock_timestamp()
  where dossier_id=p_dossier_id returning revision into v_next_revision;
  update public.newsroom_mesa_production_contexts
  set selection_payload=selection_payload||jsonb_build_object(
    'productionIntents',v_frozen,
    'productionGroupingV2',jsonb_build_object(
      'version',2,'state','materialized','preparationKey',v_preparation.preparation_key,
      'authorityFingerprint',v_authority
    )
  ) where dossier_id=p_dossier_id;
  insert into public.newsroom_mesa_new_output_grouping_commands(
    dossier_id,command_id,payload_fingerprint,result_revision
  ) values(p_dossier_id,p_command_id,v_command_fingerprint,v_next_revision);
  return query select jsonb_build_object(
    'dossierId',p_dossier_id,'materializationAction','created','newArticleCount',v_new_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_after_article_publication_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_dossier uuid;
begin
  -- Read canonical final state, not a stale NEW.status from an earlier statement in the transaction.
  if not exists(select 1 from public.editorial_articles a where a.id=new.id and a.status='published') then return null; end if;
  for v_dossier in select distinct p.dossier_id from public.newsroom_editorial_dossier_article_plans p
    join public.newsroom_mesa_production_contexts c on c.dossier_id=p.dossier_id where p.editorial_article_id=new.id loop
    perform public.newsroom_mesa_consolidate_publication_v2(v_dossier);
  end loop;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_after_plan_publication_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op<>'DELETE' then perform public.newsroom_mesa_consolidate_publication_v2(new.dossier_id); end if;
  if tg_op='DELETE' or (tg_op='UPDATE' and old.dossier_id is distinct from new.dossier_id) then
    perform public.newsroom_mesa_consolidate_publication_v2(old.dossier_id); end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_base_material_v2(p_key text)
 RETURNS TABLE(title text, source_refs jsonb, article_ids uuid[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id uuid; v_manifest jsonb; v_group integer; v_refs jsonb; v_articles uuid[]; v_title text; v_ambiguous integer;
begin
  if p_key ~* '^dossier:[0-9a-f-]{36}$' then
    v_id := split_part(p_key,':',2)::uuid;
    select d.title into v_title from public.newsroom_editorial_dossiers d where d.id=v_id;
    if not found then raise exception 'mesa-material-not-found'; end if;
    select coalesce(jsonb_agg(jsonb_build_object('newsroomArticleId',s.newsroom_article_id,'newsroomSnapshotId',s.newsroom_snapshot_id)),'[]'::jsonb)
      into v_refs from public.newsroom_editorial_dossier_sources s where s.dossier_id=v_id and s.included;
    select coalesce(array_agg(distinct a.id order by a.id),'{}'::uuid[]) into v_articles
      from public.newsroom_editorial_dossier_article_plans p join public.editorial_articles a on a.id=p.editorial_article_id
      where p.dossier_id=v_id and a.status='published';
    if cardinality(v_articles)=0 or exists(select 1 from public.newsroom_mesa_production_contexts c where c.dossier_id=v_id) then
      raise exception 'mesa-material-not-published'; end if;
  elsif p_key ~* '^package:[0-9a-f-]{36}:([1-9]|[12][0-9]|30)$' then
    v_id:=split_part(p_key,':',2)::uuid; v_group:=split_part(p_key,':',3)::integer;
    select p.manifest into v_manifest from public.newsroom_editorial_source_packages p where p.id=v_id;
    if not found then raise exception 'mesa-material-not-found'; end if;
    with entries as (
      select e, ord::integer entry_order,
        case when coalesce(e->>'position','') ~ '^[1-9][0-9]{0,5}$' then (e->>'position')::integer else ord::integer end source_position
      from jsonb_array_elements(v_manifest->'entries') with ordinality as item(e,ord)
      where e->>'articlePosition'=v_group::text and e->>'status'='prepared'
        and coalesce(e->>'newsroomArticleId','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        and coalesce(e->>'newsroomSnapshotId','') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    ), usage as (
      select e,source_position,entry_order,a.id article_id from entries cross join lateral (
        select o->>'publishedArticleId' id from jsonb_array_elements(case when jsonb_typeof(v_manifest->'outputs')='array' then v_manifest->'outputs' else '[]'::jsonb end) o
          where o->>'sourceArticlePosition'=v_group::text and nullif(o->>'usedAt','') is not null
        union select e->>'publishedArticleId' where nullif(e->>'usedAt','') is not null
      ) proof join public.editorial_articles a on a.id::text=lower(proof.id) and a.status='published'
    ), ambiguous as (
      select lower(e->>'newsroomArticleId') article_id,source_position
      from usage group by lower(e->>'newsroomArticleId'),source_position
      having count(distinct lower(e->>'newsroomSnapshotId'))>1
    ), ranked as (
      select e,source_position,entry_order,
        row_number() over(partition by lower(e->>'newsroomArticleId') order by source_position desc,entry_order desc) source_rank
      from usage
    ) select (select u.e->>'title' from usage u order by u.entry_order limit 1),
      coalesce((select jsonb_agg(jsonb_build_object('newsroomArticleId',r.e->>'newsroomArticleId','newsroomSnapshotId',r.e->>'newsroomSnapshotId')
        order by lower(r.e->>'newsroomArticleId')) from ranked r where r.source_rank=1),'[]'::jsonb),
      coalesce((select array_agg(distinct u.article_id order by u.article_id) from usage u),'{}'::uuid[]),
      (select count(*)::integer from ambiguous)
      into v_title,v_refs,v_articles,v_ambiguous;
    if v_ambiguous>0 then raise exception 'mesa-material-version-conflict'; end if;
  else raise exception 'mesa-material-key-invalid'; end if;
  v_refs:=public.newsroom_mesa_normalize_refs_v2(v_refs);
  if jsonb_array_length(v_refs)<2 then raise exception 'mesa-material-not-a-dossier'; end if;
  return query select coalesce(v_title,'Grupo editorial'),v_refs,v_articles;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_capture_material_v2(p_ref jsonb)
 RETURNS newsroom_mesa_material_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row public.newsroom_mesa_material_versions%rowtype; v_base record; v_expected jsonb; v_key text;
begin
  v_key:=lower(p_ref->>'key');
  v_expected:=public.newsroom_mesa_normalize_refs_v2(p_ref->'sources');
  if jsonb_array_length(v_expected)<2 then raise exception 'mesa-material-not-a-dossier'; end if;
  if nullif(p_ref->>'versionId','') is not null then
    select * into v_row from public.newsroom_mesa_material_versions v where v.id=(p_ref->>'versionId')::uuid and v.material_key=v_key;
    if not found or v_row.source_refs is distinct from v_expected then raise exception 'mesa-material-stale'; end if;
    return v_row;
  end if;
  select * into v_base from public.newsroom_mesa_base_material_v2(v_key);
  if v_base.source_refs is distinct from v_expected then raise exception 'mesa-material-stale'; end if;
  select * into v_row from public.newsroom_mesa_material_versions v where v.material_key=v_key
    and v.source_refs=v_base.source_refs and v.article_ids=v_base.article_ids and v.publication_event_id is null order by v.revision desc limit 1;
  if found then return v_row; end if;
  insert into public.newsroom_mesa_material_versions(material_key,title,source_refs,article_ids)
    values(v_key,v_base.title,v_base.source_refs,v_base.article_ids) returning * into v_row;
  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_consolidate_publication_v3(p_dossier_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_payload jsonb; v_fingerprint text; v_event uuid; v_title text;
  v_group record; v_origin public.newsroom_mesa_material_versions%rowtype;
  v_refs jsonb; v_articles uuid[]; v_version uuid; v_key text;
begin
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id=p_dossier_id for update;
  if not found or v_context.workspace_contract_version<>2 or v_context.workspace_role<>'technical'
    or v_context.workspace_state<>'active' then return false; end if;
  if not exists(select 1 from public.newsroom_editorial_dossier_article_plans p
      where p.dossier_id=p_dossier_id and p.status<>'cancelled') then return false; end if;
  if exists(select 1 from public.newsroom_editorial_dossier_article_plans p
      left join public.newsroom_mesa_output_publications op
        on op.dossier_id=p.dossier_id and op.article_plan_id=p.id
      left join public.editorial_articles a on a.id=op.editorial_article_id
      where p.dossier_id=p_dossier_id and p.status<>'cancelled'
        and (op.article_plan_id is null or a.status<>'published')) then return false; end if;
  select jsonb_build_object(
    'contractVersion',2,
    'outputs',coalesce(jsonb_agg(output_row.payload order by output_row.article_plan_id),'[]'::jsonb)
  ) into v_payload
  from (
    select op.article_plan_id,jsonb_build_object(
      'outputId',op.article_plan_id,'articleId',op.editorial_article_id,
      'sources',coalesce((select jsonb_agg(u.dossier_source_id order by u.dossier_source_id)
        from public.newsroom_mesa_output_source_usage u
        where u.dossier_id=op.dossier_id and u.article_plan_id=op.article_plan_id),'[]'::jsonb),
      'origin',jsonb_build_object('kind',op.origin_kind,'sourceId',op.origin_dossier_source_id,
        'materialKey',op.material_key,'versionId',op.material_version_id)
    ) as payload
    from public.newsroom_mesa_output_publications op
    where op.dossier_id=p_dossier_id
  ) as output_row;
  v_fingerprint:=md5(v_payload::text);
  select e.id into v_event from public.newsroom_mesa_publication_events e
    where e.dossier_id=p_dossier_id and e.fingerprint=v_fingerprint;
  if found then return false; end if;
  insert into public.newsroom_mesa_publication_events(dossier_id,fingerprint,payload)
    values(p_dossier_id,v_fingerprint,v_payload) returning id into v_event;
  select d.title into v_title from public.newsroom_editorial_dossiers d where d.id=p_dossier_id;

  for v_group in
    select op.origin_kind,op.origin_dossier_source_id,op.material_key,op.material_version_id,
      array_agg(distinct op.article_plan_id order by op.article_plan_id) plan_ids
    from public.newsroom_mesa_output_publications op where op.dossier_id=p_dossier_id
    group by op.origin_kind,op.origin_dossier_source_id,op.material_key,op.material_version_id,
      case when op.origin_kind='source' then op.article_plan_id else null end
  loop
    select public.newsroom_mesa_normalize_refs_v2(coalesce(jsonb_agg(jsonb_build_object(
      'newsroomArticleId',u.newsroom_article_id,'newsroomSnapshotId',u.newsroom_snapshot_id)
      order by u.newsroom_article_id),'[]'::jsonb)),
      array_agg(distinct u.editorial_article_id order by u.editorial_article_id)
      into v_refs,v_articles
      from public.newsroom_mesa_output_source_usage u
      where u.dossier_id=p_dossier_id and u.article_plan_id=any(v_group.plan_ids);
    if v_group.origin_kind='material' then
      select * into strict v_origin from public.newsroom_mesa_material_versions v
        where v.material_key=v_group.material_key and v.id=v_group.material_version_id;
      v_refs:=public.newsroom_mesa_normalize_refs_v2(v_origin.source_refs || v_refs);
      v_articles:=array(select distinct a from unnest(v_origin.article_ids || v_articles) a order by a);
      insert into public.newsroom_mesa_material_versions(
        material_key,title,source_refs,article_ids,parent_version_id,production_dossier_id,publication_event_id
      ) values (
        v_origin.material_key,v_origin.title,v_refs,v_articles,v_origin.id,p_dossier_id,v_event
      ) returning id into v_version;
      if v_context.theme_id is not null then
        update public.newsroom_mesa_theme_materials set version_id=v_version
          where theme_id=v_context.theme_id and material_key=v_origin.material_key
            and version_id=v_origin.id;
        if not found then
          insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
            values(v_context.theme_id,v_origin.material_key,v_version) on conflict do nothing;
        end if;
      end if;
    elsif jsonb_array_length(v_refs)>=2 then
      v_key:='output:'||(v_group.plan_ids)[1]::text;
      insert into public.newsroom_mesa_material_versions(
        material_key,title,source_refs,article_ids,production_dossier_id,publication_event_id
      ) values (v_key,v_title,v_refs,v_articles,p_dossier_id,v_event)
      returning id into v_version;
      if v_context.theme_id is not null then
        insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
          values(v_context.theme_id,v_key,v_version) on conflict do nothing;
      end if;
    end if;
  end loop;
  if v_context.theme_id is not null then
    insert into public.newsroom_editorial_theme_articles(theme_id,editorial_article_id)
      select v_context.theme_id,op.editorial_article_id
      from public.newsroom_mesa_output_publications op where op.dossier_id=p_dossier_id
      on conflict(theme_id,editorial_article_id) do nothing;
  end if;
  update public.newsroom_mesa_production_contexts set workspace_state='consolidated',consolidated_at=now()
    where dossier_id=p_dossier_id;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_consolidate_publication_v4(p_dossier_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_payload jsonb; v_fingerprint text; v_event uuid; v_title text;
  v_material jsonb; v_origin public.newsroom_mesa_material_versions%rowtype;
  v_group record; v_articles uuid[]; v_version uuid; v_key text;
  v_source_scope text; v_source_scope_count integer;
begin
  select * into v_context from public.newsroom_mesa_production_contexts context
    where context.dossier_id = p_dossier_id for update;
  if not found or v_context.workspace_contract_version <> 2 or v_context.workspace_role <> 'technical'
    or v_context.workspace_state <> 'active' then return false; end if;
  if not exists(select 1 from public.newsroom_editorial_dossier_article_plans plan
      where plan.dossier_id = p_dossier_id and plan.status <> 'cancelled') then return false; end if;
  if exists(select 1 from public.newsroom_editorial_dossier_article_plans plan
      left join public.newsroom_mesa_output_publications publication
        on publication.dossier_id = plan.dossier_id and publication.article_plan_id = plan.id
      left join public.editorial_articles article on article.id = publication.editorial_article_id
      where plan.dossier_id = p_dossier_id and plan.status <> 'cancelled'
        and (publication.article_plan_id is null or article.status <> 'published')) then return false; end if;
  if exists(select 1 from public.newsroom_mesa_output_publications publication
      where publication.dossier_id = p_dossier_id and publication.source_scope is null) then
    return public.newsroom_mesa_consolidate_publication_v3(p_dossier_id);
  end if;
  select min(publication.source_scope),count(distinct publication.source_scope)::integer
  into v_source_scope,v_source_scope_count
  from public.newsroom_mesa_output_publications publication
  where publication.dossier_id = p_dossier_id;
  if v_source_scope_count <> 1 or v_source_scope not in ('workspace','context') then return false; end if;
  select jsonb_build_object(
    'contractVersion',2,
    'sourceScope',v_source_scope,
    'outputs',coalesce(jsonb_agg(output_row.payload order by output_row.article_plan_id),'[]'::jsonb)
  ) into v_payload
  from (
    select publication.article_plan_id,
      jsonb_build_object(
        'outputId',publication.article_plan_id,
        'articleId',publication.editorial_article_id,
        'sources',coalesce((select jsonb_agg(jsonb_build_object(
          'dossierSourceId',usage.dossier_source_id,
          'newsroomArticleId',usage.newsroom_article_id,
          'newsroomSnapshotId',usage.newsroom_snapshot_id
        ) order by usage.dossier_source_id)
          from public.newsroom_mesa_output_source_usage usage
          where usage.dossier_id = publication.dossier_id
            and usage.article_plan_id = publication.article_plan_id),'[]'::jsonb)
      ) || case when v_source_scope='context'
        then jsonb_build_object('contextId',publication.production_context_id)
        else '{}'::jsonb end as payload
    from public.newsroom_mesa_output_publications publication
    where publication.dossier_id = p_dossier_id
  ) output_row;
  v_fingerprint := md5(v_payload::text);
  select event.id into v_event from public.newsroom_mesa_publication_events event
    where event.dossier_id = p_dossier_id and event.fingerprint = v_fingerprint;
  if found then return false; end if;
  insert into public.newsroom_mesa_publication_events(dossier_id,fingerprint,payload)
    values(p_dossier_id,v_fingerprint,v_payload) returning id into v_event;
  select dossier.title into v_title from public.newsroom_editorial_dossiers dossier
    where dossier.id = p_dossier_id;
  for v_material in
    select value from jsonb_array_elements(coalesce(v_context.material_refs,'[]'::jsonb))
  loop
    if jsonb_typeof(v_material -> 'sources') <> 'array'
      or nullif(v_material ->> 'key','') is null
      or nullif(v_material ->> 'versionId','') is null then
      raise exception 'mesa-publication-workspace-invalid';
    end if;
    select array_agg(distinct usage.editorial_article_id order by usage.editorial_article_id)
      into v_articles
      from public.newsroom_mesa_output_source_usage usage
      where usage.dossier_id = p_dossier_id and exists(
        select 1 from jsonb_array_elements(v_material -> 'sources') ref
        where lower(ref ->> 'newsroomArticleId') = usage.newsroom_article_id::text
          and lower(ref ->> 'newsroomSnapshotId') = usage.newsroom_snapshot_id::text
      );
    if coalesce(cardinality(v_articles),0)=0 then continue; end if;
    select * into strict v_origin from public.newsroom_mesa_material_versions version
      where version.material_key = lower(v_material ->> 'key')
        and version.id = (v_material ->> 'versionId')::uuid;
    v_articles := array(select distinct article_id from unnest(v_origin.article_ids || v_articles) article_id order by article_id);
    if v_articles = v_origin.article_ids then continue; end if;
    insert into public.newsroom_mesa_material_versions(
      material_key,title,source_refs,article_ids,parent_version_id,production_dossier_id,publication_event_id
    ) values (
      v_origin.material_key,v_origin.title,v_origin.source_refs,v_articles,v_origin.id,p_dossier_id,v_event
    ) returning id into v_version;
    if v_context.theme_id is not null then
      update public.newsroom_mesa_theme_materials theme_material set version_id=v_version
      where theme_material.theme_id=v_context.theme_id
        and theme_material.material_key=v_origin.material_key
        and theme_material.version_id=v_origin.id;
      if not found then
        insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
        values(v_context.theme_id,v_origin.material_key,v_version) on conflict do nothing;
      end if;
    end if;
  end loop;
  for v_group in
    select standalone.source_ids,standalone.source_refs,
      array_agg(distinct standalone.article_id order by standalone.article_id) article_ids,
      min(standalone.article_plan_id::text)::uuid key_plan_id
    from (
      select usage.article_plan_id,min(usage.editorial_article_id::text)::uuid article_id,
        array_agg(usage.dossier_source_id order by usage.dossier_source_id) source_ids,
        public.newsroom_mesa_normalize_refs_v2(jsonb_agg(jsonb_build_object(
          'newsroomArticleId',usage.newsroom_article_id,
          'newsroomSnapshotId',usage.newsroom_snapshot_id
        ) order by usage.newsroom_article_id,usage.newsroom_snapshot_id)) source_refs
      from public.newsroom_mesa_output_source_usage usage
      where usage.dossier_id = p_dossier_id and not exists(
        select 1
        from jsonb_array_elements(coalesce(v_context.material_refs,'[]'::jsonb)) material,
          jsonb_array_elements(coalesce(material -> 'sources','[]'::jsonb)) ref
        where lower(ref ->> 'newsroomArticleId') = usage.newsroom_article_id::text
          and lower(ref ->> 'newsroomSnapshotId') = usage.newsroom_snapshot_id::text
      )
      group by usage.article_plan_id
      having count(*) >= 2
    ) standalone
    group by standalone.source_ids,standalone.source_refs
  loop
    v_key := 'output:' || v_group.key_plan_id::text;
    insert into public.newsroom_mesa_material_versions(
      material_key,title,source_refs,article_ids,production_dossier_id,publication_event_id
    ) values(v_key,v_title,v_group.source_refs,v_group.article_ids,p_dossier_id,v_event)
    returning id into v_version;
    if v_context.theme_id is not null then
      insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
      values(v_context.theme_id,v_key,v_version) on conflict do nothing;
    end if;
  end loop;
  if v_context.theme_id is not null then
    insert into public.newsroom_editorial_theme_articles(theme_id,editorial_article_id)
    select v_context.theme_id,publication.editorial_article_id
    from public.newsroom_mesa_output_publications publication
    where publication.dossier_id = p_dossier_id
    on conflict(theme_id,editorial_article_id) do nothing;
  end if;
  if v_source_scope='context' then
    insert into public.newsroom_editorial_theme_articles(theme_id,editorial_article_id)
    select context_item.theme_id,publication.editorial_article_id
    from public.newsroom_mesa_output_publications publication
    join public.newsroom_mesa_production_context_items context_item
      on context_item.dossier_id=publication.dossier_id
      and context_item.id=publication.production_context_id
    where publication.dossier_id=p_dossier_id
      and context_item.context_kind='theme'
    on conflict(theme_id,editorial_article_id) do nothing;
  end if;
  update public.newsroom_mesa_production_contexts
  set workspace_state='consolidated',consolidated_at=now()
  where dossier_id=p_dossier_id;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_containment_write_lock_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('newsroom-mesa-organization-v1', 0)
  );
  update public.newsroom_mesa_containment_guard
    set revision = not revision where singleton;
  if not found then raise exception 'mesa-organization-containment-guard-missing'; end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_dossier_source_membership_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_theme_id uuid;
begin
  if new.included then
    select m.theme_id into v_theme_id from public.newsroom_editorial_theme_dossiers m
