CREATE OR REPLACE FUNCTION public.newsroom_mesa_grouping_authority_v2(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_v1_request jsonb := public.newsroom_mesa_grouping_request_v1(p_request);
  v_preview jsonb;
  v_context jsonb;
  v_themes jsonb := '[]';
  v_loose_sources jsonb := '[]';
  v_theme_id uuid;
  v_theme_title text;
  v_theme_source_ids uuid[];
  v_position bigint;
  v_material jsonb;
begin
  select value.plan into strict v_preview
  from public.newsroom_mesa_preview_intents_v1(v_v1_request) value;
  select value into strict v_context
  from jsonb_array_elements(v_preview -> 'contexts') value
  where value ->> 'kind' = 'selection';

  for v_theme_id, v_position in
    select (value #>> '{}')::uuid, ordinality
    from jsonb_array_elements(v_v1_request -> 'selection' -> 'themeIds') with ordinality selected(value, ordinality)
  loop
    select theme.title into v_theme_title
    from public.newsroom_editorial_themes theme
    where theme.id = v_theme_id and theme.status = 'open';
    if not found then raise exception 'mesa-grouping-theme-unavailable'; end if;

    select array_agg(membership.newsroom_article_id order by membership.newsroom_article_id)
    into v_theme_source_ids
    from public.newsroom_editorial_theme_sources membership
    where membership.theme_id = v_theme_id;
    if cardinality(coalesce(v_theme_source_ids, '{}'::uuid[])) not between 1 and 20
      or exists (
        select 1 from unnest(v_theme_source_ids) source_id
        where not exists (
          select 1 from jsonb_array_elements(v_context -> 'sources') source
          where source ->> 'newsroomArticleId' = source_id::text
        )
      )
    then raise exception 'mesa-grouping-theme-sources-invalid'; end if;
    v_themes := v_themes || jsonb_build_array(jsonb_build_object(
      'themeId',v_theme_id,'title',v_theme_title,'position',v_position,'seedSourceIds',to_jsonb(v_theme_source_ids)
    ));
  end loop;

  select coalesce(jsonb_agg(explicit.value order by explicit.value #>> '{}'),'[]'::jsonb)
  into v_loose_sources
  from jsonb_array_elements(v_v1_request -> 'selection' -> 'sourceIds') explicit(value)
  where not exists (
    select 1
    from public.newsroom_editorial_theme_sources membership
    where membership.newsroom_article_id=(explicit.value #>> '{}')::uuid
      and membership.theme_id in (
        select (selected.value #>> '{}')::uuid
        from jsonb_array_elements(v_v1_request -> 'selection' -> 'themeIds') selected(value)
      )
  );

  v_material := jsonb_build_object(
    'request',v_v1_request,
    'baseAuthorityFingerprint',v_preview -> 'authorityFingerprint',
    'themes',v_themes,
    'looseSourceIds',v_loose_sources
  );
  return jsonb_build_object(
    'version',2,
    'authorityFingerprint',encode(sha256(convert_to(v_material::text,'UTF8')),'hex'),
    'material',v_material,
    'basePreview',v_preview,
    'themes',v_themes,
    'looseSourceIds',v_loose_sources
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_grouping_request_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_selection jsonb;
  v_normalized_selection jsonb;
  v_uuid constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  if jsonb_typeof(p_request) is distinct from 'object'
    or not (p_request ?& array['version','preparationKey','title','selection'])
    or p_request - array['version','preparationKey','title','selection'] <> '{}'
    or p_request -> 'version' is distinct from '2'::jsonb
    or lower(coalesce(p_request ->> 'preparationKey','')) !~ v_uuid
    or length(btrim(coalesce(p_request ->> 'title',''))) not between 1 and 180
    or jsonb_typeof(p_request -> 'selection') is distinct from 'object'
  then raise exception 'mesa-grouping-input-invalid'; end if;
  v_selection := p_request -> 'selection';
  if not (v_selection ?& array['sourceIds','themeIds','candidateArticleIds','reviewArticleIds'])
    or v_selection - array['sourceIds','themeIds','candidateArticleIds','reviewArticleIds'] <> '{}'
    or jsonb_typeof(v_selection -> 'sourceIds') is distinct from 'array'
    or jsonb_typeof(v_selection -> 'themeIds') is distinct from 'array'
    or jsonb_typeof(v_selection -> 'candidateArticleIds') is distinct from 'array'
    or jsonb_typeof(v_selection -> 'reviewArticleIds') is distinct from 'array'
    or jsonb_array_length(v_selection -> 'sourceIds') + jsonb_array_length(v_selection -> 'themeIds') < 1
    or jsonb_array_length(v_selection -> 'sourceIds') > 20
    or jsonb_array_length(v_selection -> 'themeIds') > 20
    or jsonb_array_length(v_selection -> 'candidateArticleIds') > 200
    or jsonb_array_length(v_selection -> 'reviewArticleIds') > 30
  then raise exception 'mesa-grouping-input-invalid'; end if;
  if exists (
    select 1 from jsonb_array_elements(v_selection -> 'sourceIds') value
    where jsonb_typeof(value) <> 'string' or lower(value #>> '{}') !~ v_uuid
  ) or exists (
    select 1 from jsonb_array_elements(v_selection -> 'themeIds') value
    where jsonb_typeof(value) <> 'string' or lower(value #>> '{}') !~ v_uuid
  ) or exists (
    select 1 from jsonb_array_elements(v_selection -> 'candidateArticleIds') value
    where jsonb_typeof(value) <> 'string' or lower(value #>> '{}') !~ v_uuid
  ) or exists (
    select 1 from jsonb_array_elements(v_selection -> 'reviewArticleIds') value
    where jsonb_typeof(value) <> 'string' or lower(value #>> '{}') !~ v_uuid
  ) then raise exception 'mesa-grouping-input-invalid'; end if;
  v_normalized_selection := jsonb_build_object(
    'sourceIds',(select coalesce(jsonb_agg(to_jsonb(lower(value #>> '{}')) order by lower(value #>> '{}')),'[]') from jsonb_array_elements(v_selection -> 'sourceIds') value),
    'themeIds',(select coalesce(jsonb_agg(to_jsonb(lower(value #>> '{}')) order by lower(value #>> '{}')),'[]') from jsonb_array_elements(v_selection -> 'themeIds') value),
    'candidateArticleIds',(select coalesce(jsonb_agg(to_jsonb(lower(value #>> '{}')) order by lower(value #>> '{}')),'[]') from jsonb_array_elements(v_selection -> 'candidateArticleIds') value),
    'reviewArticleIds',(select coalesce(jsonb_agg(to_jsonb(lower(value #>> '{}')) order by lower(value #>> '{}')),'[]') from jsonb_array_elements(v_selection -> 'reviewArticleIds') value),
    'newArticleCount',1
  );
  if exists (
    select value #>> '{}' from jsonb_array_elements(v_normalized_selection -> 'reviewArticleIds') value
    except select value #>> '{}' from jsonb_array_elements(v_normalized_selection -> 'candidateArticleIds') value
  ) or exists (
    select value #>> '{}' from jsonb_array_elements(v_normalized_selection -> 'sourceIds') value group by value #>> '{}' having count(*) > 1
  ) or exists (
    select value #>> '{}' from jsonb_array_elements(v_normalized_selection -> 'themeIds') value group by value #>> '{}' having count(*) > 1
  ) then raise exception 'mesa-grouping-input-invalid'; end if;
  return public.newsroom_mesa_normalize_intent_v1(jsonb_build_object(
    'version',1,'preparationKey',lower(p_request ->> 'preparationKey'),'title',btrim(p_request ->> 'title'),
    'themes','[]'::jsonb,'sources','[]'::jsonb,'selection',v_normalized_selection
  ));
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_intent_latest_article_receipts_v2(p_article_ids uuid[])
 RETURNS TABLE(receipts jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ids uuid[];
begin
  if p_article_ids is null or cardinality(p_article_ids) not between 1 and 30
    or array_position(p_article_ids,null) is not null
  then raise exception 'mesa-intent-article-receipts-input-invalid'; end if;
  select array_agg(distinct id order by id) into v_ids from unnest(p_article_ids) requested(id);
  if cardinality(v_ids)<>cardinality(p_article_ids) then
    raise exception 'mesa-intent-article-receipts-input-invalid';
  end if;

  return query
  select coalesce(jsonb_agg(jsonb_build_object(
    'contextKey',r.context_key,'themeId',r.theme_id,'articleId',r.editorial_article_id,
    'slot',r.slot,'decision',r.decision,
    'capturedAt',to_char(r.captured_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'sources',r.sources
  ) order by r.editorial_article_id,r.dossier_id,r.output_id),'[]'::jsonb)
  from (
    select x.*,rank() over(partition by x.editorial_article_id order by x.captured_at desc) capture_rank
    from public.newsroom_mesa_intent_article_receipts x
    where x.editorial_article_id=any(v_ids)
  ) r
  where r.capture_rank=1;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_intent_output_focus_source_ids_v1(p_context jsonb, p_request jsonb, p_output jsonb, p_outputs jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_all uuid[];
  v_explicit uuid[];
  v_theme_sources uuid[];
  v_selected_themes uuid[];
  v_evidence_sources uuid[];
  v_evidence_themes uuid[];
  v_selected uuid[];
  v_reviewed uuid[] := '{}'::uuid[];
  v_remaining uuid[];
  v_existing jsonb;
  v_existing_focus uuid[];
  v_touches_theme boolean := false;
  v_has_existing boolean := false;
begin
  select coalesce(
    array_agg(
      distinct lower(source ->> 'newsroomArticleId')::uuid
      order by lower(source ->> 'newsroomArticleId')::uuid
    ),
    '{}'::uuid[]
  )
  into v_all
  from jsonb_array_elements(coalesce(p_context -> 'sources', '[]'::jsonb)) source
  where source ->> 'newsroomArticleId'
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

  if cardinality(v_all) < 1
    or p_context ->> 'kind' <> 'selection'
    or jsonb_typeof(p_request -> 'selection') is distinct from 'object'
  then
    return null;
  end if;

  select coalesce(
    array_agg(
      distinct lower(value #>> '{}')::uuid
      order by lower(value #>> '{}')::uuid
    ),
    '{}'::uuid[]
  )
  into v_explicit
  from jsonb_array_elements(
    coalesce(p_request -> 'selection' -> 'sourceIds', '[]'::jsonb)
  )
  where value #>> '{}'
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

  select coalesce(
    array_agg(
      distinct lower(value #>> '{}')::uuid
      order by lower(value #>> '{}')::uuid
    ),
    '{}'::uuid[]
  )
  into v_selected_themes
  from jsonb_array_elements(
    coalesce(p_request -> 'selection' -> 'themeIds', '[]'::jsonb)
  )
  where value #>> '{}'
    ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

  select coalesce(array_agg(id order by id), '{}'::uuid[])
  into v_theme_sources
  from unnest(v_all) source(id)
  where not (source.id = any(v_explicit));

  if p_output ->> 'kind' = 'existing' then
    if jsonb_typeof(p_output -> 'target' -> 'evidence') is distinct from 'object' then
      return null;
    end if;

    select coalesce(array_agg(distinct id order by id), '{}'::uuid[])
    into v_evidence_sources
    from (
      select lower(value #>> '{}')::uuid as id
      from jsonb_array_elements(
        coalesce(p_output -> 'target' -> 'evidence' -> 'sourceIds', '[]'::jsonb)
      )
      where value #>> '{}'
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    ) evidence
    where evidence.id = any(v_all);

    if cardinality(v_selected_themes) = 1 then
      select coalesce(
        array_agg(
          distinct lower(value #>> '{}')::uuid
          order by lower(value #>> '{}')::uuid
        ),
        '{}'::uuid[]
      )
      into v_evidence_themes
      from jsonb_array_elements(
        coalesce(p_output -> 'target' -> 'evidence' -> 'themeIds', '[]'::jsonb)
      )
      where value #>> '{}'
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';

      v_touches_theme :=
        v_selected_themes[1] = any(v_evidence_themes)
        or exists (
          select 1
          from unnest(v_evidence_sources) evidence_source(id)
          where evidence_source.id = any(v_theme_sources)
        );

      if v_touches_theme and cardinality(v_theme_sources) > 0 then
        select coalesce(array_agg(distinct id order by id), '{}'::uuid[])
        into v_selected
        from (
          select id from unnest(v_evidence_sources) source(id)
          union
          select id from unnest(v_theme_sources) source(id)
        ) selected;
        return v_selected;
      end if;
    end if;

    return case
      when cardinality(v_evidence_sources) > 0 then v_evidence_sources
      else null
    end;
  end if;

  if p_output ->> 'kind' = 'new' then
    if coalesce((p_context ->> 'newArticleCount')::integer, 0) <> 1 then
      return null;
    end if;

    for v_existing in
      select value
      from jsonb_array_elements(coalesce(p_outputs, '[]'::jsonb))
      where value ->> 'kind' = 'existing'
        and value ->> 'contextKey' = p_output ->> 'contextKey'
    loop
      v_has_existing := true;
      v_existing_focus := public.newsroom_mesa_intent_output_focus_source_ids_v1(
        p_context,
        p_request,
        v_existing,
        '[]'::jsonb
      );
      if v_existing_focus is null or cardinality(v_existing_focus) < 1 then
        return null;
      end if;
      v_reviewed := v_reviewed || v_existing_focus;
    end loop;

    if not v_has_existing then
      return null;
    end if;

    select coalesce(array_agg(distinct id order by id), '{}'::uuid[])
    into v_reviewed
    from unnest(v_reviewed) reviewed(id);

    select coalesce(array_agg(id order by id), '{}'::uuid[])
    into v_remaining
    from unnest(v_explicit) source(id)
    where source.id = any(v_all)
      and not (source.id = any(v_reviewed));

    return case
      when cardinality(v_remaining) > 0 then v_remaining
      else null
    end;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id uuid, p_package_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_workspace public.newsroom_mesa_production_contexts%rowtype;
  v_plan jsonb; v_manifest jsonb; v_output jsonb; v_context jsonb; v_item jsonb;
  v_ids uuid[]; v_expected uuid[]; v_source jsonb;
begin
  if p_dossier_id is null or p_package_id is null then raise exception 'mesa-intent-publication-input-invalid'; end if;
  select * into v_workspace from public.newsroom_mesa_production_contexts w where w.dossier_id=p_dossier_id for update;
  if not found or v_workspace.workspace_role<>'technical' or v_workspace.workspace_contract_version<>2
    or v_workspace.workspace_state not in ('active','consolidated') then
    raise exception 'mesa-intent-publication-workspace-invalid';
  end if;
  select p.frozen_plan into v_plan from public.newsroom_mesa_intent_preparations p where p.dossier_id=p_dossier_id for share;
  if not found or v_workspace.selection_payload -> 'productionIntents' is distinct from v_plan
    or v_plan ->> 'contractVersion' is distinct from '1'
    or jsonb_typeof(v_plan -> 'outputs') is distinct from 'array'
    or jsonb_array_length(v_plan -> 'outputs') not between 1 and 30
    or jsonb_typeof(v_plan -> 'contexts') is distinct from 'array' then
    raise exception 'mesa-intent-publication-plan-invalid';
  end if;
  select p.manifest into v_manifest from public.newsroom_editorial_source_packages p where p.id=p_package_id for share;
  if not found or v_manifest ->> 'version' is distinct from '5'
    or v_manifest ->> 'provenanceContract' is distinct from 'mesa-v2'
    or v_manifest -> 'productionIntents' is distinct from v_plan
    or jsonb_typeof(v_manifest -> 'outputs') is distinct from 'array'
    or jsonb_array_length(v_manifest -> 'outputs')<>jsonb_array_length(v_plan -> 'outputs') then
    raise exception 'mesa-intent-publication-package-invalid';
  end if;
  -- A second package may not take over a partially published preparation.
  if exists (select 1 from public.newsroom_mesa_output_publications p
    where p.dossier_id=p_dossier_id and p.package_id<>p_package_id) then
    raise exception 'mesa-intent-publication-package-conflict';
  end if;
  if (select count(*) from public.newsroom_editorial_dossier_article_plans p
      where p.dossier_id=p_dossier_id and p.status<>'cancelled')<>jsonb_array_length(v_plan -> 'outputs') then
    raise exception 'mesa-intent-publication-plan-invalid';
  end if;
  for v_output in select value from jsonb_array_elements(v_plan -> 'outputs') loop
    if not exists (select 1 from public.newsroom_editorial_dossier_article_plans p
      join public.newsroom_mesa_article_plan_contexts a on a.dossier_id=p.dossier_id and a.article_plan_id=p.id
      where p.dossier_id=p_dossier_id and p.id=(v_output ->> 'outputId')::uuid and p.status<>'cancelled'
        and a.production_context_id=(v_output ->> 'productionContextId')::uuid
        and p.destination=case when v_output ->> 'kind'='existing' then 'update' else 'new' end
        and p.update_target_editorial_article_id is not distinct from (v_output -> 'target' ->> 'editorialArticleId')::uuid
        and public.newsroom_mesa_plan_context_sources_valid_v1(p_dossier_id,p.id,a.production_context_id)) then
      raise exception 'mesa-intent-publication-output-invalid';
    end if;
    select value into v_context from jsonb_array_elements(v_plan -> 'contexts')
      where value ->> 'key'=v_output ->> 'contextKey'
        and value ->> 'productionContextId'=v_output ->> 'productionContextId';
    if not found or (v_output ->> 'kind'='existing' and v_context -> 'reviewPublished' is distinct from 'true'::jsonb) then
      raise exception 'mesa-intent-publication-context-invalid';
    end if;
    if (select count(*) from jsonb_array_elements(v_manifest -> 'outputs') o
      where o ->> 'outputId'=v_output ->> 'outputId')<>1 then
      raise exception 'mesa-intent-publication-package-invalid';
    end if;
    select o into strict v_item from jsonb_array_elements(v_manifest -> 'outputs') o where o ->> 'outputId'=v_output ->> 'outputId';
    if v_item -> 'articlePlan' ->> 'articlePlanId' is distinct from v_output ->> 'outputId'
      or v_item -> 'articlePlan' ->> 'dossierId' is distinct from p_dossier_id::text
      or v_item -> 'articlePlan' ->> 'contextId' is distinct from v_output ->> 'productionContextId'
      or v_item -> 'articlePlan' ->> 'sourceScope' is distinct from 'context'
      or jsonb_typeof(v_item -> 'contextSourceIds') is distinct from 'array' then
      raise exception 'mesa-intent-publication-package-invalid';
    end if;
    select array_agg((s #>> '{}')::uuid order by (s #>> '{}')::uuid) into v_ids from jsonb_array_elements(v_item -> 'contextSourceIds') s;
    select array_agg(c.dossier_source_id order by c.dossier_source_id) into v_expected
      from public.newsroom_mesa_production_context_sources c where c.dossier_id=p_dossier_id and c.production_context_id=(v_output ->> 'productionContextId')::uuid;
    if v_ids is distinct from v_expected then raise exception 'mesa-intent-publication-source-invalid'; end if;
  end loop;
  -- A later snapshot is valid new material for a future production; it must not
  -- invalidate THIS frozen package. Mutation of its original snapshot does.
  for v_context in select value from jsonb_array_elements(v_plan -> 'contexts') loop
    for v_source in select value from jsonb_array_elements(v_context -> 'sources') loop
      select to_jsonb(s) into v_item from public.newsroom_article_snapshots s
        where s.id=(v_source ->> 'newsroomSnapshotId')::uuid
          and s.article_id=(v_source ->> 'newsroomArticleId')::uuid for share;
      if not found or encode(sha256(convert_to(v_item::text,'UTF8')),'hex') is distinct from v_source ->> 'snapshotFingerprint' then
        raise exception 'mesa-intent-frozen-source-stale';
      end if;
    end loop;
  end loop;
  return v_plan;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_normalize_intent_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_item jsonb; v_themes jsonb := '[]'; v_sources jsonb := '[]';
  v_selection jsonb := null; v_selection_sources jsonb := '[]'; v_selection_themes jsonb := '[]';
  v_selection_candidates jsonb := '[]'; v_selection_articles jsonb := '[]';
  v_uuid constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
  if jsonb_typeof(p_request) is distinct from 'object'
    or not (p_request ?& array['version','preparationKey','title','themes','sources'])
    or p_request - array['version','preparationKey','title','themes','sources','selection'] <> '{}'
    or p_request -> 'version' is distinct from '1'::jsonb
    or jsonb_typeof(p_request -> 'preparationKey') is distinct from 'string'
    or lower(p_request ->> 'preparationKey') !~ v_uuid
    or jsonb_typeof(p_request -> 'title') is distinct from 'string'
    or length(btrim(p_request ->> 'title')) not between 1 and 180
    or jsonb_typeof(p_request -> 'themes') is distinct from 'array'
    or jsonb_typeof(p_request -> 'sources') is distinct from 'array'
  then raise exception 'mesa-intent-input-invalid'; end if;
  if jsonb_array_length(p_request -> 'themes') > 20
    or jsonb_array_length(p_request -> 'sources') > 200
  then raise exception 'mesa-intent-input-invalid'; end if;
  for v_item in select value from jsonb_array_elements(p_request -> 'themes') loop
    if jsonb_typeof(v_item) is distinct from 'object'
      or not (v_item ?& array['themeId','action'])
      or jsonb_typeof(v_item -> 'themeId') is distinct from 'string'
      or lower(v_item ->> 'themeId') !~ v_uuid
      or coalesce(v_item ->> 'action','') not in ('defer','prepare')
    then raise exception 'mesa-intent-theme-invalid'; end if;
    if v_item ->> 'action' = 'defer' then
      if v_item - array['themeId','action'] <> '{}' then raise exception 'mesa-intent-theme-invalid'; end if;
    else
      if not (v_item ?& array['reviewPublished','newArticleCount'])
        or v_item - array['themeId','action','reviewPublished','newArticleCount'] <> '{}'
        or jsonb_typeof(v_item -> 'reviewPublished') is distinct from 'boolean'
        or jsonb_typeof(v_item -> 'newArticleCount') is distinct from 'number'
        or (v_item ->> 'newArticleCount') !~ '^[0-9]+$'
      then raise exception 'mesa-intent-theme-invalid'; end if;
      if (v_item ->> 'newArticleCount')::numeric not between 0 and 30 then raise exception 'mesa-intent-theme-invalid'; end if;
    end if;
    v_themes := v_themes || jsonb_build_array(v_item || jsonb_build_object('themeId',lower(v_item ->> 'themeId')));
  end loop;
  for v_item in select value from jsonb_array_elements(p_request -> 'sources') loop
    if jsonb_typeof(v_item) is distinct from 'object'
      or not (v_item ?& array['sourceId','destination'])
      or jsonb_typeof(v_item -> 'sourceId') is distinct from 'string'
      or lower(v_item ->> 'sourceId') !~ v_uuid
      or coalesce(v_item ->> 'destination','') not in ('defer','independent','theme')
    then raise exception 'mesa-intent-source-invalid'; end if;
    case v_item ->> 'destination'
    when 'defer' then
      if v_item - array['sourceId','destination'] <> '{}' then raise exception 'mesa-intent-source-invalid'; end if;
    when 'theme' then
      if not (v_item ? 'themeId') or v_item - array['sourceId','destination','themeId'] <> '{}'
        or jsonb_typeof(v_item -> 'themeId') is distinct from 'string' or lower(v_item ->> 'themeId') !~ v_uuid
      then raise exception 'mesa-intent-source-invalid'; end if;
      v_item := v_item || jsonb_build_object('themeId',lower(v_item ->> 'themeId'));
      if not exists (select 1 from jsonb_array_elements(v_themes) t
        where t ->> 'themeId' = v_item ->> 'themeId' and t ->> 'action' = 'prepare')
      then raise exception 'mesa-intent-incorporation-target-invalid'; end if;
    else
      if not (v_item ? 'newArticleCount') or v_item - array['sourceId','destination','newArticleCount'] <> '{}'
        or jsonb_typeof(v_item -> 'newArticleCount') is distinct from 'number'
        or (v_item ->> 'newArticleCount') !~ '^[0-9]+$'
      then raise exception 'mesa-intent-source-invalid'; end if;
      if (v_item ->> 'newArticleCount')::numeric not between 1 and 30 then raise exception 'mesa-intent-source-invalid'; end if;
    end case;
    v_sources := v_sources || jsonb_build_array(v_item || jsonb_build_object('sourceId',lower(v_item ->> 'sourceId')));
  end loop;
  if exists (select 1 from jsonb_array_elements(v_themes) t group by t ->> 'themeId' having count(*) > 1)
    or exists (select 1 from jsonb_array_elements(v_sources) s group by s ->> 'sourceId' having count(*) > 1)
  then raise exception 'mesa-intent-selection-duplicate'; end if;
  if p_request ? 'selection' then
    v_selection := p_request -> 'selection';
    if jsonb_typeof(v_selection) is distinct from 'object'
      or not (v_selection ?& array['sourceIds','reviewArticleIds','newArticleCount'])
      or v_selection - array['sourceIds','themeIds','candidateArticleIds','reviewArticleIds','newArticleCount'] <> '{}'
      or jsonb_typeof(v_selection -> 'sourceIds') is distinct from 'array'
      or jsonb_array_length(v_selection -> 'sourceIds') > 20
      or jsonb_typeof(coalesce(v_selection -> 'themeIds','[]'::jsonb)) is distinct from 'array'
      or jsonb_array_length(coalesce(v_selection -> 'themeIds','[]'::jsonb)) > 20
      or jsonb_typeof(coalesce(v_selection -> 'candidateArticleIds','[]'::jsonb)) is distinct from 'array'
      or jsonb_array_length(coalesce(v_selection -> 'candidateArticleIds','[]'::jsonb)) > 200
      or jsonb_typeof(v_selection -> 'reviewArticleIds') is distinct from 'array'
      or jsonb_array_length(v_selection -> 'reviewArticleIds') > 30
      or jsonb_typeof(v_selection -> 'newArticleCount') is distinct from 'number'
      or (v_selection ->> 'newArticleCount') !~ '^[0-9]+$'
      or (v_selection ->> 'newArticleCount')::numeric not between 0 and 30
    then raise exception 'mesa-intent-selection-invalid'; end if;
    for v_item in select value from jsonb_array_elements(v_selection -> 'sourceIds') loop
      if jsonb_typeof(v_item) is distinct from 'string' or lower(v_item #>> '{}') !~ v_uuid then raise exception 'mesa-intent-selection-invalid'; end if;
      v_selection_sources := v_selection_sources || jsonb_build_array(lower(v_item #>> '{}'));
    end loop;
    for v_item in select value from jsonb_array_elements(coalesce(v_selection -> 'themeIds','[]'::jsonb)) loop
      if jsonb_typeof(v_item) is distinct from 'string' or lower(v_item #>> '{}') !~ v_uuid then raise exception 'mesa-intent-selection-invalid'; end if;
      v_selection_themes := v_selection_themes || jsonb_build_array(lower(v_item #>> '{}'));
    end loop;
    for v_item in select value from jsonb_array_elements(coalesce(v_selection -> 'candidateArticleIds','[]'::jsonb)) loop
      if jsonb_typeof(v_item) is distinct from 'string' or lower(v_item #>> '{}') !~ v_uuid then raise exception 'mesa-intent-selection-invalid'; end if;
      v_selection_candidates := v_selection_candidates || jsonb_build_array(lower(v_item #>> '{}'));
    end loop;
    for v_item in select value from jsonb_array_elements(v_selection -> 'reviewArticleIds') loop
      if jsonb_typeof(v_item) is distinct from 'string' or lower(v_item #>> '{}') !~ v_uuid then raise exception 'mesa-intent-selection-invalid'; end if;
      v_selection_articles := v_selection_articles || jsonb_build_array(lower(v_item #>> '{}'));
    end loop;
    if jsonb_array_length(v_selection_sources)+jsonb_array_length(v_selection_themes) < 1
      or (select count(distinct value #>> '{}') from jsonb_array_elements(v_selection_sources)) <> jsonb_array_length(v_selection_sources)
      or (select count(distinct value #>> '{}') from jsonb_array_elements(v_selection_themes)) <> jsonb_array_length(v_selection_themes)
      or (select count(distinct value #>> '{}') from jsonb_array_elements(v_selection_candidates)) <> jsonb_array_length(v_selection_candidates)
      or (select count(distinct value #>> '{}') from jsonb_array_elements(v_selection_articles)) <> jsonb_array_length(v_selection_articles)
      or exists (select 1 from jsonb_array_elements(v_selection_sources) selected join jsonb_array_elements(v_sources) source on source ->> 'sourceId'=selected #>> '{}')
      or exists (select 1 from jsonb_array_elements(v_selection_themes) selected join jsonb_array_elements(v_themes) theme on theme ->> 'themeId'=selected #>> '{}')
      or (v_selection ? 'candidateArticleIds' and exists (
        select 1 from jsonb_array_elements(v_selection_articles) reviewed
        where not exists (select 1 from jsonb_array_elements(v_selection_candidates) candidate where candidate #>> '{}'=reviewed #>> '{}')
      ))
      or jsonb_array_length(v_selection_articles)+(v_selection ->> 'newArticleCount')::integer < 1
    then raise exception 'mesa-intent-selection-invalid'; end if;
    select coalesce(jsonb_agg(value order by value #>> '{}'),'[]'::jsonb) into v_selection_sources from jsonb_array_elements(v_selection_sources);
    select coalesce(jsonb_agg(value order by value #>> '{}'),'[]'::jsonb) into v_selection_themes from jsonb_array_elements(v_selection_themes);
    select coalesce(jsonb_agg(value order by value #>> '{}'),'[]'::jsonb) into v_selection_candidates from jsonb_array_elements(v_selection_candidates);
    select coalesce(jsonb_agg(value order by value #>> '{}'),'[]'::jsonb) into v_selection_articles from jsonb_array_elements(v_selection_articles);
    v_selection := jsonb_build_object('sourceIds',v_selection_sources,'reviewArticleIds',v_selection_articles,
      'newArticleCount',(v_selection ->> 'newArticleCount')::integer)
      || case when p_request -> 'selection' ? 'themeIds' then jsonb_build_object('themeIds',v_selection_themes) else '{}'::jsonb end
      || case when p_request -> 'selection' ? 'candidateArticleIds' then jsonb_build_object('candidateArticleIds',v_selection_candidates) else '{}'::jsonb end;
  end if;
  return jsonb_build_object('version',1,'preparationKey',lower(p_request ->> 'preparationKey'),
    'title',btrim(p_request ->> 'title'),
    'themes',(select coalesce(jsonb_agg(t order by t ->> 'themeId'),'[]') from jsonb_array_elements(v_themes) t),
    'sources',(select coalesce(jsonb_agg(s order by s ->> 'sourceId'),'[]') from jsonb_array_elements(v_sources) s))
    || case when v_selection is null then '{}'::jsonb else jsonb_build_object('selection',v_selection) end;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_normalize_refs_v2(p_refs jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if p_refs is null or jsonb_typeof(p_refs) <> 'array' or jsonb_array_length(p_refs) > 10000 then
    raise exception 'mesa-material-source-invalid';
  end if;
  if exists(select 1 from jsonb_array_elements(p_refs) r
    where jsonb_typeof(r) <> 'object' or coalesce(r->>'newsroomArticleId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or coalesce(r->>'newsroomSnapshotId','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$') then
    raise exception 'mesa-material-source-invalid';
  end if;
  if exists(select 1 from jsonb_array_elements(p_refs) r group by (r->>'newsroomArticleId')::uuid
    having count(distinct (r->>'newsroomSnapshotId')::uuid) > 1) then
    raise exception 'mesa-material-version-conflict';
  end if;
  if exists(select 1 from jsonb_array_elements(p_refs) r where not exists(
    select 1 from public.newsroom_article_snapshots s where s.id=(r->>'newsroomSnapshotId')::uuid
      and s.article_id=(r->>'newsroomArticleId')::uuid)) then raise exception 'mesa-material-snapshot-mismatch'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('newsroomArticleId',a,'newsroomSnapshotId',s) order by a),'[]'::jsonb)
  into v_result from (select distinct (r->>'newsroomArticleId')::uuid a,(r->>'newsroomSnapshotId')::uuid s
    from jsonb_array_elements(p_refs) r) refs;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_preview_intents_v1(p_request jsonb)
 RETURNS TABLE(plan jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request jsonb := public.newsroom_mesa_normalize_intent_v1(p_request);
  v_intent jsonb;
  v_theme public.newsroom_editorial_themes%rowtype;
  v_id uuid;
  v_key text;
  v_source jsonb;
  v_sources jsonb;
  v_history jsonb;
  v_candidates jsonb;
  v_contexts jsonb := '[]';
  v_outputs jsonb := '[]';
  v_incorporations jsonb := '[]';
  v_context jsonb;
  v_article jsonb;
  v_review_count integer := 0;
  v_new_count integer := 0;
  v_source_count integer;
  v_i integer;
  v_material jsonb;
begin
  for v_intent in
    select item
    from pg_catalog.jsonb_array_elements(v_request -> 'themes') as row_value(item)
    where item ->> 'action' = 'prepare'
  loop
    select *
    into v_theme
    from public.newsroom_editorial_themes as theme_row
    where theme_row.id = (v_intent ->> 'themeId')::uuid
      and theme_row.status = 'open';
    if not found then
      raise exception 'mesa-intent-theme-unavailable'
        using detail = v_intent ->> 'themeId';
    end if;
    v_key := 'theme:' || v_theme.id::text;
    v_sources := '[]';
    for v_id in
      select membership.newsroom_article_id
      from public.newsroom_editorial_theme_sources as membership
      where membership.theme_id = v_theme.id
      union
      select (source_item ->> 'sourceId')::uuid
      from pg_catalog.jsonb_array_elements(v_request -> 'sources')
        as source_row(source_item)
      where source_item ->> 'destination' = 'theme'
        and source_item ->> 'themeId' = v_theme.id::text
      order by 1
    loop
      v_source := public.newsroom_mesa_intent_source_v1(v_id);
      if v_source is null
        or v_source ->> 'newsroomSnapshotId' is null
        or v_source -> 'usable' is distinct from 'true'::jsonb
      then
        raise exception 'mesa-intent-source-snapshot-unavailable'
          using detail = v_key || ':' || v_id::text;
      end if;
      v_sources := v_sources || pg_catalog.jsonb_build_array(v_source);
      if not exists (
        select 1
        from public.newsroom_editorial_theme_sources as membership
        where membership.theme_id = v_theme.id
          and membership.newsroom_article_id = v_id
      ) then
        v_incorporations := v_incorporations
          || pg_catalog.jsonb_build_array(
            pg_catalog.jsonb_build_object(
              'themeId', v_theme.id,
              'sourceId', v_id
            )
          );
      end if;
    end loop;
    if pg_catalog.jsonb_array_length(v_sources) = 0 then
      raise exception 'mesa-intent-theme-sources-missing' using detail = v_key;
    end if;
    select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'editorialArticleId', article_row.id,
          'slug', article_row.slug,
          'title', article_row.title,
          'matchdayId', article_row.matchday_id,
          'contentFingerprint', pg_catalog.encode(
            pg_catalog.sha256(
              pg_catalog.convert_to(
                pg_catalog.to_jsonb(article_row)::text,
                'UTF8'
              )
            ),
            'hex'
          ),
          'article', pg_catalog.to_jsonb(article_row)
        )
        order by article_row.id
      ),
      '[]'
    )
    into v_history
    from public.newsroom_editorial_theme_articles as membership
    join public.editorial_articles as article_row
      on article_row.id = membership.editorial_article_id
    where membership.theme_id = v_theme.id
      and article_row.status = 'published';
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(v_history) as history_row(item)
      where nullif(pg_catalog.btrim(item ->> 'slug'), '') is null
        or nullif(pg_catalog.btrim(item ->> 'title'), '') is null
    ) then
      raise exception 'mesa-intent-published-history-invalid' using detail = v_key;
    end if;
    if (v_intent ->> 'reviewPublished')::boolean
      and pg_catalog.jsonb_array_length(v_history) = 0
    then
      raise exception 'mesa-intent-nothing-to-review' using detail = v_key;
    end if;
    if not (v_intent ->> 'reviewPublished')::boolean
      and (v_intent ->> 'newArticleCount')::integer = 0
    then
      raise exception 'mesa-intent-theme-work-missing' using detail = v_key;
    end if;
    v_contexts := v_contexts || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'key', v_key,
        'kind', 'theme',
        'themeId', v_theme.id,
        'sourceId', null,
        'title', v_theme.title,
        'theme', pg_catalog.to_jsonb(v_theme),
        'reviewPublished', v_intent -> 'reviewPublished',
        'newArticleCount', v_intent -> 'newArticleCount',
        'sources', v_sources,
        'publishedArticles', v_history
      )
    );
  end loop;

  for v_intent in
    select item
    from pg_catalog.jsonb_array_elements(v_request -> 'sources') as row_value(item)
    where item ->> 'destination' = 'independent'
  loop
    v_id := (v_intent ->> 'sourceId')::uuid;
    v_key := 'source:' || v_id::text;
    if exists (
      select 1
      from public.newsroom_editorial_theme_sources as membership
      where membership.newsroom_article_id = v_id
    ) then
      raise exception 'mesa-intent-independent-source-not-loose' using detail = v_key;
    end if;
    v_source := public.newsroom_mesa_intent_source_v1(v_id);
    if v_source is null
      or v_source ->> 'newsroomSnapshotId' is null
      or v_source -> 'usable' is distinct from 'true'::jsonb
    then
      raise exception 'mesa-intent-source-snapshot-unavailable' using detail = v_key;
    end if;
    v_contexts := v_contexts || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'key', v_key,
        'kind', 'source',
        'themeId', null,
        'sourceId', v_id,
        'title', 'Fonte independente',
        'reviewPublished', false,
        'newArticleCount', v_intent -> 'newArticleCount',
        'sources', pg_catalog.jsonb_build_array(v_source),
        'publishedArticles', '[]'::jsonb
      )
    );
  end loop;

  if v_request ? 'selection' then
    v_key := 'selection:' || (v_request ->> 'preparationKey');
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        coalesce(v_request -> 'selection' -> 'themeIds', '[]'::jsonb)
      ) as selected(value)
      where not exists (
        select 1
        from public.newsroom_editorial_themes as theme_row
        where theme_row.id = (selected.value #>> '{}')::uuid
          and theme_row.status = 'open'
      )
    ) then
      raise exception 'mesa-intent-theme-unavailable' using detail = v_key;
    end if;
    v_sources := '[]'::jsonb;
    for v_id in
      select (value #>> '{}')::uuid
      from pg_catalog.jsonb_array_elements(
        v_request -> 'selection' -> 'sourceIds'
      )
      union
      select membership.newsroom_article_id
      from public.newsroom_editorial_theme_sources as membership
      where membership.theme_id in (
        select (value #>> '{}')::uuid
        from pg_catalog.jsonb_array_elements(
          coalesce(v_request -> 'selection' -> 'themeIds', '[]'::jsonb)
        )
      )
      order by 1
    loop
      v_source := public.newsroom_mesa_intent_source_v1(v_id);
      if v_source is null
        or v_source ->> 'newsroomSnapshotId' is null
        or v_source -> 'usable' is distinct from 'true'::jsonb
      then
        raise exception 'mesa-intent-source-snapshot-unavailable'
          using detail = v_key || ':' || v_id::text;
      end if;
      v_sources := v_sources || pg_catalog.jsonb_build_array(v_source);
    end loop;
    if pg_catalog.jsonb_array_length(v_sources) = 0 then
      raise exception 'mesa-intent-selection-sources-missing' using detail = v_key;
    end if;
    select candidates
    into strict v_candidates
    from public.newsroom_mesa_global_article_candidates_v1(
      array(
        select (value #>> '{}')::uuid
        from pg_catalog.jsonb_array_elements(
          v_request -> 'selection' -> 'sourceIds'
        )
      ),
      array(
        select (value #>> '{}')::uuid
        from pg_catalog.jsonb_array_elements(
          coalesce(v_request -> 'selection' -> 'themeIds', '[]'::jsonb)
        )
      )
    );
    select coalesce(
      pg_catalog.jsonb_agg(candidate order by candidate ->> 'editorialArticleId'),
      '[]'::jsonb
    )
    into v_candidates
    from pg_catalog.jsonb_array_elements(v_candidates) as row_value(candidate);
    if v_request -> 'selection' ? 'candidateArticleIds'
      and (
        select coalesce(
          pg_catalog.jsonb_agg(
            candidate -> 'editorialArticleId'
            order by candidate ->> 'editorialArticleId'
          ),
          '[]'::jsonb
        )
        from pg_catalog.jsonb_array_elements(v_candidates) as row_value(candidate)
      ) is distinct from v_request -> 'selection' -> 'candidateArticleIds'
    then
      raise exception 'mesa-intent-selection-candidates-stale' using detail = v_key;
    end if;
    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        v_request -> 'selection' -> 'reviewArticleIds'
      ) as requested(value)
      where not exists (
        select 1
        from pg_catalog.jsonb_array_elements(v_candidates) as candidate(value)
        where candidate.value ->> 'editorialArticleId' = requested.value #>> '{}'
      )
    ) then
      raise exception 'mesa-intent-selection-target-unavailable' using detail = v_key;
    end if;
    select coalesce(
      pg_catalog.jsonb_agg(candidate order by candidate ->> 'editorialArticleId'),
      '[]'::jsonb
    )
    into v_history
    from pg_catalog.jsonb_array_elements(v_candidates) as row_value(candidate)
    where exists (
      select 1
      from pg_catalog.jsonb_array_elements(
        v_request -> 'selection' -> 'reviewArticleIds'
      ) as requested(value)
      where requested.value #>> '{}' = candidate ->> 'editorialArticleId'
    );
    v_contexts := v_contexts || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'key', v_key,
        'kind', 'selection',
        'themeId', null,
        'sourceId', null,
        'title', v_request ->> 'title',
        'reviewPublished',
          pg_catalog.jsonb_array_length(
            v_request -> 'selection' -> 'reviewArticleIds'
          ) > 0,
        'newArticleCount', v_request -> 'selection' -> 'newArticleCount',
        'sources', v_sources,
        'publishedArticles', v_history,
        'candidateArticles', v_candidates
      )
    );
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(context_item order by context_item ->> 'key'),
    '[]'
  )
  into v_contexts
  from pg_catalog.jsonb_array_elements(v_contexts) as row_value(context_item);
  for v_context in
    select context_item
    from pg_catalog.jsonb_array_elements(v_contexts) as row_value(context_item)
    where (context_item ->> 'reviewPublished')::boolean
  loop
    for v_article in
      select article_item
      from pg_catalog.jsonb_array_elements(v_context -> 'publishedArticles')
        as row_value(article_item)
    loop
      if exists (
        select 1
        from pg_catalog.jsonb_array_elements(v_outputs) as output_row(item)
        where output_row.item -> 'target' ->> 'editorialArticleId'
          = v_article ->> 'editorialArticleId'
      ) then
        raise exception 'mesa-intent-review-target-conflict';
      end if;
      v_review_count := v_review_count + 1;
      v_outputs := v_outputs || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'slot', 'EXISTING_' || pg_catalog.lpad(v_review_count::text, 2, '0'),
          'contextKey', v_context ->> 'key',
          'kind', 'existing',
          'target', v_article
        )
      );
    end loop;
  end loop;
  for v_context in
    select value
    from pg_catalog.jsonb_array_elements(v_contexts)
  loop
    for v_i in 1..(v_context ->> 'newArticleCount')::integer loop
      v_new_count := v_new_count + 1;
      v_outputs := v_outputs || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'slot', 'NEW_' || pg_catalog.lpad(v_new_count::text, 2, '0'),
          'contextKey', v_context ->> 'key',
          'kind', 'new',
          'target', null
        )
      );
    end loop;
  end loop;
  select pg_catalog.count(distinct source_item ->> 'newsroomArticleId')::integer
  into v_source_count
  from pg_catalog.jsonb_array_elements(v_contexts) as context_row(context_item)
  cross join lateral pg_catalog.jsonb_array_elements(
    context_row.context_item -> 'sources'
  ) as source_row(source_item);
  if pg_catalog.jsonb_array_length(v_contexts) > 20 then
    raise exception 'mesa-intent-context-limit';
  end if;
  if v_source_count > 20 then raise exception 'mesa-intent-source-limit'; end if;
  if v_review_count + v_new_count = 0 then
    raise exception 'mesa-intent-no-work-requested';
  end if;
  if v_review_count + v_new_count > 30 then
    raise exception 'mesa-intent-output-limit';
  end if;
  v_material := pg_catalog.jsonb_build_object(
    'contractVersion', 1,
    'request', v_request,
    'preparationKey', v_request ->> 'preparationKey',
    'title', v_request ->> 'title',
    'contexts', v_contexts,
    'outputs', v_outputs,
    'incorporations', v_incorporations,
    'deferred', pg_catalog.jsonb_build_object(
      'themeIds', (
        select coalesce(pg_catalog.jsonb_agg(item -> 'themeId'), '[]')
        from pg_catalog.jsonb_array_elements(v_request -> 'themes')
          as row_value(item)
        where item ->> 'action' = 'defer'
      ),
      'sourceIds', (
        select coalesce(pg_catalog.jsonb_agg(item -> 'sourceId'), '[]')
        from pg_catalog.jsonb_array_elements(v_request -> 'sources')
          as row_value(item)
        where item ->> 'destination' = 'defer'
      )
    ),
    'totals', pg_catalog.jsonb_build_object(
      'contexts', pg_catalog.jsonb_array_length(v_contexts),
      'sources', v_source_count,
      'reviews', v_review_count,
      'newArticles', v_new_count
    )
  );
  return query
  select v_material || pg_catalog.jsonb_build_object(
    'capturedAt', pg_catalog.to_char(
      pg_catalog.statement_timestamp() at time zone 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
    ),
    'authorityFingerprint', pg_catalog.encode(
      pg_catalog.sha256(
        pg_catalog.convert_to(v_material::text, 'UTF8')
      ),
      'hex'
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_protect_theme_source_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1 from public.newsroom_editorial_theme_dossiers td
    join public.newsroom_editorial_dossier_sources ds on ds.dossier_id = td.dossier_id
    where td.theme_id = old.theme_id and ds.newsroom_article_id = old.newsroom_article_id and ds.included
  ) then raise exception 'mesa-organization-source-in-dossier'; end if;
  return old;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_scope_intent_receipt_sources_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_plan jsonb;v_output jsonb;v_allowed uuid[];v_scoped jsonb;
begin
  if new.slot not like 'EXISTING\_%' escape '\' then return new; end if;
  select frozen_plan into v_plan from public.newsroom_mesa_intent_preparations
    where dossier_id=new.dossier_id;
  if not found then return new; end if;
  select value into v_output from jsonb_array_elements(v_plan->'outputs')
    where value->>'outputId'=new.output_id::text;
  if not found or jsonb_typeof(v_output->'focusSourceIds') is distinct from 'array' then return new; end if;
  select array_agg(distinct lower(value#>>'{}')::uuid order by lower(value#>>'{}')::uuid)
    into v_allowed from jsonb_array_elements(v_output->'focusSourceIds');
  select coalesce(jsonb_agg(source.value order by source.ordinality),'[]'::jsonb) into v_scoped
    from jsonb_array_elements(new.sources) with ordinality source(value,ordinality)
    where (source.value->>'newsroomArticleId')::uuid=any(v_allowed);
  if jsonb_array_length(v_scoped)<1 then raise exception 'mesa-intent-receipt-sources-invalid'; end if;
  new.sources:=v_scoped; return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_theme_source_reference_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.reference_snapshot_id is null then
    select s.id into new.reference_snapshot_id
    from public.newsroom_article_snapshots s
    where s.article_id = new.newsroom_article_id
    order by s.extracted_at desc, s.created_at desc, s.id desc limit 1;
    if new.reference_snapshot_id is not null then
      new.reference_at := pg_catalog.statement_timestamp();
    end if;
  elsif not exists (
    select 1 from public.newsroom_article_snapshots s
    where s.id = new.reference_snapshot_id and s.article_id = new.newsroom_article_id
  ) then
    raise exception 'mesa-organization-snapshot-mismatch';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_timestamp_text_valid_v1(p_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO ''
AS $function$
begin
  perform p_value::timestamptz;
  return true;
exception when others then
  return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_mesa_version_refs_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if public.newsroom_mesa_normalize_refs_v2(new.source_refs) is distinct from new.source_refs then
    raise exception 'mesa-material-source-invalid'; end if;
  insert into public.newsroom_mesa_version_source_refs(version_id,newsroom_article_id,newsroom_snapshot_id)
    select new.id,(r->>'newsroomArticleId')::uuid,(r->>'newsroomSnapshotId')::uuid from jsonb_array_elements(new.source_refs) r;
  insert into public.newsroom_mesa_version_article_refs(version_id,editorial_article_id)
    select new.id,a from unnest(new.article_ids) a;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_organize_theme_materials_v2(p_request_id uuid, p_theme_id uuid, p_title text, p_classification_key text, p_source_ids uuid[], p_material_refs jsonb)
 RETURNS TABLE(theme_id uuid, added_count integer, reused boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_payload jsonb; v_previous public.newsroom_mesa_organization_requests%rowtype;
  v_theme uuid; v_ref jsonb; v_version public.newsroom_mesa_material_versions%rowtype;
  v_ids uuid[]; v_id uuid; v_added integer:=0; v_existing uuid;
begin
  if p_request_id is null or p_source_ids is null or cardinality(p_source_ids)>200 or array_position(p_source_ids,null) is not null
    or p_material_refs is null or jsonb_typeof(p_material_refs)<>'array' or jsonb_array_length(p_material_refs)>50
    or cardinality(p_source_ids)+jsonb_array_length(p_material_refs)=0 then raise exception 'mesa-organization-invalid-input'; end if;
  if exists(select 1 from jsonb_array_elements(p_material_refs) r group by lower(r->>'key') having count(*)>1) then
    raise exception 'mesa-material-selection-invalid'; end if;
  -- Same lock as v1; update the existing guard before reading under stricter isolation levels.
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-organization-v1',0));
  update public.newsroom_mesa_containment_guard set revision=not revision where singleton;
  if not found then raise exception 'mesa-organization-containment-guard-missing'; end if;
  v_payload:=jsonb_build_object('v',2,'theme',p_theme_id,'title',case when p_theme_id is null then btrim(p_title) end,
    'classification',case when p_theme_id is null then p_classification_key end,'sources',p_source_ids,'materials',p_material_refs);
  select * into v_previous from public.newsroom_mesa_organization_requests r where r.request_id=p_request_id;
  if found then
    if v_previous.payload is distinct from v_payload then raise exception 'mesa-organization-request-conflict'; end if;
    return query select v_previous.theme_id,v_previous.added_count,true; return;
  end if;
  if p_theme_id is null then
    select t.id into v_theme from public.newsroom_create_editorial_theme_v1(btrim(p_title),p_classification_key) t;
  else
    select t.id into v_theme from public.newsroom_editorial_themes t where t.id=p_theme_id and t.status='open' for update;
    if not found then raise exception 'mesa-organization-theme-unavailable'; end if;
  end if;
  v_ids:=p_source_ids;
  for v_ref in select r from jsonb_array_elements(p_material_refs) r loop
    v_version:=public.newsroom_mesa_capture_material_v2(v_ref);
    select m.version_id into v_existing from public.newsroom_mesa_theme_materials m where m.theme_id=v_theme and m.material_key=v_version.material_key;
    if found and v_existing<>v_version.id then raise exception 'mesa-material-already-linked'; end if;
    insert into public.newsroom_mesa_theme_materials(theme_id,material_key,version_id)
      values(v_theme,v_version.material_key,v_version.id) on conflict do nothing;
    v_ids:=v_ids || array(select (r->>'newsroomArticleId')::uuid from jsonb_array_elements(v_version.source_refs) r);
  end loop;
  v_ids:=array(select distinct x from unnest(v_ids) x order by x);
  if cardinality(v_ids)>200 then raise exception 'mesa-organization-invalid-input'; end if;
  foreach v_id in array v_ids loop
    if not exists(select 1 from public.newsroom_editorial_theme_sources m where m.theme_id=v_theme and m.newsroom_article_id=v_id) then v_added:=v_added+1; end if;
    perform public.newsroom_set_editorial_theme_source_membership_v1(v_theme,v_id,true);
  end loop;
  insert into public.newsroom_mesa_organization_requests(request_id,payload,theme_id,added_count) values(p_request_id,v_payload,v_theme,v_added);
  return query select v_theme,v_added,false;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_organize_theme_selection_v3(p_request_id uuid, p_theme_id uuid, p_title text, p_classification_key text, p_source_ids uuid[], p_editorial_article_ids uuid[], p_material_refs jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(theme_id uuid, added_count integer, reused boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_article_ids uuid[];
  v_previous public.newsroom_mesa_organization_requests%rowtype;
  v_result record;
  v_article_id uuid;
begin
  if p_editorial_article_ids is null or cardinality(p_editorial_article_ids) > 30
    or array_position(p_editorial_article_ids, null) is not null
    or cardinality(p_editorial_article_ids) <> (select count(distinct id) from unnest(p_editorial_article_ids) id)
  then raise exception 'mesa-organization-invalid-input'; end if;
  v_article_ids := array(select id from unnest(p_editorial_article_ids) id order by id);
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-organization-v1',0));
  select * into v_previous from public.newsroom_mesa_organization_requests r where r.request_id=p_request_id;
  if found and v_previous.explicit_article_ids is distinct from v_article_ids then
    raise exception 'mesa-organization-request-conflict';
  end if;
  -- Validate only the identities explicitly selected in the UI; never infer membership from sources.
  foreach v_article_id in array v_article_ids loop
    perform 1 from public.editorial_articles a where a.id=v_article_id and a.status='published' for share;
    if not found then raise exception 'mesa-organization-article-unavailable'; end if;
  end loop;
  if p_material_refs is null then
    select * into v_result from public.newsroom_organize_theme_sources_v1(
      p_request_id,p_theme_id,p_title,p_classification_key,p_source_ids);
  else
    select * into v_result from public.newsroom_organize_theme_materials_v2(
      p_request_id,p_theme_id,p_title,p_classification_key,p_source_ids,p_material_refs);
  end if;
  foreach v_article_id in array v_article_ids loop
    perform public.newsroom_set_editorial_theme_article_membership_v1(v_result.theme_id,v_article_id,true);
  end loop;
  update public.newsroom_mesa_organization_requests r set explicit_article_ids=v_article_ids
    where r.request_id=p_request_id and r.explicit_article_ids is distinct from v_article_ids;
  return query select v_result.theme_id,v_result.added_count,v_result.reused;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_organize_theme_sources_v1(p_request_id uuid, p_theme_id uuid, p_title text, p_classification_key text, p_source_ids uuid[])
 RETURNS TABLE(theme_id uuid, added_count integer, reused boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_theme_id uuid;
  v_count integer;
  v_payload jsonb;
  v_previous public.newsroom_mesa_organization_requests%rowtype;
  v_source_id uuid;
begin
  if p_request_id is null or p_source_ids is null
    or pg_catalog.cardinality(p_source_ids) < 1
    or pg_catalog.cardinality(p_source_ids) > 200
    or pg_catalog.array_position(p_source_ids, null) is not null
    or (select pg_catalog.count(distinct x) from pg_catalog.unnest(p_source_ids) x)
      <> pg_catalog.cardinality(p_source_ids)
    or (p_theme_id is null and (
      nullif(pg_catalog.btrim(p_title), '') is null
      or pg_catalog.char_length(pg_catalog.btrim(p_title)) > 180
      or p_classification_key is null
      or p_classification_key not in ('benfica','sporting','fc_porto','other_liga_clubs','outside_liga_other')
    ))
  then raise exception 'mesa-organization-invalid-input'; end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('newsroom-mesa-organization-v1', 0));
  v_payload := pg_catalog.jsonb_build_object(
    'themeId', p_theme_id,
    'title', case when p_theme_id is null then pg_catalog.btrim(p_title) else null end,
    'classification', case when p_theme_id is null then p_classification_key else null end,
    'sources', (select pg_catalog.jsonb_agg(x order by x) from pg_catalog.unnest(p_source_ids) x)
  );
  select * into v_previous from public.newsroom_mesa_organization_requests r
    where r.request_id = p_request_id;
  if found then
    if v_previous.payload is distinct from v_payload then
      raise exception 'mesa-organization-request-conflict';
    end if;
    return query select v_previous.theme_id, v_previous.added_count, true;
    return;
  end if;

  if exists (
    select 1 from pg_catalog.unnest(p_source_ids) x(id)
    left join public.newsroom_articles a on a.id = x.id where a.id is null
  ) then raise exception 'mesa-organization-source-not-found'; end if;

  if p_theme_id is null then
    select t.id into v_theme_id from public.newsroom_create_editorial_theme_v1(
      pg_catalog.btrim(p_title), p_classification_key
    ) t;
  else
    select t.id into v_theme_id from public.newsroom_editorial_themes t
      where t.id = p_theme_id and t.status = 'open' for update;
    if not found then raise exception 'mesa-organization-theme-unavailable'; end if;
  end if;

  select pg_catalog.count(*)::integer into v_count
    from pg_catalog.unnest(p_source_ids) x(id)
    where not exists (select 1 from public.newsroom_editorial_theme_sources m
      where m.theme_id = v_theme_id and m.newsroom_article_id = x.id);
  foreach v_source_id in array p_source_ids loop
    perform public.newsroom_set_editorial_theme_source_membership_v1(v_theme_id, v_source_id, true);
  end loop;
  insert into public.newsroom_mesa_organization_requests(request_id, payload, theme_id, added_count)
    values(p_request_id, v_payload, v_theme_id, v_count);
  return query select v_theme_id, v_count, false;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_pin_editorial_profile_version_for_plan(p_dossier_id uuid, p_plan_id uuid)
 RETURNS TABLE(profile_id uuid, profile_code text, profile_name text, version_id uuid, version_number integer, document_text text, content_hash text, approval_state text, version_created_at timestamp with time zone, pinned_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_plan public.newsroom_editorial_dossier_article_plans%rowtype;
  v_profile public.newsroom_editorial_profiles%rowtype;
  v_version public.newsroom_editorial_profile_versions%rowtype;
  v_pinned_at timestamptz;
begin
  if p_dossier_id is null or p_plan_id is null then
    raise exception 'editorial_profile_pin_input_invalid'
      using errcode = '23514';
  end if;

  select plan_row.*
  into v_plan
  from public.newsroom_editorial_dossier_article_plans plan_row
  where plan_row.id = p_plan_id
    and plan_row.dossier_id = p_dossier_id
  for update;

  if not found then
    raise exception 'editorial_dossier_article_plan_not_found'
      using errcode = 'P0002';
  end if;

  if v_plan.editorial_profile_version_id is not null then
    select profile_row.*
    into v_profile
    from public.newsroom_editorial_profiles profile_row
    where profile_row.id = v_plan.editorial_profile_id;

    select version_row.*
    into v_version
    from public.newsroom_editorial_profile_versions version_row
    where version_row.profile_id = v_plan.editorial_profile_id
      and version_row.id = v_plan.editorial_profile_version_id;

    if v_profile.id is null
       or v_version.id is null
       or v_plan.editorial_profile_pinned_at is null then
      raise exception 'editorial_profile_relation_invalid'
        using errcode = '55000';
    end if;

    v_pinned_at := v_plan.editorial_profile_pinned_at;
  else
    select profile_row.*
    into v_profile
    from public.newsroom_editorial_profiles profile_row
    where profile_row.code = 'jornada-pt'
    for update;

    if not found or v_profile.active_version_id is null then
      raise exception 'editorial_profile_unavailable'
        using errcode = '55000';
    end if;

    select version_row.*
    into v_version
    from public.newsroom_editorial_profile_versions version_row
    where version_row.profile_id = v_profile.id
      and version_row.id = v_profile.active_version_id;

    if not found then
      raise exception 'editorial_profile_relation_invalid'
        using errcode = '55000';
    end if;

    v_pinned_at := now();
    update public.newsroom_editorial_dossier_article_plans plan_row
    set editorial_profile_id = v_profile.id,
        editorial_profile_version_id = v_version.id,
        editorial_profile_pinned_at = v_pinned_at,
        updated_at = now()
    where plan_row.id = p_plan_id
      and plan_row.dossier_id = p_dossier_id
      and plan_row.editorial_profile_version_id is null;

    if not found then
      raise exception 'editorial_profile_plan_pin_conflict'
        using errcode = '40001';
    end if;
  end if;

  return query
  select
    v_profile.id,
    v_profile.code,
    v_profile.name,
    v_version.id,
    v_version.version_number,
    v_version.document_text,
    v_version.content_hash,
    v_version.approval_state,
    v_version.created_at,
    v_pinned_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_place_mesa_intent_latest_v1(p_dossier_id uuid, p_package_id uuid, p_article_ids uuid[])
 RETURNS TABLE(result jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_plan jsonb; v_expected uuid[]; v_requested uuid[]; v_days uuid[];
  v_day uuid; v_article public.editorial_articles%rowtype; v_existing uuid;
  v_count integer; v_path text; v_label text; v_now timestamptz:=clock_timestamp();
begin
  if p_article_ids is null or cardinality(p_article_ids) not between 1 and 30
    or array_position(p_article_ids,null) is not null
    or (select count(distinct x) from unnest(p_article_ids) x)<>cardinality(p_article_ids) then
    raise exception 'mesa-intent-latest-input-invalid';
  end if;
  v_plan:=public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id,p_package_id);
  select array_agg(x order by x) into v_requested from unnest(p_article_ids) x;
  select array_agg(a.id order by a.id) into v_expected
    from public.newsroom_mesa_output_publications p
    join public.editorial_articles a on a.id=p.editorial_article_id
    where p.dossier_id=p_dossier_id and p.package_id=p_package_id and a.matchday_id is not null;
  if v_requested is distinct from v_expected then
    raise exception 'mesa-intent-latest-article-set-invalid';
  end if;
  -- Lock canonical rows in the same order as the finalizer. Never use text or
  -- article identity supplied by a client to construct the public projection.
  perform 1 from public.editorial_articles a where a.id=any(v_requested) order by a.id for update;
  if exists (select 1 from public.newsroom_mesa_output_publications p
      join public.editorial_articles a on a.id=p.editorial_article_id
      where p.dossier_id=p_dossier_id and a.id=any(v_requested)
        and (a.status<>'published' or encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')
          is distinct from p.payload->>'intentResultFingerprint')) then
    raise exception 'mesa-intent-published-result-stale';
  end if;
  select array_agg(distinct a.matchday_id order by a.matchday_id) into v_days
    from public.editorial_articles a where a.id=any(v_requested);
  -- A completed replay is not permission to restore a later manually removed
  -- Latest entry. The immutable completion is returned without further writes.
  if exists (select 1 from public.newsroom_mesa_intent_finalizations f
      where f.dossier_id=p_dossier_id and f.package_id=p_package_id) then
    return query select jsonb_build_object('action','reused','articleCount',cardinality(v_requested),'matchdayCount',cardinality(v_days));
    return;
  end if;
  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();
  perform 1 from public.matchdays d where d.id=any(v_days) order by d.id for update;
  for v_article in select * from public.editorial_articles a where a.id=any(v_requested) order by a.matchday_id,a.id loop
    if v_article.published_at is null or exists(select 1 from unnest(array[
        v_article.slug,v_article.label,v_article.title,v_article.subtitle,v_article.body,v_article.image_url,v_article.author
      ]) field where nullif(btrim(field),'') is null) then
      raise exception 'mesa-intent-latest-article-incomplete';
    end if;
    v_path:='/noticias/'||btrim(v_article.slug);
    -- Equivalent to projectEditorialArticleToZone(article, 'editorial_line_item').
    v_label:=to_char(v_article.published_at at time zone 'Europe/Lisbon','HH24:MI')||' · '||btrim(v_article.label);
    select count(*),min(n.id::text)::uuid into v_count,v_existing
      from public.matchday_latest_news n
      where n.matchday_id=v_article.matchday_id and btrim(n.link_url)=v_path;
    if v_count>1 then raise exception 'mesa-intent-latest-existing-duplicate'; end if;
    if v_existing is not null then
      update public.matchday_latest_news set time_label=v_label,time_label_color=null,
        title=btrim(v_article.title),subtitle=null,image_url=null,link_url=v_path,
        article_id=null,status='published',updated_at=v_now where id=v_existing;
    else
      insert into public.matchday_latest_news(matchday_id,time_label,time_label_color,title,subtitle,
        image_url,link_url,article_id,status,sort_order,created_at,updated_at)
      select v_article.matchday_id,v_label,null,btrim(v_article.title),null,null,v_path,null,'published',
        coalesce(max(n.sort_order),0)+1,v_now,v_now
      from public.matchday_latest_news n where n.matchday_id=v_article.matchday_id;
    end if;
  end loop;
  foreach v_day in array v_days loop
    perform * from public.set_matchday_latest_news_settings_v15(v_day,'latest_news',null,null,false);
    perform public.normalize_matchday_latest_news_order(v_day);
  end loop;
  return query select jsonb_build_object('action','placed','articleCount',cardinality(v_requested),'matchdayCount',cardinality(v_days));
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_prepare_mesa_contexts_v3(p_preparation_key uuid, p_title text, p_contexts jsonb, p_incorporate_theme_id uuid DEFAULT NULL::uuid, p_incorporate_source_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS TABLE(dossier_id uuid, preparation_action text, source_count integer, published_context_count integer, image_count integer, context_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request_fingerprint text;
  v_existing public.newsroom_mesa_production_contexts%rowtype;
  v_result record;
  v_context jsonb;
  v_contexts jsonb := '[]'::jsonb;
  v_refs jsonb;
  v_union_refs jsonb := '[]'::jsonb;
  v_ref jsonb;
  v_kind text;
  v_source_id uuid;
  v_theme_id uuid;
  v_title_snapshot text;
  v_context_id uuid;
  v_snapshot_id uuid;
  v_ordinality bigint;
  v_ref_ordinality bigint;
  v_requested_theme_sources uuid[];
  v_current_theme_sources uuid[];
  v_incorporate_source_ids uuid[];
begin
  if p_preparation_key is null
    or nullif(btrim(p_title), '') is null
    or length(btrim(p_title)) > 180
    or p_contexts is null
    or jsonb_typeof(p_contexts) is distinct from 'array'
  then
    raise exception 'mesa-context-preparation-input-invalid';
  end if;

  if jsonb_array_length(p_contexts) not between 1 and 20
    or p_incorporate_source_ids is null
    or array_position(p_incorporate_source_ids, null) is not null
  then
    raise exception 'mesa-context-preparation-input-invalid';
  end if;

  select coalesce(array_agg(source_id order by source_id), '{}'::uuid[])
  into v_incorporate_source_ids
  from (
    select distinct source_id
    from unnest(p_incorporate_source_ids) source_rows(source_id)
  ) normalized;

  if cardinality(v_incorporate_source_ids) <> cardinality(p_incorporate_source_ids)
    or cardinality(v_incorporate_source_ids) > 20
    or (p_incorporate_theme_id is null and cardinality(v_incorporate_source_ids) <> 0)
    or (p_incorporate_theme_id is not null and cardinality(v_incorporate_source_ids) < 1)
  then
    raise exception 'mesa-context-incorporation-input-invalid';
  end if;

  v_request_fingerprint := md5(jsonb_build_object(
    'contractVersion', 3,
    'title', btrim(p_title),
    'contexts', p_contexts,
    'incorporateThemeId', p_incorporate_theme_id,
    'incorporateSourceIds', to_jsonb(v_incorporate_source_ids)
  )::text);

  perform pg_advisory_xact_lock(
    hashtextextended('newsroom-mesa-organization-v1', 0)
  );

  select context.*
  into v_existing
  from public.newsroom_mesa_production_contexts context
  where context.preparation_key = p_preparation_key;

  if found then
    if v_existing.selection_payload ->> 'contextRequestFingerprint'
        is distinct from v_request_fingerprint
      or v_existing.workspace_contract_version is distinct from 2::smallint
      or v_existing.workspace_state is distinct from 'active'
      or not exists (
        select 1
        from public.newsroom_mesa_production_context_items item
        where item.dossier_id = v_existing.dossier_id
      )
    then
      raise exception 'mesa-context-preparation-conflict';
    end if;

    return query
    select
      v_existing.dossier_id,
      'reused'::text,
      jsonb_array_length(v_existing.source_refs),
      (
        select count(*)::integer
        from public.newsroom_editorial_dossier_published_contexts published_context
        where published_context.dossier_id = v_existing.dossier_id
      ),
      (
        select count(*)::integer
        from public.newsroom_editorial_dossier_images image
        where image.dossier_id = v_existing.dossier_id
      ),
      (
        select count(*)::integer
        from public.newsroom_mesa_production_context_items item
        where item.dossier_id = v_existing.dossier_id
      );
    return;
  end if;

  if exists (
    select 1
    from public.newsroom_editorial_dossiers dossier
    where dossier.preparation_key = p_preparation_key
  ) then
    raise exception 'mesa-context-prepared-before-v3';
  end if;

  for v_context, v_ordinality in
    select context.value, context.ordinality
    from jsonb_array_elements(p_contexts)
      with ordinality context(value, ordinality)
  loop
    if jsonb_typeof(v_context) is distinct from 'object'
      or jsonb_typeof(v_context -> 'sources') is distinct from 'array'
    then
      raise exception 'mesa-context-selection-invalid';
    end if;

    v_kind := lower(btrim(coalesce(v_context ->> 'kind', '')));
    v_source_id := null;
    v_theme_id := null;

    begin
      if v_kind = 'source' then
        v_source_id := (v_context ->> 'sourceId')::uuid;
      elsif v_kind = 'theme' then
        v_theme_id := (v_context ->> 'themeId')::uuid;
      elsif v_kind = 'selection' then
        if coalesce(v_context ->> 'sourceId','') <> ''
          or coalesce(v_context ->> 'themeId','') <> ''
        then raise exception 'mesa-context-selection-invalid'; end if;
      else
        raise exception 'mesa-context-selection-invalid';
      end if;
    exception
      when invalid_text_representation or not_null_violation then
        raise exception 'mesa-context-selection-invalid';
    end;

    v_refs := public.newsroom_mesa_normalize_refs_v2(v_context -> 'sources');
    if jsonb_array_length(v_refs) not between 1 and 20 then
      raise exception 'mesa-context-selection-invalid';
    end if;

    if v_kind = 'source' then
      if jsonb_array_length(v_refs) <> 1
        or lower(v_refs -> 0 ->> 'newsroomArticleId') <> v_source_id::text
      then
        raise exception 'mesa-context-source-selection-invalid';
      end if;
      select coalesce(nullif(btrim(article.title), ''), 'Fonte')
      into v_title_snapshot
      from public.newsroom_articles article
      where article.id = v_source_id;
      if not found then
        raise exception 'mesa-context-source-unavailable';
      end if;
      if exists (
        select 1
        from public.newsroom_editorial_theme_sources membership
        where membership.newsroom_article_id = v_source_id
      ) then
        raise exception 'mesa-context-source-not-loose';
      end if;
    elsif v_kind = 'theme' then
      select theme.title
      into v_title_snapshot
      from public.newsroom_editorial_themes theme
      where theme.id = v_theme_id
        and theme.status = 'open'
      for update;
      if not found then
        raise exception 'mesa-context-theme-unavailable';
      end if;
    else
      v_title_snapshot := btrim(p_title);
    end if;

    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object(
      'kind', v_kind,
      'sourceId', v_source_id,
      'themeId', v_theme_id,
      'titleSnapshot', v_title_snapshot,
      'sortOrder', v_ordinality,
      'sources', v_refs
    ));
    v_union_refs := v_union_refs || v_refs;
  end loop;

  if exists (
    select 1
    from jsonb_array_elements(v_contexts) context(value)
    group by
      context.value ->> 'kind',
      coalesce(context.value ->> 'sourceId', context.value ->> 'themeId')
    having count(*) > 1
  ) then
    raise exception 'mesa-context-selection-duplicate';
  end if;

  v_union_refs := public.newsroom_mesa_normalize_refs_v2(v_union_refs);
  if jsonb_array_length(v_union_refs) not between 1 and 20 then
    raise exception 'mesa-context-selection-invalid';
  end if;

  if p_incorporate_theme_id is not null then
    if jsonb_array_length(v_contexts) <> 1
      or v_contexts -> 0 ->> 'kind' <> 'theme'
      or lower(v_contexts -> 0 ->> 'themeId') <> p_incorporate_theme_id::text
    then
      raise exception 'mesa-context-incorporation-ambiguous';
    end if;

    if exists (
      select 1
      from unnest(v_incorporate_source_ids) requested(source_id)
      where not exists (
        select 1
        from jsonb_array_elements(v_contexts -> 0 -> 'sources') ref(value)
        where lower(ref.value ->> 'newsroomArticleId') = requested.source_id::text
      )
        or exists (
          select 1
          from public.newsroom_editorial_theme_sources membership
          where membership.newsroom_article_id = requested.source_id
        )
    ) then
      raise exception 'mesa-context-incorporation-source-invalid';
    end if;

    foreach v_source_id in array v_incorporate_source_ids
    loop
      select (ref.value ->> 'newsroomSnapshotId')::uuid
      into strict v_snapshot_id
      from jsonb_array_elements(v_contexts -> 0 -> 'sources') ref(value)
      where lower(ref.value ->> 'newsroomArticleId') = v_source_id::text;

      perform public.newsroom_set_editorial_theme_source_membership_v1(
        p_incorporate_theme_id,
        v_source_id,
        true
      );
      perform public.newsroom_acknowledge_theme_source_v1(
        p_incorporate_theme_id,
        v_source_id,
        v_snapshot_id
      );
    end loop;
  end if;

  for v_context in
    select context.value
    from jsonb_array_elements(v_contexts) context(value)
    where context.value ->> 'kind' = 'theme'
  loop
    select array_agg(membership.newsroom_article_id order by membership.newsroom_article_id)
    into v_current_theme_sources
    from public.newsroom_editorial_theme_sources membership
    where membership.theme_id = (v_context ->> 'themeId')::uuid;

    select array_agg(
      distinct (ref.value ->> 'newsroomArticleId')::uuid
      order by (ref.value ->> 'newsroomArticleId')::uuid
    )
    into v_requested_theme_sources
    from jsonb_array_elements(v_context -> 'sources') ref(value);

    if coalesce(v_current_theme_sources, '{}'::uuid[])
      is distinct from coalesce(v_requested_theme_sources, '{}'::uuid[])
    then
      raise exception 'mesa-context-theme-membership-stale';
    end if;
  end loop;

  select *
  into v_result
  from public.newsroom_prepare_mesa_materials_v2(
    p_preparation_key,
    null,
    btrim(p_title),
    v_union_refs,
    '[]'::jsonb
  );

  update public.newsroom_mesa_production_contexts context
  set selection_payload = jsonb_build_object(
    'contractVersion', 3,
    'contextContractVersion', 1,
    'contextRequestFingerprint', v_request_fingerprint,
    'title', btrim(p_title),
    'sources', v_union_refs,
    'materials', '[]'::jsonb,
    'contexts', v_contexts,
    'incorporateThemeId', p_incorporate_theme_id,
    'incorporateSourceIds', to_jsonb(v_incorporate_source_ids)
  )
  where context.dossier_id = v_result.dossier_id;

  if not found then
    raise exception 'mesa-context-preparation-workspace-missing';
  end if;

  for v_context in
    select context.value
    from jsonb_array_elements(v_contexts) context(value)
    order by (context.value ->> 'sortOrder')::smallint
  loop
    insert into public.newsroom_mesa_production_context_items(
      dossier_id,
      context_kind,
      source_newsroom_article_id,
      theme_id,
      title_snapshot,
      sort_order
    ) values (
      v_result.dossier_id,
      v_context ->> 'kind',
      (v_context ->> 'sourceId')::uuid,
      (v_context ->> 'themeId')::uuid,
      v_context ->> 'titleSnapshot',
      (v_context ->> 'sortOrder')::smallint
    )
    returning id into v_context_id;

    for v_ref, v_ref_ordinality in
      select ref.value, ref.ordinality
      from jsonb_array_elements(v_context -> 'sources')
        with ordinality ref(value, ordinality)
    loop
      insert into public.newsroom_mesa_production_context_sources(
        dossier_id,
        production_context_id,
        dossier_source_id,
        sort_order
      )
      select
        v_result.dossier_id,
        v_context_id,
        dossier_source.id,
        v_ref_ordinality::smallint
      from public.newsroom_editorial_dossier_sources dossier_source
      where dossier_source.dossier_id = v_result.dossier_id
        and dossier_source.newsroom_article_id = (v_ref ->> 'newsroomArticleId')::uuid
        and dossier_source.newsroom_snapshot_id = (v_ref ->> 'newsroomSnapshotId')::uuid
        and dossier_source.included;

      if not found then
        raise exception 'mesa-context-frozen-source-missing';
      end if;
    end loop;
  end loop;

  return query
  select
    v_result.dossier_id,
    v_result.preparation_action,
    v_result.source_count,
    v_result.published_context_count,
    v_result.image_count,
    jsonb_array_length(v_contexts);
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_prepare_mesa_grouping_v2(p_request jsonb, p_expected_authority_fingerprint text)
 RETURNS TABLE(result jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_v1_request jsonb := public.newsroom_mesa_grouping_request_v1(p_request);
  v_key uuid := (v_v1_request ->> 'preparationKey')::uuid;
  v_existing public.newsroom_mesa_new_output_grouping_preparations%rowtype;
  v_authority jsonb;
  v_preview jsonb;
  v_context jsonb;
  v_contexts jsonb;
  v_source jsonb;
  v_sources jsonb;
  v_snapshot_fingerprint text;
  v_result record;
  v_context_id uuid;
  v_plan_id uuid;
  v_plan_ids uuid[] := '{}';
  v_all_source_ids uuid[];
  v_existing_outputs jsonb := '[]';
  v_item jsonb;
  v_theme jsonb;
  v_i integer := 0;
  v_source_id uuid;
  v_dossier_source_id uuid;
  v_group_id uuid;
  v_loose_ids uuid[];
begin
  if p_expected_authority_fingerprint is null or p_expected_authority_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'mesa-grouping-fingerprint-invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-organization-v1',0));
  select * into v_existing
  from public.newsroom_mesa_new_output_grouping_preparations
  where preparation_key = v_key;
  if found then
    if v_existing.request is distinct from p_request
      or v_existing.authority_fingerprint is distinct from p_expected_authority_fingerprint
    then raise exception 'mesa-grouping-preparation-conflict'; end if;
    return query select jsonb_build_object('dossierId',v_existing.dossier_id,'preparationAction','reused');
    return;
  end if;
  if exists(select 1 from public.newsroom_mesa_intent_preparations where preparation_key=v_key)
    or exists(select 1 from public.newsroom_mesa_production_contexts where preparation_key=v_key)
    or exists(select 1 from public.newsroom_editorial_dossiers where preparation_key=v_key)
  then raise exception 'mesa-grouping-preparation-key-used'; end if;

  perform 1 from public.newsroom_editorial_themes theme
  where theme.id in (
    select (value #>> '{}')::uuid from jsonb_array_elements(v_v1_request -> 'selection' -> 'themeIds') value
  ) order by theme.id for update;
  perform 1 from public.newsroom_articles article
  where article.id in (
    select (value #>> '{}')::uuid from jsonb_array_elements(v_v1_request -> 'selection' -> 'sourceIds') value
    union
    select membership.newsroom_article_id from public.newsroom_editorial_theme_sources membership
    where membership.theme_id in (
      select (value #>> '{}')::uuid from jsonb_array_elements(v_v1_request -> 'selection' -> 'themeIds') value
    )
  ) order by article.id for update;
  perform 1 from public.newsroom_article_snapshots snapshot
  where snapshot.article_id in (
    select article.id from public.newsroom_articles article
    where article.id in (
      select (value #>> '{}')::uuid from jsonb_array_elements(v_v1_request -> 'selection' -> 'sourceIds') value
      union
      select membership.newsroom_article_id from public.newsroom_editorial_theme_sources membership
      where membership.theme_id in (
        select (value #>> '{}')::uuid from jsonb_array_elements(v_v1_request -> 'selection' -> 'themeIds') value
      )
    )
  ) order by snapshot.id for share;

  v_authority := public.newsroom_mesa_grouping_authority_v2(p_request);
  if v_authority ->> 'authorityFingerprint' is distinct from p_expected_authority_fingerprint then
    raise exception 'mesa-grouping-authority-stale';
  end if;
  v_preview := v_authority -> 'basePreview';
  select value into strict v_context from jsonb_array_elements(v_preview -> 'contexts') value
  where value ->> 'kind'='selection';
  v_contexts := jsonb_build_array(jsonb_build_object(
    'kind','selection','themeId',null,'sourceId',null,
    'sources',(select jsonb_agg(jsonb_build_object(
      'newsroomArticleId',source -> 'newsroomArticleId','newsroomSnapshotId',source -> 'newsroomSnapshotId'
    ) order by source ->> 'newsroomArticleId') from jsonb_array_elements(v_context -> 'sources') source)
  ));

  -- This call freezes dossier sources, snapshots and images only. Both optional
  -- incorporation inputs are deliberately empty, so no Theme membership changes.
  select * into strict v_result
  from public.newsroom_prepare_mesa_contexts_v3(v_key,v_v1_request ->> 'title',v_contexts,null,'{}');
  select id into strict v_context_id
  from public.newsroom_mesa_production_context_items
  where dossier_id=v_result.dossier_id and context_kind='selection';

  -- Complete the v1 capture from the exact snapshot identity frozen in the
  -- dossier. Do not consult the live article or choose a newer snapshot here:
  -- this fingerprint becomes part of the persisted v2 preparation and is
  -- reused unchanged by materialization retries.
  v_contexts := '[]'::jsonb;
  for v_context in select value from jsonb_array_elements(v_preview -> 'contexts') value loop
    v_sources := '[]'::jsonb;
    for v_source in select value from jsonb_array_elements(v_context -> 'sources') value loop
      select encode(sha256(convert_to(to_jsonb(snapshot)::text,'UTF8')),'hex')
      into strict v_snapshot_fingerprint
      from public.newsroom_editorial_dossier_sources dossier_source
      join public.newsroom_article_snapshots snapshot
        on snapshot.article_id=dossier_source.newsroom_article_id
        and snapshot.id=dossier_source.newsroom_snapshot_id
      where dossier_source.dossier_id=v_result.dossier_id
        and dossier_source.newsroom_article_id=(v_source ->> 'newsroomArticleId')::uuid
        and dossier_source.newsroom_snapshot_id=(v_source ->> 'newsroomSnapshotId')::uuid
        and dossier_source.included;
      v_sources:=v_sources||jsonb_build_array(
        v_source||jsonb_build_object('snapshotFingerprint',v_snapshot_fingerprint)
      );
    end loop;
    v_contexts:=v_contexts||jsonb_build_array(
      v_context||jsonb_build_object('sources',v_sources)
    );
  end loop;
  v_preview:=jsonb_set(v_preview,'{contexts}',v_contexts);

  select array_agg(dossier_source_id order by sort_order) into v_all_source_ids
  from public.newsroom_mesa_production_context_sources
  where dossier_id=v_result.dossier_id and production_context_id=v_context_id;

  for v_item in select value from jsonb_array_elements(v_preview -> 'outputs') value where value ->> 'kind'='existing' loop
    v_i := v_i + 1;
    select saved.article_plan_id into strict v_plan_id
    from public.newsroom_save_mesa_context_article_plan_v1(
      v_result.dossier_id,null,left((v_item ->> 'slot') || ' — ' || (v_item -> 'target' ->> 'title'),180),
      'planned',v_i*10,'news','standard','Rever o artigo: UPDATE ou SEM ALTERAÇÃO.',v_all_source_ids,v_context_id
    ) saved;
    perform public.newsroom_save_dossier_article_plan_state_v1(
      v_result.dossier_id,v_plan_id,'update',(v_item -> 'target' ->> 'editorialArticleId')::uuid,
      '{}','preserve_published',null
    );
    v_plan_ids := v_plan_ids || v_plan_id;
    v_existing_outputs := v_existing_outputs || jsonb_build_array(jsonb_build_object(
      'slot',v_item -> 'slot','kind','existing','outputId',v_plan_id,'productionContextId',v_context_id,
      'targetEditorialArticleId',v_item -> 'target' -> 'editorialArticleId','targetSlug',v_item -> 'target' -> 'slug',
      'targetTitle',v_item -> 'target' -> 'title','targetMatchdayId',v_item -> 'target' -> 'matchdayId'
    ));
  end loop;

  select coalesce(array_agg((value #>> '{}')::uuid order by value #>> '{}'),'{}'::uuid[]) into v_loose_ids
  from jsonb_array_elements(v_authority -> 'looseSourceIds') value;
  insert into public.newsroom_mesa_new_output_groupings(
    dossier_id,production_context_id,loose_source_ids,target_count,existing_outputs
  ) values (
    v_result.dossier_id,v_context_id,v_loose_ids,
    case when cardinality(v_loose_ids)=0 then 0 else null end,
    v_existing_outputs
  );

  for v_theme in select value from jsonb_array_elements(v_authority -> 'themes') value order by (value ->> 'position')::integer loop
    insert into public.newsroom_mesa_new_output_theme_targets(
      dossier_id,theme_id,title_snapshot,position,target_count,seed_source_ids
    ) values (
      v_result.dossier_id,(v_theme ->> 'themeId')::uuid,v_theme ->> 'title',(v_theme ->> 'position')::smallint,
      null,array(select (value #>> '{}')::uuid from jsonb_array_elements(v_theme -> 'seedSourceIds') value)
    );
  end loop;

  v_i := 0;
  foreach v_source_id in array v_loose_ids loop
    v_i := v_i + 1;
    select id into strict v_dossier_source_id
    from public.newsroom_editorial_dossier_sources
    where dossier_id=v_result.dossier_id and newsroom_article_id=v_source_id and included;
    v_group_id := gen_random_uuid();
    insert into public.newsroom_mesa_new_output_groups(
      id,dossier_id,production_context_id,seed_kind,seed_theme_id,position
    ) values (v_group_id,v_result.dossier_id,v_context_id,'selection',null,v_i);
    insert into public.newsroom_mesa_new_output_group_sources(dossier_id,group_id,dossier_source_id,sort_order)
    values(v_result.dossier_id,v_group_id,v_dossier_source_id,1);
  end loop;

  if cardinality(v_plan_ids)>0 then
    perform public.newsroom_set_mesa_shared_outputs_v2(v_result.dossier_id,v_plan_ids);
  end if;
  insert into public.newsroom_mesa_new_output_grouping_preparations(
    preparation_key,dossier_id,request,authority_fingerprint,authority_snapshot,base_preview
  ) values (
    v_key,v_result.dossier_id,p_request,p_expected_authority_fingerprint,v_authority -> 'material',v_preview
  );
  update public.newsroom_mesa_production_contexts
  set selection_payload=selection_payload || jsonb_build_object(
    'productionGroupingV2',jsonb_build_object(
      'version',2,'state','planned','preparationKey',v_key,'authorityFingerprint',p_expected_authority_fingerprint
    )
  ) where dossier_id=v_result.dossier_id;
  return query select jsonb_build_object('dossierId',v_result.dossier_id,'preparationAction','created');
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_prepare_mesa_intents_v1(p_request jsonb, p_expected_authority_fingerprint text)
 RETURNS TABLE(result jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_plan jsonb;
  v_outputs jsonb := '[]'::jsonb;
  v_output jsonb;
  v_context jsonb;
  v_focus_source_ids uuid[];
  v_dossier_id uuid;
begin
  select original.result
  into strict v_result
  from public.newsroom_prepare_mesa_intents_v1_context_v1(
    p_request,
    p_expected_authority_fingerprint
  ) original;

  v_plan := v_result -> 'plan';
  v_dossier_id := (v_plan ->> 'dossierId')::uuid;

  for v_output in
    select value
    from jsonb_array_elements(v_plan -> 'outputs')
  loop
    select value
    into strict v_context
    from jsonb_array_elements(v_plan -> 'contexts')
    where value ->> 'key' = v_output ->> 'contextKey';

    v_focus_source_ids := public.newsroom_mesa_intent_output_focus_source_ids_v1(
      v_context,
      v_plan -> 'request',
      v_output,
      v_plan -> 'outputs'
    );

    if v_focus_source_ids is not null and cardinality(v_focus_source_ids) > 0 then
      v_output := v_output || jsonb_build_object(
        'focusSourceIds',
        to_jsonb(v_focus_source_ids)
      );
    end if;

    v_outputs := v_outputs || jsonb_build_array(v_output);
  end loop;

  v_plan := jsonb_set(v_plan, '{outputs}', v_outputs);
  v_result := jsonb_set(v_result, '{plan}', v_plan);

  update public.newsroom_mesa_intent_preparations
  set frozen_plan = v_plan
  where dossier_id = v_dossier_id;

  update public.newsroom_mesa_production_contexts
  set selection_payload = jsonb_set(
    selection_payload,
    '{productionIntents}',
    v_plan,
    true
  )
  where dossier_id = v_dossier_id;

  return query select v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_prepare_mesa_intents_v1_context_v1(p_request jsonb, p_expected_authority_fingerprint text)
 RETURNS TABLE(result jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request jsonb := public.newsroom_mesa_normalize_intent_v1(p_request);
  v_key uuid := (v_request ->> 'preparationKey')::uuid;
  v_existing public.newsroom_mesa_intent_preparations%rowtype;
  v_preview jsonb; v_contexts jsonb := '[]'; v_context jsonb; v_item jsonb;
  v_result record; v_context_id uuid; v_plan_id uuid; v_ids uuid[]; v_plan_ids uuid[] := '{}';
  v_frozen_contexts jsonb := '[]'; v_outputs jsonb := '[]'; v_frozen jsonb; v_i integer := 0;
begin
  if p_expected_authority_fingerprint is null or p_expected_authority_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'mesa-intent-fingerprint-invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-organization-v1',0));
  -- Test idempotency before current-state reads: a retry must not be invalidated
  -- by memberships created by its own first successful call.
  select * into v_existing from public.newsroom_mesa_intent_preparations p where p.preparation_key = v_key;
  if found then
    if v_existing.request is distinct from v_request or v_existing.authority_fingerprint is distinct from p_expected_authority_fingerprint then
      raise exception 'mesa-intent-preparation-conflict';
    end if;
    return query select jsonb_build_object('dossierId',v_existing.dossier_id,'preparationAction','reused','plan',v_existing.frozen_plan);
    return;
  end if;
  if exists (select 1 from public.newsroom_mesa_production_contexts w where w.preparation_key = v_key)
    or exists (select 1 from public.newsroom_editorial_dossiers d where d.preparation_key = v_key)
  then raise exception 'mesa-intent-preparation-key-used'; end if;
  update public.newsroom_mesa_containment_guard set revision = not revision where singleton;
  if not found then raise exception 'mesa-organization-containment-guard-missing'; end if;
  perform 1 from public.newsroom_editorial_themes t where t.id in (
    select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'
    union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)) x
  ) order by t.id for update;
  -- Parent FOR UPDATE locks also block an ingest inserting a new snapshot through
  -- its FK while sources are frozen. Existing snapshot rows are locked as well.
  perform 1 from public.newsroom_articles a where a.id in (
    select (x ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') x where x ->> 'destination' <> 'defer'
    union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'sourceIds','[]'::jsonb)) x
    union select m.newsroom_article_id from public.newsroom_editorial_theme_sources m
      where m.theme_id in (
        select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'
        union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)) x
      )
  ) order by a.id for update;
  perform 1 from public.newsroom_article_snapshots s where s.article_id in (
    select a.id from public.newsroom_articles a where a.id in (
      select (x ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') x where x ->> 'destination' <> 'defer'
    union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'sourceIds','[]'::jsonb)) x
      union select m.newsroom_article_id from public.newsroom_editorial_theme_sources m where m.theme_id in (
        select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'
        union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)) x))
  ) order by s.id for share;
  perform 1 from public.newsroom_editorial_article_classifications c where c.newsroom_article_id in (
    select (x ->> 'sourceId')::uuid from jsonb_array_elements(v_request -> 'sources') x where x ->> 'destination' <> 'defer'
    union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'sourceIds','[]'::jsonb)) x
    union select m.newsroom_article_id from public.newsroom_editorial_theme_sources m where m.theme_id in (
      select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare'
      union select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'themeIds','[]'::jsonb)) x)
  ) order by c.newsroom_article_id for share;
  perform 1 from public.editorial_articles a where a.id in (
    select m.editorial_article_id from public.newsroom_editorial_theme_articles m where m.theme_id in (
      select (x ->> 'themeId')::uuid from jsonb_array_elements(v_request -> 'themes') x where x ->> 'action' = 'prepare')
    union select (x #>> '{}')::uuid
      from jsonb_array_elements(coalesce(v_request -> 'selection' -> 'reviewArticleIds','[]'::jsonb)) x
  ) order by a.id for share;
  select p.plan into strict v_preview from public.newsroom_mesa_preview_intents_v1(v_request) p;
  if v_preview ->> 'authorityFingerprint' is distinct from p_expected_authority_fingerprint then
    raise exception 'mesa-intent-authority-stale';
  end if;
  -- Incorporations and all workspaces/plans share THIS transaction. Any later
  -- exception rolls everything back; previewing the request never associates.
  for v_item in select value from jsonb_array_elements(v_preview -> 'incorporations') loop
    perform public.newsroom_set_editorial_theme_source_membership_v1((v_item ->> 'themeId')::uuid,(v_item ->> 'sourceId')::uuid,true);
  end loop;
  for v_context in select value from jsonb_array_elements(v_preview -> 'contexts') loop
    v_contexts := v_contexts || jsonb_build_array(jsonb_build_object('kind',v_context -> 'kind',
      'themeId',v_context -> 'themeId','sourceId',v_context -> 'sourceId',
      'sources',(select jsonb_agg(jsonb_build_object('newsroomArticleId',s -> 'newsroomArticleId',
        'newsroomSnapshotId',s -> 'newsroomSnapshotId') order by s ->> 'newsroomArticleId') from jsonb_array_elements(v_context -> 'sources') s)));
  end loop;
  select * into strict v_result from public.newsroom_prepare_mesa_contexts_v3(v_key,v_request ->> 'title',v_contexts,null,'{}');
  for v_context in select value from jsonb_array_elements(v_preview -> 'contexts') loop
    select c.id into strict v_context_id from public.newsroom_mesa_production_context_items c
      where c.dossier_id = v_result.dossier_id and c.context_kind = v_context ->> 'kind'
        and c.theme_id is not distinct from (v_context ->> 'themeId')::uuid
        and c.source_newsroom_article_id is not distinct from (v_context ->> 'sourceId')::uuid;
    v_frozen_contexts := v_frozen_contexts || jsonb_build_array(v_context || jsonb_build_object('productionContextId',v_context_id));
  end loop;
  for v_item in select value from jsonb_array_elements(v_preview -> 'outputs') loop
    v_i := v_i + 1;
    select c into strict v_context from jsonb_array_elements(v_frozen_contexts) c where c ->> 'key' = v_item ->> 'contextKey';
    v_context_id := (v_context ->> 'productionContextId')::uuid;
    select array_agg(s.dossier_source_id order by s.sort_order) into v_ids
      from public.newsroom_mesa_production_context_sources s where s.dossier_id = v_result.dossier_id and s.production_context_id = v_context_id;
    select p.article_plan_id into strict v_plan_id from public.newsroom_save_mesa_context_article_plan_v1(
      v_result.dossier_id,null,left((v_item ->> 'slot') || ' — ' || coalesce(v_item -> 'target' ->> 'title','novo artigo'),180),
      'planned',v_i*10,'news','standard',case when v_item ->> 'kind' = 'existing' then 'Rever o artigo: UPDATE ou SEM ALTERAÇÃO.'
        else 'Produzir artigo novo apenas com as fontes deste contexto; não rever os artigos de referência.' end,v_ids,v_context_id) p;
    perform public.newsroom_save_dossier_article_plan_state_v1(v_result.dossier_id,v_plan_id,
      case when v_item ->> 'kind' = 'existing' then 'update' else 'new' end,
      (v_item -> 'target' ->> 'editorialArticleId')::uuid,'{}',
      case when v_item ->> 'kind' = 'existing' then 'preserve_published' else 'unselected' end,null);
    v_plan_ids := v_plan_ids || v_plan_id;
    v_outputs := v_outputs || jsonb_build_array(v_item || jsonb_build_object('outputId',v_plan_id,'productionContextId',v_context_id));
  end loop;
  perform public.newsroom_set_mesa_shared_outputs_v2(v_result.dossier_id,v_plan_ids);
  v_frozen := v_preview || jsonb_build_object('dossierId',v_result.dossier_id,'contexts',v_frozen_contexts,'outputs',v_outputs);
  insert into public.newsroom_mesa_intent_preparations(preparation_key,dossier_id,request,authority_fingerprint,captured_at,frozen_plan)
    values(v_key,v_result.dossier_id,v_request,p_expected_authority_fingerprint,(v_preview ->> 'capturedAt')::timestamptz,v_frozen);
  update public.newsroom_mesa_production_contexts set selection_payload = selection_payload || jsonb_build_object('productionIntents',v_frozen)
    where dossier_id = v_result.dossier_id;
  return query select jsonb_build_object('dossierId',v_result.dossier_id,'preparationAction','created','plan',v_frozen);
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_prepare_mesa_materials_v2(p_preparation_key uuid, p_theme_id uuid, p_title text, p_source_refs jsonb, p_material_refs jsonb)
 RETURNS TABLE(dossier_id uuid, preparation_action text, source_count integer, published_context_count integer, image_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb; v_existing public.newsroom_mesa_production_contexts%rowtype; v_result record;
  v_ref jsonb; v_version public.newsroom_mesa_material_versions%rowtype;
  v_refs jsonb; v_materials jsonb:='[]'::jsonb; v_context_ids uuid[]:='{}'::uuid[];
begin
  if p_preparation_key is null or nullif(btrim(p_title),'') is null or length(btrim(p_title))>180
    or p_material_refs is null or jsonb_typeof(p_material_refs)<>'array' or jsonb_array_length(p_material_refs)>50 then
    raise exception 'mesa-material-selection-invalid'; end if;
  if exists(select 1 from jsonb_array_elements(p_material_refs) r group by lower(r->>'key') having count(*)>1) then
    raise exception 'mesa-material-selection-invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-organization-v1',0));
  update public.newsroom_mesa_containment_guard set revision=not revision where singleton;
  if not found then raise exception 'mesa-organization-containment-guard-missing'; end if;
  v_payload:=jsonb_build_object('contractVersion',2,'theme',p_theme_id,'title',btrim(p_title),
    'sources',p_source_refs,'materials',p_material_refs);
  select * into v_existing from public.newsroom_mesa_production_contexts c
    where c.preparation_key=p_preparation_key;
  if found then
    if v_existing.selection_payload is distinct from v_payload
      or v_existing.workspace_contract_version is distinct from 2::smallint
      or v_existing.workspace_state is distinct from 'active' then
      raise exception 'mesa-material-preparation-conflict'; end if;
    return query select v_existing.dossier_id,'reused'::text,jsonb_array_length(v_existing.source_refs),
      (select count(*)::integer from public.newsroom_editorial_dossier_published_contexts pc where pc.dossier_id=v_existing.dossier_id),
      (select count(*)::integer from public.newsroom_editorial_dossier_images i where i.dossier_id=v_existing.dossier_id);
    return;
  end if;
  if exists(select 1 from public.newsroom_editorial_dossiers d where d.preparation_key=p_preparation_key) then
    raise exception 'mesa-material-prepared-before-v2'; end if;
  if p_theme_id is not null then
    perform 1 from public.newsroom_editorial_themes t where t.id=p_theme_id and t.status='open' for update;
    if not found then raise exception 'mesa-organization-theme-unavailable'; end if;
  end if;
  v_refs:=public.newsroom_mesa_normalize_refs_v2(p_source_refs);
  for v_ref in select r from jsonb_array_elements(p_material_refs) r loop
    v_version:=public.newsroom_mesa_capture_material_v2(v_ref);
    v_refs:=v_refs || v_version.source_refs;
    v_context_ids:=v_context_ids || v_version.article_ids;
    v_materials:=v_materials || jsonb_build_array(jsonb_build_object(
      'key',v_version.material_key,'versionId',v_version.id,'sources',v_version.source_refs));
  end loop;
  v_refs:=public.newsroom_mesa_normalize_refs_v2(v_refs);
  v_context_ids:=array(select distinct a from unnest(v_context_ids) a order by a);
  if cardinality(v_context_ids)>20 then raise exception 'mesa-material-context-limit'; end if;
  if exists(select 1 from unnest(v_context_ids) requested(id) where not exists(
    select 1 from public.editorial_articles a where a.id=requested.id and a.status='published')) then
    raise exception 'mesa-material-context-unavailable'; end if;
  if jsonb_array_length(v_refs)<1 or jsonb_array_length(v_refs)>20 then raise exception 'mesa-material-selection-invalid'; end if;
  if exists(select 1 from jsonb_array_elements(v_refs) r where not exists(
    select 1 from public.newsroom_editorial_article_classifications c
      where c.newsroom_article_id=(r->>'newsroomArticleId')::uuid)) then
    raise exception 'mesa-material-classification-required'; end if;
  select * into v_result from public.newsroom_prepare_editorial_dossier_workspace_v1(
    p_preparation_key,btrim(p_title),
    array(select (r->>'newsroomArticleId')::uuid from jsonb_array_elements(v_refs) r),
    array(select (r->>'newsroomSnapshotId')::uuid from jsonb_array_elements(v_refs) r),v_context_ids);
  insert into public.newsroom_mesa_production_contexts(
    dossier_id,theme_id,preparation_key,selection_payload,source_refs,material_refs,
    workspace_role,workspace_contract_version,workspace_state
  ) values (
    v_result.dossier_id,p_theme_id,p_preparation_key,v_payload,v_refs,v_materials,
    'technical',2,'active'
  );
  return query select v_result.dossier_id,v_result.preparation_action,v_result.source_count,
    v_result.published_context_count,v_result.image_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_prepare_theme_continuity_v1(p_preparation_key uuid, p_theme_id uuid, p_new_article_count integer, p_expected_authority_fingerprint text)
 RETURNS TABLE(dossier_id uuid, production_context_id uuid, preparation_action text, source_count integer, published_article_count integer, new_article_count integer, output_count integer, authority_fingerprint text, slots jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_read record;
  v_result record;
  v_theme_title text;
  v_contexts jsonb;
  v_context_id uuid;
  v_dossier_source_ids uuid[];
  v_plan_ids uuid[] := '{}'::uuid[];
  v_plan_id uuid;
  v_slots jsonb := '[]'::jsonb;
  v_slot jsonb;
  v_item jsonb;
  v_ordinality bigint;
  v_output_count integer;
  v_existing_payload jsonb;
begin
  if p_preparation_key is null or p_theme_id is null
    or p_new_article_count is null or p_new_article_count < 0
    or p_new_article_count > 30
    or nullif(btrim(coalesce(p_expected_authority_fingerprint, '')), '') is null
  then
    raise exception 'theme-continuity-preparation-input-invalid';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-organization-v1', 0));
  update public.newsroom_mesa_containment_guard
    set revision = not revision
    where singleton;
  if not found then
    raise exception 'mesa-organization-containment-guard-missing';
  end if;

  select t.title into v_theme_title
  from public.newsroom_editorial_themes t
  where t.id = p_theme_id and t.status = 'open'
  for update;
  if not found then
    raise exception 'theme-continuity-theme-unavailable';
  end if;

  select * into v_read
  from public.newsroom_mesa_theme_continuity_v1(p_theme_id);
  if not found or v_read.authority_fingerprint is distinct from p_expected_authority_fingerprint then
    raise exception 'theme-continuity-authority-stale';
  end if;
  if v_read.source_count not between 1 and 20 then
    raise exception 'theme-continuity-source-limit';
  end if;
  v_output_count := v_read.published_article_count + p_new_article_count;
  if v_output_count not between 1 and 30 then
    raise exception 'theme-continuity-output-limit';
  end if;
  -- These locks keep source metadata, frozen snapshot bodies and published
  -- targets stable until the workspace has been created.
  perform 1
  from public.newsroom_articles article
  where article.id in (
    select (source.value ->> 'newsroomArticleId')::uuid
    from jsonb_array_elements(v_read.sources) source(value)
  )
  for share;
  perform 1
  from public.newsroom_article_snapshots snapshot
  where snapshot.id in (
    select (source.value ->> 'latestSnapshotId')::uuid
    from jsonb_array_elements(v_read.sources) source(value)
    where source.value ->> 'latestSnapshotId' is not null
  )
  for share;
  perform 1
  from public.editorial_articles article
  where article.id in (
    select (published.value ->> 'editorialArticleId')::uuid
    from jsonb_array_elements(v_read.published_articles) published(value)
  )
  for share;

  select * into v_read
  from public.newsroom_mesa_theme_continuity_v1(p_theme_id);
  if not found or v_read.authority_fingerprint is distinct from p_expected_authority_fingerprint then
    raise exception 'theme-continuity-authority-stale';
  end if;
  if exists (
    select 1 from jsonb_array_elements(v_read.sources) source(value)
    where source.value ->> 'latestSnapshotId' is null
  ) then
    raise exception 'theme-continuity-source-snapshot-unavailable';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_read.sources) source(value)
    join public.newsroom_article_snapshots snapshot
      on snapshot.id = (source.value ->> 'latestSnapshotId')::uuid
    where jsonb_typeof(snapshot.body) is distinct from 'array'
      or not exists (
        select 1
        from jsonb_array_elements(
          case when jsonb_typeof(snapshot.body) = 'array'
            then snapshot.body else '[]'::jsonb end
        ) block(value)
        where block.value ->> 'type' in ('paragraph', 'heading')
          and nullif(btrim(block.value ->> 'text'), '') is not null
      )
  ) then
    raise exception 'theme-continuity-source-snapshot-unusable';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_read.published_articles) published(value)
    where nullif(btrim(published.value ->> 'editorialArticleId'), '') is null
      or nullif(btrim(published.value ->> 'slug'), '') is null
      or nullif(btrim(published.value ->> 'title'), '') is null
      or nullif(btrim(published.value ->> 'matchdayId'), '') is null
  ) then
    raise exception 'theme-continuity-published-target-unavailable';
  end if;

  v_contexts := jsonb_build_array(jsonb_build_object(
    'kind', 'theme',
    'themeId', p_theme_id,
    'sources', (
      select jsonb_agg(jsonb_build_object(
        'newsroomArticleId', source.value ->> 'newsroomArticleId',
        'newsroomSnapshotId', source.value ->> 'latestSnapshotId'
      ) order by source.ordinality)
      from jsonb_array_elements(v_read.sources) with ordinality source(value, ordinality)
    )
  ));

  select * into v_result
  from public.newsroom_prepare_mesa_contexts_v3(
    p_preparation_key,
    left(v_theme_title || ' — continuidade', 180),
    v_contexts,
    null,
    '{}'::uuid[]
  );

  select context_item.id into strict v_context_id
  from public.newsroom_mesa_production_context_items context_item
  where context_item.dossier_id = v_result.dossier_id
    and context_item.context_kind = 'theme'
    and context_item.theme_id = p_theme_id;

  select workspace.selection_payload into strict v_existing_payload
  from public.newsroom_mesa_production_contexts workspace
  where workspace.dossier_id = v_result.dossier_id
  for update;

  if v_existing_payload ? 'themeContinuity' then
    if v_existing_payload -> 'themeContinuity' ->> 'authorityFingerprint'
        is distinct from v_read.authority_fingerprint
      or (v_existing_payload -> 'themeContinuity' ->> 'newArticleCount')::integer
        is distinct from p_new_article_count
      or jsonb_array_length(v_existing_payload -> 'themeContinuity' -> 'slots')
        is distinct from v_output_count
    then
      raise exception 'theme-continuity-preparation-conflict';
    end if;
    return query select v_result.dossier_id, v_context_id, 'reused'::text,
      v_read.source_count, v_read.published_article_count, p_new_article_count,
      v_output_count, v_read.authority_fingerprint,
      v_existing_payload -> 'themeContinuity' -> 'slots';
    return;
  end if;

  select array_agg(source.id order by context_source.sort_order)
  into v_dossier_source_ids
  from public.newsroom_mesa_production_context_sources context_source
  join public.newsroom_editorial_dossier_sources source
    on source.dossier_id = context_source.dossier_id
    and source.id = context_source.dossier_source_id
  where context_source.dossier_id = v_result.dossier_id
    and context_source.production_context_id = v_context_id;

  for v_item, v_ordinality in
    select published.value, published.ordinality
    from jsonb_array_elements(v_read.published_articles)
      with ordinality published(value, ordinality)
  loop
    select saved.article_plan_id into strict v_plan_id
    from public.newsroom_save_mesa_context_article_plan_v1(
      v_result.dossier_id,
      null,
      left('EXISTING_' || lpad(v_ordinality::text, 2, '0') || ' — '
        || (v_item ->> 'title'), 180),
      'planned',
      v_ordinality::integer * 10,
      'news',
      'standard',
      'Rever o artigo publicado e decidir UPDATE ou SEM_ALTERAÇÃO.',
      v_dossier_source_ids,
      v_context_id
    ) saved;
    perform public.newsroom_save_dossier_article_plan_state_v1(
      v_result.dossier_id,
      v_plan_id,
      'update',
      (v_item ->> 'editorialArticleId')::uuid,
      '{}'::uuid[],
      'preserve_published',
      null
    );
    v_plan_ids := v_plan_ids || v_plan_id;
    v_slots := v_slots || jsonb_build_array(jsonb_build_object(
      'slot', 'EXISTING_' || lpad(v_ordinality::text, 2, '0'),
      'kind', 'existing',
      'outputId', v_plan_id,
      'productionContextId', v_context_id,
      'targetEditorialArticleId', v_item ->> 'editorialArticleId',
      'targetSlug', v_item ->> 'slug',
      'targetTitle', v_item ->> 'title',
      'targetMatchdayId', v_item ->> 'matchdayId'
    ));
  end loop;

  for v_ordinality in 1..p_new_article_count
  loop
    select saved.article_plan_id into strict v_plan_id
    from public.newsroom_save_mesa_context_article_plan_v1(
      v_result.dossier_id,
      null,
      'NEW_' || lpad(v_ordinality::text, 2, '0') || ' — novo artigo',
      'planned',
      (v_read.published_article_count + v_ordinality)::integer * 10,
      'news',
      'standard',
      'Produzir um novo artigo distinto dos artigos existentes em revisão.',
      v_dossier_source_ids,
      v_context_id
    ) saved;
    perform public.newsroom_save_dossier_article_plan_state_v1(
      v_result.dossier_id,
      v_plan_id,
      'new',
      null,
      '{}'::uuid[],
      'unselected',
      null
    );
    v_plan_ids := v_plan_ids || v_plan_id;
    v_slots := v_slots || jsonb_build_array(jsonb_build_object(
      'slot', 'NEW_' || lpad(v_ordinality::text, 2, '0'),
      'kind', 'new',
      'outputId', v_plan_id,
      'productionContextId', v_context_id,
      'targetEditorialArticleId', null
    ));
  end loop;

  perform public.newsroom_set_mesa_shared_outputs_v2(v_result.dossier_id, v_plan_ids);

  update public.newsroom_mesa_production_contexts workspace
  set selection_payload = jsonb_set(
    workspace.selection_payload,
    '{themeContinuity}',
    jsonb_build_object(
      'contractVersion', 1,
      'themeId', p_theme_id,
      'authorityFingerprint', v_read.authority_fingerprint,
      'baselineDossierId', v_read.baseline ->> 'dossierId',
      'baselineConsolidatedAt', v_read.baseline ->> 'consolidatedAt',
      'sourceDiff', (
        select jsonb_agg(jsonb_build_object(
          'newsroomArticleId', source.value ->> 'newsroomArticleId',
          'newsroomSnapshotId', source.value ->> 'latestSnapshotId',
          'change', source.value ->> 'change'
        ) order by source.ordinality)
        from jsonb_array_elements(v_read.sources) with ordinality source(value, ordinality)
      ),
      'publishedArticleCount', v_read.published_article_count,
      'newArticleCount', p_new_article_count,
      'slots', v_slots
    ),
    true
  )
  where workspace.dossier_id = v_result.dossier_id;

  return query select v_result.dossier_id, v_context_id,
    v_result.preparation_action, v_read.source_count,
    v_read.published_article_count, p_new_article_count, v_output_count,
    v_read.authority_fingerprint, v_slots;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_prepare_theme_dossier_v1(p_theme_id uuid, p_preparation_key uuid, p_title text, p_newsroom_article_ids uuid[], p_newsroom_snapshot_ids uuid[], p_published_context_article_ids uuid[])
 RETURNS TABLE(dossier_id uuid, preparation_action text, source_count integer, published_context_count integer, image_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result record;
begin
  if p_theme_id is null then raise exception 'mesa-organization-invalid-input'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('newsroom-mesa-organization-v1', 0));
  perform 1 from public.newsroom_editorial_themes t where t.id = p_theme_id and t.status = 'open' for update;
  if not found then raise exception 'mesa-organization-theme-unavailable'; end if;
  -- The explicit preparation may add selected NOVAS to the chosen Theme.
  -- The foundation validates sources/snapshots; attachment below adds membership.
  select * into v_result from public.newsroom_prepare_editorial_dossier_workspace_v1(
    p_preparation_key,p_title,p_newsroom_article_ids,p_newsroom_snapshot_ids,p_published_context_article_ids
  );
  perform public.newsroom_attach_dossier_to_theme_v1(v_result.dossier_id,p_theme_id);
  return query select v_result.dossier_id,v_result.preparation_action,v_result.source_count,
    v_result.published_context_count,v_result.image_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_protect_bound_mesa_plan_context_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1 from public.newsroom_mesa_output_publications publication
    where publication.dossier_id = old.dossier_id and publication.article_plan_id = old.article_plan_id
  ) or exists (
    select 1
    from public.newsroom_editorial_source_packages package,
      jsonb_array_elements(coalesce(package.manifest -> 'outputs', '[]'::jsonb)) output
    where output -> 'articlePlan' ->> 'sourceScope' = 'context'
      and lower(output -> 'articlePlan' ->> 'dossierId') = old.dossier_id::text
      and lower(output -> 'articlePlan' ->> 'articlePlanId') = old.article_plan_id::text
  ) then
    raise exception 'mesa-article-plan-context-already-bound' using errcode = '23514';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_protect_frozen_dossier_source_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' and exists (
    select 1 from public.newsroom_mesa_production_context_sources frozen
    where frozen.dossier_id = old.dossier_id and frozen.dossier_source_id = old.id
  ) then
    raise exception 'mesa-production-context-source-immutable' using errcode = '23514';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  if exists (
    select 1 from public.newsroom_mesa_production_context_sources frozen
    where frozen.dossier_id = old.dossier_id and frozen.dossier_source_id = old.id
  ) and (
    new.dossier_id is distinct from old.dossier_id
    or new.newsroom_article_id is distinct from old.newsroom_article_id
    or new.newsroom_snapshot_id is distinct from old.newsroom_snapshot_id
    or new.included is distinct from old.included
  ) then
    raise exception 'mesa-production-context-source-immutable' using errcode = '23514';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_publish_mesa_intent_output_v1(p_dossier_id uuid, p_output_id uuid, p_package_id uuid, p_dossier_source_ids uuid[], p_article jsonb)
 RETURNS TABLE(editorial_article_id uuid, article_slug text, publication_action text, consolidated boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_intent jsonb; v_slot jsonb; v_expected jsonb; v_current jsonb;
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_plan public.newsroom_editorial_dossier_article_plans%rowtype;
  v_manifest jsonb; v_manifest_output jsonb;
  v_existing public.newsroom_mesa_output_publications%rowtype;
  v_article_id uuid; v_slug text; v_label text; v_title text; v_subtitle text; v_body text;
  v_image text; v_author text; v_published_at timestamptz; v_matchday uuid; v_mode text;
  v_previous_slug text; v_source_scope text := 'workspace'; v_production_context_id uuid;
  v_declared_context_source_ids uuid[]; v_frozen_context_source_ids uuid[];
  v_is_2c boolean;
  v_payload jsonb; v_fingerprint text; v_consolidated boolean; v_now timestamptz := now();
begin
  if p_dossier_id is null or p_output_id is null or p_package_id is null
    or p_dossier_source_ids is null or cardinality(p_dossier_source_ids) < 1
    or cardinality(p_dossier_source_ids) > 20 or array_position(p_dossier_source_ids, null) is not null
    or (select count(distinct source_id) from unnest(p_dossier_source_ids) source_id) <> cardinality(p_dossier_source_ids)
    or p_article is null or jsonb_typeof(p_article) <> 'object' then
    raise exception 'mesa-publication-input-invalid';
  end if;

  -- All intent writers/finalizers acquire the workspace first, then canonical
  -- articles in ID order. Publication never calls the generic consolidator.
  v_intent := public.newsroom_mesa_lock_intent_publication_v1(p_dossier_id,p_package_id);
  select o into v_slot from jsonb_array_elements(v_intent -> 'outputs') o
    where o ->> 'outputId' = p_output_id::text;
  if not found then raise exception 'mesa-intent-output-invalid'; end if;
  v_expected := v_slot -> 'target';
  select * into v_context from public.newsroom_mesa_production_contexts context
    where context.dossier_id = p_dossier_id for update;
  if not found or v_context.workspace_role <> 'technical' or v_context.workspace_contract_version <> 2
    or v_context.workspace_state not in ('active', 'consolidated') then
    raise exception 'mesa-publication-workspace-invalid';
  end if;

  v_is_2c := coalesce(
    v_context.selection_payload ->> 'contractVersion' = '3'
      and v_context.selection_payload ->> 'contextContractVersion' = '1',
    false
  );
  if coalesce(
    v_context.selection_payload ->> 'contractVersion' = '3'
      or v_context.selection_payload ? 'contextContractVersion',
    false
  ) and not v_is_2c then
    raise exception 'mesa-publication-workspace-invalid';
  end if;
  if v_is_2c is distinct from (exists (
      select 1 from public.newsroom_mesa_production_context_items context_item
      where context_item.dossier_id = p_dossier_id
    )) then
    raise exception 'mesa-publication-workspace-invalid';
  end if;

  select * into v_plan from public.newsroom_editorial_dossier_article_plans plan
    where plan.dossier_id = p_dossier_id and plan.id = p_output_id
      and plan.status <> 'cancelled' for update;
  if not found then raise exception 'mesa-publication-output-invalid'; end if;

  if v_is_2c then
    select assignment.production_context_id
    into v_production_context_id
    from public.newsroom_mesa_article_plan_contexts assignment
    where assignment.dossier_id = p_dossier_id
      and assignment.article_plan_id = p_output_id;
    if not found or not public.newsroom_mesa_plan_context_sources_valid_v1(
      p_dossier_id, p_output_id, v_production_context_id
    ) then
      raise exception 'mesa-publication-output-invalid';
    end if;
    v_source_scope := 'context';
  elsif exists (
    select 1 from public.newsroom_mesa_article_plan_contexts assignment
    where assignment.dossier_id = p_dossier_id
      and assignment.article_plan_id = p_output_id
  ) then
    raise exception 'mesa-publication-workspace-invalid';
  end if;

  select package.manifest into v_manifest from public.newsroom_editorial_source_packages package
    where package.id = p_package_id for update;
  if not found or (v_manifest ->> 'version')::integer <> 5
    or v_manifest ->> 'provenanceContract' <> 'mesa-v2' then
    raise exception 'mesa-publication-package-invalid';
  end if;

  select output.value into v_manifest_output
  from jsonb_array_elements(v_manifest -> 'outputs') output(value)
  where lower(output.value ->> 'outputId') = p_output_id::text
    and lower(output.value -> 'articlePlan' ->> 'articlePlanId') = p_output_id::text
    and lower(output.value -> 'articlePlan' ->> 'dossierId') = p_dossier_id::text;
  if not found
    or v_manifest_output -> 'articlePlan' ->> 'sourceScope' is distinct from v_source_scope
    or v_manifest_output -> 'articlePlan' ? 'origin' then
    raise exception 'mesa-publication-package-invalid';
  end if;

  if v_source_scope = 'context' then
    if lower(v_manifest_output -> 'articlePlan' ->> 'contextId')
      is distinct from v_production_context_id::text
      or jsonb_typeof(v_manifest_output -> 'contextSourceIds') is distinct from 'array'
    then
      raise exception 'mesa-publication-package-invalid';
    end if;
    begin
      select array_agg((source_id.value #>> '{}')::uuid order by (source_id.value #>> '{}')::uuid)
      into v_declared_context_source_ids
      from jsonb_array_elements(v_manifest_output -> 'contextSourceIds') source_id(value);
    exception when others then
      raise exception 'mesa-publication-package-invalid';
    end;
    select array_agg(context_source.dossier_source_id order by context_source.dossier_source_id)
    into v_frozen_context_source_ids
    from public.newsroom_mesa_production_context_sources context_source
    where context_source.dossier_id = p_dossier_id
      and context_source.production_context_id = v_production_context_id;
    if v_declared_context_source_ids is distinct from v_frozen_context_source_ids
      or exists (
        select 1 from unnest(p_dossier_source_ids) requested(id)
        where not (requested.id = any(v_frozen_context_source_ids))
      )
    then
      raise exception 'mesa-publication-source-invalid';
    end if;
  end if;

  if exists(select 1 from unnest(p_dossier_source_ids) requested(id)
    left join public.newsroom_editorial_dossier_sources dossier_source
      on dossier_source.id = requested.id
      and dossier_source.dossier_id = p_dossier_id
      and dossier_source.included
    where dossier_source.id is null
      or not exists(select 1 from jsonb_array_elements(v_context.source_refs) ref
        where lower(ref ->> 'newsroomArticleId') = dossier_source.newsroom_article_id::text
          and lower(ref ->> 'newsroomSnapshotId') = dossier_source.newsroom_snapshot_id::text)
      or not exists(select 1 from jsonb_array_elements(v_manifest -> 'entries') entry
        where entry ->> 'status' = 'prepared'
          and lower(entry ->> 'provenanceSourceId') = requested.id::text
          and lower(entry ->> 'newsroomArticleId') = dossier_source.newsroom_article_id::text
          and lower(entry ->> 'newsroomSnapshotId') = dossier_source.newsroom_snapshot_id::text)
  ) then raise exception 'mesa-publication-source-invalid'; end if;

  begin
    v_article_id := (p_article ->> 'id')::uuid;
  exception when others then
    raise exception 'mesa-publication-article-invalid';
  end;
  v_slug := btrim(coalesce(p_article ->> 'slug', ''));
  v_label := btrim(coalesce(p_article ->> 'label', ''));
  v_title := btrim(coalesce(p_article ->> 'title', ''));
  v_subtitle := btrim(coalesce(p_article ->> 'subtitle', ''));
  v_body := btrim(coalesce(p_article ->> 'body', ''));
  v_image := nullif(btrim(coalesce(p_article ->> 'imageUrl', '')), '');
  v_author := btrim(coalesce(p_article ->> 'author', ''));
  v_mode := lower(btrim(coalesce(p_article ->> 'mode', '')));
  begin
    v_published_at := (p_article ->> 'publishedAt')::timestamptz;
    v_matchday := (p_article ->> 'matchdayId')::uuid;
  exception when others then
    raise exception 'mesa-publication-article-invalid';
  end;
  if v_article_id is null or v_published_at is null
    or v_slug = '' or v_label = '' or v_title = '' or v_subtitle = '' or v_body = '' or v_author = ''
    or v_mode not in ('create', 'update') then
    raise exception 'mesa-publication-article-invalid';
  end if;

  v_payload := jsonb_build_object(
    'article', jsonb_build_object(
      'id', v_article_id, 'slug', v_slug, 'label', v_label, 'title', v_title,
      'subtitle', v_subtitle, 'body', v_body, 'imageUrl', v_image, 'author', v_author,
      'publishedAt', v_published_at, 'matchdayId', v_matchday, 'mode', v_mode
    ),
    'sources', (select to_jsonb(array_agg(source_id order by source_id)) from unnest(p_dossier_source_ids) source_id),
    'packageId', p_package_id,
    'outputId', p_output_id,
    'sourceScope', v_source_scope
  ) || case when v_source_scope = 'context'
    then jsonb_build_object('contextId', v_production_context_id)
    else '{}'::jsonb end;
  v_fingerprint := md5(v_payload::text);

  select * into v_existing from public.newsroom_mesa_output_publications publication
    where publication.dossier_id = p_dossier_id and publication.article_plan_id = p_output_id;
  if found then
    if v_existing.fingerprint <> v_fingerprint or v_existing.editorial_article_id <> v_article_id
      or v_existing.source_scope is distinct from v_source_scope
      or v_existing.production_context_id is distinct from v_production_context_id
      or not exists(select 1 from public.editorial_articles article
        where article.id = v_article_id and article.status = 'published') then
      raise exception 'mesa-publication-provenance-conflict';
    end if;
    -- Retry never overwrites a later manual edit, even after the first write.
    select to_jsonb(a) into v_current from public.editorial_articles a where a.id=v_article_id for update;
    if encode(sha256(convert_to(v_current::text,'UTF8')),'hex')
        is distinct from v_existing.payload ->> 'intentResultFingerprint' then
      raise exception 'mesa-intent-published-result-stale';
    end if;
    return query select v_article_id, v_slug, 'reused'::text,
      v_context.workspace_state = 'consolidated';
    return;
  end if;
  if v_context.workspace_state = 'consolidated' then
    raise exception 'mesa-publication-provenance-conflict';
  end if;

  if v_mode = 'create' then
    if v_slot ->> 'kind' <> 'new' or v_matchday is null
      or v_plan.destination <> 'new' or v_plan.update_target_editorial_article_id is not null
      or v_image is null
      or exists(select 1 from public.editorial_articles article
        where article.id = v_article_id or article.slug = v_slug) then
      raise exception 'mesa-publication-article-conflict';
    end if;
    insert into public.editorial_articles(
      id, status, scope, author, label, title, subtitle, body, slug, image_url,
      image_caption, published_at, competition_id, season_id, matchday_id, created_at, updated_at
    ) values (
      v_article_id, 'published', 'matchday', v_author, v_label, v_title, v_subtitle,
      v_body, v_slug, v_image, null, v_published_at, null, null, v_matchday, v_now, v_now
    );
  else
    if v_slot ->> 'kind' <> 'existing' or v_plan.destination <> 'update'
      or v_plan.update_target_editorial_article_id is distinct from v_article_id
      or v_expected ->> 'editorialArticleId' is distinct from v_article_id::text
      or v_expected ->> 'slug' is distinct from v_slug
      or (v_expected ->> 'matchdayId')::uuid is distinct from v_matchday then
      raise exception 'mesa-publication-update-target-invalid';
    end if;
    select to_jsonb(article), article.slug into v_current, v_previous_slug
      from public.editorial_articles article
      where article.id=v_article_id and article.status='published' for update;
    if not found or encode(sha256(convert_to(v_current::text,'UTF8')),'hex')
        is distinct from v_expected ->> 'contentFingerprint' then
      raise exception 'mesa-intent-update-target-stale';
    end if;
    -- Preserve scope, competition, season, matchday (including NULL), slug,
    -- publication date, caption and all other non-editorial identity fields.
    update public.editorial_articles article
      set label=v_label, title=v_title, subtitle=v_subtitle, body=v_body,
        author=v_author, image_url=coalesce(v_image,article.image_url), updated_at=v_now
      where article.id=v_article_id and article.status='published'
        and article.matchday_id is not distinct from v_matchday and article.slug=v_slug;
    if not found then raise exception 'mesa-publication-update-target-invalid'; end if;
  end if;

  insert into public.newsroom_mesa_output_publications(
    dossier_id, article_plan_id, package_id, editorial_article_id, source_scope,
    production_context_id, origin_kind, origin_dossier_source_id, material_key,
    material_version_id, fingerprint, payload
  ) values (
    p_dossier_id, p_output_id, p_package_id, v_article_id, v_source_scope,
    v_production_context_id, null, null, null, null, v_fingerprint,
    v_payload || jsonb_build_object('intentResultFingerprint',(
      select encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex')
      from public.editorial_articles a where a.id=v_article_id
    ))
  );
  insert into public.newsroom_mesa_output_source_usage(
    dossier_id, article_plan_id, dossier_source_id, newsroom_article_id,
    newsroom_snapshot_id, editorial_article_id, package_id
  ) select p_dossier_id, p_output_id, dossier_source.id, dossier_source.newsroom_article_id,
      dossier_source.newsroom_snapshot_id, v_article_id, p_package_id
    from public.newsroom_editorial_dossier_sources dossier_source
    where dossier_source.dossier_id = p_dossier_id
      and dossier_source.id = any(p_dossier_source_ids);
  -- NEW materializes a new canonical article and therefore owns the
  -- one-to-one Article Plan -> editorial_article_id link. UPDATE is a revision
  -- of an article that may already be owned by its original creation plan; the
  -- revision is linked through newsroom_mesa_output_publications and receipts.
  if v_mode = 'create' then
    update public.newsroom_editorial_dossier_article_plans plan
      set editorial_article_id = v_article_id, updated_at = v_now
      where plan.dossier_id = p_dossier_id and plan.id = p_output_id
        and plan.editorial_article_id is null;
    if not found then raise exception 'mesa-publication-output-conflict'; end if;
  elsif exists (
    select 1
    from public.newsroom_editorial_dossier_article_plans plan
    where plan.dossier_id = p_dossier_id
      and plan.id = p_output_id
      and plan.editorial_article_id is not null
      and plan.editorial_article_id is distinct from v_article_id
  ) then
    raise exception 'mesa-publication-output-conflict';
  end if;
  v_consolidated := false; -- only the explicit intent finalizer completes this cycle
  if v_mode = 'update' then
    perform * from public.sync_editorial_article_live_snapshots_v15(v_article_id, v_previous_slug);
  end if;
  return query select v_article_id, v_slug,
    case when v_mode = 'update' then 'updated' else 'created' end, v_consolidated;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_publish_mesa_output_v2(p_dossier_id uuid, p_output_id uuid, p_package_id uuid, p_dossier_source_ids uuid[], p_article jsonb)
 RETURNS TABLE(editorial_article_id uuid, article_slug text, publication_action text, consolidated boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_plan public.newsroom_editorial_dossier_article_plans%rowtype;
  v_manifest jsonb; v_manifest_output jsonb;
  v_existing public.newsroom_mesa_output_publications%rowtype;
  v_article_id uuid; v_slug text; v_label text; v_title text; v_subtitle text; v_body text;
  v_image text; v_author text; v_published_at timestamptz; v_matchday uuid; v_mode text;
  v_previous_slug text; v_source_scope text := 'workspace'; v_production_context_id uuid;
  v_declared_context_source_ids uuid[]; v_frozen_context_source_ids uuid[];
  v_is_2c boolean;
  v_payload jsonb; v_fingerprint text; v_consolidated boolean; v_now timestamptz := now();
begin
  if p_dossier_id is null or p_output_id is null or p_package_id is null
    or p_dossier_source_ids is null or cardinality(p_dossier_source_ids) < 1
    or cardinality(p_dossier_source_ids) > 20 or array_position(p_dossier_source_ids,null) is not null
    or (select count(distinct source_id) from unnest(p_dossier_source_ids) source_id) <> cardinality(p_dossier_source_ids)
    or p_article is null or jsonb_typeof(p_article) <> 'object' then
    raise exception 'mesa-publication-input-invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-output:' || p_output_id::text,0));
  select * into v_context from public.newsroom_mesa_production_contexts context
  where context.dossier_id=p_dossier_id for update;
  if not found or v_context.workspace_role <> 'technical' or v_context.workspace_contract_version <> 2
    or v_context.workspace_state not in ('active','consolidated') then
    raise exception 'mesa-publication-workspace-invalid';
  end if;
  v_is_2c := coalesce(
    v_context.selection_payload ->> 'contractVersion'='3'
    and v_context.selection_payload ->> 'contextContractVersion'='1',false
  );
  if coalesce(
    v_context.selection_payload ->> 'contractVersion'='3'
    or v_context.selection_payload ? 'contextContractVersion',false
  ) and not v_is_2c then raise exception 'mesa-publication-workspace-invalid'; end if;
  if v_is_2c is distinct from (exists (
    select 1 from public.newsroom_mesa_production_context_items context_item
    where context_item.dossier_id=p_dossier_id
  )) then raise exception 'mesa-publication-workspace-invalid'; end if;
  select * into v_plan from public.newsroom_editorial_dossier_article_plans plan
  where plan.dossier_id=p_dossier_id and plan.id=p_output_id and plan.status <> 'cancelled'
  for update;
  if not found then raise exception 'mesa-publication-output-invalid'; end if;
  if v_is_2c then
    select assignment.production_context_id into v_production_context_id
    from public.newsroom_mesa_article_plan_contexts assignment
    where assignment.dossier_id=p_dossier_id and assignment.article_plan_id=p_output_id;
    if not found or not public.newsroom_mesa_plan_context_sources_valid_v1(p_dossier_id,p_output_id,v_production_context_id) then
      raise exception 'mesa-publication-output-invalid';
    end if;
    v_source_scope := 'context';
  elsif exists (
    select 1 from public.newsroom_mesa_article_plan_contexts assignment
    where assignment.dossier_id=p_dossier_id and assignment.article_plan_id=p_output_id
  ) then raise exception 'mesa-publication-workspace-invalid'; end if;
  select package.manifest into v_manifest from public.newsroom_editorial_source_packages package
  where package.id=p_package_id for update;
  if not found or (v_manifest ->> 'version')::integer <> 5
    or v_manifest ->> 'provenanceContract' <> 'mesa-v2' then
    raise exception 'mesa-publication-package-invalid';
  end if;
  select output.value into v_manifest_output
  from jsonb_array_elements(v_manifest -> 'outputs') output(value)
  where lower(output.value ->> 'outputId')=p_output_id::text
    and lower(output.value -> 'articlePlan' ->> 'articlePlanId')=p_output_id::text
    and lower(output.value -> 'articlePlan' ->> 'dossierId')=p_dossier_id::text;
  if not found
    or v_manifest_output -> 'articlePlan' ->> 'sourceScope' is distinct from v_source_scope
    or v_manifest_output -> 'articlePlan' ? 'origin' then
    raise exception 'mesa-publication-package-invalid';
  end if;
  if v_source_scope='context' then
    if lower(v_manifest_output -> 'articlePlan' ->> 'contextId') is distinct from v_production_context_id::text
      or jsonb_typeof(v_manifest_output -> 'contextSourceIds') is distinct from 'array' then
      raise exception 'mesa-publication-package-invalid';
    end if;
    begin
      select array_agg((source_id.value #>> '{}')::uuid order by (source_id.value #>> '{}')::uuid)
      into v_declared_context_source_ids
      from jsonb_array_elements(v_manifest_output -> 'contextSourceIds') source_id(value);
    exception when others then raise exception 'mesa-publication-package-invalid'; end;
    select array_agg(context_source.dossier_source_id order by context_source.dossier_source_id)
    into v_frozen_context_source_ids
    from public.newsroom_mesa_production_context_sources context_source
    where context_source.dossier_id=p_dossier_id
      and context_source.production_context_id=v_production_context_id;
    if v_declared_context_source_ids is distinct from v_frozen_context_source_ids
      or exists (
        select 1 from unnest(p_dossier_source_ids) requested(id)
        where not (requested.id = any(v_frozen_context_source_ids))
      ) then raise exception 'mesa-publication-source-invalid'; end if;
  end if;
  if exists(
    select 1 from unnest(p_dossier_source_ids) requested(id)
    left join public.newsroom_editorial_dossier_sources dossier_source
      on dossier_source.id=requested.id
      and dossier_source.dossier_id=p_dossier_id
      and dossier_source.included
    where dossier_source.id is null
      or not exists(
        select 1 from jsonb_array_elements(v_context.source_refs) ref
        where lower(ref ->> 'newsroomArticleId')=dossier_source.newsroom_article_id::text
          and lower(ref ->> 'newsroomSnapshotId')=dossier_source.newsroom_snapshot_id::text
      )
      or not exists(
        select 1 from jsonb_array_elements(v_manifest -> 'entries') entry
        where entry ->> 'status'='prepared'
          and lower(entry ->> 'provenanceSourceId')=requested.id::text
          and lower(entry ->> 'newsroomArticleId')=dossier_source.newsroom_article_id::text
          and lower(entry ->> 'newsroomSnapshotId')=dossier_source.newsroom_snapshot_id::text
      )
  ) then raise exception 'mesa-publication-source-invalid'; end if;
  begin v_article_id := (p_article ->> 'id')::uuid;
  exception when others then raise exception 'mesa-publication-article-invalid'; end;
  v_slug := btrim(coalesce(p_article ->> 'slug',''));
  v_label := btrim(coalesce(p_article ->> 'label',''));
  v_title := btrim(coalesce(p_article ->> 'title',''));
  v_subtitle := btrim(coalesce(p_article ->> 'subtitle',''));
  v_body := btrim(coalesce(p_article ->> 'body',''));
  v_image := nullif(btrim(coalesce(p_article ->> 'imageUrl','')),'');
  v_author := btrim(coalesce(p_article ->> 'author',''));
  v_mode := lower(btrim(coalesce(p_article ->> 'mode','')));
  begin
    v_published_at := (p_article ->> 'publishedAt')::timestamptz;
    v_matchday := (p_article ->> 'matchdayId')::uuid;
  exception when others then raise exception 'mesa-publication-article-invalid'; end;
  if v_slug='' or v_label='' or v_title='' or v_subtitle='' or v_body='' or v_author=''
    or v_mode not in ('create','update') then raise exception 'mesa-publication-article-invalid'; end if;
  v_payload := jsonb_build_object(
    'article',jsonb_build_object(
      'id',v_article_id,'slug',v_slug,'label',v_label,'title',v_title,
      'subtitle',v_subtitle,'body',v_body,'imageUrl',v_image,'author',v_author,
      'publishedAt',v_published_at,'matchdayId',v_matchday,'mode',v_mode
    ),
    'sources',(select to_jsonb(array_agg(source_id order by source_id)) from unnest(p_dossier_source_ids) source_id),
    'packageId',p_package_id,'outputId',p_output_id,'sourceScope',v_source_scope
  ) || case when v_source_scope='context'
    then jsonb_build_object('contextId',v_production_context_id) else '{}'::jsonb end;
  v_fingerprint := md5(v_payload::text);
  select * into v_existing from public.newsroom_mesa_output_publications publication
  where publication.dossier_id=p_dossier_id and publication.article_plan_id=p_output_id;
  if found then
    if v_existing.fingerprint <> v_fingerprint or v_existing.editorial_article_id <> v_article_id
      or v_existing.source_scope is distinct from v_source_scope
      or v_existing.production_context_id is distinct from v_production_context_id
      or not exists(
        select 1 from public.editorial_articles article
        where article.id=v_article_id and article.status='published'
      ) then raise exception 'mesa-publication-provenance-conflict'; end if;
    return query select v_article_id,v_slug,'reused'::text,v_context.workspace_state='consolidated';
    return;
  end if;
  if v_context.workspace_state='consolidated' then raise exception 'mesa-publication-provenance-conflict'; end if;
  if v_mode='create' then
    if v_plan.destination <> 'new' or v_plan.update_target_editorial_article_id is not null
      or v_image is null
      or exists(select 1 from public.editorial_articles article where article.id=v_article_id or article.slug=v_slug) then
      raise exception 'mesa-publication-article-conflict';
    end if;
    insert into public.editorial_articles(
      id,status,scope,author,label,title,subtitle,body,slug,image_url,
      image_caption,published_at,competition_id,season_id,matchday_id,created_at,updated_at
    ) values (
      v_article_id,'published','matchday',v_author,v_label,v_title,v_subtitle,v_body,v_slug,v_image,
      null,v_published_at,null,null,v_matchday,v_now,v_now
    );
  else
    if v_plan.destination <> 'update' or v_plan.update_target_editorial_article_id <> v_article_id then
      raise exception 'mesa-publication-update-target-invalid';
    end if;
    select article.slug into v_previous_slug from public.editorial_articles article
    where article.id=v_article_id and article.status='published' and article.matchday_id=v_matchday
    for update;
    if not found or v_previous_slug <> v_slug then raise exception 'mesa-publication-update-target-invalid'; end if;
    update public.editorial_articles article
    set label=v_label,title=v_title,subtitle=v_subtitle,body=v_body,
      author=v_author,image_url=coalesce(v_image,article.image_url),
      status='published',scope='matchday',competition_id=null,season_id=null,updated_at=v_now
    where article.id=v_article_id and article.status='published'
      and article.matchday_id=v_matchday and article.slug=v_slug;
    if not found then raise exception 'mesa-publication-update-target-invalid'; end if;
  end if;
  insert into public.newsroom_mesa_output_publications(
    dossier_id,article_plan_id,package_id,editorial_article_id,source_scope,
    production_context_id,origin_kind,origin_dossier_source_id,material_key,
    material_version_id,fingerprint,payload
  ) values (
    p_dossier_id,p_output_id,p_package_id,v_article_id,v_source_scope,
    v_production_context_id,null,null,null,null,v_fingerprint,v_payload
  );
  insert into public.newsroom_mesa_output_source_usage(
    dossier_id,article_plan_id,dossier_source_id,newsroom_article_id,
    newsroom_snapshot_id,editorial_article_id,package_id
  ) select p_dossier_id,p_output_id,dossier_source.id,dossier_source.newsroom_article_id,
      dossier_source.newsroom_snapshot_id,v_article_id,p_package_id
    from public.newsroom_editorial_dossier_sources dossier_source
    where dossier_source.dossier_id=p_dossier_id and dossier_source.id=any(p_dossier_source_ids);
  update public.newsroom_editorial_dossier_article_plans plan
  set editorial_article_id=v_article_id,updated_at=v_now
  where plan.dossier_id=p_dossier_id and plan.id=p_output_id and plan.editorial_article_id is null;
  if not found then raise exception 'mesa-publication-output-conflict'; end if;
  v_consolidated := public.newsroom_mesa_consolidate_publication_v4(p_dossier_id);
  if v_mode='update' then
    perform * from public.sync_editorial_article_live_snapshots_v15(v_article_id,v_previous_slug);
  end if;
  return query select v_article_id,v_slug,
    case when v_mode='update' then 'updated' else 'created' end,v_consolidated;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_remove_theme_source_v1(p_theme_id uuid, p_source_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_theme_id is null or p_source_id is null then raise exception 'mesa-organization-invalid-input'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('newsroom-mesa-organization-v1', 0));
  if exists (
    select 1 from public.newsroom_editorial_theme_dossiers td
    join public.newsroom_editorial_dossier_sources ds on ds.dossier_id = td.dossier_id
    where td.theme_id = p_theme_id and ds.newsroom_article_id = p_source_id and ds.included
  ) then raise exception 'mesa-organization-source-in-dossier'; end if;
  perform public.newsroom_set_editorial_theme_source_membership_v1(p_theme_id,p_source_id,false);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_save_editorial_dossier_article_plan(p_dossier_id uuid, p_article_plan_id uuid, p_working_title text, p_status text, p_sort_order integer, p_article_kind text, p_length_mode text, p_editorial_instructions text, p_dossier_source_ids uuid[])
 RETURNS TABLE(article_plan_id uuid)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_plan_id uuid := coalesce(p_article_plan_id, pg_catalog.gen_random_uuid());
  v_is_create boolean := p_article_plan_id is null;
  v_existing_status text;
  v_editorial_article_id uuid;
  v_source_count integer := coalesce(cardinality(p_dossier_source_ids), 0);
  v_distinct_source_count integer;
  v_source_id uuid;
begin
  if p_dossier_id is null then
    raise exception 'editorial_dossier_article_plan_dossier_required'
      using errcode = '23514';
  end if;

  if btrim(coalesce(p_working_title, '')) = '' then
    raise exception 'editorial_dossier_article_plan_title_required'
      using errcode = '23514';
  end if;

  if p_status not in ('planned', 'ready', 'cancelled') then
    raise exception 'editorial_dossier_article_plan_status_invalid'
      using errcode = '23514';
  end if;

  if p_article_kind not in ('news', 'analysis', 'preview', 'summary') then
    raise exception 'editorial_dossier_article_plan_kind_invalid'
      using errcode = '23514';
  end if;

  if p_length_mode not in ('brief', 'standard', 'developed') then
    raise exception 'editorial_dossier_article_plan_length_invalid'
      using errcode = '23514';
  end if;

  if p_sort_order is null or p_sort_order < 0 then
    raise exception 'editorial_dossier_article_plan_order_invalid'
      using errcode = '23514';
  end if;

  perform 1
  from public.newsroom_editorial_dossiers dossier
  where dossier.id = p_dossier_id
  for update;

  if not found then
    raise exception 'editorial_dossier_not_found'
      using errcode = 'P0002';
  end if;

  if v_is_create then
    if p_status = 'cancelled' then
      raise exception 'editorial_dossier_article_plan_new_cancelled_invalid'
        using errcode = '23514';
    end if;
  else
    select
      plan.status,
      plan.editorial_article_id
    into
      v_existing_status,
      v_editorial_article_id
    from public.newsroom_editorial_dossier_article_plans plan
    where plan.id = p_article_plan_id
      and plan.dossier_id = p_dossier_id
    for update;

    if not found then
      raise exception 'editorial_dossier_article_plan_not_found'
        using errcode = 'P0002';
    end if;

    if v_editorial_article_id is not null then
      raise exception 'editorial_dossier_article_plan_already_converted'
        using errcode = '23514';
    end if;
  end if;

  select count(distinct source_row.source_id)
  into v_distinct_source_count
  from unnest(coalesce(p_dossier_source_ids, '{}'::uuid[]))
    as source_row(source_id);

  if v_distinct_source_count <> v_source_count then
    raise exception 'editorial_dossier_article_plan_source_duplicate'
      using errcode = '23514';
  end if;

  if p_status = 'ready'
     and (
       btrim(coalesce(p_editorial_instructions, '')) = ''
       or v_source_count < 1
     ) then
    raise exception 'editorial_dossier_article_plan_ready_incomplete'
      using errcode = '23514';
  end if;

  if p_status <> 'cancelled' then
    for v_source_id in
      select source_row.source_id
      from unnest(coalesce(p_dossier_source_ids, '{}'::uuid[]))
        as source_row(source_id)
    loop
      if not exists (
        select 1
        from public.newsroom_editorial_dossier_sources dossier_source
        where dossier_source.id = v_source_id
          and dossier_source.dossier_id = p_dossier_id
          and (
            dossier_source.included
            or exists (
              select 1
              from public.newsroom_editorial_dossier_article_plan_sources existing_assignment
              where existing_assignment.article_plan_id = v_plan_id
                and existing_assignment.dossier_source_id = v_source_id
                and existing_assignment.dossier_id = p_dossier_id
            )
          )
      ) then
        raise exception 'editorial_dossier_article_plan_source_unavailable'
          using errcode = '23514';
      end if;
    end loop;
  end if;

  if v_is_create then
    insert into public.newsroom_editorial_dossier_article_plans (
      id,
      dossier_id,
      working_title,
      status,
      sort_order,
      article_kind,
      length_mode,
      editorial_instructions
    ) values (
      v_plan_id,
      p_dossier_id,
      btrim(p_working_title),
      p_status,
      p_sort_order,
      p_article_kind,
      p_length_mode,
      btrim(coalesce(p_editorial_instructions, ''))
    );
  else
    update public.newsroom_editorial_dossier_article_plans plan
    set working_title = btrim(p_working_title),
        status = p_status,
        sort_order = p_sort_order,
        article_kind = p_article_kind,
        length_mode = p_length_mode,
        editorial_instructions = btrim(coalesce(p_editorial_instructions, ''))
    where plan.id = v_plan_id
      and plan.dossier_id = p_dossier_id;
  end if;

  if p_status <> 'cancelled' then
    delete from public.newsroom_editorial_dossier_article_plan_sources assignment
    where assignment.article_plan_id = v_plan_id
      and assignment.dossier_id = p_dossier_id
      and not (
        assignment.dossier_source_id = any(coalesce(p_dossier_source_ids, '{}'::uuid[]))
      );

    insert into public.newsroom_editorial_dossier_article_plan_sources (
      id,
      dossier_id,
      article_plan_id,
      dossier_source_id,
      sort_order
    )
    select
      pg_catalog.gen_random_uuid(),
      p_dossier_id,
      v_plan_id,
      ordered_source.source_id,
      ordered_source.ordinality::integer * 10
    from unnest(coalesce(p_dossier_source_ids, '{}'::uuid[]))
      with ordinality as ordered_source(source_id, ordinality)
    on conflict on constraint newsroom_editorial_dossier_article_plan_sources_plan_source_key
    do update
    set sort_order = excluded.sort_order;
  end if;

  update public.newsroom_editorial_dossiers dossier
  set updated_at = now()
  where dossier.id = p_dossier_id;

  return query select v_plan_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_save_mesa_context_article_plan_v1(p_dossier_id uuid, p_article_plan_id uuid, p_working_title text, p_status text, p_sort_order integer, p_article_kind text, p_length_mode text, p_editorial_instructions text, p_dossier_source_ids uuid[], p_production_context_id uuid)
 RETURNS TABLE(article_plan_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_article_plan_id uuid;
begin
  if p_production_context_id is null then raise exception 'mesa-article-plan-context-input-invalid'; end if;
  perform 1
  from public.newsroom_mesa_production_contexts workspace
  where workspace.dossier_id = p_dossier_id
    and workspace.workspace_role = 'technical'
    and workspace.workspace_contract_version = 2
    and workspace.workspace_state = 'active'
    and workspace.selection_payload ->> 'contractVersion' = '3'
    and workspace.selection_payload ->> 'contextContractVersion' = '1'
    and exists (
      select 1 from public.newsroom_mesa_production_context_items context_item
      where context_item.dossier_id = workspace.dossier_id and context_item.id = p_production_context_id
    )
  for update;
  if not found then raise exception 'mesa-article-plan-context-workspace-invalid'; end if;
  select saved.article_plan_id into strict v_article_plan_id
  from public.newsroom_save_editorial_dossier_article_plan(
    p_dossier_id,p_article_plan_id,p_working_title,p_status,p_sort_order,
    p_article_kind,p_length_mode,p_editorial_instructions,p_dossier_source_ids
  ) saved;
  perform public.newsroom_assign_mesa_article_plan_context_v1(p_dossier_id,v_article_plan_id,p_production_context_id);
  return query select v_article_plan_id;
end;
$function$

