CREATE OR REPLACE FUNCTION public.newsroom_set_editorial_theme_article_membership_v1(p_theme_id uuid, p_editorial_article_id uuid, p_associated boolean)
 RETURNS TABLE(theme_id uuid, editorial_article_id uuid, associated boolean, changed boolean, added_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_row_count bigint := 0;
  v_added_at timestamptz;
begin
  if p_theme_id is null
    or p_editorial_article_id is null
    or p_associated is null
  then
    raise exception 'editorial_theme_invalid_input'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.newsroom_editorial_themes as theme_row
    where theme_row.id = p_theme_id
  )
  then
    raise exception 'editorial_theme_not_found'
      using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public.editorial_articles as article_row
    where article_row.id = p_editorial_article_id
  )
  then
    raise exception 'editorial_theme_article_not_found'
      using errcode = 'P0002';
  end if;

  if p_associated then
    insert into public.newsroom_editorial_theme_articles (
      theme_id,
      editorial_article_id
    ) values (
      p_theme_id,
      p_editorial_article_id
    )
    on conflict on constraint newsroom_editorial_theme_articles_pkey
    do nothing;

    get diagnostics v_row_count = row_count;

    select relation_row.added_at
    into v_added_at
    from public.newsroom_editorial_theme_articles as relation_row
    where relation_row.theme_id = p_theme_id
      and relation_row.editorial_article_id = p_editorial_article_id;
  else
    delete from public.newsroom_editorial_theme_articles as relation_row
    where relation_row.theme_id = p_theme_id
      and relation_row.editorial_article_id = p_editorial_article_id;

    get diagnostics v_row_count = row_count;
  end if;

  return query
  select
    p_theme_id,
    p_editorial_article_id,
    p_associated,
    v_row_count > 0,
    v_added_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_set_editorial_theme_source_membership_v1(p_theme_id uuid, p_newsroom_article_id uuid, p_associated boolean)
 RETURNS TABLE(theme_id uuid, newsroom_article_id uuid, associated boolean, changed boolean, added_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_row_count bigint := 0;
  v_added_at timestamptz;
  v_classification_key text;
begin
  if p_theme_id is null
    or p_newsroom_article_id is null
    or p_associated is null
  then
    raise exception 'editorial_theme_invalid_input'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'newsroom-theme-source-classification-v1',
      0
    )
  );

  select theme_row.classification_key
  into v_classification_key
  from public.newsroom_editorial_themes as theme_row
  where theme_row.id = p_theme_id;

  if not found then
    raise exception 'editorial_theme_not_found'
      using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public.newsroom_articles as article_row
    where article_row.id = p_newsroom_article_id
  )
  then
    raise exception 'editorial_theme_source_not_found'
      using errcode = 'P0002';
  end if;

  if p_associated then
    if exists (
      select 1
      from public.newsroom_editorial_theme_sources as membership_row
      join public.newsroom_editorial_themes as theme_row
        on theme_row.id = membership_row.theme_id
      where membership_row.newsroom_article_id = p_newsroom_article_id
        and membership_row.theme_id <> p_theme_id
        and theme_row.classification_key is distinct from
          v_classification_key
    )
    then
      raise exception 'editorial_theme_source_classification_conflict'
        using errcode = '23514';
    end if;

    insert into public.newsroom_editorial_theme_sources (
      theme_id,
      newsroom_article_id
    ) values (
      p_theme_id,
      p_newsroom_article_id
    )
    on conflict on constraint newsroom_editorial_theme_sources_pkey
    do nothing;

    get diagnostics v_row_count = row_count;

    perform public.newsroom_set_manual_article_classification_v1(
      p_newsroom_article_id,
      v_classification_key
    );

    select relation_row.added_at
    into v_added_at
    from public.newsroom_editorial_theme_sources as relation_row
    where relation_row.theme_id = p_theme_id
      and relation_row.newsroom_article_id = p_newsroom_article_id;
  else
    delete from public.newsroom_editorial_theme_sources as relation_row
    where relation_row.theme_id = p_theme_id
      and relation_row.newsroom_article_id = p_newsroom_article_id;

    get diagnostics v_row_count = row_count;
  end if;

  return query
  select
    p_theme_id,
    p_newsroom_article_id,
    p_associated,
    v_row_count > 0,
    v_added_at;
end;
$function$

