CREATE OR REPLACE FUNCTION public.newsroom_set_manual_article_classifications_v2(p_newsroom_article_ids uuid[], p_classification_key text)
 RETURNS TABLE(requested_count integer, changed_count integer, classification_key text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_changed_count bigint := 0;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'newsroom-theme-source-classification-v1',
      0
    )
  );

  if p_newsroom_article_ids is null
    or pg_catalog.cardinality(p_newsroom_article_ids) < 1
    or pg_catalog.cardinality(p_newsroom_article_ids) > 20
    or pg_catalog.array_position(p_newsroom_article_ids, null) is not null
    or (
      select pg_catalog.count(distinct requested_row.newsroom_article_id)
      from pg_catalog.unnest(p_newsroom_article_ids)
        as requested_row(newsroom_article_id)
    ) <> pg_catalog.cardinality(p_newsroom_article_ids)
    or (
      p_classification_key is not null
      and p_classification_key not in (
        'benfica',
        'sporting',
        'fc_porto',
        'other_liga_clubs',
        'outside_liga_other'
      )
    )
  then
    raise exception 'newsroom_article_classification_invalid_input'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from pg_catalog.unnest(p_newsroom_article_ids)
      as requested_row(newsroom_article_id)
    left join public.newsroom_articles as article_row
      on article_row.id = requested_row.newsroom_article_id
    where article_row.id is null
  )
  then
    raise exception 'newsroom_article_classification_source_not_found'
      using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from pg_catalog.unnest(p_newsroom_article_ids)
      as requested_row(newsroom_article_id)
    join public.newsroom_articles as article_row
      on article_row.id = requested_row.newsroom_article_id
    where article_row.first_detected_at
      < '2026-09-09T14:02:00Z'::timestamptz
  )
  then
    raise exception 'newsroom_article_classification_source_outside_cycle'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from pg_catalog.unnest(p_newsroom_article_ids)
      as requested_row(newsroom_article_id)
    join public.newsroom_editorial_theme_sources as membership_row
      on membership_row.newsroom_article_id = requested_row.newsroom_article_id
    join public.newsroom_editorial_themes as theme_row
      on theme_row.id = membership_row.theme_id
    where p_classification_key is null
      or theme_row.classification_key is distinct from p_classification_key
  )
  then
    raise exception 'newsroom_article_classification_theme_conflict'
      using errcode = '23514';
  end if;

  if p_classification_key is null then
    delete from public.newsroom_editorial_article_classifications
      as classification_row
    where classification_row.newsroom_article_id = any (
      p_newsroom_article_ids
    );

    get diagnostics v_changed_count = row_count;
  else
    insert into public.newsroom_editorial_article_classifications (
      newsroom_article_id,
      classification_key,
      classification_source,
      classified_at
    )
    select
      requested_row.newsroom_article_id,
      p_classification_key,
      'manual',
      pg_catalog.statement_timestamp()
    from pg_catalog.unnest(p_newsroom_article_ids)
      as requested_row(newsroom_article_id)
    on conflict on constraint
      newsroom_editorial_article_classifications_pkey
    do update
    set
      classification_key = excluded.classification_key,
      classification_source = excluded.classification_source,
      classified_at = excluded.classified_at
    where (
      newsroom_editorial_article_classifications.classification_key,
      newsroom_editorial_article_classifications.classification_source
    ) is distinct from (
      excluded.classification_key,
      excluded.classification_source
    );

    get diagnostics v_changed_count = row_count;
  end if;

  return query
  select
    pg_catalog.cardinality(p_newsroom_article_ids),
    v_changed_count::integer,
    p_classification_key;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_set_mesa_output_origin_v2(p_dossier_id uuid, p_article_plan_id uuid, p_origin_kind text, p_origin_dossier_source_id uuid, p_material_key text, p_material_version_id uuid)
 RETURNS TABLE(origin_action text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_existing public.newsroom_mesa_output_origins%rowtype;
  v_source public.newsroom_editorial_dossier_sources%rowtype;
begin
  select * into v_context from public.newsroom_mesa_production_contexts c
    where c.dossier_id = p_dossier_id for update;
  if not found or v_context.workspace_role <> 'technical'
    or v_context.workspace_contract_version <> 2
    or v_context.workspace_state <> 'active' then
    raise exception 'mesa-output-origin-invalid';
  end if;
  perform 1 from public.newsroom_editorial_dossier_article_plans p
    where p.dossier_id=p_dossier_id and p.id=p_article_plan_id
      and p.editorial_article_id is null and p.status<>'cancelled' for update;
  if not found then raise exception 'mesa-output-origin-invalid'; end if;

  if p_origin_kind='source' then
    if p_material_key is not null or p_material_version_id is not null
      or p_origin_dossier_source_id is null then raise exception 'mesa-output-origin-invalid'; end if;
    select * into v_source from public.newsroom_editorial_dossier_sources s
      where s.dossier_id=p_dossier_id and s.id=p_origin_dossier_source_id and s.included;
    if not found or not exists (
      select 1 from jsonb_array_elements(coalesce(v_context.selection_payload->'sources','[]'::jsonb)) r
      where lower(r->>'newsroomArticleId')=v_source.newsroom_article_id::text
        and lower(r->>'newsroomSnapshotId')=v_source.newsroom_snapshot_id::text
    ) then raise exception 'mesa-output-origin-invalid'; end if;
  elsif p_origin_kind='material' then
    if p_origin_dossier_source_id is not null or p_material_key is null or p_material_version_id is null
      or not exists (
        select 1 from jsonb_array_elements(v_context.material_refs) r
        where lower(r->>'key')=lower(p_material_key)
          and lower(r->>'versionId')=p_material_version_id::text
      ) then raise exception 'mesa-output-origin-invalid'; end if;
  else raise exception 'mesa-output-origin-invalid'; end if;

  select * into v_existing from public.newsroom_mesa_output_origins o
    where o.dossier_id=p_dossier_id and o.article_plan_id=p_article_plan_id;
  if found then
    if v_existing.origin_kind is distinct from p_origin_kind
      or v_existing.origin_dossier_source_id is distinct from p_origin_dossier_source_id
      or v_existing.material_key is distinct from lower(p_material_key)
      or v_existing.material_version_id is distinct from p_material_version_id then
      raise exception 'mesa-output-origin-conflict';
    end if;
    return query select 'reused'::text; return;
  end if;
  insert into public.newsroom_mesa_output_origins(
    dossier_id,article_plan_id,origin_kind,origin_dossier_source_id,material_key,material_version_id
  ) values (
    p_dossier_id,p_article_plan_id,p_origin_kind,p_origin_dossier_source_id,lower(p_material_key),p_material_version_id
  );
  return query select 'created'::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.newsroom_set_mesa_shared_outputs_v2(p_dossier_id uuid, p_article_plan_ids uuid[])
 RETURNS TABLE(output_count integer, cancelled_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context public.newsroom_mesa_production_contexts%rowtype;
  v_cancelled integer := 0;
begin
  if p_dossier_id is null
    or p_article_plan_ids is null
    or cardinality(p_article_plan_ids) not between 1 and 30
    or array_position(p_article_plan_ids,null) is not null
    or (select count(distinct requested_id) from unnest(p_article_plan_ids) requested(requested_id)) <> cardinality(p_article_plan_ids) then
    raise exception 'mesa-shared-outputs-input-invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('newsroom-mesa-shared-outputs:' || p_dossier_id::text,0));
  select context.* into v_context
  from public.newsroom_mesa_production_contexts context
  where context.dossier_id = p_dossier_id
  for update;
  if not found
    or v_context.workspace_role <> 'technical'
    or v_context.workspace_contract_version <> 2
    or v_context.workspace_state <> 'active'
    or exists (
      select 1 from public.newsroom_mesa_output_publications publication
      where publication.dossier_id = p_dossier_id
    ) then raise exception 'mesa-shared-outputs-workspace-invalid'; end if;
  if exists (
    select 1
    from unnest(p_article_plan_ids) requested(id)
    left join public.newsroom_editorial_dossier_article_plans plan
      on plan.dossier_id = p_dossier_id
      and plan.id = requested.id
      and plan.status <> 'cancelled'
      and plan.editorial_article_id is null
    where plan.id is null
  ) then raise exception 'mesa-shared-outputs-plan-invalid'; end if;
  if exists (
    select 1 from public.newsroom_mesa_production_context_items context_item
    where context_item.dossier_id = p_dossier_id
  ) and exists (
    select 1
    from unnest(p_article_plan_ids) requested(id)
    left join public.newsroom_mesa_article_plan_contexts assignment
      on assignment.dossier_id = p_dossier_id and assignment.article_plan_id = requested.id
    where assignment.article_plan_id is null
      or not public.newsroom_mesa_plan_context_sources_valid_v1(
        assignment.dossier_id,assignment.article_plan_id,assignment.production_context_id
      )
  ) then raise exception 'mesa-shared-outputs-plan-context-invalid'; end if;
  update public.newsroom_editorial_dossier_article_plans plan
  set status='cancelled',updated_at=now()
  where plan.dossier_id = p_dossier_id
    and plan.status <> 'cancelled'
    and plan.editorial_article_id is null
    and not (plan.id = any(p_article_plan_ids));
  get diagnostics v_cancelled = row_count;
  update public.newsroom_editorial_dossiers dossier
  set output_mode = case when cardinality(p_article_plan_ids)=1 then 'single' else 'multiple' end,
      output_count = cardinality(p_article_plan_ids),
      updated_at = now()
  where dossier.id = p_dossier_id;
  if not found then raise exception 'mesa-shared-outputs-workspace-invalid'; end if;
  return query select cardinality(p_article_plan_ids),v_cancelled;
end;
$function$

CREATE OR REPLACE FUNCTION public.portal_create_modality(p_portal_context_id uuid, p_catalog_code text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_slug text DEFAULT NULL::text, p_local_code text DEFAULT NULL::text, p_status text DEFAULT 'draft'::text, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(result_modality_id uuid, result_portal_entity_id uuid, result_portal_context_id uuid, result_catalog_modality_id uuid, result_name text, result_slug text, result_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_auth_user_id uuid := auth.uid();
  v_actor_portal_user_id uuid;
  v_context record;
  v_catalog_id uuid := null;
  v_catalog_code text := null;
  v_catalog_name text := null;
  v_name text;
  v_slug text;
  v_local_code text := nullif(btrim(coalesce(p_local_code, '')), '');
  v_status text := coalesce(nullif(btrim(p_status), ''), 'draft');
  v_has_permission boolean := false;
  v_modality_id uuid;
begin
  if v_auth_user_id is null then
    raise exception 'portal_not_authenticated' using errcode = '28000';
  end if;

  if p_portal_context_id is null then
    raise exception 'portal_invalid_context' using errcode = '22023';
  end if;

  if v_status not in ('draft', 'active', 'archived') then
    raise exception 'portal_invalid_modality_status' using errcode = '22023';
  end if;

  select
    u.id
  into v_actor_portal_user_id
  from public.portal_users u
  where u.auth_user_id = v_auth_user_id
    and u.status = 'active'
  limit 1;

  if v_actor_portal_user_id is null then
    raise exception 'portal_user_not_found' using errcode = 'P0002';
  end if;

  select
    c.id,
    c.portal_entity_id,
    c.label,
    c.status
  into v_context
  from public.portal_contexts c
  where c.id = p_portal_context_id;

  if not found then
    raise exception 'portal_context_not_found' using errcode = 'P0002';
  end if;

  if v_context.status <> 'active' then
    raise exception 'portal_context_not_active' using errcode = '42501';
  end if;

  if nullif(btrim(coalesce(p_catalog_code, '')), '') is not null then
    select
      mc.id,
      mc.code,
      mc.name
    into
      v_catalog_id,
      v_catalog_code,
      v_catalog_name
    from public.portal_modality_catalog mc
    where lower(mc.code) = lower(btrim(p_catalog_code))
      and mc.status = 'active'
    limit 1;

    if v_catalog_id is null then
      raise exception 'portal_catalog_modality_not_found_or_inactive' using errcode = 'P0002';
    end if;
  end if;

  v_name := nullif(btrim(coalesce(p_name, v_catalog_name, '')), '');

  if v_name is null then
    raise exception 'portal_modality_name_required' using errcode = '22023';
  end if;

  v_slug := lower(
    regexp_replace(
      coalesce(
        nullif(btrim(p_slug), ''),
        nullif(btrim(v_catalog_code), ''),
        v_name
      ),
      '[^a-zA-Z0-9]+',
      '-',
      'g'
    )
  );
  v_slug := nullif(btrim(v_slug, '-'), '');

  if v_slug is null then
    raise exception 'portal_modality_slug_required' using errcode = '22023';
  end if;

  select exists (
    select 1
    from public.portal_permissions p
    where p.portal_user_id = v_actor_portal_user_id
      and p.status = 'active'
      and p.can_view = true
      and p.can_create = true
      and p.can_edit = true
      and p.portal_entity_id = v_context.portal_entity_id
      and p.portal_competition_id is null
      and (p.portal_context_id is null or p.portal_context_id = v_context.id)
  ) into v_has_permission;

  if not v_has_permission then
    raise exception 'portal_modality_create_not_allowed' using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.portal_modalities pm
    where pm.portal_entity_id = v_context.portal_entity_id
      and pm.portal_context_id = v_context.id
      and lower(pm.slug) = lower(v_slug)
  ) then
    raise exception 'portal_modality_slug_already_exists' using errcode = '23505';
  end if;

  if v_catalog_id is not null and exists (
    select 1
    from public.portal_modalities pm
    where pm.portal_entity_id = v_context.portal_entity_id
      and pm.portal_context_id = v_context.id
      and pm.catalog_modality_id = v_catalog_id
  ) then
    raise exception 'portal_catalog_modality_already_active_in_context' using errcode = '23505';
  end if;

  insert into public.portal_modalities (
    portal_entity_id,
    portal_context_id,
    catalog_modality_id,
    name,
    slug,
    local_code,
    status,
    notes,
    metadata
  ) values (
    v_context.portal_entity_id,
    v_context.id,
    v_catalog_id,
    v_name,
    v_slug,
    v_local_code,
    v_status,
    p_notes,
    jsonb_build_object(
      'phase', 'PORTAL-ESCOLAS-MODALIDADES-CRIACAO-AUDITADA-1',
      'source', 'portal_create_modality',
      'created_by_auth_user_id', v_auth_user_id,
      'created_by_portal_user_id', v_actor_portal_user_id,
      'catalog_code', v_catalog_code,
      'created_at', now()
    )
  )
  returning id into v_modality_id;

  insert into public.portal_audit_events (
    portal_entity_id,
    portal_context_id,
    portal_competition_id,
    actor_reference,
    actor_portal_user_id,
    action_type,
    object_type,
    object_id,
    previous_status,
    new_status,
    metadata
  ) values (
    v_context.portal_entity_id,
    v_context.id,
    null,
    v_auth_user_id::text,
    v_actor_portal_user_id,
    'portal_modality_created',
    'portal_modalities',
    v_modality_id,
    null,
    v_status,
    jsonb_build_object(
      'phase', 'PORTAL-ESCOLAS-MODALIDADES-CRIACAO-AUDITADA-1',
      'source_function', 'portal_create_modality',
      'portal_context_id', v_context.id,
      'catalog_modality_id', v_catalog_id,
      'catalog_code', v_catalog_code,
      'new', jsonb_build_object(
        'name', v_name,
        'slug', v_slug,
        'local_code', v_local_code,
        'status', v_status,
        'notes', p_notes
      )
    )
  );

  return query
  select
    pm.id,
    pm.portal_entity_id,
    pm.portal_context_id,
    pm.catalog_modality_id,
    pm.name,
    pm.slug,
    pm.status
  from public.portal_modalities pm
  where pm.id = v_modality_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.preserve_matchday_editorial_worked_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if jornada_private.is_matchday_live_layout_carryover_v18(new.matchday_id) then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.editorially_worked_at is not null then
    new.editorially_worked_at := old.editorially_worked_at;
  elsif new.editorially_worked_at is null
    and new.continuity_source_matchday_id is not null
    and new.continuity_source_composition_id is not null
  then
    new.editorially_worked_at := pg_catalog.statement_timestamp();
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_matchday_reference_composition(p_matchday_id uuid, p_composition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source_season_id uuid;
  v_source_number integer;
  v_next_matchday_id uuid;
  v_source_is_managed boolean;
  v_transition public.matchday_editorial_continuity_transitions%rowtype;
  v_has_transition boolean := false;
  v_transition_before jsonb;
  v_transition_after jsonb;
  v_source_archive_before text;
  v_source_archive_after text;
  v_published_id uuid;
  v_first_publication jsonb;
begin
  if p_matchday_id is null or p_composition_id is null then
    raise exception 'composition_invalid';
  end if;

  perform jornada_private.acquire_matchday_live_desk_handoff_lock();
  perform jornada_private.acquire_matchday_live_layout_cutover_core_lock();

  select matchday_row.season_id, matchday_row.number
  into v_source_season_id, v_source_number
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id;

  if not found then
    raise exception 'composition_matchday_not_found';
  end if;

  select target_row.id
  into v_next_matchday_id
  from public.matchdays as target_row
  where target_row.season_id = v_source_season_id
    and target_row.number = v_source_number + 1;

  perform 1
  from public.matchdays as lock_row
  where lock_row.id = p_matchday_id
     or lock_row.id = v_next_matchday_id
  order by lock_row.id
  for update;

  select transition_row.*
  into v_transition
  from public.matchday_editorial_continuity_transitions as transition_row
  where transition_row.source_matchday_id = p_matchday_id
  for key share;

  v_has_transition := found;

  select source_desk.is_managed
  into v_source_is_managed
  from public.matchday_editorial_desk_control as source_desk
  where source_desk.matchday_id = p_matchday_id
  for update;

  if not found then
    raise exception 'composition_source_matchday_control_missing';
  end if;

  if v_has_transition then
    if v_next_matchday_id is null
      or v_transition.target_matchday_id <> v_next_matchday_id
      or v_transition.continuity_version not in (6, 19)
    then
      raise exception 'composition_historical_transition_invalid';
    end if;

    if v_source_is_managed then
      raise exception 'composition_historical_source_still_live';
    end if;

    v_transition_before := pg_catalog.to_jsonb(v_transition);

    if v_transition.continuity_version = 19 then
      if jornada_private.matchday_live_layout_continuity_authority_v19(
           p_matchday_id
         ) <> 'physical'
      then
        raise exception 'composition_historical_physical_authority_invalid';
      end if;

      perform jornada_private.assert_matchday_live_layout_historical_republish_v20(
        p_matchday_id,
        v_next_matchday_id,
        v_transition.source_composition_id
      );

      v_source_archive_before := jornada_private.matchday_live_layout_physical_archive_hash_v19(
        p_matchday_id
      );
    else
      if jornada_private.matchday_live_layout_continuity_authority_v19(
           p_matchday_id
         ) <> 'legacy'
      then
        raise exception 'composition_historical_legacy_authority_invalid';
      end if;

      if not exists (
        select 1
        from jornada_private.matchday_live_layout_cutover_control as control_row
        where control_row.scope = 'live_layout'
          and control_row.authority_mode = 'authoritative'
      ) then
        raise exception 'composition_historical_authority_not_active';
      end if;

      if exists (
        select 1
        from public.matchday_live_layout_placements as source_placement
        where source_placement.matchday_id = p_matchday_id
      ) or exists (
        select 1
        from public.matchday_live_layout_bank_item_state_memory as source_memory
        where source_memory.matchday_id = p_matchday_id
      ) then
        raise exception 'composition_historical_source_not_retired';
      end if;
    end if;

    v_published_id := public.activate_matchday_reference_composition(
      p_matchday_id,
      p_composition_id,
      true
    );

    select pg_catalog.to_jsonb(transition_row)
    into v_transition_after
    from public.matchday_editorial_continuity_transitions as transition_row
    where transition_row.source_matchday_id = p_matchday_id;

    if v_transition_after is distinct from v_transition_before then
      raise exception 'composition_historical_transition_changed';
    end if;

    if v_transition.continuity_version = 19 then
      perform jornada_private.assert_matchday_live_layout_historical_republish_v20(
        p_matchday_id,
        v_next_matchday_id,
        v_transition.source_composition_id
      );

      v_source_archive_after := jornada_private.matchday_live_layout_physical_archive_hash_v19(
        p_matchday_id
      );

      if v_source_archive_after is distinct from v_source_archive_before then
        raise exception 'composition_historical_physical_archive_changed';
      end if;
    elsif exists (
      select 1
      from public.matchday_editorial_desk_control as source_desk
      where source_desk.matchday_id = p_matchday_id
        and source_desk.is_managed
    ) or exists (
      select 1
      from public.matchday_live_layout_placements as source_placement
      where source_placement.matchday_id = p_matchday_id
    ) or exists (
      select 1
      from public.matchday_live_layout_bank_item_state_memory as source_memory
      where source_memory.matchday_id = p_matchday_id
    ) then
      raise exception 'composition_historical_republish_postcondition_failed';
    end if;

    return pg_catalog.jsonb_build_object(
      'publicationKind', 'historical_republish',
      'publishedCompositionId', v_published_id,
      'sourceMatchdayId', p_matchday_id,
      'nextMatchdayId', v_transition.target_matchday_id,
      'carryoverApplied', false,
      'materialized', false,
      'sourceRetired', true,
      'transitionPreserved', true,
      'continuityVersion', v_transition.continuity_version
    );
  end if;

  if not v_source_is_managed then
    raise exception 'composition_first_publication_source_not_live';
  end if;

  v_first_publication := public.publish_matchday_reference_composition_with_continuity(
    p_matchday_id,
    p_composition_id
  );

  return v_first_publication || pg_catalog.jsonb_build_object(
    'publicationKind', 'first_publication'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_matchday_reference_composition_with_continuity(p_matchday_id uuid, p_composition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source_season_id uuid;
  v_source_number integer;
  v_next_matchday_id uuid;
  v_authority text;
begin
  if p_matchday_id is null or p_composition_id is null then
    raise exception 'composition_invalid';
  end if;

  perform jornada_private.acquire_matchday_live_desk_handoff_lock();
  perform jornada_private.acquire_matchday_live_layout_cutover_core_lock();

  select matchday_row.season_id, matchday_row.number
  into v_source_season_id, v_source_number
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id;

  if not found then
    raise exception 'composition_matchday_not_found';
  end if;

  select target_row.id
  into v_next_matchday_id
  from public.matchdays as target_row
  where target_row.season_id = v_source_season_id
    and target_row.number = v_source_number + 1;

  if not found then
    raise exception 'composition_next_matchday_not_found';
  end if;

  perform 1
  from public.matchdays as lock_row
  where lock_row.id in (p_matchday_id, v_next_matchday_id)
  order by lock_row.id
  for update;

  v_authority := jornada_private.matchday_live_layout_continuity_authority_v19(
    p_matchday_id
  );

  if v_authority = 'physical' then
    return jornada_private.materialize_matchday_live_layout_physical_handoff_v19(
      p_matchday_id,
      v_next_matchday_id,
      p_composition_id,
      'normal'
    );
  end if;

  return jornada_private.publish_matchday_continuity_legacy_v6(
    p_matchday_id,
    p_composition_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.recover_matchday_live_layout_continuity(p_source_matchday_id uuid, p_target_matchday_id uuid, p_source_composition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_authority text;
begin
  if p_source_matchday_id is null
    or p_target_matchday_id is null
    or p_source_composition_id is null
  then
    raise exception 'matchday-live-continuity-recovery-invalid-envelope';
  end if;

  perform jornada_private.acquire_matchday_live_desk_handoff_lock();
  perform jornada_private.acquire_matchday_live_layout_cutover_core_lock();

  perform 1
  from public.matchdays as lock_row
  where lock_row.id in (p_source_matchday_id, p_target_matchday_id)
  order by lock_row.id
  for update;

  v_authority := jornada_private.matchday_live_layout_continuity_authority_v19(
    p_source_matchday_id
  );

  if v_authority = 'physical' then
    return jornada_private.materialize_matchday_live_layout_physical_handoff_v19(
      p_source_matchday_id,
      p_target_matchday_id,
      p_source_composition_id,
      'recovery'
    ) || pg_catalog.jsonb_build_object('recovered', true);
  end if;

  return jornada_private.recover_matchday_continuity_legacy_v6(
    p_source_matchday_id,
    p_target_matchday_id,
    p_source_composition_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_matchday_editorial_bank_contextual_classification(p_bank_item_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_bank record;
  v_classification_key text;
  v_classification_source text;
begin
  select bank_row.* into v_bank
  from public.matchday_editorial_bank_items as bank_row
  where bank_row.id = p_bank_item_id
  for update;

  if not found then return; end if;
  if v_bank.classification_source = 'manual' then return; end if;

  if pg_catalog.lower(pg_catalog.btrim(coalesce(v_bank.source_type, ''))) <> 'editorial_article' then
    v_classification_key := null;
    v_classification_source := null;
  elsif pg_catalog.lower(pg_catalog.btrim(coalesce(v_bank.status, ''))) <> 'active' then
    return;
  elsif v_bank.automatic_eligible then
    perform jornada_private.refresh_matchday_editorial_bank_automatic_classifications(
      p_bank_item_ids => array[p_bank_item_id],
      p_refresh_distribution => false
    );
    return;
  elsif v_bank.classification_source = 'continuity_assisted' and v_bank.classification_key is not null then
    return;
  elsif v_bank.continuity_source_matchday_id is not null and v_bank.continuity_source_composition_id is not null then
    with recursive matchday_chain as (
      select transition_row.source_matchday_id as lookup_matchday_id, 1 as depth
      from public.matchday_editorial_continuity_transitions as transition_row
      where transition_row.target_matchday_id = v_bank.matchday_id
        and transition_row.source_matchday_id = v_bank.continuity_source_matchday_id
        and transition_row.source_composition_id = v_bank.continuity_source_composition_id
      union all
      select transition_row.source_matchday_id, chain.depth + 1
      from matchday_chain as chain
      join public.matchday_editorial_continuity_transitions as transition_row
        on transition_row.target_matchday_id = chain.lookup_matchday_id
      where chain.depth < 100
    )
    select ancestor_row.classification_key
    into v_classification_key
    from matchday_chain as chain
    join public.matchday_editorial_bank_items as ancestor_row
      on ancestor_row.matchday_id = chain.lookup_matchday_id
     and pg_catalog.lower(pg_catalog.btrim(coalesce(ancestor_row.source_type, ''))) = 'editorial_article'
     and pg_catalog.lower(pg_catalog.btrim(coalesce(ancestor_row.source_id, ''))) = pg_catalog.lower(pg_catalog.btrim(coalesce(v_bank.source_id, '')))
    where ancestor_row.classification_key is not null
    order by chain.depth, ancestor_row.created_at, ancestor_row.id
    limit 1;

    if v_classification_key is not null then v_classification_source := 'continuity_assisted'; end if;
  end if;

  if v_classification_key is null then
    if v_bank.classification_key is null and v_bank.classification_source is null and v_bank.classified_at is null then return; end if;
  elsif v_bank.classification_key = v_classification_key
    and v_bank.classification_source = v_classification_source
    and v_bank.classified_at is not null
  then return;
  end if;

  perform jornada_private.write_matchday_editorial_bank_contextual_classification(
    p_bank_item_id,
    v_classification_key,
    v_classification_source
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_matchday_editorial_profile_distribution(p_matchday_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_profile_key text;
  v_competition_slug text;
  v_now timestamptz := pg_catalog.now();
  v_placed_count integer;
begin
  if p_matchday_id is null then
    raise exception 'matchday-editorial-profile-distribution-invalid-input';
  end if;

  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-editorial-profile-distribution-matchday-not-found';
  end if;

  if exists (
    select 1
    from jornada_private.matchday_live_layout_physical_cutovers as cutover_row
    where cutover_row.matchday_id = p_matchday_id
  ) then
    return 0;
  end if;

  select assignment_row.profile_key, competition_row.slug
  into v_profile_key, v_competition_slug
  from public.matchday_editorial_profile_assignments as assignment_row
  join public.matchdays as matchday_row on matchday_row.id = assignment_row.matchday_id
  join public.seasons as season_row on season_row.id = matchday_row.season_id
  join public.competitions as competition_row on competition_row.id = season_row.competition_id
  where assignment_row.matchday_id = p_matchday_id
  for update of assignment_row;

  if not found then
    return 0;
  end if;

  if v_profile_key is distinct from 'liga_portugal_v1' then
    raise exception 'matchday-editorial-profile-distribution-invalid-profile';
  end if;

  if v_competition_slug is distinct from 'liga-portugal' then
    raise exception 'matchday-editorial-profile-distribution-incompatible-competition';
  end if;

  insert into public.matchday_editorial_profile_state_items (
    matchday_id, profile_key, source_type, source_id
  )
  select p_matchday_id, v_profile_key, plan_row.source_type, plan_row.source_id
  from public.matchday_editorial_profile_distribution_plan(p_matchday_id) as plan_row
  on conflict (matchday_id, profile_key, source_type, source_id) do nothing;

  update public.matchday_editorial_profile_state_items as state_row
  set zone_key = null,
      sort_order = null,
      updated_at = v_now
  where state_row.matchday_id = p_matchday_id
    and state_row.profile_key = v_profile_key
    and (state_row.zone_key is not null or state_row.sort_order is not null)
    and not exists (
      select 1
      from public.matchday_editorial_profile_distribution_plan(p_matchday_id) as plan_row
      where plan_row.source_type = state_row.source_type
        and plan_row.source_id = state_row.source_id
    );

  with desired_state as materialized (
    select * from public.matchday_editorial_profile_distribution_plan(p_matchday_id)
  )
  update public.matchday_editorial_profile_state_items as state_row
  set zone_key = null,
      sort_order = null,
      updated_at = v_now
  from desired_state as desired_row
  where state_row.matchday_id = p_matchday_id
    and state_row.profile_key = v_profile_key
    and state_row.source_type = desired_row.source_type
    and state_row.source_id = desired_row.source_id
    and state_row.zone_key is not null
    and (state_row.zone_key, state_row.sort_order)
      is distinct from (desired_row.zone_key, desired_row.sort_order);

  with desired_state as materialized (
    select * from public.matchday_editorial_profile_distribution_plan(p_matchday_id)
  )
  update public.matchday_editorial_profile_state_items as state_row
  set zone_key = desired_row.zone_key,
      sort_order = desired_row.sort_order,
      updated_at = v_now
  from desired_state as desired_row
  where state_row.matchday_id = p_matchday_id
    and state_row.profile_key = v_profile_key
    and state_row.source_type = desired_row.source_type
    and state_row.source_id = desired_row.source_id
    and (state_row.zone_key, state_row.sort_order)
      is distinct from (desired_row.zone_key, desired_row.sort_order);

  select pg_catalog.count(*)::integer
  into v_placed_count
  from public.matchday_editorial_profile_state_items as state_row
  where state_row.matchday_id = p_matchday_id
    and state_row.profile_key = v_profile_key
    and state_row.zone_key is not null;

  return v_placed_count;
end;
$function$

