CREATE OR REPLACE FUNCTION public.set_matchday_historical_article_decision_v1(p_matchday_id uuid, p_article_ids uuid[], p_decision text)
 RETURNS TABLE(updated_count bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_requested_count integer;
  v_distinct_count integer;
  v_existing_article_count integer;
  v_eligible_article_count integer;
begin
  if p_matchday_id is null
     or p_article_ids is null
     or coalesce(cardinality(p_article_ids), 0) = 0
     or p_decision is null
     or p_decision not in ('selected', 'bank', 'undecided') then
    raise exception 'matchday-historical-article-decision-v1-invalid-input';
  end if;

  if exists (
    select 1
    from unnest(p_article_ids) as requested(article_id)
    where requested.article_id is null
  ) then
    raise exception 'matchday-historical-article-decision-v1-invalid-article';
  end if;

  select
    count(*)::integer,
    count(distinct requested.article_id)::integer
  into v_requested_count, v_distinct_count
  from unnest(p_article_ids) as requested(article_id);

  if v_requested_count <> v_distinct_count then
    raise exception 'matchday-historical-article-decision-v1-duplicate-article';
  end if;

  perform 1
  from public.matchdays as matchday
  where matchday.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-historical-article-decision-v1-matchday-not-found';
  end if;

  perform 1
  from public.editorial_articles as article
  where article.id = any(p_article_ids)
  for key share;

  select count(*)::integer
  into v_existing_article_count
  from public.editorial_articles as article
  where article.id = any(p_article_ids);

  if v_existing_article_count <> v_requested_count then
    raise exception 'matchday-historical-article-decision-v1-article-not-found';
  end if;

  perform 1
  from public.matchday_editorial_bank_items as bank_item
  where bank_item.matchday_id = p_matchday_id
    and bank_item.status = 'active'
    and lower(btrim(coalesce(bank_item.source_type, ''))) = 'editorial_article'
    and exists (
      select 1
      from unnest(p_article_ids) as requested(article_id)
      where lower(btrim(bank_item.source_id)) = lower(requested.article_id::text)
    )
  for share;

  select count(distinct requested.article_id)::integer
  into v_eligible_article_count
  from unnest(p_article_ids) as requested(article_id)
  where exists (
    select 1
    from public.editorial_articles as article
    join public.matchday_editorial_bank_items as bank_item
      on lower(btrim(bank_item.source_id)) = lower(article.id::text)
     and bank_item.matchday_id = p_matchday_id
     and bank_item.status = 'active'
     and lower(btrim(coalesce(bank_item.source_type, ''))) = 'editorial_article'
    where article.id = requested.article_id
      and (
        article.matchday_id is null
        or article.matchday_id = p_matchday_id
        or (
          bank_item.continuity_source_matchday_id is not null
          and bank_item.continuity_revalidated_at is not null
        )
      )
  );

  if v_eligible_article_count <> v_requested_count then
    raise exception 'matchday-historical-article-decision-v1-article-not-eligible';
  end if;

  insert into jornada_private.matchday_historical_article_decisions (
    matchday_id,
    article_id,
    decision,
    updated_at
  )
  select
    p_matchday_id,
    requested.article_id,
    p_decision,
    statement_timestamp()
  from unnest(p_article_ids) as requested(article_id)
  on conflict (matchday_id, article_id) do update
  set
    decision = excluded.decision,
    updated_at = excluded.updated_at;

  return query select v_requested_count::bigint;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_matchday_latest_news_settings_v15(p_matchday_id uuid, p_latest_zone_mode text, p_latest_zone_title text DEFAULT NULL::text, p_latest_zone_title_color text DEFAULT NULL::text, p_write_title boolean DEFAULT false)
 RETURNS TABLE(is_physical boolean, changed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_is_physical boolean;
  v_profile_key text;
  v_changed boolean := false;
begin
  if p_matchday_id is null
    or p_latest_zone_mode not in ('latest_news', 'editorial_line')
    or (
      p_latest_zone_title_color is not null
      and p_latest_zone_title_color !~ '^#[0-9A-Fa-f]{6}$'
    )
    or (
      p_write_title
      and pg_catalog.char_length(
        pg_catalog.btrim(coalesce(p_latest_zone_title, ''))
      ) > 120
    )
  then
    raise exception 'matchday-latest-settings-v15-invalid-input';
  end if;

  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-latest-settings-v15-matchday-not-found';
  end if;

  select marker_row.profile_key
  into v_profile_key
  from jornada_private.matchday_live_layout_physical_cutovers as marker_row
  where marker_row.matchday_id = p_matchday_id;

  v_is_physical := v_profile_key is not null;

  if v_is_physical then
    if not exists (
      select 1
      from public.matchday_editorial_profile_assignments as assignment_row
      where assignment_row.matchday_id = p_matchday_id
        and assignment_row.profile_key = v_profile_key
    ) or not exists (
      select 1
      from public.matchday_live_layout_workspace_settings as settings_row
      where settings_row.matchday_id = p_matchday_id
    ) then
      raise exception 'matchday-latest-settings-v15-physical-state-incoherent';
    end if;

    update public.matchday_live_layout_workspace_settings as settings_row
    set latest_zone_mode = p_latest_zone_mode,
        latest_zone_title = case
          when p_write_title
            then pg_catalog.btrim(coalesce(p_latest_zone_title, ''))
          else settings_row.latest_zone_title
        end,
        latest_zone_title_color = case
          when p_write_title
            then pg_catalog.upper(p_latest_zone_title_color)
          else settings_row.latest_zone_title_color
        end,
        updated_at = pg_catalog.statement_timestamp()
    where settings_row.matchday_id = p_matchday_id
      and row(
        settings_row.latest_zone_mode,
        settings_row.latest_zone_title,
        settings_row.latest_zone_title_color
      ) is distinct from row(
        p_latest_zone_mode,
        case when p_write_title
          then pg_catalog.btrim(coalesce(p_latest_zone_title, ''))
          else settings_row.latest_zone_title end,
        case when p_write_title
          then pg_catalog.upper(p_latest_zone_title_color)
          else settings_row.latest_zone_title_color end
      );
    v_changed := found;

    perform jornada_private.begin_matchday_live_layout_downstream_v14(
      p_matchday_id
    );

    begin
      insert into public.matchday_editorials as editorial_row (
        matchday_id,
        latest_zone_mode,
        latest_zone_title,
        latest_zone_title_color,
        updated_at
      ) values (
        p_matchday_id,
        p_latest_zone_mode,
        case when p_write_title
          then nullif(pg_catalog.btrim(coalesce(p_latest_zone_title, '')), '')
          else (
            select nullif(settings_row.latest_zone_title, '')
            from public.matchday_live_layout_workspace_settings
              as settings_row
            where settings_row.matchday_id = p_matchday_id
          ) end,
        case when p_write_title
          then pg_catalog.upper(p_latest_zone_title_color)
          else (
            select settings_row.latest_zone_title_color
            from public.matchday_live_layout_workspace_settings
              as settings_row
            where settings_row.matchday_id = p_matchday_id
          ) end,
        pg_catalog.statement_timestamp()
      )
      on conflict (matchday_id) do update
      set latest_zone_mode = excluded.latest_zone_mode,
          latest_zone_title = excluded.latest_zone_title,
          latest_zone_title_color = excluded.latest_zone_title_color,
          updated_at = pg_catalog.statement_timestamp()
      where row(
        editorial_row.latest_zone_mode,
        editorial_row.latest_zone_title,
        editorial_row.latest_zone_title_color
      ) is distinct from row(
        excluded.latest_zone_mode,
        excluded.latest_zone_title,
        excluded.latest_zone_title_color
      );
      v_changed := v_changed or found;

    exception when others then
      perform jornada_private.end_matchday_live_layout_downstream_v14(
        p_matchday_id
      );
      raise;
    end;

    perform jornada_private.end_matchday_live_layout_downstream_v14(
      p_matchday_id
    );
  else
    insert into public.matchday_editorials as editorial_row (
      matchday_id,
      latest_zone_mode,
      latest_zone_title,
      latest_zone_title_color,
      updated_at
    ) values (
      p_matchday_id,
      p_latest_zone_mode,
      case when p_write_title
        then nullif(pg_catalog.btrim(coalesce(p_latest_zone_title, '')), '')
        else null end,
      case when p_write_title
        then pg_catalog.upper(p_latest_zone_title_color)
        else null end,
      pg_catalog.statement_timestamp()
    )
    on conflict (matchday_id) do update
    set latest_zone_mode = excluded.latest_zone_mode,
        latest_zone_title = case when p_write_title
          then excluded.latest_zone_title
          else editorial_row.latest_zone_title end,
        latest_zone_title_color = case when p_write_title
          then excluded.latest_zone_title_color
          else editorial_row.latest_zone_title_color end,
        updated_at = pg_catalog.statement_timestamp()
    where row(
      editorial_row.latest_zone_mode,
      editorial_row.latest_zone_title,
      editorial_row.latest_zone_title_color
    ) is distinct from row(
      excluded.latest_zone_mode,
      case when p_write_title
        then excluded.latest_zone_title
        else editorial_row.latest_zone_title end,
      case when p_write_title
        then excluded.latest_zone_title_color
        else editorial_row.latest_zone_title_color end
    );
    v_changed := found;
  end if;

  return query select v_is_physical, v_changed;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_matchday_latest_zone_placement_v15(p_matchday_id uuid, p_latest_zone_placement text)
 RETURNS TABLE(is_physical boolean, changed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_is_physical boolean;
  v_profile_key text;
  v_changed boolean := false;
begin
  if p_matchday_id is null
    or p_latest_zone_placement not in ('top', 'four_news', 'hidden')
  then
    raise exception 'matchday-latest-placement-v15-invalid-input';
  end if;

  perform jornada_private.acquire_matchday_live_layout_cutover_writer_lock();

  perform 1
  from public.matchdays as matchday_row
  where matchday_row.id = p_matchday_id
  for update;

  if not found then
    raise exception 'matchday-latest-placement-v15-matchday-not-found';
