CREATE OR REPLACE FUNCTION public.sync_matchday_editorial_selection_from_bank()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_source_type text;
  v_source_id text;
begin
  if tg_op not in ('INSERT', 'UPDATE') then return new; end if;

  if exists (
    select 1
    from jornada_private.matchday_editorial_bank_classification_authorizations as authorization_row
    where authorization_row.backend_pid = pg_catalog.pg_backend_pid()
      and authorization_row.transaction_id = pg_catalog.pg_current_xact_id()
      and authorization_row.bank_item_id = new.id
  ) then return new; end if;

  v_source_type := pg_catalog.lower(pg_catalog.btrim(coalesce(new.source_type, '')));
  v_source_id := pg_catalog.btrim(coalesce(new.source_id, ''));

  if v_source_type not in ('editorial_article','editorial_content') or v_source_id = '' then return new; end if;

  update public.matchday_live_layout_items as live_row
  set article_id = case
        when v_source_type = 'editorial_article'
         and v_source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then v_source_id::uuid else null end,
      label = nullif(pg_catalog.btrim(new.label), ''),
      title = nullif(pg_catalog.btrim(new.title), ''),
      subtitle = nullif(pg_catalog.btrim(new.subtitle), ''),
      image_url = nullif(pg_catalog.btrim(new.image_url), ''),
      link_url = nullif(pg_catalog.btrim(new.link_url), ''),
      updated_at = pg_catalog.now()
  where live_row.matchday_id = new.matchday_id
    and live_row.slot_type in ('live_four_news:1','live_four_news:2','live_four_news:3','live_four_news:4')
    and pg_catalog.lower(pg_catalog.btrim(coalesce(live_row.source_type, ''))) = v_source_type
    and pg_catalog.btrim(coalesce(live_row.source_id, '')) = v_source_id;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_matchday_zone_row_to_bank()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if jornada_private.is_matchday_live_layout_carryover_v18(new.matchday_id) then
    return new;
  end if;
  if tg_table_name = 'matchday_latest_news' then
    if tg_op = 'UPDATE'
      and (
        new.id,new.matchday_id,new.time_label,new.title,new.link_url,new.image_url,new.status,new.created_at,new.subtitle,new.article_id,new.time_label_color
      ) is not distinct from (
        old.id,old.matchday_id,old.time_label,old.title,old.link_url,old.image_url,old.status,old.created_at,old.subtitle,old.article_id,old.time_label_color
      )
    then
      return new;
    end if;
    if pg_catalog.lower(pg_catalog.btrim(coalesce(new.status, ''))) = 'published' then
      perform public.sync_matchday_zone_publication_to_bank(new.matchday_id,new.link_url);
    end if;
  elsif tg_table_name = 'matchday_highlights' then
    if pg_catalog.lower(pg_catalog.btrim(coalesce(new.status, ''))) = 'published' then
      perform public.sync_matchday_zone_publication_to_bank(new.matchday_id,new.link_url);
    end if;
  elsif tg_table_name = 'matchday_horizontal_news' then
    if pg_catalog.lower(pg_catalog.btrim(coalesce(new.status, ''))) = 'published' then
      perform public.sync_matchday_zone_publication_to_bank(new.matchday_id,new.link_url);
    end if;
  elsif tg_table_name = 'matchday_editorials' then
    perform public.sync_matchday_zone_publication_to_bank(new.matchday_id,new.headline_link_url);
    if pg_catalog.lower(pg_catalog.btrim(coalesce(new.complementary_status, ''))) = 'published' then
      perform public.sync_matchday_zone_publication_to_bank(new.matchday_id,new.complementary_link_url);
    end if;
    if pg_catalog.lower(pg_catalog.btrim(coalesce(new.side_block_status, ''))) = 'published' then
      perform public.sync_matchday_zone_publication_to_bank(new.matchday_id,new.side_block_link_url);
    end if;
  end if;
  return new;
end;
$function$
